//class com.xq.component.accordion.data.AccordionMulNode
var AccordionMulNode=(function(){
	function AccordionMulNode(){
		this.tabDic=null;
		this.tabArr=null;
		this.isOpen=false;
		this.data=null;
		this.isCornor=false;
		this.tabDic={};
		this.tabArr=[];
	}

	__class(AccordionMulNode,'com.xq.component.accordion.data.AccordionMulNode');
	return AccordionMulNode;
})()


/**
*手风琴组建数据元
*@author xiangjia
*@date 2019-11-12
*/
//class com.xq.component.accordion.data.AccordionNode
var AccordionNode=(function(){
	function AccordionNode(){
		this.children=null;
		/**当展开时候，list显示所有的孩子*/
		this.showAllChildren=true;
		this.isOpened=false;
		this.data=null;
		/**
		*内容宽高
		**/
		this.forlderHeight=100;
		/**
		*内容宽高
		**/
		this.contentHeight=64;
		/**是否关闭其他*/
		this.isColseOther=false;
		/**对应的List选中索引*/
		this.listSelectIndex=0;
	}

	__class(AccordionNode,'com.xq.component.accordion.data.AccordionNode');
	var __proto=AccordionNode.prototype;
	/**初始化*/
	__proto.init=function(data){
		this.contentHeight=58;
		this.data=data;
		this.showAllChildren=false;
		this.isColseOther=true;
		this.children=[];
	}

	/**添加到子列表*/
	__proto.add=function(data){
		this.children&&this.children.push(data);
	}

	return AccordionNode;
})()


/**
*
*@author zhanglimin
*@date 2019-11-4
*/
//class com.xq.component.aniList.ListVo
var ListVo=(function(){
	function ListVo(){
		/**显示区域宽*/
		this.twidth=NaN;
		/**显示区域高*/
		this.theight=NaN;
		/**逻辑Render*/
		this.itemRender=null;
		/**Item高*/
		this.itemH=NaN;
		/**Item宽*/
		this.itemW=NaN;
		/**是否垂直居中*/
		this.isCenterY=false;
		/**数据*/
		this.data=null;
		/**滑动方向 1:垂直 2水平*/
		this.dir=1;
		/**间隙*/
		this.gap=5;
		/**Item更新时间*/
		this.itemCd=50;
		/**动画完成的回调函数*/
		this.twcAniCalBack=null;
	}

	__class(ListVo,'com.xq.component.aniList.ListVo');
	return ListVo;
})()


