	AttributeTypeEnum.getDifferenceValue=function(attrArr1,attrArr2){
		var attrArr=[];
		var len=attrArr1.length;
		var len1=attrArr2.length;
		for (var i=0;i < len;i++){
			var attrVo=attrArr1[i];
			for (var j=0;j < len1;j++){
				var attrVo1=attrArr2[j];
				var isSame=false;
				if(attrVo.attrId==attrVo1.attrId){
					if(parseInt(attrVo.attrValue)> parseInt(attrVo1.attrValue)){
						var attrVo2=new AttrVO();
						attrVo2=attrVo1;
						attrVo2.attrValue=parseInt(attrVo.attrValue)-parseInt(attrVo1.attrValue)+"";
						attrArr.push(attrVo2);
					}
					isSame=true;
					break ;
				}
			}
			if(!isSame){
				attrArr.push(attrVo);
			}
		}
		return attrArr;
	}

