//class com.xq.modules.active.ActivityRemaindMgr
var ActivityRemaindMgr=(function(){
	function ActivityRemaindMgr(){
		/**限时活动Model*/
		this._model=null;
		/**记录当前进行中功能Id*/
		this.curFuncId=null;
		this._model=Model.xianshiativity;
	}

	__class(ActivityRemaindMgr,'com.xq.modules.active.ActivityRemaindMgr');
	var __proto=ActivityRemaindMgr.prototype;
	/**展示活动进行提示弹窗*/
	__proto.showActivity=function(id){
		var ele=this._model.getEleById(id);
		if(!ele)return;
		var cof=ele.getCfgData();
		var funcId=cof.functionid;
		if(this.curFuncId !=funcId){
			this.curFuncId=funcId;
			if(cof.timetype==999)return;
			if(!Mgr.guide.isOpen("xianshihuodong"))return;
			if(!Mgr.guide.isOpen(funcId))return;
			this.show(ele);
		}
	}

	__proto.show=function(ele){
		if(!ele)return;
		var v=UIMgrR.openIView(com.xq.view.modules.active.IActivityRemindView,2);
		v.dataSource=ele;
	}

	/**清除当前正在进行的功能id缓存*/
	__proto.clearCurActivity=function(){
		this.curFuncId="";
	}

	/**检测限时活动是否正在进行*/
	__proto.activeIsOpen=function(func){
		if(!func)return false;
		return this.curFuncId==func;
	}

	__getset(1,ActivityRemaindMgr,'ins',function(){
		return ActivityRemaindMgr._ins=ActivityRemaindMgr._ins|| new ActivityRemaindMgr();
	});

	ActivityRemaindMgr._ins=null;
	return ActivityRemaindMgr;
})()


