//class com.xq.modules.active.jijin.JiJinMgr
var JiJinMgr=(function(){
	function JiJinMgr(){
		/**闯关返利 付费引导*/
		this.isChuanGuan=false;
		this.cfgArrDic=null;
		this.cfgDic=null;
		this.redMgr=null;
		/**当前种类的基金是否全部领取*/
		this.getAllDic=null;
		this.proData={};
		this.hasJiJinData={};
		this.baiBeiTab
		this.cfgArrDic={};
		this.cfgDic={};
		this.getAllDic={};
		var tab=CfgManager.getTableCfg("ChengZhangJiJin");
		this.baiBeiTab=CfgManager.getTableCfg("baibeifanlibuy");
		var arr=tab.objectDataArray;
		var len=arr.length;
		var targetTypeDic={};
		for(var i=0;i< len;i++){
			var o=arr[i];
			var id=o.id;
			this.cfgDic[id]=o;
			var type=o.activityType;
			var targetType=o.targetType;
			var dic1=this.cfgArrDic[type];
			if(!dic1){
				dic1={};
				this.cfgArrDic[type]=dic1;
			};
			var tarArr=dic1[targetType];
			if(!tarArr){
				tarArr=[];
				dic1[targetType]=tarArr;
			}
			tarArr.push(o);
			targetTypeDic[targetType]=1;
		}
		EventCenter.instance.onQue("LEVEL_UP",this,this.onLevelChange);
		EventCenter.instance.onQue("guanqia_changeEvent",this,this.onguanQiaChange);
		EventCenter.instance.on("UpDataTargetInfoOpraEvent",this,this.fuFeiYinDao);
		EventCenter.instance.on("guanqia_changeEvent",this,this.chuangGuangFanliTips);
		EventCenter.instance.on("LEVEL_UP",this,this.chengZhangFanliTips);
		this.redMgr=Mgr.red;
		this.redMgr.regist("touzijijin","baiyinjijin",true,"JiJinHallRed");
		this.redMgr.regist("touzijijin","huangjinjijin",true,"JiJinHallRed");
		this.redMgr.regist("touzijijin","zuanshijijin",true,"JiJinHallRed");
	}

	__class(JiJinMgr,'com.xq.modules.active.jijin.JiJinMgr');
	var __proto=JiJinMgr.prototype;
	// }
	__proto.initPro=function(){
		Mgr.operationPro.sendGetJiJinInfo("baiyinjijin");
		Mgr.operationPro.sendGetJiJinInfo("huangjinjijin");
		Mgr.operationPro.sendGetJiJinInfo("zuanshijijin");
		Mgr.operationPro.sendGetOperation("baiyinjijin");
		Mgr.operationPro.sendGetOperation("huangjinjijin");
		Mgr.operationPro.sendGetOperation("zuanshijijin");
	}

	__proto.onLevelChange=function(){
		Mgr.operationPro.sendGetOperation("zuanshijijin");
	}

	__proto.onguanQiaChange=function(){
		Mgr.operationPro.sendGetOperation("huangjinjijin");
	}

	__proto.getFunctionIdByActivityType=function(actitvityType){
		switch(actitvityType){
			case "baiyinjijin":
				return "baiyinjijin";
			case "huangjinjijin":
				return "huangjinjijin";
			case "zuanshijijin":
				return "zuanshijijin";
			}
		return "";
	}

	/***/
	__proto.getBaiBeiByType=function(activityType){
		return this.baiBeiTab.getItemByField("activityType",activityType);
	}

	__proto.refreshRed=function(activityType){
		this.getAllDic[activityType]=false;
		if(!this.isHasBuy(activityType)){
			return;
		};
		var vo=this.getProData(activityType);
		var isGetAll=true;
		if(vo){
			var getArr=vo.rewards;
			var len=getArr.length;
			var getDic={};
			for(var i=0;i < len;i++){
				var msg1=getArr[i];
				getDic[msg1.id]=msg1.awarded;
				if(msg1.id !="2")
					isGetAll=false;
			}
			this.getAllDic[activityType]=isGetAll;
			var arr=vo.deffrentActivity;
			var len=arr.length;
			for(var i=0;i < len;i++){
				var process=vo.progress;
				var cfgArr=this.getCfgDataArray(activityType,this.getChongZhiType(activityType));
				var len1=cfgArr.length;
				for(var j=0;j<len1;j++){
					var cfg=cfgArr[j];
					var id=cfg.id;
					cfg["sort"]=id;
					var targetVal=cfg.targetValue;
					var funId=cfg.activityType;
					if(process >=parseInt(targetVal)&& getDic[id]==0){
						this.redMgr.showRedPoint(funId,funId+targetVal,"JIJIN_REFRESH_CORNOR");
						}else{
						if(getDic[id]!=0){
							cfg["sort"]=9999999;
						}
						this.redMgr.hideRedPoint(funId,funId+targetVal,"JIJIN_REFRESH_CORNOR");
					}
				}
			}
		}
	}

	/**设置已经购买的基金*/
	__proto.setHasJiJin=function(activityType){
		this.hasJiJinData[activityType]=true;
		EventCenter.instance.event("JIJIN_REFRESH_VIEW",[this.getProData[activityType]]);
	}

	/**设置proto数据*/
	__proto.setData=function(vo){
		var activityType=vo.activityType;
		this.proData[activityType]=vo;
		this.refreshRed(activityType);
		EventCenter.instance.event("JIJIN_REFRESH_VIEW",[vo]);
	}

	/**获取proto数据*/
	__proto.getProData=function(activityType){
		return this.proData[activityType];
	}

	/**获取该奖励是否已经领取*/
	__proto.isGetProData=function(activityType,id){
		var vo=this.proData[activityType];
		if(vo){
			var arr=vo.rewards;
			var len=arr.length;
			for(var i=0;i< len;i++){
				var o=arr[i];
				if(o.id==id){
					return o.awarded!=0;
				}
			}
		}
		return false;
	}

	/**获取后端给的相关目标进度*/
	__proto.getProTargetProcess=function(activityType,targetType){
		var vo=this.proData[activityType];
		if(vo){
			return vo.progress;
		}
		return 0;
	}

	/**判断是否已经购买该基金*/
	__proto.isHasBuy=function(actitvityType){
		return this.hasJiJinData[actitvityType];
	}

	/**返回充值id*/
	__proto.getChongZhiId=function(actitvityType){
		switch(actitvityType){
			case "baiyinjijin":
				return 35;
			case "huangjinjijin":
				return 36;
			case "zuanshijijin":
				return 37;
			}
		return 0;
	}

	/**返回充值id*/
	__proto.getChongZhiType=function(actitvityType){
		switch(actitvityType){
			case "baiyinjijin":
				return "login_sum";
			case "huangjinjijin":
				return "pass_level";
			case "zuanshijijin":
				return "role_level";
			}
		return null;
	}

	/**获取购买基金需要的rmb*/
	__proto.getRmb=function(actitvityType){
		var o=Mgr.vip.getChongZhiData(this.getChongZhiId(actitvityType));
		if(o){
			return o.rmb;
			}else{
			return 0;
		}
	}

	/**获取购买基金会获得的道具*/
	__proto.getRewadItem=function(actitvityType){
		var o=Mgr.vip.getChongZhiData(this.getChongZhiId(actitvityType));
		if(o){
			return o.extraItem;
			}else{
			return []
		}
	}

	/**返回购买需要的vip等级*/
	__proto.getNeedVipLevel=function(actitvityType){
		var val=0;
		switch(actitvityType){
			case "baiyinjijin":
				val=Mgr.tequanMgr.getVipLevelByTequanType(17);
				break ;
			case "huangjinjijin":
				val=Mgr.tequanMgr.getVipLevelByTequanType(18);
				break ;
			case "zuanshijijin":
				val=Mgr.tequanMgr.getVipLevelByTequanType(19);
				break ;
			}
		return val;
	}

	/**判断是否可以购买*/
	__proto.isCanBuy=function(actitvityType){
		var val=0;
		switch(actitvityType){
			case "baiyinjijin":
				val=Mgr.tequanMgr.getTequanVal(17);
				break ;
			case "huangjinjijin":
				val=Mgr.tequanMgr.getTequanVal(18);
				break ;
			case "zuanshijijin":
				val=Mgr.tequanMgr.getTequanVal(19);
				break ;
			}
		return val >0;
	}

	__proto.getCfgDataById=function(id){
		return this.cfgDic[id];
	}

	__proto.getCfgDataArray=function(activityType,targetType){
		var dic=this.cfgArrDic[activityType];
		if(dic){
			return dic[targetType];
		}
		return [];
	}

	/**根据functionId判断该种类进阶是否全部领取*/
	__proto.getIsGetAllByFuncId=function(funcId){
		return this.getAllDic[funcId];
	}

	/**登录返利付费引导*/
	__proto.fuFeiYinDao=function(id){
		if(id==6){
			var opAct=NewActiveManager.ins.getActiveVerDic(6);
			if(opAct && !this.isHasBuy("baiyinjijin")){
				var time=Mgr.cfgMgr.getValueByType(220);
				var daojishi=parseInt(time)*60*1000;
				Laya.timer.once(daojishi,this,this.dengluFanLiTips);
			}
			EventCenter.instance.off("UpDataTargetInfoOpraEvent",this,this.fuFeiYinDao);
		}
	}

	__proto.dengluFanLiTips=function(){
		Laya.timer.clear(this,this.dengluFanLiTips);
		var guideSync=Mgr.fhProMgr.getGuideSync(3);
		if(guideSync)Mgr.chipPopMgr.openFuFeiYinDaoView(guideSync.value,70008,261055);
	}

	/**闯关返利 付费引导**/
	__proto.chuangGuangFanliTips=function(){
		var opAct=NewActiveManager.ins.getActiveVerDic(6);
		if(this.isChuanGuan && opAct && !this.isHasBuy("huangjinjijin")){
			var cfgArr=this.getCfgDataArray("huangjinjijin",this.getChongZhiType("huangjinjijin"));
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var obj=cfgArr[i];
				var guanKaLv=Mgr.gqMgr.gqInfo.nextLevel-1;
				if(guanKaLv==obj.targetValue){
					var guideSync=Mgr.fhProMgr.getGuideSync(4);
					if(guideSync)Mgr.chipPopMgr.openFuFeiYinDaoView(guideSync.value,70009,261056);
				}
			}
		}
		this.isChuanGuan=true;
	}

	/**成长返利 付费引导**/
	__proto.chengZhangFanliTips=function(){
		var opAct=NewActiveManager.ins.getActiveVerDic(6);
		if(opAct && !this.isHasBuy("zuanshijijin")){
			var cfgArr=this.getCfgDataArray("zuanshijijin",this.getChongZhiType("zuanshijijin"));
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var obj=cfgArr[i];
				var level=NetMgr.ins().roleVO.level;
				if(level==obj.targetValue){
					var guideSync=Mgr.fhProMgr.getGuideSync(5);
					if(guideSync)Mgr.chipPopMgr.openFuFeiYinDaoView(guideSync.value,70010,261057);
				}
			}
		}
	}

	return JiJinMgr;
})()


