		NewActiveManager.ins.regActOpenHandler(89,Handler.create(this,this.openAct,null,false));
		NewActiveManager.ins.regActEndHandler(89,Handler.create(this,this.closeAct,null,false));
		EventCenter.instance.on("GetTargetRewardOpraEvent",this,this.updateAct);
		EventCenter.instance.on("UpDataTargetInfoOpraEvent",this,this.updateAct);
		EventCenter.instance.event("ACTIVE_TOGGLE",["SVIPKuanHuanIcon"]);
