//class com.xq.modules.active.xiakeLing.XiaKeLingModel
var XiaKeLingModel=(function(){
	function XiaKeLingModel(){
		/**排名奖励配置*/
		this._rankCfg=null;
		/**排名奖励配置数据容器*/
		this._rankDc=null;
		/**当前等级*/
		this.level=0;
		/**当前经验*/
		this.exp=0;
		/**是否买了侠客令*/
		this.hasGodXiaKeToken=false;
		/**第几阶段*/
		this.curStage=0;
		/**该阶段的活动结束时间*/
		this.stageEndTime=NaN;
		/**阶段任务信息*/
		this.taskObj={};
		this.stageExp=0;
		/**赛季完成任务个数*/
		this.saiJiNum=0;
		//排行
		this.rankAry=null;
		/**我的排名*/
		this.myRnak=0;
		this.initData();
	}

	__class(XiaKeLingModel,'com.xq.modules.active.xiakeLing.XiaKeLingModel');
	var __proto=XiaKeLingModel.prototype;
	__proto.initData=function(){
		this._rankCfg=CfgManager.getTableCfg("xiakecardrank");
	}

	/**获取排名配置数据容器*/
	__proto.getRankDc=function(){
		if(!this._rankDc){
			this._rankDc=new DataContainer();
			CommonUtil.initDataContainer(this._rankDc,this._rankCfg);
		}
		return this._rankDc;
	}

	__proto.getRankArrByFlag=function(flag){
		var dc=this.getRankDc().where("flag",flag,"id");
		return dc.array;
	}

	__proto.getRewardByRankFlag=function(flag,rank){
		var arr=this.getRankArrByFlag(flag);
		var len=arr.length;
		var ele;
		var cof;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(ele){
				cof=ele.getCfgData();
				if(rank>=cof.minRank&&rank<=cof.rank){
					return cof.rankReward;
				}
			}
		}
		return "";
	}

	/**获取展示排名数据*/
	__proto.getShowRankVoArr=function(flag){
		var rankVos=[];
		var arr=this.rankAry;
		var len=arr.length;
		var info;
		var vo;
		var lastRank=1;
		for(var i=0;i<len;i++){
			info=arr[i];
			vo=new XiaKeLingRankVo();
			vo.rank=info.rank+"-"+info.rank;
			vo.playerInfo=info;
			vo.reward=this.getRewardByRankFlag(flag,info.rank);
			lastRank=info.rank+1;
			rankVos.push(vo);
		}
		arr=this.getRankArrByFlag(flag);
		len=arr.length;
		var ele;
		var cof;
		for(i=0;i<len;i++){
			ele=arr[i];
			if(ele){
				cof=ele.getCfgData();
				if(lastRank>=cof.minRank&&lastRank<=cof.rank){
					vo=new XiaKeLingRankVo();
					vo.rank=lastRank+"-"+cof.rank;
					vo.reward=cof.rankReward;
					vo.playerInfo=null;
					rankVos.push(vo);
					lastRank=cof.rank+1
				}
			}
		}
		return rankVos;
	}

	return XiaKeLingModel;
})()


