var XingYunFanPaiMgr=(function(){
	function XingYunFanPaiMgr(){
		this._model=null;
		this._red=null;
		this._model=new XingYunFanPaiModel();
		this._red=Mgr.red;
		this.registRed();
	}

	__class(XingYunFanPaiMgr,'com.xq.modules.active.xingYunFanPai.XingYunFanPaiMgr');
	var __proto=XingYunFanPaiMgr.prototype;
	//============前端接口===========
	__proto.getDayEles=function(flag){
		return this._model.getDayEles(flag);
	}

	__proto.getDayEle=function(flag,idx){
		return this._model.getDayEle(flag,idx);
	}

	/***/
	__proto.getTypeDesc=function(flag){
		var ele=this._model.getFlagEle(flag);
		if(!ele)return "";
		var cfg=ele.getCfgData();
		var item=cfg.item;
		var name=Mgr.item.getItemName(item);
		return Lang.str(2172)+name+Lang.str(2173);
	}

	/**最终大奖状态
	*0：不可领取
	*1：可领取
	*2：已领取
	**/
	__proto.getFinalPrizeStat=function(flag){
		var ele=this._model.getFlagEle(flag);
		if(!ele)return 0;
		var info=ele.getValue("s_data");
		if(!info)return 0;
		if(info.canGetType==1){
			return info.num>0?1:0;
		}
		else{
			return info.canGetType
		}
	}

	/**今日翻牌状态
	*0：未开启
	*1：可翻牌
	*2：已翻牌
	**/
	__proto.getDayStat=function(dayEle){
		if(!dayEle)return 0;
		var todayIdx=this.getTodayIdx();
		if(!todayIdx)return 0;
		var idx=dayEle.getCfgData().idx
		if(idx<todayIdx)return 2;
		if(idx==todayIdx){
			var flag=NewActiveManager.ins.getActiveFlag(197);
			var ele=this._model.getFlagEle(flag);
			if(!ele)return 0;
			var info=ele.getValue("s_data");
			if(!info)return 0;
			if(info.num>0)return 2;
			return 1;
		}
		return 0;
	}

	__proto.getTodayEle=function(){
		var flag=NewActiveManager.ins.getActiveFlag(197);
		var ele=this._model.getFlagEle(flag);
		if(!ele)return null;
		var info=ele.getValue("s_data");
		if(!info)return null;
		var targetEle;
		var arr=this.getDayEles(flag);
		var len=arr.length;
		for(var i=0;i<len;i++){
			var idx=arr[i];
			if(info.num>0){
				if(!this.ifFanPai(idx))break ;
				targetEle=idx;
			}
			else{
				if(!this.ifFanPai(idx)){
					targetEle=idx;
					break
				}
			}
		}
		if(!targetEle)return null;
		return targetEle;
	}

	__proto.getTodayIdx=function(){
		var ele=this.getTodayEle();
		if(!ele)return 0;
		return parseInt(ele.getCfgData().idx);
	}

	__proto.ifFanPai=function(ele){
		if(!ele)return false;
		var info=ele.getValue("s_data");
		if(!info||info.num==0)return false;
		return true;
	}

	//============同步后端数据=========
	__proto.updateInfo=function(msg){
		var flag=NewActiveManager.ins.getActiveFlag(197);
		this._model.updateInfo(flag,msg);
		EventCenter.instance.event("updateInfo");
		this.updateRed();
	}

	__proto.updateFanPai=function(msg){
		Mgr.xingYunFanPaiA.sendGetInfo();
		var idx=msg.info.idx;
		var flag=NewActiveManager.ins.getActiveFlag(197);
		var ele=this.getDayEle(flag,idx);
		EventCenter.instance.event("updataFanPai",[ele]);
	}

	__proto.updateReward=function(msg){
		Mgr.xingYunFanPaiA.sendGetInfo();
	}

	/**奖励展示*/
	__proto.showReward=function(items){}
	//============红点==============
	__proto.registRed=function(){
		this._red.regist("XingYunFanPaiFrame","XingYunFanPai",true,"XingYunFanPaiFrameRed");
	}

	__proto.updateRed=function(){
		if(!Mgr.guide.isOpen("XingYunFanPai"))return;
		var todayEle=this.getTodayEle();
		if(!todayEle)return;
		var stat=this.getDayStat(todayEle);
		if(stat==1){
			this._red.showRedPoint("XingYunFanPai","showRed","XingYunFanPaiRed");
		}
		else{
			this._red.hideRedPoint("XingYunFanPai","showRed","XingYunFanPaiRed");
		}
	}

	//============活动管理============
	__proto.regActive=function(){
		ActManager.ins.regist("XingYunFanPaiFrame","XingYunFanPai",197,"XingYunFanPai");
		var open=Handler.create(this,this.onActOpen,[197],false);
		NewActiveManager.ins.regActOpenHandler(197,open);
		var close=Handler.create(this,this.onActClose,[197],false);
		NewActiveManager.ins.regActEndHandler(197,close);
	}

	/**活动开启*/
	__proto.onActOpen=function(actId){
		if(actId==197){
			Mgr.xingYunFanPaiA.sendGetInfo();
		}
	}

	__proto.onActClose=function(actId){
		if(actId==195){
		}
	}

	return XingYunFanPaiMgr;
})()


