var ComeBackMgr=(function(){
	function ComeBackMgr(){
		this._model=null;
		this._red=null;
		//活动总时间
		this._endTime=NaN;
		this._ifShowTip=false;
		this._model=new ComeBackModel();
		this.registRed();
	}

	__class(ComeBackMgr,'com.xq.modules.activity.ComeBack.ComeBackMgr');
	var __proto=ComeBackMgr.prototype;
	__proto.regConfig=function(){
		var ComeBackCourtesyCfg="huiguihaoli";
		var ComeBackChargeCfg="huiguileichong";
		var ComeBackShopCfg="huiguilibao";
		NewActiveManager.ins.regActTableNameHandler(ComeBackCourtesyCfg,Handler.create(this,this.onUpdateCfg,[203],false));
		NewActiveManager.ins.regActTableNameHandler(ComeBackChargeCfg,Handler.create(this,this.onUpdateCfg,[201],false));
		NewActiveManager.ins.regActTableNameHandler(ComeBackShopCfg,Handler.create(this,this.onUpdateCfg,[202],false));
		EventCenter.instance.event("ACTIVE_TOGGLE",["ComeBackFrame",true]);
	}

	__proto.onUpdateCfg=function(id){
		this._model.initCfg(id);
	}

	__proto.openComeBackDialog=function(){
		UIMgrR.openIView(com.xq.view.modules.activity.comeBackActivity.IComeBackDialog,2);
	}

	//=======同步后端数据======
	__proto.updateRoleStage=function(msg){
		if(msg.state==1||msg.state==2){
			if(!this._ifShowTip){
				Laya.timer.once(5000,this,this.openComeBackDialog);
				this._ifShowTip=true;
			}
			this._endTime=msg.endTime;
			EventCenter.instance.event("ACTIVE_TOGGLE",["ComeBackFrame",false]);
			NewActiveManager.ins.reqTableCs(203);
			NewActiveManager.ins.reqTableCs(201);
			NewActiveManager.ins.reqTableCs(202);
			Mgr.comeBackA.sendComeBackInfo(203);
			Mgr.comeBackA.sendComeBackInfo(201);
			Mgr.comeBackA.sendComeBackInfo(202);
			}else{
			EventCenter.instance.event("ACTIVE_TOGGLE",["ComeBackFrame",true]);
		}
	}

	__proto.updateComeBackCourtesyInfo=function(msg){
		this._model.updateComeBackCourtesyInfo(msg);
		this.refreshComeBackCourtesyInfo();
	}

	__proto.updateComeBackChargeInfo=function(msg){
		this._model.updateComeBackChargeInfo(msg);
		this.refreshComeBackChargeInfo();
	}

	__proto.updateComeBackShopInfo=function(msg){
		this._model.updateComeBackShopInfo(msg);
		EventCenter.instance.event("UpdateShopInfo");
	}

	//_shopTime=msg.endTime;
	__proto.updateComeBackCourtesyLqInfo=function(msg){
		this._model.updateComeBackCourtesyLqInfo(msg);
		this.refreshComeBackCourtesyInfo();
	}

	__proto.updateComeBackChargeLqInfo=function(msg){
		this._model.updateComeBackChargeLqInfo(msg);
		this.refreshComeBackChargeInfo();
	}

	__proto.updateComeBackShopLqInfo=function(msg){
		this._model.updateComeBackShopLqInfo(msg);
		EventCenter.instance.event("UpdateShopInfo");
	}

	__proto.updateChargePro=function(msg){
		this._model.updateChargePro(msg);
		this.refreshComeBackChargeInfo();
	}

	__proto.updateCourtesyPro=function(msg){
		this._model.updateCourtesyPro(msg);
		this.refreshComeBackCourtesyInfo();
	}

	/*数据刷新*/
	__proto.refreshComeBackCourtesyInfo=function(){
		EventCenter.instance.event("UpdateCourtesyInfo");
		var arr=this.getCourtesyArr();
		this.updateRed(arr,"ComeBackCourtesy","ComeBackCourtesyRed");
	}

	__proto.refreshComeBackChargeInfo=function(){
		EventCenter.instance.event("UpdateChargeInfo");
		var arr=this.getChargeArr();
		this.updateRed(arr,"ComeBackCharge","ComeBackChargeRed");
	}

	//=======红点相关=========
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("ComeBackFrame","ComeBackCourtesy",true,"ComeBackFrameRed");
		this._red.regist("ComeBackFrame","ComeBackCharge",true,"ComeBackFrameRed");
		this._red.regist("ComeBackFrame","ComeBackShop",true,"ComeBackFrameRed");
	}

	__proto.updateRed=function(arr,funId,redType){
		var isShowRed=false;
		var ele;
		var cfg;
		var pro=0;
		var times=0;
		var len=arr.length;
		var data;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(!ele)continue ;
			cfg=ele.getCfgData();
			data=ele.getValue("s_data");
			if(!data)continue ;
			pro=data.pro;
			times=data.times;
			if(pro>=cfg.value&&times==0){
				isShowRed=true;
				break ;
			}
		}
		if(isShowRed){
			this._red.showRedPoint(funId,redType,redType);
			}else{
			this._red.hideRedPoint(funId,redType,redType);
		}
	}

	//======前端接口========
	__proto.getCourtesyArr=function(){
		if(this._model.getCourtesyDc()){
			return this._model.getCourtesyDc().array;
		}
		return [];
	}

	__proto.getChargeArr=function(){
		if(this._model.getChargeDc()){
			return this._model.getChargeDc().array;
		}
		return [];
	}

	__proto.getShopArr=function(){
		if(this._model.getShopDc()){
			return this._model.getShopDc().array;
		}
		return [];
	}

	__proto.getEndTime=function(){
		if(this._endTime-Mgr.curTime.serverTimer<=0){
			EventCenter.instance.event("ComeBackEnd");
			EventCenter.instance.event("ACTIVE_TOGGLE",["ComeBackFrame",true]);
		}
		return this._endTime-Mgr.curTime.serverTimer;
	}

	/**
	*1:可领取
	*2:未达成
	*3:已领取
	**/
	__proto.getStat=function(ele){
		if(!ele)return 0;
		var cfg=ele.getCfgData();
		var info=ele.getValue("s_data");
		if(!info||info.pro<cfg.value)return 2;
		if(info.times>0)return 3;
		return 1;
	}

	return ComeBackMgr;
})()


