//class com.xq.modules.activity.feilongzaitian.FeiLongZaiTianMgr
var FeiLongZaiTianMgr=(function(){
	function FeiLongZaiTianMgr(){
		this.feiLongZaiTianTip=null;
		this.mainShowAniUrl=null;
		this._isShowTip=false;
		this._model=null;
		this._red=null;
		this.floatTween=null;
		this._model=new FeiLongZaiTianModel();
		EventCenter.instance.on("new_function_open",this,this.newOpenFun);
		EventCenter.instance.on("ENTER_SCENE",this,this.checkMapTypeHandler);
		this.registRed();
	}

	__class(FeiLongZaiTianMgr,'com.xq.modules.activity.feilongzaitian.FeiLongZaiTianMgr');
	var __proto=FeiLongZaiTianMgr.prototype;
	/**获取当前应该展示的 配置数据 ele
	*买完 一个 领取 然后 展示下一个
	**/
	__proto.getCurShowEle=function(){
		var arr=this.getCurArr();
		var len=arr.length;
		var ele;
		var stat=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.checkEleStat(ele);
			if(stat<=1)return ele;
		}
		return ele;
	}

	/**根据ele 检测 当前档位 的状态
	*0 未购买
	*1 已购买可领取
	*2 已领取
	**/
	__proto.checkEleStat=function(ele){
		var info=ele.getValue("s_data");
		if(!info)return 0;
		return info.state
	}

	/**检测是否全部领取了 用于判断是都*/
	__proto.checkAllGot=function(){
		var arr=this.getCurArr();
		if(!arr||arr.length<=0)return true;
		var len=arr.length;
		var ele;
		var info;
		var stat=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(stat<=1)return false;
		}
		return true;
	}

	/**获取活动剩余事件*/
	__proto.getEndTime=function(){
		var vo=NewActiveManager.ins.getActiveVerDic(64);
		if(!vo)return 0;
		return vo.endTime;
	}

	/**获取当前活动flag*/
	__proto.getFlag=function(){
		var vo=NewActiveManager.ins.getActiveVerDic(64);
		if(!vo)return 0;
		return vo.flag;
	}

	/**获取活动*/
	__proto.getCurArr=function(){
		var flag=this.getFlag();
		return this._model.getElesByFlag(flag);
	}

	/**检测是否满足秒杀条件 全部没买才可以秒杀*/
	__proto.CheckCanMiaoSha=function(){
		var arr=this.getCurArr();
		var len=arr.length;
		var ele;
		var info;
		for(var i=0;i<len;i++){
			ele=arr[i];
			info=ele.getValue("s_data");
			if(!info||info.state>=1){
				return false;
			}
		}
		return true;
	}

	/**获取默认选中下标*/
	__proto.setDefualtIndex=function(){
		var arr=this.getCurArr();
		var len=arr.length;
		var ele;
		var info;
		var buyIndex=-1;
		var recIndex=-1;
		for(var i=0;i<len;i++){
			ele=arr[i];
			info=ele.getValue("s_data");
			if(!info)continue ;
			if(info.state==1&&recIndex==-1){
				recIndex=i;
				break ;
			}
			if(info.state==0&&buyIndex==-1){
				buyIndex=i;
			}
		}
		if(recIndex!=-1)return recIndex;
		if(buyIndex!=-1)return buyIndex;
		return 0;
	}

	/**用于展示的套装url*/
	__proto.getShowUrl=function(){
		var arr=this.getCurArr();
		if(!arr&&!arr[0])return "";
		var ele=arr[0];
		var cfg=ele.getCfgData();
		var urls=cfg.preani.split(";");
		var sex=NetMgr.ins().roleVO.sex;
		var url=urls[sex];
		if(!url)return "";
		return PathDefine.getUIEffectUrl("uismall/"+url);
	}

	/**同步飞龙在天后端数据*/
	__proto.updateInfo=function(msg){
		this._model.updateInfo(msg);
		this.updateRed();
		EventCenter.instance.event("UpdateInfo");
	}

	/**购买飞龙在天礼包后同步数据*/
	__proto.updateBuyInfo=function(msg){
		this._model.updateBuyInfo(msg);
		this.updateRed();
		EventCenter.instance.event("UpdateInfo");
	}

	/**领取奖励后同步数据*/
	__proto.updateReceiveInfo=function(msg){
		this._model.updateReceiveInfo(msg);
		this.updateRed();
		EventCenter.instance.event("UpdateInfo");
	}

	//===========红点逻辑==============
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("FeiLongZaiTianFrame","feilongzaitian",true,"FeiLongZaiTianFrameRed");
		this._red.regist("CustomTitle","FEILONGZAITIAN_CUSTOMTITLE",true,"FeiLongZaiTianFrameRed");
	}

	/**红点刷新*/
	__proto.updateRed=function(){
		var arr=this.getCurArr();
		var len=arr.length;
		var ele;
		var info;
		var ifOver=true;
		var ifShow=this.ifShowRedPoint();
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(ele){
				info=ele.getValue("s_data");
				if(info.state==1){
					this._red.showRedPoint("feilongzaitian",info.id+"","FeiLongZaiTianRed");
					if(ifShow){
						this._red.showRedPoint("FEILONGZAITIAN_CUSTOMTITLE",info.id+"","FeiLongZaiTianRed");
					}
				}
				else{
					this._red.hideRedPoint("feilongzaitian",info.id+"","FeiLongZaiTianRed");
					if(ifShow){
						this._red.hideRedPoint("FEILONGZAITIAN_CUSTOMTITLE",info.id+"","FeiLongZaiTianRed");
					}
				}
				if(info.state!=2){
					ifOver=false;
				}
			}
		}
		if(ifOver){
			EventCenter.instance.event("ACTIVE_TOGGLE",["feilongzaitian"]);
		}
		Mgr.taoZhuangZhiGouMgr.setIsClose(3,!ifOver);
	}

	//==========================================================
	__proto.checkMapTypeHandler=function(){
		var rolevo=NetMgr.ins().roleVO;
		if(!MapType.isCopy(rolevo.mapType)){
			if(this._isShowTip){
				this._isShowTip=false;
				Laya.timer.once(1000,this,this.openShouChongTip);
			}
		}
	}

	__proto.closeTip=function(){
		if(this.feiLongZaiTianTip){
			this.feiLongZaiTianTip.close();
		}
	}

	__proto.newOpenFun=function(funId){
		if(funId=="feilongzaitian"){
			Mgr.red.specialRedIcon("feilongzaitian",true);
			this.openShouChongTip();
		}
	}

	__proto.regActive=function(){
		var kaiFuLiBaoAct=Mgr.kflbAction;
		NewActiveManager.ins.regActOpenHandler(64,Handler.create(kaiFuLiBaoAct,kaiFuLiBaoAct.sendGetLiBaoInfo,[3],false));
		NewActiveManager.ins.regActEndHandler(64,Handler.create(this,this.hideFeiLongZaiTianIcon,null,false));
	}

	__proto.hideFeiLongZaiTianIcon=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["feilongzaitian"]);
	}

	__proto.openShouChongTip=function(){
		var tarPos;
		var shouChongRender=Game.getInstance().getNewMainView().getCenterRender().getIonRender("feilongzaitian");
		if(shouChongRender && shouChongRender.parent && shouChongRender.visible && Mgr.kaiFuHDMgr.progress > 0){
			var rolevo=NetMgr.ins().roleVO;
			if(!MapType.isCopy(rolevo.mapType)){
				if(!this.feiLongZaiTianTip){
					this.feiLongZaiTianTip=UIMgrR.getIView(com.xq.view.modules.activity.feilongzaitian.IFeiLongZaiTianTip);
				}
				Game.getInstance().mainQiPaoView.addChild(this.feiLongZaiTianTip);
				Game.getInstance().getNewMainView().addViewToHide(this.feiLongZaiTianTip,1);
				this.feiLongZaiTianTip.open();
				tarPos=new Point(shouChongRender.x,shouChongRender.y);
				if(shouChongRender.parent){
					tarPos=(shouChongRender.parent).localToGlobal(tarPos);
					this.feiLongZaiTianTip.x=tarPos.x+shouChongRender.width+5;
					this.feiLongZaiTianTip.y=tarPos.y-15-180;
					this.floatTween=FloatTween.start(this.feiLongZaiTianTip,8,0.05,0);
				}
			}
		}
	}

	/**判断是否显示飞龙在天在其他Frame中的红点*/
	__proto.ifShowRedPoint=function(){
		var isOpen=NewActiveManager.ins.checkIsOpen(64)&& !this.checkAllGot()&&Mgr.guide.isOpen("feilongzaitian");
		var obj=ActiveMgr.ins.getColCfg("feilongzaitian");
		var ifHideIcon=ActiveMgr.ins.ifHideRenderByFlag(obj);
		return isOpen&&ifHideIcon;
	}

	__getset(0,__proto,'isShowTip',null,function(boo){
		this._isShowTip=boo;
	});

	return FeiLongZaiTianMgr;
})()


