var FuLiGuanMgr=(function(){
	function FuLiGuanMgr(){
		/**登录福利*/
		this.denglufuli=null;
		this.dengLuFuLiCfg=null;
		/**当前登录天数*/
		this.dengLuDay=0;
		/**登录福利 奖励状态*/
		this.dengLuState=null;
		/**战力福利*/
		this.zhanlifuli=null;
		this.zhanLiFuLiCfg=null;
		/**目标战力*/
		this.needPower=0;
		/**当前战力福利版本号*/
		this.flag=0;
		/**战力福利 奖励状态*/
		this.zhanLiState=null;
		/**战力福利 是否是最后一轮*/
		this.isFinal=false;
		/**登录福利 红点*/
		this.dengluFuli=false;
		/**战力福利 红点*/
		this.zhanliFuli=false;
		/**当次抽奖奖励id 光效停止位置*/
		this.dangCiId=0;
		/**当次抽奖奖励道具*/
		this.dangCiItem=null;
		this.daoJiShi=5000;
		this.red=null;
		this.denglufuli=CfgManager.getTableCfg("denglufuli");
		this.dengLuFuLiCfg=this.denglufuli.objectDataArray;
		this.zhanlifuli=CfgManager.getTableCfg("zhanlifuli");
		this.zhanLiFuLiCfg=this.zhanlifuli.objectDataArray;
		this.red=Mgr.red;
		this.red.regist("fuliguan",null,true);
		EventCenter.instance.on("FIGHT_CHANGE",this,this.fightRefresh);
	}

	__class(FuLiGuanMgr,'com.xq.modules.activity.fuliguan.FuLiGuanMgr');
	var __proto=FuLiGuanMgr.prototype;
	/**根据flag 获取当前版本数据*/
	__proto.getZhanLiData=function(flag){
		var arr=[];
		var leng=this.zhanLiFuLiCfg.length;
		for (var i=0;i < leng;i++){
			if(this.zhanLiFuLiCfg[i].flag==flag){
				arr.push(this.zhanLiFuLiCfg[i]);
			}
		}
		return arr;
	}

	//------------------------------登录福利--------------------
	__proto.guanLoginInfo=function(denglufuli){
		if(this.dengLuState)this.dengLuState.length=0;
		this.dengLuDay=denglufuli.loginDay;
		this.dengLuState=denglufuli.msg;
		this.denglufuliRed();
	}

	// EventCenter.instance.event(FuLiGuanMgr.DENGLUFULI_INFO);
	__proto.guanLoginReward=function(denglufuliReward){
		if(this.dengLuState){
			this.dengLuState.push(denglufuliReward.msg);
		}
		this.denglufuliRed();
		EventCenter.instance.event("denglufuli_Reward");
	}

	/**是否已领取*/
	__proto.getDengLuState=function(id){
		var leng=this.dengLuState.length;
		for (var i=0;i < leng;i++){
			var msg=this.dengLuState[i];
			if(id==msg.id){
				return true;
			}
		}
		return false;
	}

	//------------------------------战力福利--------------------
	__proto.powerInfo=function(zhanlifuli){
		if(this.zhanLiState)this.zhanLiState.length=0;
		this.needPower=zhanlifuli.needPower;
		this.flag=zhanlifuli.flag;
		this.zhanLiState=zhanlifuli.msg;
		this.isFinal=zhanlifuli.isLastFlag;
		this.zhanlifuliRed();
		EventCenter.instance.event("zhanlifuli_info");
	}

	__proto.powerReward=function(zhanlifuliReward){
		if(this.zhanLiState){
			this.zhanLiState.push(zhanlifuliReward.msg);
		};
		var djArr=this.getZhanLiData(this.flag);
		var len=djArr.length;
		for (var i=0;i < len;i++){
			if(djArr[i].id==zhanlifuliReward.msg.id){
				this.dangCiId=i+1;
				this.dangCiItem=[djArr[i].reward];
				break ;
			}
		}
		EventCenter.instance.event("zhanlifuli_choujiang");
		this.zhanlifuliRed();
	}

	/**是否已领取*/
	__proto.getZhanLiState=function(id){
		var leng=this.zhanLiState.length;
		for (var i=0;i < leng;i++){
			var msg=this.zhanLiState[i];
			if(id==msg.id){
				return true;
			}
		}
		return false;
	}

	__proto.denglufuliRed=function(){
		var leng=this.dengLuFuLiCfg.length;
		for (var i=0;i < leng;i++){
			if(!this.getDengLuState(this.dengLuFuLiCfg[i].id)&& this.dengLuDay >=this.dengLuFuLiCfg[i].days){
				this.dengluFuli=true;
				break ;
				}else{
				this.dengluFuli=false;
			}
		}
		this.fuLiGuanRed();
	}

	__proto.fightRefresh=function(){
		Laya.timer.loop(1000,this,this.changeTime);
	}

	__proto.changeTime=function(){
		this.daoJiShi=this.daoJiShi-1000;
		if(this.daoJiShi <=0){
			this.daoJiShi=5000;
			this.zhanlifuliRed();
			Laya.timer.clear(this,this.changeTime);
		}
	}

	__proto.zhanlifuliRed=function(){
		var roleVO=NetMgr.ins().roleVO;
		if(this.needPower > 0 && roleVO.fightValue >=this.needPower){
			this.zhanliFuli=true;
			}else{
			this.zhanliFuli=false;
		}
		this.fuLiGuanRed();
	}

	/**福利官红点*/
	__proto.fuLiGuanRed=function(){
		if(this.dengluFuli || this.zhanliFuli){
			this.red.showRedPoint("fuliguan","fuliguan","fuliguan");
			}else{
			this.red.hideRedPoint("fuliguan","fuliguan","fuliguan");
		}
		this.closeIcon();
		EventCenter.instance.event("fuliguan_red");
	}

	/**关闭福利官icon*/
	__proto.closeIcon=function(){
		if(this.dengLuFuLiCfg && this.dengLuState){
			if(this.dengLuFuLiCfg.length==this.dengLuState.length && this.needPower==0){
				EventCenter.instance.event("ACTIVE_TOGGLE",["fuliguan"]);
			}
		}
	}

	FuLiGuanMgr.DENGLUFULI_REWARD="denglufuli_Reward";
	FuLiGuanMgr.ZHANLIFULI_INFO="zhanlifuli_info";
	FuLiGuanMgr.ZHANLIFULI_CHOUJIANG="zhanlifuli_choujiang";
	FuLiGuanMgr.FULIGUAN_RED="fuliguan_red";
	return FuLiGuanMgr;
})()


