		var info;
		var ele;
		for(var i=0;i<len;i++){
			info=arr[i];
			ele=this.getTaskData(info.id);
			if(!ele)continue ;
			var state=info.state;
			ele.setValue("H",state);
			ele.sortIndex=state==2?state*100+info.id:info.id;
		}
