var MeiRiXuanShangMgr=(function(){
	function MeiRiXuanShangMgr(){
		/**表-chuanshixunbaoku*/
		this.mrxs=null;
		this.mrxsCfg=null;
		/**倒计时*/
		this.mrlcTime=NaN;
		/**剩余次数*/
		this.remainTimes=0;
		/**最大次数 */
		this.maxTimes=0;
		/**当前悬赏id*/
		this.xsList=null;
		this.red=null;
		this.timeDjs=NaN;
		;
		this.mrxs=CfgManager.getTableCfg("xuanshangrenwu");
		this.mrxsCfg=this.mrxs.objectDataArray;
		this.maxTimes=Mgr.cfgMgr.getValueByType(177);
		this.red=Mgr.red;
		this.red.regist("richang","meiritisheng",true,"ACT_CORNER_UPDATE");
	}

	__class(MeiRiXuanShangMgr,'com.xq.modules.activityLobby.MeiRiXuanShangMgr');
	var __proto=MeiRiXuanShangMgr.prototype;
	/**每日悬赏*/
	__proto.getMrxsData=function(id){
		var len=this.mrxsCfg.length;
		for (var i=0;i < len;i++){
			if(this.mrxsCfg[i].ID==id){
				return this.mrxsCfg[i];
			}
		}
		return null;
	}

	/**获取当前显示数据*/
	__proto.getMuBiaoData=function(){
		if(!this.xsList)return [];
		var data=[];
		var len=this.xsList.length;
		for (var i=0;i < len;i++){
			if(this.xsList[i].isFinish !=2){
				data.push(this.getMrxsData(this.xsList[i].id));
			}
		}
		return data;
	}

	/**获取每日悬赏的当前任务*/
	__proto.getCurTask=function(){
		var ary=this.getMuBiaoData();
		var len=ary.length;
		for (var i=0;i < len;i++){
			var item=ary[i];
			if(this.isMuBiaoState(item.ID)!=2){
				var obj={};
				var tempNum=this.isProgress(item.ID)
				obj.dec=item.name+"("+tempNum+"/"+item.cjValue+")";
				obj.panelId=52002;
				obj.dec2=CodeMgr.ins.getStringByCode(260917);
				obj.state=tempNum >=parseInt(item.cjValue);
				return obj;
			}
		}
		return null;
	}

	/**0未达成，1可领取，2已领取*/
	__proto.isMuBiaoState=function(id){
		var len=this.xsList.length;
		for (var i=0;i < len;i++){
			if(id==this.xsList[i].id){
				return this.xsList[i].isFinish;
			}
		}
		return null;
	}

	/**根据id获取当前进度值*/
	__proto.isProgress=function(id){
		var len=this.xsList.length;
		for (var i=0;i < len;i++){
			if(id==this.xsList[i].id){
				return this.xsList[i].progress;
			}
		}
		return-1;
	}

	__proto.redMrxs=function(){
		var len=this.xsList.length;
		this.red.hideRedPoint("meiritisheng","_reward",RedTypeEnum.MeiRiXuanShangRed);
		for (var i=0;i < len;i++){
			var state=this.isMuBiaoState(this.xsList[i].id);
			if(state==1){
				this.red.showRedPoint("meiritisheng","_reward",RedTypeEnum.MeiRiXuanShangRed);
				break ;
			}
		}
	}

	/**倒计时刷新*/
	__proto.renovateTask=function(){
		if(this.timeDjs >=Mgr.curTime.serverTimer){
			Laya.timer.loop(1000,this,this.djsTime);
			}else{
			Laya.timer.clear(this,this.djsTime);
		}
	}

	__proto.djsTime=function(){
		if(this.timeDjs <=Mgr.curTime.serverTimer){
			Laya.timer.clear(this,this.djsTime);
			Mgr.mrxsMgr.csMrxs();
		}
	}

	MeiRiXuanShangMgr.MEIRIXUANSHANG="meirixuanshang";
	MeiRiXuanShangMgr.MEIRIXUANSHANG_TASK="meirixuanshang_task";
	return MeiRiXuanShangMgr;
})()


