//class com.xq.modules.adActivity.AdActivityMgr
var AdActivityMgr=(function(){
	function AdActivityMgr(){
		this._model=null;
		this._red=null;
		this._model=new AdActivityModel();
		this._red=Mgr.red;
		this.registRed();
	}

	__class(AdActivityMgr,'com.xq.modules.adActivity.AdActivityMgr');
	var __proto=AdActivityMgr.prototype;
	__proto.init=function(){
		if(Configs.isShowAdActive&&Mgr.guide.isOpen("AdActivity")){
			Mgr.adActivityA.sendGetInfo();
		}
	}

	/**获取奖励配置ele数组*/
	__proto.getRewardArr=function(){
		return this._model.getRewardArr();
	}

	__proto.getDataVo=function(){
		return this._model.getDataVo();
	}

	/**我的当前观影值*/
	__proto.getMyValue=function(){
		var vo=this.getDataVo();
		if(!vo)return 0;
		return vo.curValue;
	}

	/**进度条显示*/
	__proto.getProValue=function(){
		var curV=this.getMyValue();
		var rewardArr=this.getRewardArr();
		var len=rewardArr.length;
		var pro=curV;
		var ele;
		var cfg;
		var nextEle;
		var nextCfg;
		for(var i=0;i<len;i++){
			ele=rewardArr[i];
			cfg=ele.getCfgData();
			if(curV<cfg.val){
				return pro?0.2*(i+(pro/(pro+(cfg.val-curV)))):0.2*i;
			}
			pro=curV-cfg.val;
			if(i==len-1&&pro>=0){
				return 1;
			}
		}
		return 0;
	}

	/**调用观看广告*/
	__proto.watchAd=function(){
		BaseSDK.ins.sendWatchAd(Handler.create(this,this.sendWatchOver));
	}

	__proto.sendWatchOver=function(){
		Mgr.adActivityA.sendWatchOneTime();
	}

	/**获取奖励状态
	*0：未达成
	*1：可领取
	*2：已领取
	**/
	__proto.getRewardStat=function(ele){
		if(!ele)return 0;
		var ifGot=ele.getValue("Got");
		if(ifGot)return 2;
		var cfg=ele.getCfgData();
		var needV=cfg.val;
		var constVo=this._model.getDataVo();
		if(!constVo)return 0;
		var curV=constVo.curValue;
		return curV>=needV?1:0;
	}

	/**检测观看次数*/
	__proto.checkWatchTimes=function(){
		var vo=this.getDataVo();
		if(!vo)return false;
		return vo.watchTimes<vo.timeLimit;
	}

	//===========同步后端数据=========
	__proto.updateInfo=function(msg){
		this._model.updateInfo(msg);
		EventCenter.instance.event("UpdateAdActivityInfo");
		this.updateRed();
	}

	/**领取奖励后后刷新数据状态*/
	__proto.updateReward=function(msg){
		this._model.updateReward(msg);
		EventCenter.instance.event("UpdateAdActivityReward");
		this.updateRed();
	}

	//===========红点相关===========
	__proto.registRed=function(){
		this._red.regist("AdActivityFrame","AdActivity",true,"AdActivityFrameRed");
	}

	__proto.updateRed=function(){
		var arr=this.getRewardArr();
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			if(this.getRewardStat(ele)==1){
				this._red.showRedPoint("AdActivity","reward","AdActivityRed");
				return;
			}
		}
		this._red.hideRedPoint("AdActivity","reward","AdActivityRed");
	}

	return AdActivityMgr;
})()


