__proto.onUseItem=function(useItemSC){
	var guid=useItemSC.itemGuid;
	var count=useItemSC.count;
	var itemVO=this.lastUseItemDic[guid];
	if(itemVO){
		Mgr.prompt.optionPrompt(Lang.str(2189)+count+Lang.str(2190)+itemVO.cfgItem.name+Lang.str(2191));
		var showEle=Mgr.item.getUseItemShowEle(itemVO.templateId);
		if(showEle){
			var reward=TextUtil.rewardItemsCountChange(count,showEle.getCfgData().showReward);
			RewardUtil.show(reward);
		}
	}

}


//无调用方法
__proto.showBagItemTip=function(itemVo){
	var templateId=itemVo.templateId;
	var type=templateId.charAt(0);
	if(type=="z"|| type=="s"){
		var equipTi=UIMgrR.openIView(com.xq.view.modules.tip.IEquipTipPanelView,2);
		equipTi.dataSource=itemVo;
	}

	else if(type=="y"){
		var horseTip=UIMgrR.openIView(com.xq.view.modules.tip.IEquipTipPanelView,2);
		horseTip.dataSource=itemVo;
	}

	else{
		var itemTip=UIMgrR.openIView(com.xq.view.modules.tip.ITipPanelView,2);
		itemTip.dataSource=itemVo;
	}

}


/**
*通过id获取物品
**/
__proto.getItems=function(temlateID){
	var result=[];
	var len=this.bagGoodsArr.length;
	for (var i=0;i < len;i++){
		var vo=this.bagGoodsArr[i];
		if(vo && vo.templateId==temlateID){
			result.push(vo);
		}
	}

	return result;
}


/**
*通过物品功能类型 DaoJuBiao中的skill字段获取背包数组
*/
__proto.getItemsBySkill=function(skill){
	if (this.bagGoodsArr==null){
		return null;
	};

	var result=[];
	var len=this.bagGoodsArr.length;
	for (var j=0;j < len;j++){
		var b=this.bagGoodsArr[j];
		if (b==null){
			continue ;
		}
		if (b.templateId.charAt(0)!="d"){
			continue ;
		}
		if (b.cfgItem.skill==skill){
			result.push(b);
		}
	}

	return result;
}


/**
*获得物品，用于道具使用提示检测
**/
__proto.onAddItemsPopTips=function(addItemSC){
	if (!this.bagGoodsArr || !this.bagGuidDic)return;
	var items=addItemSC.items;
	for (var i=0;i < items.length;i++){
		var itemMsg=items[i];
		var templateId=itemMsg.templateId;
		if(templateId.charAt(0)=="d"){
			var config=this.iCfg.getItemByField("id",templateId);
			if(!config)continue ;
			var itemVO=this.createItemVo(itemMsg,true);
			if (config.category==34){
				this.useItemByVo(itemVO);
			}
			if((config.usetip=="1" || config.usetip=="2")&& config.xuni !="1"){
				console.log(itemVO.goodName+":"+itemVO.count);
				this.itemUseAlertList.push(itemVO);
			}
		}
		else{
			var equipVO=this.createEquipVO(itemMsg);
			if(Mgr.yuanShenM.checkIfYuanShenEquip(equipVO)){
				this.laterAddOneYSEquipToTip(equipVO);
			}
			else if(Mgr.zhuoYueZhuangBeiM.checkIfZhuoYueEquip(equipVO)){
				this.laterAddOneZYEquipToTip(equipVO);
			}
			else{
				this.laterAddOneEquipToTip(equipVO);
			}
		}
	}

	Mgr.itemPro.sendGetBagGoodsMsg();
	this.itemChanged();
	this.popUpUseTip();
	EventCenter.instance.event("ITEM_ADD");
}


__proto.laterAddOneYSEquipToTip=function(equipVO){
	var equipType=parseInt(equipVO.cfgItem.type);
	var ysType=YuanShenType.getYSType(equipType);
	var info=Model.yuanShen.getInfoByType(ysType);
	var eqpart=parseInt(equipVO.cfgItem.eqpart);
	if(equipVO.rareLv > 2&&info){
		var curStar=info.getEquipStarBySlot(eqpart);
		var star=parseInt(equipVO.cfgItem.star);
		if(star>curStar){
			this.ysEquipArr.push(equipVO);
		}
	}

}


__proto.laterAddOneZYEquipToTip=function(equipVO){
	var eqpart=parseInt(equipVO.cfgItem.eqpart);
	var ele=Mgr.zhuoYueZhuangBeiM.getSlotEle(eqpart);
	var info=ele.getValue(ZhuoYueZhuangBeiType.Type_ZhuoYueZhuangBei.toString());
	if(!info){
		this.zyEquipArr.push(equipVO);
		}else{
		var equipId=info.templateId;
		var equipCfg=Model.equipCfg.getEquipCfgById(equipId);
		var jie=equipVO.cfgItem.itemlevel
		if(!equipCfg||equipCfg.itemlevel<jie){
			this.zyEquipArr.push(equipVO);
		}
	}

}


__proto.laterAddOneEquipToTip=function(equipVO,isPopUpTip){
	(isPopUpTip===void 0)&& (isPopUpTip=false);
	if(!Mgr.equip.curModel)return;
	var equipArr=Mgr.equip.curModel.wearEquipArr;
	if(equipVO.rareLv > 2 && equipArr.length > 0){
		if(this.equipUseAlertList.length==0){
			this.addOneEquipToTip(equipVO,isPopUpTip);
			}else{
			this.laterEquipArr.push(equipVO);
		}
	}

}


__proto.addOneEquipToTip=function(equipVO,isPopUpTip){
	(isPopUpTip===void 0)&& (isPopUpTip=false);
	var len=this.equipUseAlertList.length;
	var flag=false;
	if(equipVO){
		this.bagGuidDic[equipVO.guid]=equipVO;
		if (equipVO.partPos >=1 && equipVO.partPos <=10){
			var roleId=Mgr.equip.checkEquipCanReplaceRole(equipVO);
			if(roleId!=0 && equipVO.rareLv > 3){
				this.equipUseAlertList.unshift(equipVO);
				flag=true;
			}
		}
		if(isPopUpTip){
			Laya.timer.once(100,this,this.popUpUseTip);
		}
	}

	return flag;
}


__proto.checkBestEquip=function(){
	var screenEquipDic=new Dictionary();
	var betterEquipArr=[];
	if(!this.bagEquipArr)return;
	var len=this.bagEquipArr.length;
	for (var i=0;i < len;i++){
		var equipVO=this.bagEquipArr[i];
		if(!equipVO)break ;
		if(Mgr.yuanShenM.checkIfYuanShenEquip(equipVO))continue ;
		if(Mgr.zhuoYueZhuangBeiM.checkIfZhuoYueEquip(equipVO))continue ;
		var roleId=Mgr.equip.checkEquipCanReplaceRole(equipVO);
		if(equipVO.rareLv > 3){
			if(roleId!=0){
				var curPartEquip=screenEquipDic.get(equipVO.partPos);
				if(curPartEquip){
					if(curPartEquip.totalScore < equipVO.totalScore){
						screenEquipDic.set(equipVO.partPos,equipVO)
					}
					}else{
					screenEquipDic.set(equipVO.partPos,equipVO)
				}
			}
		}
	}

	this.equipUseAlertList=screenEquipDic.values;
	this.popUpUseTip();
}


__proto.popAllItem=function(){
	this.popUpUseTip();
	Laya.timer.once(300,this,this.delayPop);
}


__proto.delayPop=function(){
	var len=this.itemUseAlertList.length;
	for (var i=0;i < len;i++){
		this.popUpUseTip()
	}

}


/**
*弹出使用提示框，从数组上弹出最后面的 装备或物品
*装备优先
**/
__proto.popUpUseTip=function(){
	if(!this.isShowUseTip){
		this.itemUseAlertList=[];
	}

	if(!this.useTip){
		this.useTip=UIMgrR.newInstanceByIClass(com.xq.view.mainUI.subPanel.IGetItemToUseTipView);
		this.useTip.popupCenter=false;
	}

	if(this.useTip.isPopup){
		if(this.lastPopItem && this.itemUseAlertList.length > 0){
			var isUpdate=false;
			for (var i=0;i < this.itemUseAlertList.length;i++){
				var nextBagVo=this.itemUseAlertList[i];
				if(nextBagVo && this.lastPopItem.templateId==nextBagVo.templateId){
					isUpdate=true;
					this.lastPopItem.count+=nextBagVo.count;
					this.itemUseAlertList.splice(i,1);
					i--;
				}
			}
			if(isUpdate)
				this.useTip.setData(this.lastPopItem);
		}
		return;
	}

	this.useTip.pos(Laya.stage.width-220,Laya.stage.height-550);
	if(this.equipUseAlertList.length > 0){
		var equipVo=this.equipUseAlertList.pop();
		while(equipVo){
			if(equipVo.replaceRoleId==0){
				equipVo=this.equipUseAlertList.pop();
				}else if(this.equipTipCdTime >=Mgr.curTime.serverTimer){
				Mgr.equip.wearEquip(equipVo);
				equipVo.replaceRoleId=0;
				}else{
				break ;
			}
		}
		if(this.lastPopEquip && (this.lastPopEquip.templateId==equipVo.templateId)){
			this.popUpUseTip()
			}else{
			if(equipVo){
				this.useTip.setData(equipVo);
				this.useTip.show();
				this.lastPopEquip=equipVo;
				this.lastPopItem=null;
				return;
			}
		}
		}else{
		this.lastPopEquip=null;
	}

	if(this.laterEquipArr.length > 0){
		var hasEquip=false;
		while(this.laterEquipArr.length > 0){
			var evo=this.laterEquipArr.pop();
			hasEquip=this.addOneEquipToTip(evo,true);
			if(hasEquip){
				break ;
			}
		}
		if(hasEquip){
			return;
		}
	}

	if(this.itemUseAlertList.length > 0){
		var vo=this.itemUseAlertList.pop();
		if(vo){
			this.useTip.setData(vo);
			this.useTip.show();
			this.lastPopItem=vo;
		}
		}else{
		this.lastPopItem=null;
	};

	var isRefresh=false;
	for (i=0;i < this.itemUseAlertList.length;i++){
		nextBagVo=this.itemUseAlertList[i];
		if(nextBagVo && this.lastPopItem.templateId==nextBagVo.templateId){
			isRefresh=true;
		}
	}

	if(isRefresh){
		this.popUpUseTip();
	}

	if(this.ysEquipArr.length>0){
		var ysVO=this.ysEquipArr.pop();
		this.useTip.setData(ysVO);
		this.useTip.show();
	}

	if(this.zyEquipArr.length>0){
		var zyVO=this.zyEquipArr.pop();
		this.useTip.setData(zyVO);
		this.useTip.show();
	}

}


/**
*2.0计算背包材料数量,传Id
*checkBind：-1不筛选绑定，0只要非绑定，1只要绑定
*
*/
__proto.getBagMatCount=function(templateId,checkBind){
	(checkBind===void 0)&& (checkBind=-1);
	if (templateId=="")return 0;
	this.serverTime=Mgr.curTime.serverTimer;
	if(this.numChanged || this.serverTime-this.lastItemUpT > 60000){
		this.lastItemUpT=this.serverTime;
		this.numChanged=false;
		this.itemNumDic={};
		this.bindItemNumDic={};
		var len=this.bagGoodsArr.length;
		for (var j=0;j < len;j++){
			var num=0;
			var b=this.bagGoodsArr[j];
			if (b==null){
				continue ;
			}
			if (b.endTime !=0 && b.endTime-this.serverTime < 0){
				continue ;
			};
			var tpID=b.templateId;
			if(tpID.charAt(0)!="d"){
				num=1;
				}else{
				num=b.count;
			};
			var dic=b.bind ? this.bindItemNumDic :this.itemNumDic;
			if(dic[tpID]){
				dic[tpID]+=num;
				}else{
				dic[tpID]=num;
			}
		}
	};

	var config=this.iCfg.getItemByField("id",templateId);
	if(config && config.category==18){
		var minggeList=this.minggeMgr.getBagArr();
		len=minggeList.length;
		var count=0;
		for(var i=0;i < len;i++){
			var info=minggeList[i];
			var cfg=this.minggeMgr.getMGCof(info.templateId);
			if(templateId==cfg.itemid){
				count++;
			}
		}
		return count;
	};

	var bindNum=0;
	var unBindNum=0;
	if(checkBind==-1){
		bindNum=this.bindItemNumDic[templateId] ? this.bindItemNumDic[templateId] :0;
		unBindNum=this.itemNumDic[templateId] ? this.itemNumDic[templateId] :0;
		return bindNum+unBindNum;
		}else if(checkBind==0){
		return this.itemNumDic[templateId] ? this.itemNumDic[templateId] :0;
		}else{
		return this.bindItemNumDic[templateId] ? this.bindItemNumDic[templateId] :0;
	}

}


/**通过道具类型获取到道具*/
__proto.getItemByCatogory=function(category){
	var len=this.bagGoodsArr.length;
	var arr=[];
	for (var j=0;j < len;j++){
		var b=this.bagGoodsArr[j];
		if (b && b.templateId.charAt(0)=="d" && b.cfgItem.category==category){
			arr.push(b);
		}
	}

	return arr;
}


/**传入一个guid 判断此道具或装备是否存在*/
__proto.getItemByGuid=function(guid){
	var len=this.bagGoodsArr.length;
	var arr=[];
	for (var j=0;j < len;j++){
		var b=this.bagGoodsArr[j];
		if (b && b.guid==guid){
			return true;
		}
	}

	return false;
}


/**
*通过id获得一个不过期的物品
*/
__proto.getBagVO=function(templateId,checkBind){
	(checkBind===void 0)&& (checkBind=-1);
	this.serverTime=Mgr.curTime.serverTimer;
	var len=this.bagGoodsArr.length;
	for (var i=0;i < len;i++){
		var b=this.bagGoodsArr[i];
		if (!b)continue ;
		if (b.endTime !=0 && b.endTime-this.serverTime < 0)continue ;
		if (b.templateId==templateId){
			if(templateId.charAt(0)!="d"){
				return b;
			}
			if (checkBind==-1){
				return b;
			}
			else if (checkBind==0 && b.bind==0){
				return b;
			}
			else if (checkBind==1 && b.bind==1){
				return b;
			}
		}
	}

	return null;
}


