/**根据装备星数 转生等级 品质 获取符合条件的数组*/
__proto.getEquipVoByThree=function(starLv,zhuanShengLv,rarelv,equipType){
	(equipType===void 0)&& (equipType=1);
	var equipArr=[];
	if(!this.bagEquipArr)return equipArr;
	var len=this.bagEquipArr.length;
	for (var i=0;i < len;i++){
		var vo=this.bagEquipArr[i];
		if(vo && starLv==parseInt(vo.cfgItem.star)&& zhuanShengLv==vo.cfgItem.itemlevel && rarelv==vo.rareLv && equipType==vo.cfgItem.type){
			equipArr.push(vo);
		}
	}

	return equipArr
}


/**根据装备星数品质 获取符合条件的数组
*============================state为0 代表去除戒指和配饰的所有（对应）品质等级的
*============================state为1 代表所有（对应）品质等级的
*============================state为2 代表所有戒指和配饰所有品质等级的
*============================state为3 代表所有戒指所有品质等级的
*============================state为4 代表所有配饰所有品质等级的
**/
__proto.getEquipVoByTwo=function(starLv,rarelv,state,equipType,jie){
	(state===void 0)&& (state=0);
	(equipType===void 0)&& (equipType=1);
	(jie===void 0)&& (jie=0);
	var equipArr=[];
	var len=this.bagEquipArr.length;
	for (var i=0;i < len;i++){
		var vo=this.bagEquipArr[i];
		if(!vo)continue ;
		switch(state){
			case 0:
				if(vo.type!=200&&(vo.cfgItem.eqpart==7 || vo.cfgItem.eqpart==8))
					continue ;
			case 1:
				if(starLv !=parseInt(vo.cfgItem.star)|| rarelv !=vo.rareLv){
					continue ;
				}
				break ;
			case 2:
				if((vo.cfgItem.eqpart !=7 && vo.cfgItem.eqpart !=8))
					continue ;
				break ;
			case 3:
				if(vo.cfgItem.eqpart !=7)
					continue ;
				break ;
			case 4:
				if(vo.cfgItem.eqpart !=8)
					continue ;
				break ;
			}
		if(vo.type==equipType){
			if(equipType==200){
				if(vo.cfgItem.itemlevel==jie){
					equipArr.push(vo);
				}
			}
			else{
				equipArr.push(vo);
			}
		}
	}

	return equipArr
}


__proto.getEquipVoByMore=function(itemlevelMin,itemlevelMax,rarelvMin,rarelvMax,starLvMin,starLvMax){
	var equipArr=[];
	var len=this.bagEquipArr.length;
	for (var i=0;i < len;i++){
		var vo=this.bagEquipArr[i];
		if(vo){
			if((vo.cfgItem.itemlevel >=itemlevelMin && vo.cfgItem.itemlevel <=itemlevelMax)&& (vo.cfgItem.star >=starLvMin && vo.cfgItem.star <=starLvMax)&& (vo.rareLv >=rarelvMin && vo.rareLv <=rarelvMax)){
				equipArr.push(vo);
			}
		}
	}

	return equipArr
}


/**
*判断需求道具是否足够
*items=道具id:数量 <br/>
*checkBind：-1不筛选绑定，0只要非绑定，1只要绑定
**/
__proto.checkItemIsEnough=function(items,checkBind){
	(checkBind===void 0)&& (checkBind=-1);
	if(!items)return true;
	if((items instanceof Array)){
		var arr=items;
	}

	else if((typeof items=='string')){
		arr=items.split(";");
	};

	var len=arr.length;
	for(var i=0;i< len;i++){
		if(!arr[i] || arr[i]==""){
			continue ;
		};
		var itemArr=arr[i].split(":");
		var itemId=itemArr[0];
		var num=parseInt(itemArr[1]);
		var config=this.iCfg.getItemByField("id",itemId);
		if(!config){
			config=this.eCfg.getItemByField("id",itemId);
			if(!config){
				console.error(Lang.str(2195)+itemId);
				return false;
			}
		}
		if(config.category==18){
			if(!this.minggeMgr.checkMinggeIsEnough(itemId,num)){
				return false;
			}
			}else{
			var totalNum=this.getBagMatCount(itemId,checkBind);
			if(num>totalNum){
				return false;
			}
		}
	}

	return true;
}


/**检测某个背包道具是否满足需求
*用于 单个道具的检测 例如抽奖道具 boss挑战道具等
*id：道具Id needNum:需求数量
**/
__proto.checkSingleItemEnough=function(id,needNum){
	var totalNum=this.getBagMatCount(id);
	return totalNum>=needNum;
}


/**
*判断合成需求装备是否足够
**/
__proto.checkEquipIsEnough=function(compoundInfo){
	var compoundArr=this.getEquipVoByThree(parseInt(compoundInfo.starlv),parseInt(compoundInfo.zhuanshenglv),parseInt(compoundInfo.compound),compoundInfo.equipType);
	if(compoundArr.length >=parseInt(compoundInfo.costNum)&& Mgr.bag.checkItemIsEnough(compoundInfo.xiaohao1)){
		return true;
		}else{
		return false;
	}

}


/**
*判断是否有可分解装备
**/
__proto.checkEquipIsReslove=function(compoundInfo){
	var resloveArr;
	if(compoundInfo.part){
		if(compoundInfo.part=="7"||compoundInfo.part=="8"){
			var ringObj=Mgr.equipCompMgr.getEquipReslove();
			}else{
			var arr=compoundInfo.xiaohao1.split(":");
		};
		var tempArr;
		if(compoundInfo.part==7){
			tempArr=this.getEquipVoByTwo(compoundInfo.starlv,compoundInfo.compound,3);
			}else if(compoundInfo.part==8){
			tempArr=this.getEquipVoByTwo(compoundInfo.starlv,compoundInfo.compound,4);
		}
		if(tempArr){
			resloveArr=[];
			var len=tempArr.length;
			for(var i=0;i< len;i++){
				var e=tempArr[i];
				if(e["partPos"]==7 || e["partPos"]==8){
					if(ringObj && ringObj[e.templateId])
						resloveArr.push(e);
				}
				else if(e.templateId==arr[0]){
					resloveArr.push(e);
				}
			}
		}
		}else{
		resloveArr=this.getEquipVoByTwo(compoundInfo.starlv,compoundInfo.compound,0,compoundInfo.equipType,compoundInfo.zhuanshenglv);
	}

	Mgr.equipCompMgr.equipResloveDic.set(compoundInfo.equipType+"_"+compoundInfo.starlv+"_"+compoundInfo.part+"_"+compoundInfo.compound+"_"+compoundInfo.zhuanshenglv,resloveArr);
	return false;
}


/**
*检测背包格子数是否能存放奖励道具
*@param str 道具字符串<br/>needTip 是否需弹文本提示
**/
__proto.hasEnoughGrids=function(str,needTip){
	(needTip===void 0)&& (needTip=false);
	if(!str)
		return false;
	if((typeof str=='string')){
		var ary=str.split(";");
	}

	else{
		ary=str;
	};

	var num_item=0;
	var num_equip=0;
	var num_gem=0;
	var num_fabao=0;
	var len=ary.length;
	for(var i=0;i<len;i++){
		var itemsArr=ary[i].split(":");
		var id=itemsArr[0];
		var num=parseInt(itemsArr[1]);
		if(!num)num=1;
		if(id.indexOf("dj")!=-1){
			var config=this.iCfg.getItemByField("id",id);
			if(!config)continue ;
			var ownNum=this.getBagMatCount(id);
			if(ownNum<=0 ||config.maxstack<ownNum+num){
				if(config.category==2){
					num_gem++;
					}else if(config.category==33){
					num_fabao++;
					}else{
					num_item++;
				}
			}
		}
		else{
			num_equip++;
		}
	}

	if(!this.checkEnough(1,num_item)){
		if(needTip){
			Mgr.prompt.optionPrompt(Lang.str(2196));
		}
		return false;
	}

	if(!this.checkEnough(4,num_equip)){
		if(needTip){
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(1006));
		}
		return false;
	}

	if(!this.checkEnough(2,num_gem)){
		if(needTip){
			Mgr.prompt.optionPrompt(Lang.str(2197));
		}
		return false;
	}

	if(!this.checkEnough(3,num_fabao)){
		if(needTip){
			Mgr.prompt.optionPrompt(Lang.str(2198));
		}
		return false;
	}

	return true;
}


