	/**添加或者删除玩家功能称号*/
	__proto.updateScenePlayerTitle=function(isAdd){
		if(!this.bossInfos)
			return;
		var currentMonster=null;
		var msg;
		for(var $each_msg in this.bossInfos){
			msg=this.bossInfos[$each_msg];
			if(msg.removeBossTime < Mgr.curTime.serverTimer){
				var player=UnitManager.ins.getPlayerByRoleID(Number(msg.bossId));
				if(player){
					if(isAdd){
						player.scale(2,2);
						player.setFunTitle(132);
					}
					else{
						player.scale(1,1);
						player.setFunTitle(-1);
					}
				}
			}
		}
	}

	__proto.updateScenePlayerTitle2=function(oldList,newList){
		var oldMsg;
		var len2=0;
		var newMsg;
		var i=0;
		var j=0;
		var len=0;
		var player;
		var noDelete=false;
		if(oldList){
			len=oldList.length;
			for (i=0;i < len;i++){
				noDelete=false;
				oldMsg=oldList[i];
				player=UnitManager.ins.getPlayerByRoleID(Number(oldMsg.bossId));
				if(!player)
					continue ;
				if(newList){
					len2=newList.length;
					for(j=0;j < len2;j++){
						newMsg=newList[j];
						if(oldMsg.bossId==newMsg.bossId){
							noDelete=true;
							break ;
						}
					}
				}
				if(noDelete)
					continue ;
				player.scale(1,1);
				player.setFunTitle(-1);
			}
		}
		if(newList){
			len2=newList.length;
			for(j=0;j < len2;j++){
				newMsg=newList[j];
				player=UnitManager.ins.getPlayerByRoleID(Number(newMsg.bossId));
				if(player){
					player.scale(2,2);
					player.setFunTitle(132);
				}
			}
		}
	}

	/**得到最近的一个怪物*/
	__proto.getNearBossInfos=function(){
		if(!this.bossInfos)
			return null;
		var minLen=20000000;
		var currentMonster=null;
		var dx=0,dy=0,squarelen=0;
		var mainAvatar=Model.game.mPlayer;
		var msg;
		for(var $each_msg in this.bossInfos){
			msg=this.bossInfos[$each_msg];
			var pointArr=SceneContainer.GridToGlobal(msg.x,msg.y);
			dx=mainAvatar.x-pointArr[0];
			dy=mainAvatar.y-pointArr[1];
			squarelen=Math.sqrt(dx *dx+dy *dy);
			if(squarelen < minLen){
				currentMonster=msg;
				minLen=squarelen;
			}
		}
		if(currentMonster)
			return currentMonster;
		return this.bossInfos[0];
	}

	__proto.getBossState=function(bossId){
		var msg;
		for(var $each_msg in this.bossInfos){
			msg=this.bossInfos[$each_msg];
			if(msg.bossId==bossId){
				return msg;
			}
		}
		return null;
	}

	/**得到某怪物进度数据*/
	__proto.getBossValueById=function(bossId){
		if(!this.bossValues)
			return null;
		var len=this.bossValues.length;
		var msg;
		for(var i=0;i < len;i++){
			msg=this.bossValues[i];
			if(msg.bossId==bossId){
				return msg;
			}
		}
		return null;
	}

	//------------
	__proto.autoFightBoss=function(){
		if(!this.bossValues)
			return;
		var near=this.getNearBossInfos();
		if(!near)
			return;
		var valueMsg=this.getBossValueById(near.bossId);
		if(valueMsg && valueMsg.targetVal !=0){
			this.onSearch(near);
			return;
		};
		var len=this.bossValues.length;
		var msg;
		for(var i=0;i < len;i++){
			msg=this.bossValues[i];
			if(msg.targetVal !=0 && this.getBossState(msg.bossId)){
				this.onSearch(this.getBossState(msg.bossId));
				return;
			}
		}
	}

	__proto.onSearch=function(bossState){
		AIController.ins().clearAutoChangeForbit();
		AIController.ins().changeForbitAutoCombat(false);
		var pointArr=SceneContainer.GridToGlobal(bossState.x,bossState.y);
		AIController.ins().startAutoPath(NetMgr.ins().roleVO.mapId,pointArr[0],pointArr[1],Handler.create(this,this.moveComplete,[bossState.bossId]));
	}

	__proto.moveComplete=function(bossId){
		AIController.ins().startAutoCombat(bossId);
	}

