/**
*战报 管理类
*@author hh
*@date 2020-9-4
**/
//class com.xq.modules.battleReport.BattleReportMgr
var BattleReportMgr=(function(){
	function BattleReportMgr(){
		this.vo=null;
		/**动作类型字典 不用行为类型 处理方式不一样*/
		this._actionDic=null;
		/**战报数组*/
		this._reportList=null;
		/**一号选手*/
		this._playerA=null;
		/**二号选手*/
		this._playerB=null;
		this._closeHandler=null;
		this._ready=false;
		this.roleVoDic=null;
		this.alertTip=null;
		this.setupActionDic();
		this.roleVoDic={};
	}

	__class(BattleReportMgr,'com.xq.modules.battleReport.BattleReportMgr');
	var __proto=BattleReportMgr.prototype;
	//=============================行动组=======================================
	__proto.setupActionDic=function(){
		this._actionDic={};
		this._actionDic[1]=Handler.create(this,this.doSkill,null,false);
		this._actionDic[2]=Handler.create(this,this.doBuff,null,false);
		this._actionDic[3]=Handler.create(this,this.doCreateRole,null,false);
	}

	__proto.doSkill=function(msg){
		var attackerId=msg.attackerId;
		var attPlayer=UnitManager.ins.getPlayerByRoleID(attackerId);
		if(!attPlayer)return false;
		if(!this._ready||attPlayer.isDead || !attPlayer.curActIsOk || attPlayer.isPermitSkill){
			return false;
		};
		var targetId=msg.targertedId;
		var tarPlayer=UnitManager.ins.getPlayerByRoleID(targetId);
		if(!tarPlayer)return false;
		var skillId=msg.params1;
		var op=SkillManager.ins.getSkillOPBase(skillId,attPlayer,true);
		if(!op)return false;
		attPlayer.attackNormal(op);
		var myHarm=parseInt(msg.params3);
		var targetHarm=parseInt(msg.params2);
		attPlayer.vo.curHp-=myHarm;
		tarPlayer.vo.curHp-=targetHarm;
		var dir=CommonUtil.changeDir(attPlayer.x,attPlayer.y,tarPlayer.x,tarPlayer.y);
		HarmManager.ins.hurt(parseInt(msg.params4),targetHarm,tarPlayer,dir);
		EventCenter.instance.event("UpdatePlayerHp",[msg.targertedId,targetHarm]);
		return true;
	}

	__proto.doBuff=function(msg){
		var targetId=msg.targertedId;
		var tarPlayer=UnitManager.ins.getPlayerByRoleID(targetId);
		if(!tarPlayer)return false;
		if(!this._ready)return false;
		var buffMsg=new BufferMsg();
		buffMsg.attackerId=msg.attackerId;
		var buff=this.createBuff(msg.params2);
		buff.layers=1;
		buff.target=tarPlayer;
		buff.djsTime=200;
		buff.start();
		tarPlayer.updateBuff(buff,false);
		return true;
	}

	__proto.createBuff=function(buffId){
		var buff=new BaseBuffer();
		var cfgObj=BufferManager.ins.getCofById(buffId);
		if(cfgObj){
			buff.bindVo(cfgObj);
		}
		return buff;
	}

	__proto.doCreateRole=function(msg){
		var playerVo=new BattlePlayerVo();
		playerVo.setData(msg);
		var roleVo=this.getRoleVo(playerVo);
		if(playerVo.index==1){
			var gx=16;
			var dir=2;
		}
		else{
			gx=31;
			dir=6;
		};
		var gy=15;
		roleVo.gx=gx;
		roleVo.gy=gy;
		roleVo.faceto=dir;
		var player=UnitManager.ins.createRole(roleVo);
		player.mouseEnabled=false;
		SceneContainer.getInstance().unitLayer.addChild(player);
		var name=roleVo.name;
		var subPlayer;
		var arr=playerVo.subList;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var data=arr[i];
			if(dir==2){
				subPlayer=this.createdSubPlayer(data,gx-2,gy-1+i,dir,name);
			}
			else{
				subPlayer=this.createdSubPlayer(data,gx+2,gy-1+i,dir,name);
			}
			subPlayer.mouseEnabled=false;
			player.addSubplayer(subPlayer);
		}
		if(playerVo.index==1){
			this._playerA=player;
		}
		else{
			this._playerB=player;
		}
		return true;
	}

	//=================================================================
	__proto.updateVo=function(msg){
		if(!this.vo){
			this.vo=new BattleReportVo();
		}
		this.vo.setData(msg);
	}

	/**启动*/
	__proto.start=function(){
		this.showTips();
		var arr=SceneContainer.GridToGlobal(24,15);
		SceneContainer.getInstance().mapCamera.lookAt(null);
		SceneContainer.getInstance().mapCamera.lookAtPos(arr[0],arr[1]);
		EventCenter.instance.event("MainViewTopInfoStat",false);
		this.showOrHideMainPlayer(false);
		Laya.timer.once(2000,this,this.moveToTarget,[24,15]);
		this._ready=false;
		Laya.timer.once(3000,this,this.getReady);
		this._reportList=this.vo.reportList.concat();
		this.startReport();
	}

	__proto.getReady=function(){
		this._ready=true;
	}

	/**结束*/
	__proto.end=function(){
		this.closeTips();
		EventCenter.instance.event("MainViewTopInfoStat",true);
		this.showOrHideMainPlayer(true);
		this.endReport();
	}

	/**隐藏主角色*/
	__proto.showOrHideMainPlayer=function(stat){
		var mainPlayer=Game.getInstance().player;
		if(mainPlayer&&mainPlayer.visible!=stat){
			mainPlayer.visible=stat;
		}
	}

	/**创建所有角色包括子角色*/
	__proto.createdSubPlayer=function(data,gx,gy,dir,name){
		var subRoleVo=this.getSubRoleVo(data);
		subRoleVo.faceto=dir;
		subRoleVo.gx=gx;
		subRoleVo.gy=gy;
		subRoleVo.name=name+"["+subRoleVo["cofName"]+"]";
		var subPlayer=UnitManager.ins.createRole(subRoleVo);
		SceneContainer.getInstance().unitLayer.addChild(subPlayer);
		return subPlayer;
	}

	__proto.getRoleVo=function(vo){
		var id=vo.roleId;
		var roleVo=this.roleVoDic[id];
		if(roleVo){
			return roleVo;
		}
		roleVo=new RoleVO();
		roleVo.guid=vo.roleId;
		roleVo.name=vo.name;
		roleVo.hasZuoqi=false;
		roleVo.isRide=0;
		roleVo.sex=vo.sex;
		roleVo.job=vo.sex?"C":"A";
		roleVo.curHp=roleVo.maxHp=vo.maxHp?10000:vo.maxHp;
		roleVo.zuoQiHuanHuaId=vo.zhanqiId;
		roleVo.zuoqiPeiDaiId=0;
		roleVo.wingHuanHuaId=vo.zhanyiId;
		roleVo.wingLevel=1;
		roleVo.wuQiHuanHuaId=vo.zhanwuId;
		roleVo.shenBingPeiDaiId=0;
		roleVo.roleHuanHuaId=vo.shizhuangId;
		var tempObJ=Model.shenjiang.getCfgByJob(roleVo.job);
		roleVo.res=tempObJ.res;
		roleVo.moveSpeed=360;
		this.roleVoDic[id]=roleVo;
		return roleVo;
	}

	__proto.getSubRoleVo=function(vo){
		var id=vo.subRoleId;
		var roleVo=this.roleVoDic[id];
		if(roleVo){
			return roleVo;
		}
		roleVo=new RoleVO();
		roleVo.guid=id;
		roleVo.shenBingPeiDaiId=-1;
		roleVo.zhenFaId=vo.fazhenId;
		var type=vo.jinjieId;
		roleVo.shenJiangType=type;
		if(type > Mgr.heroSysMgr.heroModel.minGap){
			cfg=Mgr.szMgr.getCfgById(type+"");
			roleVo.res=[cfg.res];
		}
		else{
			var cfg=Mgr.heroSysMgr.getSjCfg(type);
			roleVo.res=cfg.res;
		}
		roleVo.moveSpeed=360;
		roleVo["cofName"]=cfg.name;
		this.roleVoDic[id]=roleVo;
		return roleVo;
	}

	/**移动到指定格子*/
	__proto.moveToTarget=function(gx,gy){
		var arr=SceneContainer.GridToGlobal(gx,gy)
		var targetX=arr[0];
		var targetY=arr[1];
		var path=SceneContainer.findPath(this._playerA.x,this._playerA.y,targetX-64,targetY);
		this._playerA.move(path);
		path=SceneContainer.findPath(this._playerB.x,this._playerB.y,targetX+64,targetY);
		this._playerB.move(path);
		var subArr=this._playerA.subPlayer;
		var len=subArr.length;
		for(var i=0;i<len;i++){
			var subPlayer=subArr[i];
			path=SceneContainer.findPath(subPlayer.x,subPlayer.y,targetX-48,targetY);
			subPlayer.move(path);
		}
		subArr=this._playerB.subPlayer;
		len=subArr.length;
		for(i=0;i<len;i++){
			subPlayer=subArr[i];
			path=SceneContainer.findPath(subPlayer.x,subPlayer.y,targetX+16,targetY);
			subPlayer.move(path);
		}
	}

	/**开始播报*/
	__proto.startReport=function(){
		console.log(Lang.str(2200));
		Laya.timer.loop(200,this,this.report);
		this.report();
	}

	__proto.report=function(){
		var arr=this._reportList;
		if(arr.length>0){
			var Report=arr[0];
			var handler=this._actionDic[Report.type];
			if(handler){
				var ifSuccess=handler.runWith(Report);
			}
			if(ifSuccess){
				Report=arr.shift();
				if(Report.type==2){
					this.report();
				}
			}
		}
		else{
			this.endReport();
			this.showTip();
		}
	}

	__proto.endReport=function(){
		Laya.timer.clear(this,this.report);
	}

	__proto.showTips=function(){
		var v=UIMgrR.openIView(com.xq.view.modules.battlereport.IBattleReportView,2);
		v.pos(0,0);
	}

	__proto.closeTips=function(){
		UIMgrR.closeIView(com.xq.view.modules.battlereport.IBattleReportView);
	}

	/**队伍已满提示框*/
	__proto.showTip=function(){
		if(this.alertTip && this.alertTip.isPopup){
			this.alertTip.close();
			this.alertTip=null;
			return
		};
		var str=this.vo.winName+Lang.str(2206)+this.vo.loseName+Lang.str(2207);
		this.alertTip=AlertUtil.ShowAlert(str,Handler.create(this,this.quit,null,false),Handler.create(this,this.quit,null,false));
	}

	__proto.quit=function(){
		if(this._closeHandler){
			this._closeHandler.run();
		}
	}

	__getset(0,__proto,'closeHandler',null,function(han){
		this._closeHandler=han;
	});

	__getset(1,BattleReportMgr,'ins',function(){
		return BattleReportMgr._ins=BattleReportMgr._ins||new BattleReportMgr();
	});

	BattleReportMgr._ins=null;
	return BattleReportMgr;
})()


