		ActManager.ins.regist("BianCeXingDong","BianCeRank",95,"BianCeEvent");
		ActManager.ins.regist("BianCeXingDong","BianCeFanLi",103,"BianCeEvent");
		ActManager.ins.regist("BianCeXingDong","BianCeLiBao",102,"BianCeEvent");
		ActManager.ins.regist("BianCeXingDong","BianCeLianChong",104,"BianCeEvent");
