//class com.xq.modules.bianCeXingDong.QuanMinTiaoZhanMgr
var QuanMinTiaoZhanMgr=(function(){
	function QuanMinTiaoZhanMgr(){
		/**活动倒计时*/
		this.endTime=NaN;
		/**全民挑战榜**/
		this.quanMinBangCfg=null;
		/**后端排行数据*/
		this.rankInfoSc=null;
		this.rankData=null;
		/**昨日排行榜数据**/
		this.zuoRiRankData=null;
		/**预告下一个榜单*/
		this.nextRank=null;
		/**活动版本号*/
		this.flag=0;
		/**1：关卡榜 2：奇珍阁榜 3：铜人阵榜 4：符文塔榜
		5：练功房 6：铜雀台 7：侠客岛榜*/
		this.rankType=0;
		this.strTitleName=null;
		// }
		this.rankEndTime=NaN;
		this.strName=Lang.str(2208);
		this.quanMinBangCfg=CfgManager.getTableCfg("quanmintiaozhan");
		EventCenter.instance.on("new_function_open",this,this.newOpenFun);
	}

	__class(QuanMinTiaoZhanMgr,'com.xq.modules.bianCeXingDong.QuanMinTiaoZhanMgr');
	var __proto=QuanMinTiaoZhanMgr.prototype;
	__proto.regActive=function(){
		var bcRankHand=Handler.create(Mgr.rankingPro,Mgr.rankingPro.c_getRank,[186],false);
		NewActiveManager.ins.regActOpenHandler(186,bcRankHand);
	}

	/**全民挑战榜Cfg**/
	__proto.getBianCeBangData=function(flag,type){
		return this.quanMinBangCfg.getCfgMsgArrByTwoKey("flag",flag,"type",type);
	}

	/**全民挑战榜Cfg**/
	__proto.getCfgbyType=function(type){
		return this.quanMinBangCfg.getItemsByField("type",type);
	}

	/**全民挑战CFG*/
	__proto.getCfgByFlag=function(flag){
		return this.quanMinBangCfg.getItemsByField("flag",flag);
	}

	__proto.getTodayCfg=function(){
		return this.getBianCeBangData(this.flag,this.rankType);
	}

	__proto.getRankCfg=function(isZuoRi){
		(isZuoRi===void 0)&& (isZuoRi=false);
		var nexobj=this.getCfgbyType(this.rankType)[0];
		if(nexobj){
			this.nextRank=nexobj.nametitle;
		};
		var ary=this.getBianCeBangData(this.flag,this.rankType);
		var rankArr=[];
		var len=ary.length;
		for (var i=0;i < len;i++){
			var aryObj=ary[i];
			var a=aryObj.rank.split("|");
			var min=parseInt(a[0]);
			var max=parseInt(a[1]);
			var leng=1;
			var qujian=max-min;
			if(qujian > leng){
				leng=qujian+1;
			}
			for (var j=0;j < leng;j++){
				var rankMsg;
				if(isZuoRi){
					rankMsg=this.getZuoRiRankData(min+j);
					}else{
					rankMsg=this.getRankData(min+j);
				};
				var obj={};
				obj["reward"]=aryObj.reward;
				obj["rank"]=min+j;
				if(rankMsg){
					obj["score"]=rankMsg.score;
					obj["name"]=rankMsg.name;
					}else{
					obj["limit"]=aryObj.limit;
					obj["name"]=Lang.str(2142);
					obj["score"]=0;
				}
				obj["cfgData"]=aryObj;
				rankArr.push(obj);
			}
		}
		return rankArr;
	}

	__proto.getRankName=function(type){
		var cfgObj=this.getCfgbyType(type)[0];
		if(cfgObj){
			this.strTitleName=cfgObj.title;
		}
		else{
			this.strTitleName=Lang.str(2209);
		}
	}

	//-----------------------全民挑战榜----------------------
	__proto.getRankDataSc=function(vo){
		this.flag=vo.flag;
		this.rankType=vo.subType;
		this.rankEndTime=vo.endTime;
		this.rankInfoSc=vo;
		this.rankData={};
		var len=vo.list.length;
		for (var i=0;i < len;i++){
			var rankMsg=vo.list[i];
			this.rankData[rankMsg.rank]=rankMsg;
		}
		EventCenter.instance.event("tiaozhangrank_icon");
		EventCenter.instance.event("tiaozhangrank_info");
		this.checkShowGuideTip();
	}

	__proto.newOpenFun=function(funId){
		if(funId=="quanminchongbang"){
			this.checkShowGuideTip();
		}
	}

	__proto.checkShowGuideTip=function(){
		if(Configs.isForbitIOSPay||Configs.isForbitAndroidPay)return;
		if(!Mgr.guide.isOpen("quanminchongbang"))return;
		if(!NewActiveManager.ins.checkIsOpen(23))return;
		var vo=this.getActivityRankVo();
		ActivityRankMgr.ins.showMainTip(vo);
	}

	__proto.getActivityRankVo=function(){
		var vo=ActivityRankMgr.ins.getVo(186);
		vo.activeId=186;
		var rankCfg=this.getRankCfg();
		var rankData=rankCfg[0];
		if(rankData){
			var cfg=rankData.cfgData;
			vo.rankType=cfg.type
			vo.championName=rankData.name;
			if(cfg.res){
				var resArr=cfg.res.split(";");
				if(resArr.length > 1&&NetMgr.ins().roleVO.job=="C"){
					vo.aniUrl=PathDefine.getUiSmall(resArr[1]);
					}else{
					vo.aniUrl=PathDefine.getUiSmall(resArr[0]);
				}
			}
		}
		return vo;
	}

	__proto.getZuoRiRankDataSc=function(vo){
		this.zuoRiRankData={};
		var len=vo.list.length;
		for (var i=0;i < len;i++){
			var rankMsg=vo.list[i];
			this.zuoRiRankData[rankMsg.rank]=rankMsg;
		};
		var obj={};
		this.getRankName(vo.yesterDayFlag);
		obj["activitId"]=vo.type;
		obj["rankList"]=this.getRankCfg(true);
		obj["rankName"]=this.strTitleName;
		obj["strName"]=this.strName;
		obj["myRank"]=vo.rank;
		obj["myStar"]=vo.todayScore;
		EventCenter.instance.event("tiaozhangrank_zuoriup",obj);
	}

	/**昨日排行榜数据*/
	__proto.getZuoRiRankData=function(rank){
		return this.zuoRiRankData[rank]
	}

	__proto.getRankData=function(rank){
		return this.rankData[rank]
	}

	QuanMinTiaoZhanMgr.TIAOZHANGRANK_ICON="tiaozhangrank_icon";
	QuanMinTiaoZhanMgr.TIAOZHANGRANK_INFO="tiaozhangrank_info";
	QuanMinTiaoZhanMgr.TIAOZHANGRANK_ZUORIUP="tiaozhangrank_zuoriup";
	return QuanMinTiaoZhanMgr;
})()


