//class com.xq.modules.bingfa.BingFaMgr
var BingFaMgr=(function(){
	function BingFaMgr(){
		this.bingfaCfg=null;
		this.bingfaJinXiuCfg=null;
		this.bingfafuhunCfg=null;
		/**当前培养/进修择中的兵法的类型*/
		this.bingfaUi1to2=0;
		this.bingfaUi2to1=0;
		//---------------------------------
		this._bingFaCfgs=null;
		this.bingFaInfoDic=new Dictionary();
		this.setup();
	}

	__class(BingFaMgr,'com.xq.modules.bingfa.BingFaMgr');
	var __proto=BingFaMgr.prototype;
	__proto.setup=function(){
		this.bingfaCfg=CfgManager.getTableCfg("bingfa");
		this.bingfaJinXiuCfg=CfgManager.getTableCfg("bingfajinxiu");
		this.bingfafuhunCfg=CfgManager.getTableCfg("bingfafuhun");
		Mgr.red.regist("jiNeng","bingfa",true,RedTypeEnum.SkillHall);
		Mgr.red.regist("bingfa","bingfaTab",false,RedTypeEnum.JiNeng);
		Mgr.red.regist("bingfa","jinxiuTab",false,RedTypeEnum.JiNeng);
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.onBagChange);
		Mgr.bingFaMAct.sendGetBingFaInfo(1);
	}

	__proto.onBagChange=function(){
		this.checkRed();
	}

	__proto.checkRed=function(){
		var list=this.firstLevelBingFaCfgs;
		var len=list.length;
		var firstCfg;
		var boo=false;
		var majorDic=new Dictionary();
		for (var i=0;i < len;i++){
			firstCfg=list[i];
			var boo2=this.checkSelf(firstCfg.type);
			var boo1=this.checkJinXiu(firstCfg.type);
			var boo3=this.checkFuHun(firstCfg.type);
			if((boo1 || boo2 || boo3)){
				if(!boo){
					boo=true;
				}
			}
			this.markDic(majorDic,"bingfaTab",boo2);
			this.markDic(majorDic,"jinxiuTab",boo1);
			this.markDic(majorDic,"fuHunTab",boo3);
		};
		var keys=majorDic.keys;
		len=keys.length;
		var key;
		for(var j=0;j < len;j++){
			key=keys[j];
			if(majorDic.get(key)){
				Mgr.red.showRedPoint("bingfainfo",key,RedTypeEnum.BingFaEvent);
			}
			else{
				Mgr.red.hideRedPoint("bingfainfo",key,RedTypeEnum.BingFaEvent);
			}
		}
		if(boo){
			Mgr.red.showRedPoint("bingfa",RedTypeEnum.BingFaKey,RedTypeEnum.SkillHall);
		}
		else{
			Mgr.red.hideRedPoint("bingfa",RedTypeEnum.BingFaKey,RedTypeEnum.SkillHall);
		}
	}

	// Mgr.red.hideRedPoint(FunctionDefine.BING_FA_TAB,RedTypeEnum.BingFaTabKey,RedTypeEnum.JiNeng );
	__proto.markDic=function(majorDic,key,boo){
		if(boo){
			majorDic.set(key,true);
		}
		else{
			if(majorDic.indexOf(key)==-1)
				majorDic.set(key,false);
		}
	}

	__proto.checkFuHun=function(subtype){
		return false;
	}

	__proto.checkJinXiu=function(subtype){
		if(!this.isActive(subtype)){
			Mgr.red.hideRedPoint("jinxiuTab",RedTypeEnum.BingFaJinXiuKey+subtype,RedTypeEnum.BingFaEvent);
			return false;
		};
		var curCfg=this.getJinXiuCfg(subtype);
		if(!curCfg){
			Mgr.red.hideRedPoint("jinxiuTab",RedTypeEnum.BingFaJinXiuKey+subtype,RedTypeEnum.BingFaEvent);
			return false;
		}
		if(curCfg.shangxian <=this.getJinXiuLevel(subtype)){
			Mgr.red.hideRedPoint("jinxiuTab",RedTypeEnum.BingFaJinXiuKey+subtype,RedTypeEnum.BingFaEvent);
			return false;
		}
		if(this.isCanUpgrade(curCfg.count)){
			Mgr.red.showRedPoint("jinxiuTab",RedTypeEnum.BingFaJinXiuKey+subtype,RedTypeEnum.BingFaEvent);
			return true;
		}
		Mgr.red.hideRedPoint("jinxiuTab",RedTypeEnum.BingFaJinXiuKey+subtype,RedTypeEnum.BingFaEvent);
		return false;
	}

	__proto.checkSelf=function(subtype){
		var level=this.getLevel(subtype);
		var curCfg;
		if(level <=0){
			curCfg=this.getJinXiuCfg(subtype);
			if(!curCfg){
				Mgr.red.hideRedPoint("bingfaTab",RedTypeEnum.BingFaPingKey+subtype,RedTypeEnum.BingFaEvent);
				return false;
			}
			if(this.isCanUpgrade(curCfg.count)){
				Mgr.red.showRedPoint("bingfaTab",RedTypeEnum.BingFaPingKey+curCfg.type,RedTypeEnum.BingFaEvent);
				return true;
			}
			Mgr.red.hideRedPoint("bingfaTab",RedTypeEnum.BingFaPingKey+curCfg.type,RedTypeEnum.BingFaEvent);
			return false;
		}
		curCfg=this.getCfg(subtype,level);
		if(curCfg.whether==0){
			Mgr.red.hideRedPoint("bingfaTab",RedTypeEnum.BingFaPingKey+curCfg.type,RedTypeEnum.BingFaEvent);
			return false;
		}
		if(this.isCanUpgrade(curCfg.needitem)){
			Mgr.red.showRedPoint("bingfaTab",RedTypeEnum.BingFaPingKey+curCfg.type,RedTypeEnum.BingFaEvent);
			return true;
		}
		Mgr.red.hideRedPoint("bingfaTab",RedTypeEnum.BingFaPingKey+curCfg.type,RedTypeEnum.BingFaEvent);
		return false;
	}

	/**
	*培养数据
	*@param type
	*@param level
	*@return
	*
	*/
	__proto.getCfg=function(type,level){
		return this.bingfaCfg.getCfgMsgByTwoKey("type",type,"level",level);
	}

	/**
	*进修数据——激活用的是这个数据
	*@param type
	*@return
	*
	*/
	__proto.getJinXiuCfg=function(type){
		return this.bingfaJinXiuCfg.getItemByField("type",type);
	}

	//--------------------
	__proto.isCanUpgrade=function(cost,isHint,isActive){
		(isHint===void 0)&& (isHint=false);
		(isActive===void 0)&& (isActive=false);
		if(!cost)
			return true;
		var ary=cost.split(":");
		if(ary.length < 2)
			return true;
		var num=Mgr.bag.getBagMatCount(ary[0]);
		var isE=num >=ary[1];
		if(!isE){
			if(isHint){
				if(isActive)
					Mgr.prompt.optionPrompt(Lang.str(2210));
				else
				Mgr.prompt.optionPrompt(Lang.str(2211));
			}
			return false;
		}
		return true;
	}

	__proto.hasActive=function(type){
		var dic=this.getBingFaDic(type);
		if(dic)
			return dic.values.length > 0;
		return false;
	}

	__proto.isActive=function(subType){
		return this.getBingFaMsg(1,subType);
	}

	__proto.getLevel=function(subType){
		var msg=this.getBingFaMsg(1,subType);
		if(msg)
			return msg.peiYangLevel;
		return 0;
	}

	__proto.getJinXiuLevel=function(subType){
		var msg=this.getBingFaMsg(1,subType);
		if(msg)
			return msg.jinXiuLevel;
		return 0;
	}

	/**
	*某大类所有数据（兵法只是其中一种）
	*@param type
	*@return
	*
	*/
	__proto.getBingFaDic=function(type){
		return this.bingFaInfoDic.get(type);
	}

	/**
	*某大类中某个具体的数据
	*@param type
	*@return
	*
	*/
	__proto.getBingFaMsg=function(type,subType){
		var dic=this.getBingFaDic(type);
		if(dic)
			return dic.get(subType);
		return null;
	}

	/**
	*设置某个数据
	*@param type
	*@param bingFaMsg
	*
	*/
	__proto.setBingFaData=function(type,bingFaMsg){
		var dic=this.getBingFaDic(type);
		if(!dic){
			dic=new Dictionary();
			this.bingFaInfoDic.set(type,dic);
		}
		dic.set(bingFaMsg.subType,bingFaMsg);
	}

	/**
	*拉取兵法数据信息
	*@param msg
	*
	*/
	__proto.onGetBingFaInfoSC=function(msg){
		var dic=this.getBingFaDic(msg.type);
		if(!dic){
			dic=new Dictionary();
			this.bingFaInfoDic.set(msg.type,dic);
		}
		dic.clear();
		var len=msg.dataInfos.length;
		var bingFaMsg;
		for(var i=0;i < len;i++){
			bingFaMsg=msg.dataInfos[i];
			dic.set(bingFaMsg.subType,bingFaMsg);
		}
		this.checkRed();
	}

	/**
	*激活或是升级操作
	*@param type
	*@param subType
	*@param operateType
	*
	*/
	__proto.sendUpgradeBingFaCS=function(type,subType,operateType){
		var curTemplateId;
		if(type==1){
			switch(operateType){
				case 1:
					curTemplateId=this.getCfg(subType,this.getLevel(subType)).needitem;
					break ;
				case 2:
					curTemplateId=this.getJinXiuCfg(subType).count;
					break ;
				}
			if(curTemplateId && !this.isCanUpgrade(curTemplateId)){
				var tip=UIMgrR.openIView(com.xq.view.modules.common.IDaoJuPath,2);
				tip.setData(curTemplateId.split(":")[0]);
				return;
			}
		}
		Mgr.bingFaMAct.sendUpgradeBingFaCS(type,subType,operateType);
	}

	__proto.onUpgradeBingfaSC=function(msg){
		this.setBingFaData(msg.type,msg.dataInfo);
		this.checkRed();
		if(msg.type==1){
			switch(msg.operateType){
				case 1:
					EventCenter.instance.event("PEI_YANG");
					break ;
				case 2:
					EventCenter.instance.event("JIN_XIU");
					if(msg.dataInfo.jinXiuLevel==1){
						this.openJiHuoTip(msg.dataInfo.subType);
					}
					break ;
				}
		}
	}

	__proto.openJiHuoTip=function(type){
		var activeView=UIMgrR.openIView(com.xq.view.modules.bingfa.IBingFaJinJiHuoView,2);
		activeView.dataSource=type;
	}

	__getset(0,__proto,'firstLevelBingFaCfgs',function(){
		if(!this._bingFaCfgs){
			this._bingFaCfgs=[];
			var alls=this.bingfaCfg.objectDataArray;
			var len=alls.length;
			if(len <=0)
				return null;
			var cfgObj;
			for(var i=0;i < len;i++){
				cfgObj=alls[i];
				if(cfgObj.level==1){
					this._bingFaCfgs.push(cfgObj);
				}
			}
		}
		return this._bingFaCfgs;
	});

	__getset(1,BingFaMgr,'ins',function(){
		return BingFaMgr._ins=BingFaMgr._ins||new BingFaMgr();
	});

	BingFaMgr._ins=null;
	return BingFaMgr;
})()


