//class com.xq.modules.bossHall.shendianBoss.model.ShenDianBossMgr
var ShenDianBossMgr=(function(){
	function ShenDianBossMgr(){
		/**是否勾选自动*/
		this.ifAuto=false;
		/**当前体力*/
		this.curTl=0;
		/**今日已使用免费次数*/
		this.useFreeTimes=0;
		/**当前挑战的层数*/
		this.selectFloor=0;
		/**选择挑战的boss*/
		this.selectBoss=null;
		/**是否有体力不足无法领取的奖励*/
		this.ifHaveTempReward=false;
		/**层数表*/
		this._floorCof=null;
		/**boss表*/
		this._bossCof=null;
		/**神殿boss常量表*/
		this._constCof=null;
		/**层数dataContainer*/
		this._floorDc=null;
		/**bossdataContainer*/
		this._bossDc=null;
		/**体力上限*/
		this._tlMax=0;
		/**体力丹Id*/
		this._tldId=null;
		this._ownerDic=null;
		/**神殿boss伤害排行数组*/
		this._rankArr=null;
		/**奖励数组*/
		this._rewardArr=null;
		/**体力不足临时奖励数组*/
		this._tempArr=null;
		this.selectZsLv=0;
		this.alertTip=null;
		this._bossCof=CfgManager.getTableCfg("shendianboss");
		this._floorCof=CfgManager.getTableCfg("shendianfloor");
		this._constCof=CfgManager.getTableCfg("shendianconfig");
		this._ownerDic={};
		this._rankArr=[];
		this._rewardArr=[];
		this._tempArr=[];
		this.registCopyTip();
	}

	__class(ShenDianBossMgr,'com.xq.modules.bossHall.shendianBoss.model.ShenDianBossMgr');
	var __proto=ShenDianBossMgr.prototype;
	__proto.getTlLimit=function(){
		var max=this.tlMax;
		if(Mgr.teQuanKa.checkActive(4)){
			var obj=Mgr.tequanMgr.getTeQuanById(41);
			var per=obj?parseInt(obj.zhujueguanghuan):0;
			max=(100+per)/100*max;
		}
		return max;
	}

	/**根据转生等级获取默认层数下标*/
	__proto.getDefaultFloorIndex=function(){
		var zsLv=NetMgr.ins().roleVO.zhuanshengLevel;
		var arr=this.floorDc.array;
		var len=arr.length;
		var ele;
		var cof;
		for(var i=0;i<len;i++){
			ele=arr[i];
			cof=ele.getCfgData();
			if(cof.zslevel==zsLv){
				return i;
			}
		}
		return 0;
	}

	/**根据层数获取boss数据*/
	__proto.getBossArrByFloor=function(floor){
		var dc=this.bossDc.where("floor",floor,"number");
		if(dc){
			return dc.array;
		}
		return null;
	}

	/**刷新boss信息*/
	__proto.updateBossInfo=function(msg){
		var floor=msg.floor;
		var arr=msg.infos;
		var len=arr.length;
		var info;
		for(var i=0;i<len;i++){
			info=arr[i];
			var ele=this.bossDc.getElement(info.number);
			if(ele){
				ele.setValue("refreshTime",info.refreshTime);
			}
		}
	}

	/**场景中刷新boss状态*/
	__proto.updateBossStat=function(msg){
		var number=msg.info.number;
		var ele=this.bossDc.getElement(number);
		if(ele){
			ele.setValue("refreshTime",msg.info.refreshTime);
		}
	}

	__proto.onEnterSDBoss=function(){
		EventCenter.instance.once("ENTER_SCENE",this,this.onEnter);
		EventCenter.instance.event("BossHall_Close");
		EventCenter.instance.on("BOSS_OWER_CHANGE",this,this.setOwner);
	}

	__proto.onQuitSDBoss=function(){
		EventCenter.instance.off("BOSS_OWER_CHANGE",this,this.setOwner);
	}

	/**进入场景*/
	__proto.onEnter=function(){
		AIController.ins().stopAutoCombat();
		Laya.timer.once(1000,this,this.findTarget);
	}

	__proto.findTarget=function(){
		if(!this.selectBoss)return;
		if(this.selectBoss.getValue("refreshTime")>Mgr.curTime.serverTimer)return;
		var posArr=this.selectBoss.getCfgData().pointNew.split(":");
		var pointArr=SceneContainer.GridToGlobal(parseInt(posArr[0]),parseInt(posArr[1]));
		AIController.ins().startAutoPath(NetMgr.ins().roleVO.mapId,pointArr[0],pointArr[1],Handler.create(this,this.moveComplete));
	}

	__proto.moveComplete=function(){
		AIController.ins().startAutoCombat();
	}

	__proto.setOwner=function(monsterId){
		var v=UIMgrR.getIView(com.xq.view.mainUI.subPanel.IMiniUnitBloodBoxView);
		var ownvo=this.getOwnerByMonsterId(monsterId);
		if(v&&ownvo)
			v.setOwer(ownvo,1);
	}

	/**本层boss掉落*/
	__proto.curFloorReward=function(){
		var ele=this.floorDc.getElement(this.selectFloor);
		if(ele){
			var cof=ele.getCfgData();
			return cof.drop;
		}
		return null;
	}

	/**本层小怪掉落*/
	__proto.curFloorReward_monster=function(){
		var ele=this.floorDc.getElement(this.selectFloor);
		if(ele){
			var cof=ele.getCfgData();
			return cof.drop1;
		}
		return null;
	}

	/**通过MonsterId 判断是否是神殿boss的boss*/
	__proto.ifShenDian=function(monsterStr){
		return monsterStr.indexOf("shendian")!=-1;
	}

	/**更新归属者*/
	__proto.updateOwner=function(vo){
		this._ownerDic[vo.monsterCfgId]=vo;
	}

	/**重置归属者*/
	__proto.resetOwner=function(){
		this._ownerDic={};
	}

	/**通过monsterId获取对应boss的归属者信息*/
	__proto.getOwnerByMonsterId=function(monsterStr){
		return this._ownerDic[monsterStr];
	}

	/**获取boss伤害排行榜*/
	__proto.getBossDamageRank=function(msg){
		this.clearRankArr();
		this._rankArr=[0];
		var isPushOwner=false;
		var rankArr=msg.rankMsg;
		var len=rankArr.length;
		if(len==0){
			return [];
		};
		var dataVo;
		for (var j=0;j < len;j++){
			dataVo=ShenDianDamageVo.getItem();
			dataVo.setInfo(rankArr[j]);
			if(dataVo.isOwner){
				this._rankArr[0]=dataVo;
				isPushOwner=true;
			}
			else if (!dataVo.isMe){
				if(this._rankArr.length<5){
					this._rankArr.push(dataVo);
				}
			}
			if(isPushOwner&&this._rankArr.length>=5){
				break ;
			}
		}
		return this._rankArr;
	}

	/**清理vo*/
	__proto.clearRankArr=function(){
		var len=this._rankArr.length;
		for(var i=0;i<len;i++){
			if(this._rankArr[i]){
				this._rankArr[i].dispose();
			}
		}
		this._rankArr.length=0;
	}

	/**获取归属者信息*/
	__proto.getOwerInfo=function(){
		var len=this._rankArr.length;
		for(var i=0;i<len;i++){
			if(this._rankArr[i].isOwner){
				return this._rankArr[i];
			}
		}
		return null;
	}

	//=================奖励相关====================
	__proto.updateReward=function(msg){
		var newRewards=TextUtil.rewardMsgToItemsId(msg.rewards);
		this._rewardArr=CommonUtil.rewardMerge(this._rewardArr,newRewards);
	}

	__proto.clearReward=function(){
		this._rewardArr.length=0;
		EventCenter.instance.event("updateReward");
	}

	__proto.updateTempReward=function(msg){
		this._tempArr=TextUtil.rewardMsgToItemsId(msg.rewards);
	}

	//=================副本内界面==================
	__proto.openCopyView=function(){
		UIMgrR.openIView(com.xq.view.modules.bossHall.shendianBoss.view.IShenDianBossCopyView,2);
	}

	__proto.closeAllView=function(){
		UIMgrR.closeIView(com.xq.view.modules.bossHall.shendianBoss.view.IShenDianBossCopyView);
	}

	__proto.registCopyTip=function(){
		CopyTipMgr.ins.regisCopyTip(2016,Handler.create(this,this.closeAllView,null,false));
	}

	__proto.showPrompt=function(msg){
		var arr=msg.rewards;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var id=arr[i].templateId;
			var count=arr[i].count;
			Mgr.prompt.optionGetItem(id,count);
		}
	}

	/**自动使用*/
	__proto.autoUse=function(){
		if(this.subFreeTime>0){
			Mgr.shendianBossA.c_useFree();
		}
		else{
			var Item=Mgr.bag.getItemVoByID(this.tldId);
			if(Item&&Item.count>0){
				Mgr.bag.useItem(Item.guid,1);
			}
			else{
				Mgr.shendianBossA.c_quit();
			}
		}
	}

	//没丹退出 以后可能会弹出购买
	__proto.showUseTLD=function(){
		var limit=this.getTlLimit();
		if(this.curTl>=limit){
			Mgr.prompt.optionPrompt(Lang.str(2232));
		}
		else{
			if(this.subFreeTime<=0&&!this.ifTiLiDan){
				this.showPath();
			}
			else{
				if(this.curTl+50>limit){
					if(this.subFreeTime>0){
						var str=Lang.str(2233);
					}
					else{
						str=Lang.str(2234);
					}
					if(this.alertTip && this.alertTip.isPopup){
						this.alertTip.close();
						this.alertTip=null;
						return;
					}
					this.alertTip=AlertUtil.ShowAlert(str,Handler.create(this,this.useTLD,null,false));
				}
				else{
					this.useTLD();
				}
			}
		}
	}

	/**使用体力丹*/
	__proto.useTLD=function(){
		if(this.subFreeTime>0){
			Mgr.shendianBossA.c_useFree();
		}
		else{
			var Item=Mgr.bag.getItemVoByID(this.tldId);
			if(Item&&Item.count>0){
				Mgr.bag.useItem(Item.guid,1);
			}
		}
	}

	__proto.showTempReward=function(){
		UIMgrR.openIView(com.xq.view.modules.bossHall.shendianBoss.view.IShenDianBossListView,3);
	}

	__proto.showUseTip=function(){
		if(this.ifHaveTempReward){
			this.ifHaveTempReward=false;
			var str=Lang.str(2235);
		}
		else{
			str=Lang.str(2236);
		};
		var tips=UIMgrR.openIView(com.xq.view.modules.bossHall.shendianBoss.view.ITiLiDanTips,3);
		tips.setTips(str);
	}

	__proto.quit=function(){
		Mgr.shendianBossA.c_quit();
	}

	/**展示获取途径*/
	__proto.showPath=function(){
		var tip=UIMgrR.openIView(com.xq.view.modules.common.IDaoJuPath,2);
		tip.setData(this.tldId);
	}

	/**圣殿boss信息数据*/
	__proto.initFightVo=function(fightVo){
		this.openCopyView();
		fightVo.hideAry=[1,2,3,4];
		fightVo.aniType=1;
		fightVo.reward=this.curFloorReward();
		fightVo.closeFun=Handler.create(Mgr.shendianBossA,Mgr.shendianBossA.c_quit,null,false);
	}

	/**是否有体力丹*/
	__getset(0,__proto,'ifTiLiDan',function(){
		var Item=Mgr.bag.getItemVoByID(this.tldId);
		if(!Item)return false;
		return Item.count>0;
	});

	__getset(0,__proto,'bossDc',function(){
		if(!this._bossDc){
			this._bossDc=new DataContainer();
			var arr=this._bossCof.objectDataArray;
			var len=arr.length;
			var ele;
			var cof;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this._bossDc.addElement(cof.number,ele);
			}
		}
		return this._bossDc;
	});

	__getset(0,__proto,'tlMax',function(){
		return this._tlMax=this._tlMax||parseInt(this._constCof.objectDataArray[0].maxTili);
	});

	__getset(0,__proto,'tempArr',function(){
		return this._tempArr;
	});

	__getset(0,__proto,'tldId',function(){
		return this._tldId=this._tldId||this._constCof.objectDataArray[0].tilidan;
	});

	/**剩余免费次数*/
	__getset(0,__proto,'subFreeTime',function(){
		var allTiems=Mgr.tequanMgr.getTequanVal(32);
		return allTiems-this.useFreeTimes;
	});

	__getset(0,__proto,'floorDc',function(){
		if(!this._floorDc){
			this._floorDc=new DataContainer();
			var arr=this._floorCof.objectDataArray;
			var len=arr.length;
			var ele;
			var cof;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this._floorDc.addElement(cof.floor,ele);
			}
		}
		return this._floorDc;
	});

	__getset(0,__proto,'myReward',function(){
		return this._rewardArr;
	});

	return ShenDianBossMgr;
})()


//class com.xq.modules.bossHall.shendianBoss.model.ShenDianDamageVo
var ShenDianDamageVo=(function(){
	function ShenDianDamageVo(){
		/**optional int64 roleId=1;数据类型：int64*/
		this.roleId=NaN;
		/**optional int64 damageValue=2;数据类型：int64*/
		this.damageValue=NaN;
		/**optional string roleName=3;数据类型：string*/
		this.roleName=null;
		/**optional int32 luckyCount=4;数据类型：int32*/
		this.luckyCount=0;
		/**optional string face=5;数据类型：string*/
		this.face=null;
		/**optional int32 sex=6;数据类型：int32*/
		this.sex=0;
		/**optional int32 level=7;数据类型：int32*/
		this.level=0;
		/**optional string job=8;数据类型：string*/
		this.job=null;
		/**optional int32 bossLuckyCount=9;数据类型：int32*/
		this.bossLuckyCount=0;
		/**optional string monsterId=10;数据类型：string*/
		this.monsterId=null;
		/**是否是归属者*/
		this.isOwner=false;
		/**是否是我自己*/
		this.isMe=false;
		/**是否是敌人*/
		this.isEnemy=false;
	}

	__class(ShenDianDamageVo,'com.xq.modules.bossHall.shendianBoss.model.ShenDianDamageVo');
	var __proto=ShenDianDamageVo.prototype;
	__proto.setInfo=function(msg){
		this.roleId=msg.roleId;
		this.roleName=msg.roleName;
		this.damageValue=msg.damageValue;
		this.luckyCount=msg.luckyCount;
		this.face=msg.face;
		this.sex=msg.sex;
		this.level=msg.level;
		this.job=msg.job;
		this.bossLuckyCount=msg.bossLuckyCount;
		this.monsterId=msg.monsterId;
		this.updateIsOwner();
		this.updateIsMe();
		this.updateIsE();
	}

	__proto.updateIsOwner=function(){
		var bossowner=Mgr.shendianBossM.getOwnerByMonsterId(this.monsterId);
		if(bossowner&&bossowner.ownerId==this.roleId){
			this.isOwner=true;
		}
		else{
			this.isOwner=false;
		}
	}

	__proto.updateIsMe=function(){
		var myId=NetMgr.ins().roleVO.guid;
		this.isMe=myId==this.roleId;
	}

	__proto.updateIsE=function(){
		var arr=Game.getInstance().player.fanjiArr;
		if(arr){
			var len=arr.length;
			for(var i=0;i<len;i++){
				if(this.roleId==arr[i].guid){
					this.isEnemy=true;
					return;
				}
			}
			this.isEnemy=false;
		}
		else{
			this.isEnemy=false;
		}
	}

	__proto.dispose=function(){
		com.xq.modules.bossHall.shendianBoss.model.ShenDianDamageVo.recover(this);
	}

	ShenDianDamageVo.getItem=function(){
		return Pool.getItemByClass("ShenDianDamageVo",ShenDianDamageVo);
	}

	ShenDianDamageVo.recover=function(item){
		Pool.recover("ShenDianDamageVo",item);
	}

	return ShenDianDamageVo;
})()


