		this._typeArr=null;
		/**boss之家伤害排行数组*/
		this._rankArr=null;
		/**伤害排行最大数量*/
		this._rankMaxCount=5;
		/**宝箱数据*/
		this._boxDic=null;
		/**剩余购买次数*/
		this._buyCount=0;
		/**宝箱物品*/
		this.boxItems=null;
		this._keyId=null;
		this._constCof=null;
		/**当前正在寻路的bossId ，如果有重复寻找就不管了*/
		this.seachBossId=null;
		this._moneyType=0;
		this._cost=0;
		this._count=0;
		//=======2021/6/4 hh============
		this._model=null;
		this.tequanCfg=CfgManager.getTableCfg("tequanboss");
		this._constCof=CfgManager.getTableCfg("BOSSBuyRewardConfig");
