var BossRefreshMgr=(function(){
	function BossRefreshMgr(){
		/**是否屏蔽Boss**/
		this.ifShield=false;
		/**Boss刷新提醒tips*/
		this.bossRfreshPanel=null;
		/**是否开通特权*/
		this._ifOpenTQ=false;
		/**自动挑战间隔**/
		this._time=0;
		/**boss刷新提醒 跳转 bossId记录*/
		this._goIdDic=null;
		this._jdMgr=null;
		this._mjMgr=null;
		this._tqMgr=null;
		this._roleVo=null;
		//========================
		this._model=null;
		/**挑战条件检测Handler 字典*/
		this._checkChallengLimitHandlers=null;
		/**自动挑战Handler字典*/
		this._autoChallengHandlers=null;
		/**获取自动关注string "monsterId;monsterId..."的Handler字典*/
		this._getRemindStrHandlers=null;
		/**自动挑战总开关*/
		this._ifStartAuto=false;
		this._jdMgr=Mgr.jindi;
		this._mjMgr=Mgr.mijing;
		this._tqMgr=Mgr.tequan;
		this._roleVo=NetMgr.ins().roleVO;
		this._goIdDic={};
		this.startListener();
		this._model=new BossRemindModel();
		this._checkChallengLimitHandlers={};
		this._autoChallengHandlers={};
		this._getRemindStrHandlers={};
		this.registFuncs();
		this.registCheckLimits();
		this.registAutoChallenges();
		this.registGetRemindStrs();
	}

	__class(BossRefreshMgr,'com.xq.modules.bosstips.BossRefreshMgr');
	var __proto=BossRefreshMgr.prototype;
	/**开启事件监听*/
	__proto.startListener=function(){
		EventCenter.instance.on("zhuanShengLevelUp",this,this.onZSLvChange);
		EventCenter.instance.on("yueka_info",this,this.onTQKChange);
		EventCenter.instance.on("LEVEL_UP",this,this.onLevelChange);
		EventCenter.instance.on("ENTER_SCENE",this,this.laterCheckAutoGoToBoss);
		EventCenter.instance.on("new_function_open",this,this.onFunctionOpen);
	}

	//=============同步后端数据===============
	__proto.updateOldData=function(msg){
		var arr=msg.monsterIdList;
		var len=arr.length;
		var removeStr="";
		var addStr="";
		for(var i=0;i<len;i++){
			var type=parseInt(arr[i]);
			if(type<1000){
				removeStr+=type+";";
				addStr+=this._model.getRemindTypeByBossType(type)+";";
			}
		}
		removeStr=removeStr.substring(0,removeStr.length-1);
		addStr=addStr.substring(0,addStr.length-1);
		if(removeStr)Mgr.bossRefresh.sendSetRfreshCS([removeStr,false,1]);
		if(addStr)Mgr.bossRefresh.sendSetRfreshCS([addStr,true,1]);
	}

	/**刷新自动挑战数据*/
	__proto.updateAutoInfo=function(msg){
		this.updateOldData(msg);
		this._model.updateAutoInfo(msg);
		EventCenter.instance.event("updateAuto");
	}

	/**设置自动挑战后刷新*/
	__proto.updateAutoOneInfo=function(msg){
		this._model.updateAutoOneInfo(msg);
		var desc=msg.isWarn?Lang.str(2242):Lang.str(2243);
		Mgr.prompt.optionPrompt(desc);
		EventCenter.instance.event("updateAuto");
		this.checkAutoChallenge();
	}

	/**刷新关注列表*/
	__proto.updateRemindInfo=function(msg){
		this._model.updateRemindInfo(msg);
		EventCenter.instance.event("updateRemind");
		this.gameStartCheckRefreshTip();
	}

	/**设置boss提醒后刷新*/
	__proto.updateRemindOneInfo=function(msg){
		this._model.updateRemindOneInfo(msg);
		var desc=msg.isWarn?Lang.str(2244):Lang.str(2245);
		Mgr.prompt.optionPrompt(desc);
		EventCenter.instance.event("updateRemind");
		if(msg.isWarn){
			var ysEle=Mgr.wuLinHuanJingM.getEleByMonsterId(msg.monsterId);
			if(!ysEle){
				this.checkShowTip(msg.monsterId);
			}
			this.checkAutoChallenge();
		}
	}

	/**收到后端 boss刷新 push包*/
	__proto.onBossRefresh=function(msg){
		var type=msg.type;
		var id=msg.monsterId;
		var vo=Model.boss.getBossStatVo(id);
		if(!vo)return;
		vo.revival();
		this.showBossRefresh(vo.monsterId);
		this.checkAutoChallenge();
	}

	__proto.sendGetInfo=function(){
		Mgr.bossRefresh.sendGetBossRemindInfo(2);
		Mgr.bossRefresh.sendGetBossRemindInfo(1);
	}

	/**根据remindType 注册对应boss开启时检测的功能Id(不一定是自己的,要看这个boss开启是不是有依赖别的)
	*例如 三界boss 和boss之家的依赖跨服boss的开启
	**/
	__proto.registFunc=function(remindType,funcId){
		this._model.registFunc(remindType,funcId);
	}

	/**这里是以前的boss统一在这里处理了 新增了boss类型 请记得在自己的管理类中注册对应boss的 funcId并调用*/
	__proto.registFuncs=function(){
		this.registFunc(1001,"worldboss");
		this.registFunc(1002,"kuafuboss");
		this.registFunc(1003,"hongzhuangboss");
		this.registFunc(1004,"kuafuboss");
		this.registFunc(1005,"yuanshenhuanjing");
		this.registFunc(1006,"ZhuoYueBoss");
	}

	/**根据remindType 注册对应boss 挑战检测的handler 例如挑战次数是否足够等,*/
	__proto.registCheckLimit=function(remindType,handler){
		this._checkChallengLimitHandlers[remindType]=handler;
	}

	/**以前的老类型，就统一在这里注册,有新的类型，请在自己的管理类里注册*/
	__proto.registCheckLimits=function(){
		this.registCheckLimit(1001,Handler.create(this,this.checkLimitWorldBoss,null,false));
		this.registCheckLimit(1002,Handler.create(this,this.checkLimitSanJieBoss,null,false));
		this.registCheckLimit(1003,Handler.create(this,this.checkLimtMijingBoss,null,false));
		this.registCheckLimit(1004,Handler.create(this,this.checkLimitBossHome,null,false));
		this.registCheckLimit(1005,Handler.create(this,this.checkLimitYuanShenBoss,null,false));
		this.registCheckLimit(1006,Handler.create(this,this.checkLimitZhuoYueBoss,null,false));
	}

	/**根据remindType 注册对应boss 自动挑战的handler*/
	__proto.registAutoChallenge=function(remindType,handler){
		this._autoChallengHandlers[remindType]=handler;
	}

	/**以前的老类型，就统一在这里注册,有新的类型，请在自己的管理类里注册*/
	__proto.registAutoChallenges=function(){
		this.registAutoChallenge(1001,Handler.create(this,this.autoChallengeJinDi,null,false));
		this.registAutoChallenge(1002,Handler.create(this,this.autoChallengeJinDi,null,false));
		this.registAutoChallenge(1003,Handler.create(this,this.autoChallengeJinDi,null,false));
		this.registAutoChallenge(1004,Handler.create(this,this.autoChallengeBossHome,null,false));
		this.registAutoChallenge(1005,Handler.create(this,this.autoChallengeYuanShenBoss,null,false));
		this.registAutoChallenge(1006,Handler.create(this,this.autoChallengeZhuoYueBoss,null,false));
	}

	/**根据remindType 注册对应boss 获取自动关注字符串的handler*/
	__proto.registGetRemindStr=function(remindType,handler){
		this._getRemindStrHandlers[remindType]=handler;
	}

	/**以前的老类型，就统一在这里注册,有新的类型，请在自己的管理类里注册*/
	__proto.registGetRemindStrs=function(){
		this.registGetRemindStr(1001,Handler.create(this,this.getWorldBossRemindArr,null,false));
		this.registGetRemindStr(1002,Handler.create(this,this.getSanJieBossRemindArr,null,false));
		this.registGetRemindStr(1003,Handler.create(this,this.getMiJingBossRemindArr,null,false));
		this.registGetRemindStr(1004,Handler.create(this,this.getBossHomeRemindArr,null,false));
	}

	/**获取可设置自动挑战的boss Folder类型 [data={folderType:xx,folderName:xx},...]*/
	__proto.getFolderTypeArr=function(){
		return this._model.getAutoTypeArr();
	}

	/**根据montserID获取folderType*/
	__proto.getFolderTypeByMonsterId=function(monsterId){
		return this._model.getFolderType(monsterId);
	}

	/**获取下拉菜单组件数据*/
	__proto.getAccordionArr=function(){
		return this._model.getAccordionData();
	}

	/**根据当前选中bossRemind Ele 获取对应boss类型的boss ele数据数组*/
	__proto.getBossArr=function(ele){
		if(!ele)return[];
		var cof=ele.getCfgData();
		var cofType=cof.cofType;
		var bossType=cof.bossType;
		switch(cofType){
			case 1:{
					return Mgr.jindi.getBossListWithoutTiYan(bossType);
				}
			case 2:{
					return Mgr.tequan.getBossArrByType(bossType);
				}
			case 3:
				return Mgr.wuLinHuanJingM.getFloorEles(1,bossType);
			case 4:
				return Mgr.zhuoYueBossM.getBossEles(1,bossType);
			}
		return [];
	}

	/**根据folderType获取该类型boss关注boss的数量*/
	__proto.getGuanZhuNum=function(folderType){
		return this._model.getGuanZhuNumByFolderType(folderType);
	}

	/**检测是否已关注*/
	__proto.checkIfGuanZhu=function(monsterId){
		return this._model.checkIfGuanZhu(monsterId);
	}

	/**检测是否勾选了自动挑战*/
	__proto.checkIfAuto=function(fodlerType){
		return this._model.checkIfAuto(fodlerType);
	}

	/**根据folderType检测该boss功能是否已经开启*/
	__proto.checkBossOpenByFolderType=function(folderType){
		if(!Mgr.guide.isOpen("bosshall"))return false;
		var func=this._model.getFuncByFolderType(folderType);
		if(!func)return true;
		return Mgr.guide.isOpen(func);
	}

	/**根据monsterId检测该boss功能是否已经开启*/
	__proto.checkBossOpen=function(monsterId){
		var folderType=this._model.getFolderType(monsterId);
		return this.checkBossOpenByFolderType(folderType);
	}

	/**根据MonsterId 检测是否达成该boss的挑战条件*/
	__proto.checkBossLimit=function(monsterId){
		return Model.boss.checkBossLimit(monsterId);
	}

	__proto.onGo=function(type){
		if(type=="OK"){
			UIMgrR.openViewByFunID("tequanyueka1");
		}
	}

	/**一键开启自动挑战*/
	__proto.oneKeyStartAuto=function(){
		var remindTypes="";
		var arr=this.getFolderTypeArr();
		var len=arr.length;
		for(var i=0;i<len;i++){
			var folderType=arr[i].folderType;
			if(!this.checkBossOpenByFolderType(folderType))continue ;
			if(!this.checkIfAuto(folderType)){
				remindTypes+=folderType+";";
			}
		}
		if(!remindTypes){
			Mgr.prompt.optionPrompt(Lang.str(2246));
			return;
		}
		remindTypes=remindTypes.substring(0,remindTypes.length-1);
		Mgr.bossRefresh.sendSetRfreshCS([remindTypes,true,1]);
	}

	/**一键关闭自动挑战*/
	__proto.oneKeyStopAuto=function(){
		var remindTypes="";
		var arr=this.getFolderTypeArr();
		var len=arr.length;
		for(var i=0;i<len;i++){
			var folderType=arr[i].folderType;
			if(!this.checkBossOpenByFolderType(folderType))continue ;
			if(this.checkIfAuto(folderType)){
				remindTypes+=folderType+";";
			}
		}
		if(!remindTypes){
			Mgr.prompt.optionPrompt(Lang.str(2247));
			return;
		}
		remindTypes=remindTypes.substring(0,remindTypes.length-1);
		Mgr.bossRefresh.sendSetRfreshCS([remindTypes,false,1]);
	}

	/**检测boss是否存活*/
	__proto.checkBossAlive=function(monsterId){
		var vo=Model.boss.getBossStatVo(monsterId);
		var ele=Mgr.wuLinHuanJingM.getEleByMonsterId(monsterId);
		if(ele){
			return true;
		};
		var zyEle=Mgr.zhuoYueBossM.getBossEleByBossId(monsterId);
		if(zyEle){
			if(!vo){
				return true;
			}
		}
		if(!vo)return false;
		return vo.revivalTime<=Mgr.curTime.serverTimer;
	}

	//=========跳转标志==========
	__proto.setGoIdDic=function(bossType,cof){
		this._goIdDic[bossType]=cof;
	}

	__proto.removeGoIdDic=function(bossType){
		this._goIdDic[bossType]=null;
	}

	__proto.getTargetIDByType=function(bossType){
		return this._goIdDic[bossType];
	}

	/**进入游戏xx秒后检测一次boss刷新提醒*/
	__proto.gameStartCheckRefreshTip=function(){
		var time=10;
		Laya.timer.once(time*1000,this,this.checkAllRefresh);
	}

	/**检测 勾选了提醒*/
	__proto.checkAllRefresh=function(){
		var remindTypeArr=this.getFolderTypeArr();
		var len=remindTypeArr.length;
		for(var i=0;i<len;i++){
			var remindType=remindTypeArr[i].folderType;
			var remindIdArr=this._model.getRemindArr(remindType);
			if(!remindIdArr||remindIdArr.length==0)continue ;
			var idLen=remindIdArr.length;
			for(var j=0;j<idLen;j++){
				var monsterId=remindIdArr[j];
				var ele=Mgr.wuLinHuanJingM.getEleByMonsterId(monsterId);
				if(this.checkBossAlive(monsterId)){
					if(!ele){
						this.showBossRefresh(monsterId);
					}
					return;
				}
			}
		}
	}

	/**检测是否可以弹出提示
	*条件：boss是否存活
	**/
	__proto.checkShowTip=function(monsterId){
		if(!this.checkBossAlive(monsterId))return;
		this.showBossRefresh(monsterId);
	}

	/**弹出Boss刷新弹窗*/
	__proto.showBossRefresh=function(monsterId,p){
		if(this.bossRfreshPanel&&this.bossRfreshPanel.isPopup){
			this.bossRfreshPanel.close();
			this.bossRfreshPanel=null;
			Laya.timer.once(1000,this,this.popupTip,[monsterId]);
			return;
		}
		this.popupTip(monsterId);
	}

	__proto.hideBoss=function(){
		if(this.bossRfreshPanel&&this.bossRfreshPanel.isPopup){
			this.bossRfreshPanel.visible=false;
		}
	}

	__proto.showBoss=function(){
		if(this.bossRfreshPanel&&this.bossRfreshPanel.isPopup){
			this.bossRfreshPanel.visible=true;
		}
	}

	__proto.popupTip=function(monsterId){
		this.bossRfreshPanel=UIMgrR.openIView(com.xq.view.modules.bosstips.IBossRefreshTips,2);
		this.bossRfreshPanel.dataSource=monsterId;
		this.bossRfreshPanel.zOrder=999;
		this.bossRfreshPanel.visible=!this.ifShield;
	}

	//============自动挑战相关===============
	__proto.getAutoChallengeStat=function(){
		return this._ifStartAuto;
	}

	/**启动自动挑战*/
	__proto.startAuto=function(){
		if(Mgr.teamMgr.ifInTeam||Mgr.fengshenlu.checkOnTeam()){
			AlertUtil.ShowAlert(Lang.str(2248),Handler.create(this,this.skipTeam),Handler.create(this,this.exitTeam,null),null,Lang.str(2249),Lang.str(2250));
			return;
		}
		this._ifStartAuto=true;
		EventCenter.instance.event("BossAutoChallengeStat");
		Mgr.prompt.optionPrompt(Lang.str(2251));
		this.sendRemindBossData();
	}

	__proto.exitTeam=function(c){
		EventCenter.instance.once("ExitTeamTeamEvent",this,this.startAuto);
		Mgr.teamAct.reqExitTeam(Mgr.teamMgr.teamType);
	}

	__proto.skipTeam=function(){
		Mgr.teamMgr.openCurTeam();
	}

	/**关闭自动挑战*/
	__proto.stopAuto=function(){
		Mgr.prompt.optionPrompt(Lang.str(2252));
		this._ifStartAuto=false;
		EventCenter.instance.event("BossAutoChallengeStat");
	}

	/**回到主界面 在判断是否还有boss可挑战*/
	__proto.laterCheckAutoGoToBoss=function(){
		if(MapType.isCopy(NetMgr.ins().roleVO.mapType))return;
		this._time=BossRefreshMgr.ifManualExit?10000 :5000;
		Laya.timer.once(this._time,this,this.sendRemindBossData);
		BossRefreshMgr.ifManualExit=false;
	}

	/**拉取设置了自动挑战且有关注boss的Boss类型的数据*/
	__proto.sendRemindBossData=function(){
		var sendType=[];
		var remindTypeArr=this.getFolderTypeArr();
		var len=remindTypeArr.length;
		for(var i=0;i<len;i++){
			var remindType=remindTypeArr[i].folderType;
			if(!this.checkIfAuto(remindType))continue ;
			var remindIdArr=this._model.getRemindArr(remindType);
			if(!remindIdArr||remindIdArr.length==0)continue ;
			var idLen=remindIdArr.length;
			for(var j=0;j<idLen;j++){
				var monsterId=remindIdArr[j];
				var bossType=Model.boss.getBossType(monsterId);
				var key=remindType+"_"+bossType;
				if(sendType.indexOf(key)!=-1)continue ;
				this.sendByRemindType(remindType,bossType);
				sendType.push(key);
			}
		}
		Laya.timer.once(3000,this,this.checkAutoChallenge);
	}

	__proto.sendByRemindType=function(remindType,bossType){
		switch(remindType){
			case 1001:
			case 1002:
			case 1003:{
					Mgr.jindiPro.sendBossListCS(bossType);
					break ;
				}
			case 1004:{
					Mgr.tequanBossPro.sendBossRefreshCS(bossType);
					break ;
				}
			case 1006:{
					Mgr.zhuoYueBossA.sendGetInfo(1);
					break ;
				}
			}
	}

	/**自动挑战检测*/
	__proto.checkAutoChallenge=function(){
		if(!this._ifStartAuto)return;
		if(MapType.isCopy(NetMgr.ins().roleVO.mapType))return;
		var remindTypeArr=this.getFolderTypeArr();
		var len=remindTypeArr.length;
		for(var i=0;i<len;i++){
			var remindType=remindTypeArr[i].folderType;
			if(!this.checkIfAuto(remindType))continue ;
			var remindIdArr=this._model.getRemindArr(remindType);
			if(!remindIdArr||remindIdArr.length==0)continue ;
			var idLen=remindIdArr.length;
			for(var j=0;j<idLen;j++){
				var monsterId=remindIdArr[j];
				if(!this.checkBossAlive(monsterId))continue ;
				if(this.checkChallengLimit(monsterId)){
					this.autoGoToBoss(monsterId);
					break ;
				}
			}
		}
	}

	/**挑战条件检测
	*1，功能开启
	*2，剩余次数
	*3，boss之家svip限制（svip不足的需要消耗玉币）
	**/
	__proto.checkChallengLimit=function(monsterId){
		if(!this.checkBossOpen(monsterId))return false;
		var remindType=this.getFolderTypeByMonsterId(monsterId);
		if(!remindType)return false;
		var handler=this._checkChallengLimitHandlers[remindType];
		if(!handler)return false;
		return handler.runWith(monsterId);
	}

	__proto.checkLimitWorldBoss=function(){
		var data=Mgr.jindi.getServerMsgByType(2);
		if(!data)return false;
		var count=data.challengeTimes;
		return count>0;
	}

	__proto.checkLimitSanJieBoss=function(){
		var msg=this._jdMgr.getServerMsgByType(11);
		if(!msg)return false;
		var times=msg.maxTimes-msg.challengeTimes;
		return times>0;
	}

	__proto.checkLimtMijingBoss=function(){
		return Mgr.jindi.hasSYCount > 0;
	}

	__proto.checkLimitBossHome=function(monsterId){
		var mySvipLv=this._roleVo.vipLevel;
		var myZsLv=this._roleVo.zhuanshengLevel;
		var myLv=this._roleVo.level;
		var cof=this._tqMgr.getCfgByBossID(monsterId);
		if(mySvipLv<cof.needVIPLevel)return false;
		if(myZsLv<cof.zhuanshenglevel)return false;
		if(myLv>(parseInt(cof.level)+100))return false;
		return true;
	}

	__proto.checkLimitYuanShenBoss=function(monsterId){
		var ysHJInfo=Mgr.wuLinHuanJingM.getHuanJingInfo(1);
		var ele=Mgr.wuLinHuanJingM.getEleByMonsterId(monsterId);
		var cfg=ele.getCfgData();
		var type=parseInt(cfg.type);
		var ifUnlock=Mgr.yuanShenM.checkTypeUnlock(type);
		if(ysHJInfo.curTL<=5)return false;
		if(!ifUnlock)return false;
		return true;
	}

	__proto.checkLimitZhuoYueBoss=function(monsterId){
		var ele=Mgr.zhuoYueBossM.getBossEleByBossId(monsterId);
		if(ele){
			var cof=ele.getCfgData();
			var attrArr=cof.needAttr;
			if(Mgr.zhuoYueZhuangBeiM.checkZYZLAll(attrArr)&&Mgr.zhuoYueBossM.checkTimes(1)){
				return true;
			}
		}
		return false;
	}

	/**自动挑战BOSS*/
	__proto.autoGoToBoss=function(monsterId){
		if(MapType.isCopy(NetMgr.ins().roleVO.mapType))return;
		var remindType=this.getFolderTypeByMonsterId(monsterId);
		if(!remindType)return;
		var handler=this._autoChallengHandlers[remindType];
		if(!handler)return;
		handler.runWith(monsterId);
	}

	__proto.autoChallengeJinDi=function(monsterId){
		var cof=this._jdMgr.getBossData(monsterId);
		if(cof){
			Mgr.copyPro.sendJinDiBoss(cof.number,true,cof.type);
		}
	}

	__proto.autoChallengeBossHome=function(monsterId){
		var cof=this._tqMgr.getCfgByBossID(monsterId);
		if(cof){
			this._tqMgr.curFloor=cof.type;
			var curEle=this._tqMgr.getTqBossDc().getElement(cof.number);
			Mgr.tequan.curSelectBoss=curEle;
			Mgr.tequanBossPro.sendEnterBossCopyCS(cof.type,true);
		}
	}

	__proto.autoChallengeYuanShenBoss=function(monsterId){
		var ele=Mgr.wuLinHuanJingM.getEleByMonsterId(monsterId);
		if(ele){
			var cof=ele.getCfgData();
			var type=parseInt(cof.type);
			var floor=parseInt(cof.ceng);
			Mgr.wuLinHuanJingA.sendEnterBossCopyCS(1,type,floor,true);
		}
	}

	__proto.autoChallengeZhuoYueBoss=function(monsterId){
		var ele=Mgr.zhuoYueBossM.getBossEleByBossId(monsterId);
		if(ele){
			var cof=ele.getCfgData();
			var id=parseInt(cof.id);
			Mgr.zhuoYueBossA.sendEnter(1,id,true);
		}
	}

	//==============自动设置关注列表逻辑===============
	__proto.getremoveRemind=function(remindType){
		return this._model.getRemindArr(remindType);
	}

	__proto.getRemind=function(remindType){
		var handler=this._getRemindStrHandlers[remindType];
		if(!handler)return [];
		return handler.run();
	}

	/**传入[remindType,remindType..]刷新对应boss的自动关注*/
	__proto.refreshAutoRemind=function(arr){
		if(!arr)return;
		var oldArr=[];
		var newArr=[];
		var len=arr.length;
		for(var i=0;i<len;i++){
			var remindType=arr[i];
			oldArr=oldArr.concat(this.getremoveRemind(remindType));
			newArr=newArr.concat(this.getRemind(remindType));
		};
		var removeStr="";
		var addStr="";
		len=oldArr.length;
		for(i=0;i<len;i++){
			var monsterId=oldArr[i];
			if(newArr.indexOf(monsterId)==-1){
				removeStr+=monsterId+";";
			}
		}
		removeStr=removeStr.substring(0,removeStr.length-1);
		Mgr.bossRefresh.sendSetRfreshCS([removeStr,false,2]);
		len=newArr.length;
		for(i=0;i<len;i++){
			monsterId=newArr[i];
			if(oldArr.indexOf(monsterId)==-1){
				addStr+=monsterId+";";
			}
		}
		addStr=addStr.substring(0,addStr.length-1);
		Mgr.bossRefresh.sendSetRfreshCS([addStr,true,2]);
	}

	/**转生等级发生变化*/
	__proto.onZSLvChange=function(){
		var arr=[1001,
		1002,
		1003,
		1004]
		this.refreshAutoRemind(arr);
	}

	/**开通特权卡刷新*/
	__proto.onTQKChange=function(){
		if(this._ifOpenTQ &&Mgr.chaoZhiTeDianMgr.isBuyZz){
			this.ifOpenTQ=false;
			var addAuto="";
			var arr=[1001,
			1002,
			1003,
			1004];
			var len=arr.length;
			for(var i=0;i<len;i++){
				if(this.checkBossOpenByFolderType(arr[i])){
					addAuto+=arr[i]+";";
				}
			}
			addAuto=addAuto.substring(0,addAuto.length-1);
			Mgr.bossRefresh.sendSetRfreshCS([addAuto,true,1]);
		}
	}

	/**SVIP等级变化*/
	__proto.onSVIPChange=function(){
		this.refreshAutoRemind([1004]);
	}

	/**功能开启*/
	__proto.onFunctionOpen=function(funId){
		if(funId=="worldboss"){}
			else if(funId=="kuafuboss"){
			this.refreshAutoRemind([1002,1004])
		}
		else if(funId=="hongzhuangboss"){
			this.refreshAutoRemind([1003])
		}
	}

	__proto.onLevelChange=function(){
		this.refreshAutoRemind([1004])
	}

	/**刷新世界boss刷新弹窗提示*/
	__proto.getWorldBossRemindArr=function(){
		if(!this.checkBossOpenByFolderType(1001))return [];
		var zsLv=this._roleVo.zhuanshengLevel;
		var remindArr=[];
		var allBossArr=this._jdMgr.getBossList(2);
		var len=allBossArr.length;
		var cof;
		for(var i=0;i<len;i++){
			cof=allBossArr[i].getCfgData();
			if(zsLv==cof.level&&cof.taskid==""){
				remindArr.push(cof.monsterid);
			}
		}
		return remindArr;
	}

	/**刷新三界boss刷新提示弹窗*/
	__proto.getSanJieBossRemindArr=function(){
		if(!this.checkBossOpenByFolderType(1002))return [];
		var zsLv=this._roleVo.zhuanshengLevel;
		var remindArr=[];
		var allBossArr=this._jdMgr.getBossList(11);
		var len=allBossArr.length;
		var cof;
		for(var i=0;i<len;i++){
			cof=allBossArr[i].getCfgData();
			if(zsLv==cof.level){
				remindArr.push(cof.monsterid);
			}
		}
		return remindArr;
	}

	/**刷新boss之家刷新自动挑战*/
	__proto.getBossHomeRemindArr=function(){
		if(!this.checkBossOpenByFolderType(1004))return [];
		var zsLv=this._roleVo.zhuanshengLevel;
		var myLv=this._roleVo.level;
		var remindArr=[];
		var allBossArr=this._jdMgr.BossHomeDC.array;
		var len=allBossArr.length;
		var cof;
		for(var i=0;i<len;i++){
			cof=allBossArr[i].getCfgData();
			if(zsLv >=cof.zhuanshenglevel&&myLv<=(parseInt(cof.level)+100)){
				remindArr.push(cof.monsterid);
			}
		}
		return remindArr;
	}

	/**刷新秘境刷新自动挑战*/
	__proto.getMiJingBossRemindArr=function(){
		if(!this.checkBossOpenByFolderType(1003))return [];
		var zsLv=this._roleVo.zhuanshengLevel;
		var mjBossTypeArr=MiJingBossMgr.BOSSTYPEARR;
		var len=mjBossTypeArr.length;
		var allBossArr;
		var len1=0;
		var cof;
		var remindArr=[];
		for(var i=0;i<len;i++){
			allBossArr=this._jdMgr.getBossList(mjBossTypeArr[i]);
			len1=allBossArr.length;
			for(var j=0;j<len1;j++){
				cof=allBossArr[j].getCfgData();
				if(zsLv==cof.level){
					remindArr.push(cof.monsterid);
				}
			}
		}
		return remindArr;
	}

	__proto.checkAutoStat=function(handler){
		if(this.getAutoChallengeStat()){
			AlertUtil.ShowAlert(Lang.str(2253),Handler.create(this,this.stopAndRunHandler,[handler]),null);
			return false;
		}
		return true;
	}

	__proto.stopAndRunHandler=function(handler){
		this.stopAuto();
		handler&&handler.run();
	}

	__getset(0,__proto,'ifOpenTQ',null,function(flag){
		this._ifOpenTQ=flag;
	});

	BossRefreshMgr.ifManualExit=false;
	BossRefreshMgr.ifAutoEnter=false;
	return BossRefreshMgr;
})()


