/**
*广告checkMgr
*
***/
//class com.xq.modules.chat.AdChatCheckMgr
var AdChatCheckMgr=(function(){
	function AdChatCheckMgr(){
		this.reccentChat=[];
		this._isLocked=false;
		this.blockWords=["app",Lang.str(2254),Lang.str(2255),"5O玩"];
		/**SVIP用户不需要接受检查*/
		this.isSVIPUser=false;
		this.roleName="";
		this.curMsg="";
		this._isLocked=LocalStorage.getItem("AD_IS_LOCKED")=="true"?true:false;
	}

	__class(AdChatCheckMgr,'com.xq.modules.chat.AdChatCheckMgr');
	var __proto=AdChatCheckMgr.prototype;
	__proto.checkRoleName=function(roleName){
		if(this.checkBlock(roleName)){
			this.isLocked=true;
		}
	}

	__proto.checkBlock=function(str){
		if(this.isSVIPUser){
			return false;
		}
		this.curMsg=str;
		var len=this.blockWords.length;
		for (var i=0;i < len;i++){
			var blockStr=this.blockWords[i];
			if(str.indexOf(blockStr)>=0){
				return true;
			};
			var size=blockStr.length;
			var isSplit=true;
			for (var j=0;j < size;j++){
				var single=blockStr.charAt(j);
				if(str.indexOf(single)==-1){
					isSplit=false;
					break ;
				}
			}
			if(isSplit){
				return true;
			}
		}
		return false;
	}

	__proto.checkMsg=function(msg){
		if(this.isSVIPUser||NetMgr.ins().roleVO.level>=250){
			return true;
		}
		this.curMsg=msg;
		if(!this.isLocked){
			var t=Browser.now();
			var isOk=true;
			var isBlock=this.checkBlock(msg);
			if(isBlock){
				isOk=false;
				this.isLocked=true;
				return isOk;
			}
			this.reccentChat.push(msg);
			if(this.reccentChat.length>5){
				var str=this.reccentChat.pop();
				var index=Math.floor(str.length *Math.random());
				var char=str.charAt(index);
				var sameCount=0;
				for (var i=0;i < this.reccentChat.length;i++){
					var temp=this.reccentChat[i];
					if(char==temp.charAt(index)){
						sameCount++;
					}
				}
				if(sameCount>=4){
					this.isLocked=true;
					isOk=false;
				}
			}
			console.log(Lang.str(2257)+(Browser.now()-t)+"ms");
			return isOk;
		}
		else{
			return false;
		}
	}

	__proto.init=function(){
		Laya.loader.load(PathDefine.FILE+"blockAdvertise.json",Handler.create(this,this.onLoaded));
	}

	__proto.onLoaded=function(data){
		if(data){
			this.blockWords=data.keywords;
		};
		var roleVo=NetMgr.ins().roleVO;
		this.roleName=roleVo.name;
		if(roleVo.vipLevel>0){
			this.isLocked=false;
			this.isSVIPUser=true;
			return;
		}
		if(this.checkBlock(roleVo.name)){
			this.isLocked=true;
		}
	}

	__getset(0,__proto,'isLocked',function(){
		return this._isLocked;
		},function(value){
		this._isLocked=value;
		LocalStorage.setItem("AD_IS_LOCKED",value+"");
		if(value){
			var err=Lang.str(2256)+this.roleName+":"+this.curMsg;
			laya.xq.cfg.reportOneBug(err,new Error(err));
		}
	});

	AdChatCheckMgr.ADCHATCHECK_IS_LOCKED="AD_IS_LOCKED";
	return AdChatCheckMgr;
})()


