		/**服务器储存的被禁言的人*/
		this.jingyanDic={};
		/**通过后台禁言的人*/
		this.systemForbitDic={};
		/**其他玩家的装备列表*/
		this.observeEquip=null;
		/**查看其他玩家信息 外观信息表*/
		this.showTab=null;
		this._chatSelect=0;
		/**当前正在私聊玩家的guid*/
		this._curChatGuid=NaN;
		this.moneyLm=0;
		this.posData=null;
		this.priObj=new Object();
		this.priJiLuObj=new Dictionary();
		this.tabDic={0:this.crossArr,1:this.worldArr ,2:this.clanArr ,3:this.zhanduiArr,4:this.sysArr};
		this.chatDic={0:0,1:0,2:0,3:0,4:0};
		this.cdDic={};
		var tab=CfgManager.getTableCfg("Config");
		this.showTab=CfgManager.getTableCfg("PlayerMessage");
		this.cdDic[0]=parseInt(tab.getItemByField("type",88).value);
		this.cdDic[1]=parseInt(tab.getItemByField("type",90).value);
		this.cdDic[4]=parseInt(tab.getItemByField("type",90).value);
		this.lvLm=parseInt(tab.getItemByField("type",27).value);
