//class com.xq.modules.collect.CollectMgr
var CollectMgr=(function(){
	function CollectMgr(){
		this.coolectEF=null;
		this.mainPlayer=null;
		this.collectVO=null;
		this.isCollecting=false;
		this._x=0;
		this._y=0;
		this.time=0;
		CollectAction.ins;
		EventCenter.instance.on("CollectEnd",this,this.endCollect)
	}

	__class(CollectMgr,'com.xq.modules.collect.CollectMgr');
	var __proto=CollectMgr.prototype;
	/**采集结束了*/
	__proto.endCollect=function(){
		this.isCollecting=false
	}

	__proto.collectStat=function(flag){
		this.isCollecting=flag;
	}

	/**
	*前往并采集
	**/
	__proto.gotoCollect=function(collect){
		if(this.isCollecting && this.mainPlayer && this.mainPlayer.CaiJiUnit && this.mainPlayer.CaiJiUnit.id==collect.id){
			CodeLinkUtil.ins().optionPrompt(Lang.str(2273));
			return;
		}
		AIController.ins().startAutoPath(NetMgr.ins().roleVO.mapId,collect.x,collect.y,Handler.create(this,this.onGotoEnd,[collect]));
	}

	__proto.onGotoEnd=function(collect){
		this.collect(collect)
	}

	__proto.collect=function(collect){
		if(collect){
			if(this.isCollecting==true){
				return;
			}
			CollectAction.ins.sendCollectApply(collect);
			this._x=Model.game.mPlayer.x;
			this._y=Model.game.mPlayer.y;
			this.isCollecting=true;
			this.collectVO=collect.vo;
			console.log(Lang.str(2274));
			var stage=Laya.stage;
			var vo=collect.vo;
			vo.state=1;
			this.coolectEF=CoolingMaskUtil.createCollectEff(Lang.str(2275),this.collectVO.cooldown+500,(stage.width>>1),stage.height>>1,stage,Handler.create(this,this.checkIsCollect));
			if(!this.mainPlayer)
				this.mainPlayer=Model.game.mPlayer;
			this.mainPlayer.isCaiJi=true;
			this.mainPlayer.CaiJiUnit=collect;
			Laya.timer.loop(100,this,this.checkIsStopCollect);
			EventCenter.instance.on("ASDFG",this,this.checkIsCollect)
		}
	}

	/**
	*检测是否移动
	*/
	__proto.checkIsStopCollect=function(_stop){
		(_stop===void 0)&& (_stop=false);
		if(Model.game.mPlayer.isCaiJi){
			if(_stop || this.mainPlayer.isActiveMove||this.mainPlayer.isDead||this.mainPlayer.isJump){
				Laya.timer.clear(this,this.checkIsStopCollect);
				Laya.timer.clear(this,this.checkIsCollect);
				if(this.coolectEF){
					this.coolectEF.dispose();
					this.coolectEF=null;
				}
				this.time=0;;
				CollectAction.ins.sendCollectInterrupt();
			}
		}
	}

	//采集终端
	__proto.onCollectFinish=function(){
		CodeLinkUtil.ins().optionPrompt(Lang.str(2276));
		console.log(Lang.str(2277));
		this.sendCollect();
		Laya.timer.clear(this,this.checkIsStopCollect);
		Laya.timer.clear(this,this.checkIsCollect);
		if(this.coolectEF){
			this.coolectEF.dispose();
			this.coolectEF=null;
		}
		this.time=0;
		this.isCollecting=false;
	}

	__proto.checkIsCollect=function(){
		this.onCollectFinish();
	}

	// time+=200;
	__proto.sendCollect=function(){
		CollectAction.ins.sendCollectSuccess();
	}

	__proto.interruptCollect=function(){
		CodeLinkUtil.ins().optionPrompt(Lang.str(2278));
		Laya.timer.clear(this,this.checkIsCollect);
		if(this.coolectEF){
			this.coolectEF.dispose();
			this.coolectEF=null;
		}
		this.isCollecting=false;
		this.time=0;
	}

	/**移除场景所有采集物*/
	__proto.clear=function(){
		var collects=UnitManager.ins.collectList.values;
		var len=collects.length;
		var collect;
		for(var i=len-1;i>=0;i--){
			collect=collects[i];
			if(collect)
				UnitManager.ins.destoryCollect(collect);
		}
	}

	CollectMgr.ins=function(){
		return CollectMgr._ins=CollectMgr._ins|| new CollectMgr();
	}

	CollectMgr._ins=null;
	return CollectMgr;
})()


