		this.curType=type;
		if(list){
			list.sort(this.sortOrder);
			return list;
		}
		list=[];
		this._tabs.set(type,list);
		var tableConfig=this.typesCfgDic.get(type);
		if(!tableConfig)
			return list;
		var alls=tableConfig.objectDataArray;
		var len=alls.length;
		if(len <=0)
			return list;
		var cfgObj;
		var boo=false;
		var newObj;
		for(var i=0;i < len;i++){
			cfgObj=alls[i];
			newObj=new Object();
			newObj.type=type;
			newObj.cfg=cfgObj;
			list.push(newObj);
		}
		list.sort(this.sortOrder);
