	__proto.sortOrder=function(newObj,newObj2){
		if(com.xq.modules.daofa.DaoFaMgr.ins.redVo){
			if(com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaActiveKey+"_"+newObj.type+"_"+newObj.cfg.id)&&
				!com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaActiveKey+"_"+newObj2.type+"_"+newObj2.cfg.id)){
				return-1;
			}
			if(!com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaActiveKey+"_"+newObj.type+"_"+newObj.cfg.id)&&
				com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaActiveKey+"_"+newObj2.type+"_"+newObj2.cfg.id)){
				return 1;
			}
			if(com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaKey+"_"+newObj.type+"_"+newObj.cfg.id)&&
				!com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaKey+"_"+newObj2.type+"_"+newObj2.cfg.id)){
				return-1;
			}
			if(!com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaKey+"_"+newObj.type+"_"+newObj.cfg.id)&&
				com.xq.modules.daofa.DaoFaMgr.ins.redVo.getCornerState(RedTypeEnum.DaoFaKey+"_"+newObj2.type+"_"+newObj2.cfg.id)){
				return 1;
			}
		}
		if(com.xq.modules.daofa.DaoFaMgr.ins.isBaGuaActive(newObj.type,newObj.cfg.id)&& !com.xq.modules.daofa.DaoFaMgr.ins.isBaGuaActive(newObj2.type,newObj2.cfg.id)){
			return-1;
		}
		if(!com.xq.modules.daofa.DaoFaMgr.ins.isBaGuaActive(newObj.type,newObj.cfg.id)&& com.xq.modules.daofa.DaoFaMgr.ins.isBaGuaActive(newObj2.type,newObj2.cfg.id)){
			return 1;
		}
		return (newObj.cfg.order-newObj2.cfg.order)< 0 ? 1 :-1;
	}

