	__class(EquipMgr,'com.xq.modules.equip.EquipMgr');
	var __proto=EquipMgr.prototype;
	/**可穿戴装备字典,仅用于第一次穿戴装备*/
	__proto.findBetterEquip=function(){
		if(this.curModel==null){
			return;
		};
		var bagArr=Mgr.bag.bagGoodsArr;
		var bagLen=Mgr.bag.bagGoodLen;
		if (bagLen > 0){
			var pydata=Mgr.payLine.model.curModel;
			for (var i=1;i <=10;i++){
				var roleVO=NetMgr.ins().roleVO;
				var maxScoreValue=0;
				if(this.curModel.wearEquipDic[i])
					maxScoreValue=this.curModel.wearEquipDic[i].totalScore;
				else
				maxScoreValue=0;
				for (var j=0;j < bagLen;j++){
					var b=bagArr[j];
					if (bagArr[j] !=null && b.partPos==i && b.cfgItem.levelreq <=this.role.zhuanshengLevel && b.cfgItem.levelwears <=this.role.level){
						if(Mgr.yuanShenM.checkIfYuanShenEquip(b)||Mgr.zhuoYueZhuangBeiM.checkIfZhuoYueEquip(b)){
							continue ;
						}
						if(parseInt(b.cfgItem.type)> 1){
							var serInfo=pydata.myPayLineInfo[parseInt(b.cfgItem.type)];
							if(serInfo){
								var jieshu=serInfo? serInfo.jieshu :1;
								if(parseInt(b.cfgItem.itemlevel)> jieshu)
									return;
							}
							else
							return;
						}
						if (b.cfgItem.job==this.role.job || b.cfgItem.job=="0"){
							if (b.totalScore > maxScoreValue){
								EventCenter.instance.event("UPGRAD_OPTION_TIP",[4,false]);
								this.curModel.wearDic[i]=b;
								maxScoreValue=b.totalScore;
							}
						}
					}
				}
			}
		}
	}

	/**通过部位稀有等级获取装备信息vo数组*/
	__proto.getEArrByPartRare=function(part,rareLv){
		var arr1=[];
		var arr=this.equipConfigData.getCfgMsgArrByTwoKey("eqpart",part.toString(),"rarelevel",rareLv.toString());
		for (var i=0;i < arr.length;i++){
			var e=Mgr.item.getItemVO(arr[i].id);
			arr1.push(e);
		}
		return arr1;
	}

	/**通过战斗力id返回数据*/
	__proto.getFactorO=function(id){
		return this.factorCfg.getItemByField("id",id.toString());
	}

	__proto.updatePaylineEquip=function(equipList){
		this.OtherSlotDic={};
		for (var i=0;i < equipList.length;i++){
			var partEquipVO;
			var itemMsg=equipList[i];
			partEquipVO=this.createEquipVO(equipList[i]);
			this.findIsChange(partEquipVO);
			this.OtherSlotDic[itemMsg.slotNum]=partEquipVO;
		}
	}

	__proto.updatePayLineEquip=function(slot,templateID){
		var vo=this.OtherSlotDic[slot];
		if(vo){
			vo=Mgr.item.getItemVO(templateID);
			this.OtherSlotDic[slot]=vo;
			EventCenter.instance.event("ROLE_EQUIP_LIST_UPDATED");
		}
	}

	/**拉取角色穿戴的装备列表*/
	__proto.updateEquipList=function(equipListSC){
		this.changeCurModel(equipListSC.roleId);
		this.wearEquips=[];
		this.equipArr=equipListSC.items;
		Mgr.equip.getModelbyRoleId(equipListSC.roleId).serverEquipArr=equipListSC.items;
		this.changeEquipRed(this.equipArr,equipListSC.roleId);
	}

	__proto.changeSerEquipShenZhu=function(guid,shenzhuInfo){
		var equipSerArr=this.getModelbyRoleId(NetMgr.ins().roleVO.guid).serverEquipArr;
		var len=equipSerArr.length;
		for (var i=0;i < len;i++){
			var itemMsg=equipSerArr[i];
			if(itemMsg.guid==guid){
				itemMsg.shenzhuinfo=shenzhuInfo;
				return;
			}
		}
	}

	__proto.changeEquipRed=function(serverEquipArr,roleId){
		if(!roleId || roleId !=NetMgr.ins().roleVO.guid){
			return;
		}
		this.wearEquips=[];
		var equipModel=this.getModelbyRoleId(roleId);
		var roleRed=this.red.getValue(RedTypeEnum.EquipChangeRed);
		var key=roleId+"_"+RedTypeEnum.EquipChangeRed;
		var oldBo=false;
		if(roleRed)
			oldBo=roleRed.getCornerState(key);
		this.red.hideRedPoint("roleZhuangbei",key,RedTypeEnum.EquipChangeRed);
		if (serverEquipArr.length > 0){
			var partEquipVO;
			var len=serverEquipArr.length;
			for (var i=0;i < len;i++){
				var itemMsg=serverEquipArr[i];
				if(itemMsg){
					partEquipVO=this.createEquipVO(itemMsg);
					this.partDic[0-itemMsg.slotNum]=partEquipVO;
					this.guidDic[itemMsg.guid]=partEquipVO;
					if (partEquipVO==null){
						alert(Lang.str(2377)+itemMsg.templateId+Lang.str(2378));
						return;
					}
					if (itemMsg.slotNum >=-10 && itemMsg.slotNum <=-1){
						this.getModelbyRoleId(roleId).wearEquipDic[0-itemMsg.slotNum]=partEquipVO;
						this.findIsChange(partEquipVO);
						this.wearEquips.push(partEquipVO);
					}
					else if (itemMsg.slotNum <=-101 && itemMsg.slotNum >=-404){
						this.findIsChange(partEquipVO);
						this.getModelbyRoleId(roleId).paylineEquDic[itemMsg.slotNum]=itemMsg
					}
				}
			}
			EventCenter.instance.event("ROLE_EQUIP_LIST_UPDATED");
		}
		this.getModelbyRoleId(roleId).wearEquipArr=this.wearEquips;
		for (var j=1;j <=10;j++){
			if(!this.getModelbyRoleId(roleId).wearEquipDic[j]){
				var equip=new EquipVO();
				equip.partPos=j;
			}
			else
			equip=this.getModelbyRoleId(roleId).wearEquipDic[j];
			this.findIsChange(equip);
			if(equip.changeVO && Mgr.bag.getItemByGuid(equip.changeVO.guid)){
				this.red.showRedPoint("roleZhuangbei",roleId+"_"+RedTypeEnum.EquipChangeRed,RedTypeEnum.EquipChangeRed);
				this.red.showRedPoint("roleZhuangbei",roleId+"_"+equip.partPos+RedTypeEnum.EquipChangeRed,RedTypeEnum.EquipChangeRed);
			}
			else
			this.red.hideRedPoint("roleZhuangbei",roleId+"_"+equip.partPos+RedTypeEnum.EquipChangeRed,RedTypeEnum.EquipChangeRed);
		}
		Mgr.shenZhuMgr.refreshShenZhuRed(this.wearEquips);
		this.findBetterEquip();
		this.enhanceTotallv();
		this.checkEquipHeadRed();
	}

	__proto.delayRefreshEquip=function(){
		Laya.timer.callLater(this,this.checkRoleEquipRedPoint);
	}

	__proto.checkRoleEquipRedPoint=function(){
		var heroAry=Mgr.subPlayer.getHeroHeadList();
		var len=heroAry.length;
		for (var i=0;i < len;i++){
			var tempVo=heroAry[i];
			if(!tempVo || !this.getModelbyRoleId(tempVo.roleId))
				continue ;
			this.changeEquipRed(this.getModelbyRoleId(tempVo.roleId).serverEquipArr,tempVo.roleId);
		}
	}

	/**头像红点*/
	__proto.checkEquipHeadRed=function(){
		var heroAry=Mgr.subPlayer.getHeroHeadList();
		var len=heroAry.length;
		var roleRed=this.red.getValue("roleZhuangbei");
		for (var i=0;i < len;i++){
			var tempVo=heroAry[i];
			if(!tempVo)
				continue ;
			var key=tempVo.roleId+"_"+RedTypeEnum.EquipChangeRed;
			var redBo=roleRed.getCornerState(key);
			if(redBo){
				EventCenter.instance.event(RedTypeEnum.RoleHeadRed,[RedTypeEnum.EquipChangeRed,i,redBo]);
				continue ;
			}
			EventCenter.instance.event(RedTypeEnum.RoleHeadRed,[RedTypeEnum.EquipChangeRed,i,false]);
		}
		EventCenter.instance.event("refresh_role_equip_red");
	}

	/**当前角色装备强化总等级*/
	__proto.enhanceTotallv=function(){
		var totalLv=0;
		if(!this.curModel){
			debugger;
			return;
		};
		var len=this.curModel.wearEquipArr.length;
		for (var i=0;i < len;i++){
			var equipVo=this.curModel.wearEquipArr [i];
			totalLv+=equipVo.strengthLv;
		}
		this.curModel.enhanceLv=totalLv;
	}

