	/**获取所有已穿装备里 各个部位最低战力的装备字典*/
	__proto.getAllMinEquipInfo=function(){
		var dic={};
		var arr=this.modelDic.values;
		var len=arr.length;
		var equipModel=arr[0];
		var wearEquipArr=equipModel.wearEquipArr;
		var len1=wearEquipArr.length;
		for(var j=0;j < len1;j++){
			var equip=wearEquipArr[j];
			var part=equip.partPos;
			var minEquipFight=dic[part] || 999999999;
			if(equip.totalScore < minEquipFight){
				dic[part]=equip.totalScore;
			}
		};
		var payLineEquipDic=equipModel.paylineEquDic;
		for(var key in payLineEquipDic){
			var payLineEquip=payLineEquipDic[key];
			part=-payLineEquip.slotNum;
			minEquipFight=dic[part] || 999999999;
			if(payLineEquip.fightValue < minEquipFight){
				dic[part]=payLineEquip.fightValue;
			}
		}
		return dic;
	}

	__proto.createEquipVO=function(i){
		if(!i)return null;
		var vo=new EquipVO();
		var templateId=i.templateId;
		var cfgItem=this.equipConfigData.getItemByField("id",templateId);
		vo.cfgItem=cfgItem;
		if (vo.cfgItem==null){
			alert(Lang.str(2379)+templateId);
			return null;
		}
		vo.partPos=parseInt(vo.cfgItem.eqpart);
		vo.slotNum=i.slotNum;
		vo.templateId=i.templateId;
		vo.guid=i.guid;
		vo.count=i.count;
		vo.owerId=i.ownerId;
		vo.rareLv=vo.cfgItem.rarelevel;
		vo.rareArr=vo.cfgItem.rareStr.split("-");
		vo.bind=i.bind;
		vo.endTime=i.endTime;
		vo.useLv=i.level;
		vo.strengthLv=i.strenLevel;
		vo.makeAttributes=i.makeAttributes;
		vo.strengthAttrs=i.strengthAttrs;
		vo.starAttrs=i.starAttrs;
		vo.shenZhuInfo=i.shenzhuinfo;
		if (cfgItem.eqpart >=1 && cfgItem.eqpart <=12){
			var equipJob=cfgItem.job;
			if (equipJob=="A"){
				vo.jobName=Lang.str(2181);
			}
			else if (equipJob=="C"){
				vo.jobName=Lang.str(2182);
			}
			else if (equipJob=="0"){
				vo.jobName=Lang.str(2183);
			}
			else{
				vo.jobName="";
			}
		}
		else{
			vo.jobName="";
		};
		var baseAttrStr=vo.cfgItem.jichuAttribute;
		var arr=baseAttrStr.split(";");
		vo.attrArr=AttributeTypeEnum.getEquipAttrArr(arr);
		if (i.strengthAttrs.length > 0){
			var strenMsg=i.strengthAttrs[0];
			vo.strenValue=strenMsg.attrValue;
		}
		if (vo.cfgItem.suit && vo.cfgItem.suit !=0){
			var suitO=Mgr.suit.getSuitMsg(vo.rareLv,vo.cfgItem.suit);
			if(suitO){
				vo.suitNum=i.suitEquipNum;
				vo.suitFV3=Mgr.suit.getAttrFV(suitO.attr3);
				vo.suitFV6=Mgr.suit.getAttrFV(suitO.attr6);
				vo.suitFV10=Mgr.suit.getAttrFV(suitO.attr10);
			}
		}
		if (i.starAttrs.length > 0){
			var starMsg=i.starAttrs[0];
			vo.starValue=starMsg.attrValue;
		}
		if (vo.partPos >=1 && vo.partPos <=10){
			vo.starLevel=i.starLevel;
			vo.washArr=i.xilianList;
			if (i.xilianList){
				vo.washFV=Mgr.equipWashMgr.getWashFV(i.xilianList);
			}
			vo.minGemLv=i.minGemLv;
			vo.gemArr=[];
			for (var i3=0;i3 < i.baoshi.length;i3++){
				var msg=i.baoshi[i3];
				vo.gemArr[msg.slot-1]=msg;
			};
			var gem0=vo.gemArr[0];
			var gem1=vo.gemArr[1];
			var gem2=vo.gemArr[2];
			var gem3=vo.gemArr[3];
			var gem4=vo.gemArr[4];
			if(gem0){
				var attr0=Mgr.gemMgr.getGemAttrData(gem0.templateId);
			}
			if(gem1){
				var attr1=Mgr.gemMgr.getGemAttrData(gem1.templateId);
			}
			if(gem2){
				var attr2=Mgr.gemMgr.getGemAttrData(gem2.templateId);
			}
			if(gem3)
				var attr3=Mgr.gemMgr.getGemAttrData(gem3.templateId);
			if(gem4)
				var attr4=Mgr.gemMgr.getGemAttrData(gem4.templateId);
			vo.gemV0=attr0 ? parseInt(attr0.attrValue):0;
			vo.gemV1=attr1 ? parseInt(attr1.attrValue):0;
			vo.gemV2=attr2 ? parseInt(attr2.attrValue):0;
			vo.gemV3=attr3 ? parseInt(attr3.attrValue):0;
			vo.gemV4=attr4 ? parseInt(attr4.attrValue):0;
		};
		var score=0;
		for (var j=0;j < vo.attrArr.length;j++){
			var attrVO=vo.attrArr[j];
			score+=parseInt(attrVO.attrFV);
		}
		if(templateId.indexOf("z")>=0 && vo.rareLv >=5){
			score+=AttributeTypeEnum.getZdlByAttrMsg(Mgr.equip.getEquipSpecialAttr(vo));
		}
		vo.attrScore=score;
		vo.totalScore=score;
		vo.whichPanel=11;
		return vo;
	}

	/**
	*检测是否可以升品或者升阶材料是否足够
	*/
	__proto.checkCanUpRedPoint=function(needMatStr){
		var matStrArr;
		matStrArr=needMatStr.split(";");
		var result=0;
		var len=matStrArr.length;
		for (var i=0;i < len;i++){
			var matStr=matStrArr[i];
			var matArr=matStr.split(":");
			var matTemplateId=matArr[0];
			var needCount=parseInt(matArr[1]);
			var bagCount=Mgr.bag.getBagMatCount(matTemplateId);
			if (bagCount >=needCount){
				result++;
			}
		}
		if (result==matStrArr.length){
			return true;
		}
		else{
			return false;
		}
	}

	/**
	*检测是否可升品红点
	*/
	__proto.checkCanUpQuaRedPoint=function(e){
		if (e==null){
			return false;
		};
		var nextEId=e.cfgItem.rareitemid;
		var nextE=Mgr.item.getItemVO(nextEId);
		var roleLv=NetMgr.ins().roleVO.level;
		if (nextE==null || nextE.cfgItem.itemlevel > roleLv){
			return false;
		};
		var needMatStr=e.cfgItem.rareconsum;
		var haveMat=this.checkCanUpRedPoint(needMatStr);
		if (haveMat){
			return true;
		}
		else{
			return false;
		}
	}

