	/**寻找更好的装备*/
	__proto.findIsChange=function(e){
		EventCenter.instance.event("UPGRAD_OPTION_TIP",[4,true]);
		var bagArr=Mgr.bag.bagGoodsArr;
		var bagLen=Mgr.bag.bagGoodLen;
		if (bagLen > 0){
			var maxScoreValue=e.totalScore;
			for (var j=0;j < bagLen;j++){
				var b=bagArr[j];
				if (bagArr[j] !=null && b.partPos==e.partPos && b.cfgItem.levelreq <=this.role.zhuanshengLevel && b.cfgItem.levelwears <=this.role.level){
					if(Mgr.yuanShenM.checkIfYuanShenEquip(b)||Mgr.zhuoYueZhuangBeiM.checkIfZhuoYueEquip(b)){
						continue ;
					}
					if(parseInt(b.cfgItem.type)> 1){
						var serInfo=Mgr.payLine.model.curModel.myPayLineInfo[parseInt(b.cfgItem.type)];
						if(serInfo){
							var jieshu=serInfo? serInfo.jieshu :1;
							if(parseInt(b.cfgItem.itemlevel)> jieshu)
								return;
						}
						else
						return;
					}
					else if (b.cfgItem.job==this.role.job || b.cfgItem.job=="0"){
						if (b.totalScore > maxScoreValue){
							EventCenter.instance.event("UPGRAD_OPTION_TIP",[4,false]);
							e.changeIndex=j;
							e.changeVO=b;
							maxScoreValue=b.totalScore;
						}
					}
				}
			}
		}
	}

	/**背包和角色面板接收换装*/
	__proto.equipChange=function(eSC){
		var bgDic=Mgr.bag.bagGuidDic;
		var bgArr=Mgr.bag.bagGoodsArr;
		var equipArr=Mgr.bag.bagEquipArr;
		if (bgDic==null){
			alert(Lang.str(2380));
			return;
		};
		var curModel=this.getModelbyRoleId(eSC.roleId);
		var newEquipVO=bgDic[eSC.newItem.itemGuid];
		var newBagIdx=bgArr.indexOf(newEquipVO);
		var newBagEquipIdx=equipArr.indexOf(newEquipVO);
		if(newEquipVO.cfgItem.skill){
			Mgr.skillPro.getNewSkill(newEquipVO.cfgItem.skill,1);
		}
		if(eSC.oldItem){
			var oldEqupVo=curModel.wearEquipDic[0-eSC.newItem.slogNum];
			var oldEquipIdx=curModel.wearEquipArr.indexOf(oldEqupVo);
			bgDic[eSC.oldItem.itemGuid]=oldEqupVo;
		}
		delete bgDic[eSC.newItem.itemGuid];
		if(newEquipVO)
			curModel.wearEquipDic[0-eSC.newItem.slogNum]=newEquipVO;
		bgArr.splice(newBagIdx,1,oldEqupVo);
		equipArr.splice(newBagIdx,1,oldEqupVo);
		if(oldEqupVo){
			Mgr.bag.laterAddOneEquipToTip(oldEqupVo,true);
		}
		this.checkMadeIconRedPoint();
		EventCenter.instance.event("ROLE_EQUIP_EXCHANGE_UPDATED");
	}

	__proto.smelt=function(arr){
		var rewardArr=[];
		var len=arr.length;
		for (var i=0;i < len;i++){
			var itemReward=arr[i];
			var itemStr=itemReward.templateId+":"+itemReward.count+":"+itemReward.bind;
			rewardArr.push(itemStr);
		}
		this.smeltItems=CommonUtil.rewardMerge(this.smeltItems,rewardArr);
		Mgr.itemPro.sendGetBagGoodsMsg();
		if(!Mgr.equip.isAutoSmelt&&this.smeltItems.length>0){
			EventCenter.instance.event("SMELT_REWARD");
			this.smeltItems.length=0;
		}
		Laya.timer.callLater(this,this.outEvent);
	}

