//class com.xq.modules.equip.EquipTipFactory
var EquipTipFactory=(function(){
	function EquipTipFactory(){}
	__class(EquipTipFactory,'com.xq.modules.equip.EquipTipFactory');
	EquipTipFactory.madeTips=function(e){
		switch(e.whichPanel){
			case 0:{
					if(e.cfgItem.type==1){
						EquipTipFactory.compareEquip(e);
					}
					else if(Mgr.yuanShenM.checkIfYuanShenEquip(e)){
						EquipTipFactory.checkBagYuanShenEquip(e);
					}
					else if(Mgr.zhuoYueZhuangBeiM.checkIfZhuoYueEquip(e)){
						EquipTipFactory.checkBagZhuoYueEquip(e);
					}
					break ;
				}
			case 8:{
					EquipTipFactory.compareEquip(e);
					break ;
				}
			case 11:
			case 1:
			case 2:
			case 4:
			case 3:
			case 6:{
					EquipTipFactory.selfEquip(e);
					break ;
				}
			default :{
					EquipTipFactory.otherEquip(e);
					break ;
				}
			}
	}

	EquipTipFactory.selfEquip=function(e){
		var oneTip=UIMgrR.getIView(com.xq.view.modules.tip.IEquipTipPanelView);
		oneTip.dataSource=e;
		UIMgrR.openIView(com.xq.view.modules.tip.IEquipTipPanelView,2);
	}

	EquipTipFactory.compareEquip=function(e){
		var oneTip=UIMgrR.getIView(com.xq.view.modules.tip.IEquipCompareTip);
		oneTip.dataSource=e;
		UIMgrR.openIView(com.xq.view.modules.tip.IEquipCompareTip,2);
	}

	EquipTipFactory.otherEquip=function(e){
		var oneTip;
		oneTip=UIMgrR.getIView(com.xq.view.modules.tip.IEquipTipPanelView);
		oneTip["rightTopImg"].visible=false;
		oneTip.dataSource=e;
		UIMgrR.openIView(com.xq.view.modules.tip.IEquipTipPanelView,2);
	}

	EquipTipFactory.openRole=function(e){
		if (e.whichPanel==8){
			EquipTipFactory.compareEquip(e);
			}else{
			var tip=UIMgrR.getIView(com.xq.view.modules.tip.IEquipTipPanelView);
			tip.dataSource=e;
			UIMgrR.openIView(com.xq.view.modules.tip.IEquipTipPanelView,2);
		}
	}

	EquipTipFactory.checkMyYuanShenEquip=function(equipId){
		var tips=UIMgrR.openIView(com.xq.view.modules.yuanshen.yuanshenEquipTip.IYuanShenEquipInfo,2);
		tips.dataSource=equipId;
	}

	EquipTipFactory.checkBagYuanShenEquip=function(e){
		var tips=UIMgrR.openIView(com.xq.view.modules.yuanshen.yuanshenEquipTip.IYuanShenEquipBagTip,2);
		tips.dataSource=e;
	}

	EquipTipFactory.checkOtherYuanShenEquip=function(equipId){
		var tips=UIMgrR.openIView(com.xq.view.modules.yuanshen.yuanshenEquipTip.IYuanShenEquipOtherTip,2);
		tips.dataSource=equipId;
	}

	EquipTipFactory.checkMyZhuoYueEquip=function(equipId){
		var tips=UIMgrR.openIView(com.xq.view.modules.zhuoYueZhuangBei.zhuoYueEquipTip.IZhuoYueEquipInfoTip,2);
		tips.dataSource=equipId;
	}

	EquipTipFactory.checkBagZhuoYueEquip=function(e){
		var tips=UIMgrR.openIView(com.xq.view.modules.zhuoYueZhuangBei.zhuoYueEquipTip.IZhuoYueEquipGoodsInfo,2);
		tips.dataSource=e;
	}

	return EquipTipFactory;
})()


