		this.gemCachObj={};
		this.curData=null;
		this._model=Model.equipGem;
		this.red=Mgr.red;
		this.gemCompoundCfg=CfgManager.getTableCfg("hechengbiao");
		this.gemAchieveCfg=CfgManager.getTableCfg("Baoshibuweijiacheng");
		EventCenter.instance.onQue("ITEM_CHANGE",this,this.itemChangeRefreshRed);
