//class com.xq.modules.equip.shenzhu.EquipShenZhuMgr
var EquipShenZhuMgr=(function(){
	function EquipShenZhuMgr(){
		/**
		*神铸配置表
		*/
		this.shenZhuCfg=null;
		/**
		*神铸data
		*/
		this.shenZhuData=null;
		this.red=null;
		/**还未替换的神铸信息*/
		this._nextShenZhuinfo=null;
		/**神铸转移消耗材料*/
		this.zhuanYiCost=null;
		/**神铸属性字典*/
		this.shenZhuDic=null;
		/**神铸技能页数*/
		this.maxIndex=0;
		this.partArr=[1,2,3,4,5,6,9,10,7,8];
		this.redVo=null;
		this.shenZhuCfg=CfgManager.getTableCfg("equipShenZhu");
		this.red=Mgr.red;
		this.red.regist("duanZao","dzshenzhu",true,RedTypeEnum.ForgeRed);
		this.redVo=this.red.getValue("dzshenzhu");
		this.getShenZhuData();
		this.zhuanYiCost=CfgManager.getTableCfg("equipShenZhuConfig").objectDataArray[0].translateCost;
		EventCenter.instance.onQue("ITEM_CHANGE" ,this,this.refreshRed);
	}

	__class(EquipShenZhuMgr,'com.xq.modules.equip.shenzhu.EquipShenZhuMgr');
	var __proto=EquipShenZhuMgr.prototype;
	__proto.getShenZhuData=function(){
		if(!this.shenZhuData){
			this.shenZhuData=new DataContainer();
			var cfgArr=this.shenZhuCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				if(cfg){
					var ele=new DataElement(cfg);
					this.shenZhuData.addElement(cfg.equipId,ele);
				}
			}
		}
		return this.shenZhuData;
	}

	__proto.getShenZhuById=function(equipId){
		if(this.getShenZhuData().getElement(equipId)){
			return this.getShenZhuData().getElement(equipId).getCfgData();
		}
		return null;
	}

	__proto.refreshShenZhuRed=function(equipArr){
		var len=equipArr.length;
		for (var i=0;i < len;i++){
			var equipVo=equipArr[i];
			this.red.hideRedPoint("dzshenzhu","dzshenzhu"+"_"+equipVo.partPos,RedTypeEnum.ShenZhuRed);
			var ele=this.getShenZhuData().getElement(equipVo.templateId);
			if(ele){
				var shenZhuObj=ele.getCfgData();
				if(shenZhuObj){
					if(!equipVo.shenZhuInfo){
						if(Mgr.bag.checkItemIsEnough(shenZhuObj.cost)){
							this.red.showRedPoint("dzshenzhu","dzshenzhu"+"_"+equipVo.partPos,RedTypeEnum.ShenZhuRed);
						}
					}
				}
			}
		}
	}

	__proto.getShenZhuArr=function(){
		var itemLevel=NetMgr.ins().roleVO.zhuanshengLevel;
		if(itemLevel < 6){
			itemLevel=6;
		};
		var arr=Mgr.equip.getEquipArrByTwo(itemLevel,4);
		var equipArr=[];
		var shenZhuEquipVo;
		for (var i=0;i < 10;i++){
			var index=this.partArr[i];
			var equipVo=Mgr.equip.curModel.wearEquipDic[index];
			if(!equipVo || !this.getShenZhuData().getElement(equipVo.templateId)){
				shenZhuEquipVo=new EquipVO();
				shenZhuEquipVo.partPos=index;
				shenZhuEquipVo.isShowTip=true;
				shenZhuEquipVo.cfgItem=arr[index-1];
				}else{
				shenZhuEquipVo=equipVo;
			}
			equipArr.push(shenZhuEquipVo);
		}
		return equipArr;
	}

	__proto.getShenZhuDic=function(){
		var equipArr=[];
		this.shenZhuDic=new Dictionary();
		var shenZhuVo;
		var index=0;
		for (var i=0;i < 10;i++){
			var part=this.partArr[i];
			var equipVo=Mgr.equip.curModel.wearEquipDic[part];
			if(equipVo && equipVo.shenZhuInfo){
				shenZhuVo=this.shenZhuDic.get(equipVo.shenZhuInfo.skillId);
				if(!shenZhuVo){
					shenZhuVo=new ShenZhuVo();
					shenZhuVo.index=index;
					index++;
				}
				shenZhuVo.shenzhuInfo=equipVo.shenZhuInfo;
				shenZhuVo.partArr.push(equipVo.partPos);
				if(shenZhuVo.partArr.length >=shenZhuVo.shenzhuInfo.num){
					shenZhuVo.isActive=true;
					}else{
					shenZhuVo.isActive=false;
				}
				this.shenZhuDic.set(equipVo.shenZhuInfo.skillId,shenZhuVo);
			}
			equipArr.push(shenZhuVo);
		}
		this.maxIndex=Math.ceil((this.shenZhuDic.values.length)/4)-1;
		if(this.maxIndex < 0){
			this.maxIndex=0;
		}
	}

	__proto.getShowSkillByIndex=function(index){
		var shenzhuArr=this.shenZhuDic.values;
		var shenzhuShowArr=[];
		if(!shenzhuArr)return null;
		var len=shenzhuArr.length;
		for (var i=0;i < len;i++){
			var shenZhuVo=shenzhuArr[i];
			if(shenZhuVo.index >=index *4 && shenZhuVo.index < (index+1)*4){
				shenzhuShowArr.push(shenZhuVo);
			}
		}
		return shenzhuShowArr;
	}

	__proto.getShowBySkillId=function(skillId){
		var shenZhuVo=this.shenZhuDic.get(skillId);
		if(shenZhuVo){
			var index=Math.ceil((shenZhuVo.index+1)/4)-1;
			return [this.getShowSkillByIndex(index),index];
			}else{
			return null;
		}
		return null;
	}

	/**传入神铸技能id 判断技能是否激活*/
	__proto.getShenZhuSkillIsActive=function(skillId){
		var shenzhuVo=this.shenZhuDic.get(skillId);
		if(shenzhuVo){
			return shenzhuVo.isActive;
			}else{
			return false;
		}
	}

	__proto.getSelectIndex=function(){
		var shenzhuArr=this.getShenZhuArr();
		var len=shenzhuArr.length;
		for (var i=0;i < len;i++){
			var equipVo=shenzhuArr[i];
			if(this.redVo.getCornerState("dzshenzhu"+"_"+equipVo.partPos)){
				return this.getIndexByPart(equipVo.partPos);
			}
		}
		for (i=0;i < len;i++){
			equipVo=shenzhuArr[i];
			if(equipVo.cfgItem){
				return this.getIndexByPart(equipVo.partPos);
			}
		}
		return 0;
	}

	__proto.getIndexByPart=function(part){
		for (var i=0;i < 10;i++){
			if(this.partArr[i]==part){
				return i;
			}
		}
		return 0;
	}

	__proto.exchangeShenZhu=function(msg){
		var equipVo=Mgr.equip.guidDic[msg.equipId];
		equipVo.shenZhuInfo=msg.attrInfo;
		Mgr.equip.changeSerEquipShenZhu(msg.equipId,msg.attrInfo);
		var tarEquipVo=Mgr.bag.bagGuidDic[msg.tarequipId];
		tarEquipVo.shenZhuInfo=msg.tarAttrInfo;
		this.refreshRed();
		this.getShenZhuDic();
		EventCenter.instance.event("equip_shenzhu_exchange",[msg]);
	}

	__proto.refreshRed=function(){
		if(Mgr.equip.curModel){
			this.refreshShenZhuRed(Mgr.equip.curModel.wearEquipArr);
		}
	}

	__proto.getExchangeEquipArr=function(part){
		var arr=[];
		var equipArr=Mgr.bag.bagEquipArr;
		var len=equipArr.length;
		for (var i=0;i < len;i++){
			var equipVo=equipArr[i];
			if(equipVo && equipVo.partPos==part && this.getShenZhuData().getElement(equipVo.templateId)){
				arr.push(equipVo);
			}
		}
		return arr;
	}

	__proto.getShenZhuSkillNum=function(skillId){
		var skillNum=0;
		var equipArr=Mgr.equip.curModel.wearEquipArr;
		var len=equipArr.length;
		var equipVo;
		for (var i=0;i < len;i++){
			equipVo=equipArr[i];
			if(equipVo && equipVo.shenZhuInfo && equipVo.shenZhuInfo.skillId==skillId){
				skillNum++;
			}
		}
		return skillNum;
	}

	__getset(0,__proto,'nextShenZhuinfo',function(){
		return this._nextShenZhuinfo;
		},function(shenZhuInfo){
		this._nextShenZhuinfo=shenZhuInfo;
	});

	EquipShenZhuMgr.EQUIP_SHENZHU="equip_shenzhu";
	EquipShenZhuMgr.EQUIP_SHENZHU_REPLACE="equip_shenzhu_replace";
	EquipShenZhuMgr.CHOOSE_SHENZHU_ZHUANYI="choose_shenzhu_zhuanyi";
	EquipShenZhuMgr.EQUIP_SHENZHU_EXCHANGE="equip_shenzhu_exchange";
	return EquipShenZhuMgr;
})()


