//class com.xq.modules.equip.suit.SuitMgr
var SuitMgr=(function(){
	function SuitMgr(){
		/**
		*收集装备表
		*/
		this.collectEquipCfg=null;
		/**
		*装备表
		*/
		this.equipCfg=null;
		/**
		*兑换装备表
		*/
		this.collectEquipData=null;
		this.red=null;
		/**当前套装唯一编号 */
		this.curSuitId=0;
		/**当前可预览最大大类id*/
		this.maxShowSuitTab=0;
		/**当前套装已激活件数 3 6 8*/
		this.curActiveNum=0;
		this.activeArr=[3,6,8];
		/**套装 大类数组*/
		this.suitTabArr=null;
		/**套装 装备阶级数组*/
		this.suitItemArr=null;
		/**套装中装备最大阶级*/
		this.suitMaxLevel=0;
		/**套装后端信息字典*/
		this.suitSerDic=null;
		/**每个套装激活数量*/
		this.suitNumDic=null;
		/**套装大类数量*/
		this.suitDaLeiNum=0;
		this._selectCurSuitId=0;
		this.orangeArr=null;
		this.redArr=null;
		/**
		*服务器整理收集装备数据
		*/
		this.suitRewardDic=null;
		this.suitRewardArr=null;
		/**当前套装数量*/
		this.wearNum=0;
		this.suitSerDic=new Dictionary();
		this.suitNumDic=new Dictionary();
		this.equipCfg=CfgManager.getTableCfg("ZhuangBeiBiao");
		this.collectEquipCfg=CfgManager.getTableCfg("newshoujizhuangbei");
		this.red=Mgr.red;
		EventCenter.instance.onQue("ROLE_EQUIP_EXCHANGE_UPDATED",this,this.checkIconRedPoint);
		EventCenter.instance.on("new_function_open",this,this.newOpenFun);
		this.suitTabArr=[];
		this.suitItemArr=[];
		this.neatenSuitInfo();
	}

	__class(SuitMgr,'com.xq.modules.equip.suit.SuitMgr');
	var __proto=SuitMgr.prototype;
	__proto.setSuitSerValue=function(shouJiSuitMsg){
		this.suitSerDic.set(shouJiSuitMsg.id,shouJiSuitMsg);
	}

	__proto.getSuitSerValue=function(id){
		return this.suitSerDic.get(id);
	}

	__proto.getCollectEquipData=function(){
		if(!this.collectEquipData){
			this.collectEquipData=new DataContainer();
			var cfgArr=this.collectEquipCfg.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				if(cfg){
					var ele=new DataElement(cfg);
					this.collectEquipData.addElement(cfg.ID,ele);
				}
				if(i==(len-1)){
					this.suitDaLeiNum=parseInt(cfg.dalei);
				}
			}
		}
		return this.collectEquipData;
	}

	__proto.neatenSuitInfo=function(){
		var suitArr=this.collectEquipCfg.objectDataArray;
		var len=suitArr.length;
		this.suitMaxLevel=parseInt(suitArr[len-1].level);
		for (var i=0;i <=this.suitMaxLevel;i++){
			var suitLevelArr=this.getSuitArrByOne(i);
			if(suitLevelArr){
				this.suitTabArr.push(suitLevelArr[0]);
				this.suitItemArr.push(suitLevelArr);
			}
		}
	}

	/**通过装备阶级获取一个数组 然后组装成suitVo数组*/
	__proto.getSuitArrByOne=function(level){
		var suitVoArr=[];
		var suitArr=this.collectEquipCfg.getItemsByField("level",level+"");
		if(suitArr.length==0){
			return null;
		};
		var len=suitArr.length;
		for (var i=0;i < len;i++){
			var suitInfo=suitArr[i];
			var cfgArr=this.equipCfg.getCfgMsgArrByThreeKey("itemlevel",parseInt(suitInfo.level),"rarelevel",parseInt(suitInfo.rarelevel),"star",suitInfo.star);
			var equipArr=[];
			for (var j=0;j < cfgArr.length;j++){
				var templateId=cfgArr[j].id;
				var e=Mgr.item.getItemVO(templateId);
				equipArr.push(e);
			}
			suitVoArr.push(this.createSuitVo(suitInfo,equipArr));
		}
		return suitVoArr;
	}

	__proto.newOpenFun=function(id,initBo){
		(id===void 0)&& (id="");
		(initBo===void 0)&& (initBo=false);
		if(!initBo){
			if(id=="roleSuit"){}
				}
		else{
			if(Mgr.guide.isOpen("roleSuit")){}
				}
	}

	/**通过套装稀有级别和第套装获取到一行数据*/
	__proto.getSuitMsg=function(rareLv,suitNum){
		return this.collectEquipCfg.getCfgMsgByTwoKey("rarelevel",rareLv.toString(),"suit",suitNum);
	}

	/**通过套装稀有级别和第套装获取到一行数据*/
	__proto.getSuitMsgById=function(id){
		return this.getCollectEquipData().getElement(id+"").getCfgData();
	}

	__proto.getSuitArrByRareLv=function(rareLv){
		var roleVO=NetMgr.ins().roleVO;
		var roleJob=roleVO.job;
		var lv=roleVO.level;
		var allSuitArr=[];
		var collectCfgArr=this.collectEquipCfg.objectDataArray;
		var len=collectCfgArr.length;
		for (var suitIndex=1;suitIndex <=len;suitIndex++){
			var obj=collectCfgArr[suitIndex-1];
			if (!obj){
				debugger
				continue ;
			};
			var cfgArr=this.equipCfg.getCfgMsgArrByThreeKey("suit",suitIndex,"rarelevel",obj.rarelevel,"star",0);
			var equipArr=[];
			for (var j=0;j < cfgArr.length;j++){
				var templateId=cfgArr[j].id;
				var job=cfgArr[j].job;
				var e=Mgr.item.getItemVO(templateId);
				e.whichPanel=10;
				if (job=="0" || job==roleJob){
					equipArr.push(e);
				}
			};
			var suitVO=this.createSuitVo(obj,equipArr);
			allSuitArr.push(suitVO);
		};
		var showArr=[];
		if (rareLv==SuitMgr.ORANGE_RARE){
			for (var i2=0;i2 < allSuitArr.length;i2++){
				var temp=allSuitArr[i2];
				if(Mgr.equip.curModel.curSuitId >=parseInt(temp.suitId))
					temp.isActivation=true;
				else
				temp.isActivation=false;
				showArr.push(temp);
			}
			this.orangeArr=showArr;
			return this.orangeArr;
		}
		else{
			this.redArr=allSuitArr;
			return this.redArr;
		}
	}

	__proto.createSuitVo=function(obj,equipArr){
		var suitVO=new SuitVO;
		suitVO.cfg=obj;
		suitVO.suitNum=obj.suit;
		suitVO.equipArr=equipArr;
		suitVO.suitLv=parseInt(obj.showLevel);
		suitVO.suitRareLv=obj.rarelevel;
		suitVO.suitId=obj.ID;
		suitVO.huanHuaId=obj.huanhuaid;
		suitVO.addFV=obj.zhanlibiaosheng;
		var attr1Str=obj.attr1;
		var attr1Arr=this.getAttrArr(attr1Str);
		suitVO.attr1=attr1Arr;
		suitVO.attr1FV=this.getAttrFV(attr1Str);
		var attr2Str=obj.attr2;
		var attr2Arr=this.getAttrArr(attr2Str);
		suitVO.attr2=attr2Arr;
		suitVO.attr2FV=this.getAttrFV(attr2Str);
		var attr3Str=obj.attr3;
		var attr3Arr=this.getAttrArr(attr3Str);
		suitVO.attr3=attr3Arr;
		suitVO.attr3FV=this.getAttrFV(attr3Str);
		var attr4Str=obj.attr4;
		var attr4Arr=this.getAttrArr(attr4Str);
		suitVO.attr4=attr4Arr;
		suitVO.attr4FV=this.getAttrFV(attr4Str);
		var attr5Str=obj.attr5;
		var attr5Arr=this.getAttrArr(attr5Str);
		suitVO.attr5=attr5Arr;
		suitVO.attr5FV=this.getAttrFV(attr5Str);
		var attr6Str=obj.attr6;
		var attr6Arr=this.getAttrArr(attr6Str);
		suitVO.attr6=attr6Arr;
		suitVO.attr6FV=this.getAttrFV(attr6Str);
		var attr7Str=obj.attr7;
		var attr7Arr=this.getAttrArr(attr7Str);
		suitVO.attr7=attr7Arr;
		suitVO.attr7FV=this.getAttrFV(attr7Str);
		var attr10Str=obj.attr10;
		var attr10Arr=this.getAttrArr(attr10Str);
		suitVO.attr10=attr10Arr;
		suitVO.attr10FV=this.getAttrFV(attr10Str);
		return suitVO;
	}

	/**
	*传进去套装属性字符串，返回属性字符串数组
	*/
	__proto.getAttrArr=function(attrStr){
		var resultStrArr=[];
		var attrTypeStrArr=attrStr.split(";");
		for (var i=0;i < attrTypeStrArr.length;i++){
			var attrTypeStr=attrTypeStrArr[i];
			var attrStrArr=attrTypeStr.split(":");
			var attr=new AttributeMsg();
			var attrOneStr=attrStrArr[0];
			var attrObj=AttributeTypeEnum.getMsgByZhanLiCfg(attrOneStr);
			attr.attrId=parseInt(attrObj.id);
			attr.attrValue=parseInt(attrStrArr[1]);
			resultStrArr.push(attr);
		}
		return resultStrArr;
	}

	/**
	*传进去套装属性字符串，返回战斗力
	*/
	__proto.getAttrFV=function(attrStr){
		var fv=0;
		var attrTypeStrArr=attrStr.split(";");
		for (var i=0;i < attrTypeStrArr.length;i++){
			var str=attrTypeStrArr[i];
			var arr=str.split(":");
			var factor=AttributeTypeEnum.getAttrFactor(arr[0]);
			fv+=Math.floor(parseFloat(arr[1])*factor);
		}
		return fv;
	}

	/**
	*检测页签红点s
	*/
	__proto.checkSuitTabRedPoint=function(selectSuitId){
		(selectSuitId===void 0)&& (selectSuitId=0);
		if(!Mgr.guide.isOpen("roleSuit"))
			return;
		this.red.hideRedPoint("roleSuit","roleSuit");
		this.red.hideRedPoint("roleSuitNewRed","roleSuit","roleSuit");
		this.hideAllDaLeiRed();
		this.curSuitId=0;
		var serArr=this.suitSerDic.values;
		var len=serArr.length;
		for (var i=0;i < len;i++){
			var suitMsg=serArr[i];
			var allActiveArr=suitMsg.suitEquipState;
			var curSuitWearNum=0;
			this.red.hideRedPoint("roleSuit","roleSuit"+"_"+suitMsg.id ,RedTypeEnum.RefreshSuitRed);
			var len1=allActiveArr.length;
			for (var j=0;j < len1;j++){
				var cfg=this.getSuitMsgById(suitMsg.id);
				var equipState=allActiveArr[j];
				if(equipState.activeState){
					curSuitWearNum++;
				}
				if(this.curPartIsActive(cfg,equipState)){
					this.setCurSuitId(suitMsg.id);
					this.red.showRedPoint("roleSuitNewRed","roleSuit","roleSuit");
					this.red.showRedPoint("roleSuit",suitMsg.id+"_"+equipState.equipPart ,RedTypeEnum.RefreshSuitRed);
					this.red.showRedPoint("roleSuit","roleSuit"+"_"+suitMsg.id ,RedTypeEnum.RefreshSuitRed);
					this.red.showRedPoint("roleSuit","roleSuit"+"_tab"+cfg.dalei,RedTypeEnum.RefreshSuitRed);
					}else{
					this.red.hideRedPoint("roleSuit",suitMsg.id+"_"+equipState.equipPart ,RedTypeEnum.RefreshSuitRed);
				}
			}
			this.suitNumDic.set(suitMsg.id,curSuitWearNum);
		}
		this.setCurSuitId(this._selectCurSuitId);
		EventCenter.instance.event("GUIDE_SUIT_UPDAE");
	}

	__proto.setCurSuitId=function(suitId){
		if(!this.curSuitId){
			this.curSuitId=suitId;
		}
	}

	/**去掉套装下方页签红点*/
	__proto.hideAllDaLeiRed=function(){
		for (var i=1;i <=this.suitDaLeiNum;i++){
			this.red.hideRedPoint("roleSuit","roleSuit"+"_tab"+i ,RedTypeEnum.RefreshSuitRed);
		}
	}

	__proto.curPartIsActive=function(cfg,suitMsg){
		if(suitMsg.activeState || suitMsg.equipPart==7 || suitMsg.equipPart==8){
			return false;
			}else{
			if(!Mgr.equip.curModel)return false;
			var dic=Mgr.equip.curModel.wearEquipDic;
			if(!dic)return false;
			var equipVo=dic[suitMsg.equipPart];
			if(equipVo && equipVo.cfgItem.itemlevel >=cfg.level && equipVo.rareLv >=cfg.rarelevel && equipVo.cfgItem.star >=cfg.star){
				return true;
			}
		}
		return false;
	}

	/**
	*检测收集装备红点
	*/
	__proto.checkIconRedPoint=function(){
		Laya.timer.callLater(this,this.checkR);
	}

	__proto.checkR=function(){
		FrameSmooth.add(Handler.create(this,this.delayCheck));
	}

	__proto.delayCheck=function(){
		this.checkSuitTabRedPoint();
	}

	/**
	*获取身上的套装数组vo
	*/
	__proto.getSuitWearArr=function(){
		var arr;
		var dic=Mgr.equip.partDic;
		for (var i=0;i < 10;i++){
			var e=dic[i+1];
			if (e && e.cfgItem.suit > 0){
				arr[i]=e;
			}
			else{
				arr[i]=null;
			}
		}
		return arr;
	}

	__proto.setMaxShowSuitTab=function(suitId){
		var nowSuitTab=suitId;
		if(this.maxShowSuitTab !=nowSuitTab){
			Mgr.equipPro.sendCollectEquip();
		}
		this.maxShowSuitTab=nowSuitTab;
	}

	__proto.getMaxShowSuitTab=function(){
		return this.maxShowSuitTab;
	}

	__getset(0,__proto,'selectCurSuitId',null,function(select){
		this._selectCurSuitId=select;
	});

	SuitMgr.ORANGE_RARE=4;
	SuitMgr.RED_RARE=5;
	SuitMgr.GOLD_RARE=6;
	SuitMgr.ORANGE_SUIT_NUM=10;
	SuitMgr.PART_NUM=10;
	return SuitMgr;
})()


