	__proto.checkWuDaoLevelUp=function(lv){
		var lastLv=this.model.getWuDaoLv();
		if(!lastLv||!lv||lastLv==lv)return;
		NetMgr.ins().roleVO.fenghouLevel=lv;
		var cfg=this.getZLDataByTypeLvl(1,lv);
		if(!cfg||!cfg.rewarditem)return;
		UIMgrR.openIView(com.xq.view.modules.fenghoubaijiang.IFengHouUpShow,2);
	}

