//class com.xq.modules.fourteenluxurygifts.FourtenGuideMgr
var FourtenGuideMgr=(function(){
	function FourtenGuideMgr(){
		this._fuLiMgr=null;
		this._xianshiMgr=null;
		this._fuLiMgr=Mgr.fuLiDaTing;
		this._xianshiMgr=Mgr.xianShi;
	}

	__class(FourtenGuideMgr,'com.xq.modules.fourteenluxurygifts.FourtenGuideMgr');
	var __proto=FourtenGuideMgr.prototype;
	__proto.getMinTimeCfg=function(){
		var guideObj;
		var todayArray=this._xianshiMgr.getTodayActivity();
		var len=todayArray.length;
		var ele;
		var stat=0;
		var date;
		var dateTime=NaN;
		var serverTime=NaN;
		var time=NaN;
		var minTime=NaN;
		var minTimeObj;
		if(guideObj)guideObj.type="ZaiXian";
		for(var i=0;i<len;i++){
			ele=todayArray[i];
			stat=this._xianshiMgr.getActivityStat(ele);
			if(stat==2){
				var cfg=ele.getCfgData();
				date=Mgr.xianShi.getOpenDate(ele);
				dateTime=date.getTime();
				serverTime=Mgr.curTime.serverTimer;
				time=dateTime-serverTime;
				cfg.timeDown=time;
				cfg.type="XianShi";
				if(!minTime){
					minTime=time;
					minTimeObj=cfg;
					}else if(time<minTime){
					minTime=time;
					minTimeObj=cfg;
				}
			}
		}
		if(guideObj&&guideObj.timeDown>0){
			if(minTimeObj){
				if(minTimeObj.timeDown<guideObj.timeDown){
					return minTimeObj;
					}else{
					return guideObj;
				}
				}else{
				return guideObj;
			}
		}
		return minTimeObj;
	}

	return FourtenGuideMgr;
})()


