	__class(FourtenMgr,'com.xq.modules.fourteenluxurygifts.FourtenMgr');
	var __proto=FourtenMgr.prototype;
	// EventCenter.instance.on(WeekKaView.YUEKA_INFO,this,refreshRedDot);
	__proto.onFunOpen=function(funcId){
		if(funcId=="fulidating"){
			Mgr.fourteenPro.sendFourteen();
		}
	}

	//拉取数据
	__proto.init=function(){
		this.cfgData_vo.length=0;
		for (var j=0;j < this.data_Array.length;j++){
			var fourteenVO=new FourteenLuxuryGiftsVO();
			fourteenVO.configData=this.data_Array[j];
			var day_=j+1;
			if(this.rewardListoryId.indexOf(day_)>-1){
				fourteenVO.already=true;
			}
			if(day_ <=this.day&&this.rewardListoryId.indexOf(day_)==-1){
				fourteenVO.receive=true;
				}else{
				fourteenVO.receive=false;
			}
			this.cfgData_vo.push(fourteenVO);
		}
	}

	__proto.receiveGet14Day=function(vo){
		if(vo.day > this.data_Array.length){
			this.day=this.data_Array.length;
			}else{
			this.day=vo.day;
		}
		this.setTodayShowReward(vo.rewardListory);
		this.rewardListory=vo.rewardListory;
		this.rewardListoryId=[];
		if(this.rewardListory){
			var len=this.rewardListory.length;
			for (var i=0;i < len;i++){
				this.rewardListoryId.push(this.rewardListory[i].id);
			}
		}
		this.redDot();
		this.refreshRedDot();
		this.init();
		EventCenter.instance.event("BOOL_RECVMESSAGE");
		this.updateForteenGuide(vo.rewardListory.length);
	}

	__proto.updateForteenGuide=function(rewardLen){
		if(!Configs.isForbitIOSPay&&!Configs.isForbitAndroidPay){
			if(Mgr.guide.isOpen("fulidating")){
				if(!this.fourteenGuide){
					this.fourteenGuide=UIMgrR.getIView(com.xq.view.modules.fourteenluxurygifts.IFourteenGuide)
				}
				this.fourteenGuide.open();
				Game.getInstance().getNewMainView().getBox_mainAdd().addChild(this.fourteenGuide);
				var minTimeObj=Mgr.fourtenGuideM.getMinTimeCfg();
				if(minTimeObj){
					EventCenter.instance.event("refresh_time");
				}
			}
		}
	}

	// }
	__proto.closeFourteenGuide=function(){
		if(this.fourteenGuide){
			this.fourteenGuide.dispose();
			this.fourteenGuide.removeSelf();
			this.fourteenGuide=null;
		}
	}

	__proto.setTodayShowReward=function(rewardArr){
		this.todayShowReward=-1;
		var len=rewardArr.length;
		for (var i=0;i < this.day;i++){
			var isGet=false;
			for (var j=0;j < len;j++){
				if(i+1==rewardArr[j].id)
					isGet=true;
			}
			if(!isGet){
				this.todayShowReward=i;
				break ;
			}
		}
		if(this.todayShowReward==-1){
			this.todayShowReward=this.day;
		}
	}

	/**十四日累积登陆更新红点*/
	__proto.redDot=function(){
		this.lingqu_array.length=0;
		for (var j=1;j < this.day;j++){
			if(j <=this.data_Array.length && this.rewardListoryId.indexOf(j)==-1){
				this.lingqu_array.push(j);
			}
		}
	}

	/**八日活动红点数据刷新*/
	__proto.refreshRedDot=function(){
		if(!this.rewardListoryId)return;
		var len=this.data_Array.length;
		for (var i=0;i < len;i++){
			if(this.rewardListoryId.indexOf(i+1)==-1 && this.data_Array[i].number <=this.day){
				this.red.showRedPoint("shisitianhaoli","day"+i,"fulidating");
				}else{
				if(this.rewardListory){
					var leng=this.rewardListory.length;
					for (var j=0;j < leng;j++){
						var rewLis=this.rewardListory[j];
						if(Mgr.chaoZhiTeDianMgr.isBuyYk && !rewLis.tequanIsGet){
							this.red.showRedPoint("shisitianhaoli","day"+i,"fulidating");
							}else{
							this.red.hideRedPoint("shisitianhaoli","day"+i,"fulidating");
						}
					}
					}else{
					this.red.hideRedPoint("shisitianhaoli","day"+i,"fulidating");
				}
			}
		}
		this.closeTbN();
	}

	// Laya.timer.once(500,this,setKelingQu);
	__proto.setKelingQu=function(){
		var flag=this.red.getValue("fulidating").hasCornor;
		if(this.lastFlag !=flag){
			EventCenter.instance.event("MAIN_VIEW_FOURTEN",["fulidating",flag]);
			this.lastFlag=flag;
		}
	}

	__proto.getData=function(i,double){
		if(double > 0){
			i=double*7+i;
		};
		var obj=Mgr.fourtenMgr.cfgData_vo[i];
		return obj
	}

	/**14日礼包页签关闭**/
	__proto.closeTbN=function(){
		if(this.rewardListory){
			var len=this.data_Array.length;
			var leng=this.rewardListory.length;
			if(leng==len){
				for (var i=0;i < leng;i++){
					var rewLis=this.rewardListory[i];
					if(!rewLis.tequanIsGet){
						return;
					}
				}
				EventCenter.instance.event("activity_TabN","shisitianhaoli");
			}
		}
	}

	FourtenMgr.UPDATE_RED_EIGHTDAY="UPDATE_RED_EIGHTDAY";
	return FourtenMgr;
