/**
*福利大厅管理
*@author yangtaiyu
*@date 2019-12-27
*/
//class com.xq.modules.fulidating.FuliDaTingMgr
var FuliDaTingMgr=(function(){
	function FuliDaTingMgr(){
		/**活动版本号*/
		this.flag=NaN;
		/**倒计时*/
		this.mrlcTime=NaN;
		/**是否是永久活动，是则不需要显示活动倒计时*/
		this.isActivity=false;
		this.time=null;
		this.obj=null;
		/**摇钱树加红点*/
		this.isRed_YQS=false;
		/**摇钱树表数组*/
		this.costArr=[];
		this.zxCfgData=null;
		this.qdylCfgData=null;
		this.red=null;
		/**打开面板类型 0按钮 1是其他*/
		this.openType=1;
		//================================获取摇钱树数据做红点判断================================
		this.times=0;
		this.cost=0;
		this.maxTimes=0;
		/**等级礼包领奖数据*/
		this.levelInfo=[];
		/**后端发来的等级礼包数据*/
		this.djlbData=null;
		//========================签到有礼=====================================
		this.qdylInfo=null;
		this.extraInfo=null;
		this.qdArr=[];
		/**存储额外奖励id的数组*/
		this.qdExtArr=[];
		/**是否可领取额外奖励*/
		this.isExt=false;
		//======================定时监听=============================
		this.listenDic={};
		this.removeArr=[];
		this.loopTime=10000;
		this.isJiShi=false;
		this.zxCfgData=CfgManager.getTableCfg("zaixianlingjiang");
		this.qdylCfgData=CfgManager.getTableCfg("QianDaoConfig");
		var collectid="dengjilibao";
		var cfgData_cost=CfgManager.getTableCfg("yaoqianshu");
		var cfgArr=cfgData_cost.objectDataArray;
		this.costArr=cfgArr?cfgArr:[];
		this.red=Mgr.red;
		this.red.regist("fulidating","qiandao",true,"fulidating");
		this.red.regist("fulidating","yaoqianshu",true,"fulidating");
	}

	__class(FuliDaTingMgr,'com.xq.modules.fulidating.FuliDaTingMgr');
	var __proto=FuliDaTingMgr.prototype;
	__proto.getMaxtime=function(currVipLv){
		var cfgData_Vip=CfgManager.getTableCfg("vipbiao");
		var vipObj=cfgData_Vip.getItemByField("lv",currVipLv);
		this.maxTimes=vipObj.yaoqiancount;
	}

	/**获取本次消耗*/
	__proto.getCost=function(currInx){
		var tempLen=this.costArr.length;
		for(var i=0;i<tempLen;i++){
			if(this.costArr[i].id==currInx+1){
				this.cost=this.costArr[i].cost;
				break ;
			}
		}
		return this.cost;
	}

	/**获取摇钱树数据*/
	__proto.getYQSInfo=function(yaoqian){
		if(Mgr.guide.isOpen("yaoqianshu")&& yaoqian){
			var freetime=yaoqian.yuekaTimes;
			this.getMaxtime(NetMgr.ins().roleVO.vipLevel);
			var goldCount=NetMgr.ins().roleVO.yuanbao;
			var index=this.maxTimes-yaoqian.times;
			if(freetime > 0 || index==0){
				this.red.showRedPoint("yaoqianshu","redyqs","fulidating");
			}
			else{
				this.red.hideRedPoint("yaoqianshu","redyqs","fulidating");
			}
		}
	}

	__proto.getDJLBInfo=function(vo){
		this.djlbData=vo;
		this.levelInfo=vo.rewards;
	}

	/**获取签到有礼表格数据*/
	__proto.getQDYLData=function(type,value){
		return this.qdylCfgData.getAllItemByFiled(type,value);
	}

	__proto.getQDYLDataArr=function(){
		return this.qdylCfgData.objectDataArray;
	}

	__proto.getQDYLInfo=function(vo){
		this.qdylInfo=vo;
		var now=Mgr.curTime.serverTimer;
		var nowTime=CommonUtil.formatDate(now,7);
		var last=this.qdylInfo.lastSigninTime;
		var lasttime=CommonUtil.formatDate(last,7);
		this.qdArr=this.getQDYLDataArr();
		this.qdExtArr.length=0;
		var day=this.qdylInfo.signinedDays;
		var circle=Math.ceil(day / 30);
		if(circle==0)
			circle=1;
		var qdLen=this.qdArr.length;
		for(var i=0;i<qdLen;i++){
			var item=this.qdArr[i];
			if(item.extraReward!="" && item.circle==circle){
				this.qdExtArr.push(this.qdArr[i].id);
			}
		};
		var qdExLen=this.qdExtArr.length;
		var arr=this.qdylInfo.extraRewardHistory;
		this.isExt=false;
		for(var j=0;j<qdExLen;j++){
			var exdy=parseInt(this.qdExtArr[j]);
			if(exdy<=day&&arr.indexOf(exdy)==-1){
				this.isExt=true;
			}
		}
		if(Mgr.guide.isOpen("qiandao")){
			if(nowTime!=lasttime||last==0||this.isExt){
				this.red.showRedPoint("qiandao","redqd","fulidating");
			}
			else{
				this.red.hideRedPoint("qiandao","redqd","fulidating");
			}
		}
		EventCenter.instance.event("on_get_qiandao_pull");
	}

	// EventCenter.instance.event(FuliDaTingView.UPDATE_RED_POINT);
	__proto.getQDYLExInfo=function(vo){
		this.extraInfo=vo;
		EventCenter.instance.event("extra_rewade");
	}

	/**添加监听
	*type:监听事件类型
	*id:
	*time:倒计时 剩余时间
	**/
	__proto.addListen=function(type,id,time){
		if(time > 0)
			this.listenDic[type+"-"+id]=time;
		else{
			if(time < 0)
				this.sendEvent(type+"-"+id);
			delete this.listenDic[type+"-"+id];
			return;
		}
		if(!this.isJiShi){
			this.isJiShi=true;
			Laya.timer.loop(this.loopTime,this,this.daosjishi,null,true,true);
		}
	}

	/**计时器*/
	__proto.daosjishi=function(){
		var num=0;
		this.removeArr.length=0;
		for(var name in this.listenDic){
			var time=this.listenDic[name];
			if(time<=0){
				this.removeArr.push(name);
				this.sendEvent(name);
			}
			else{
				time=time-this.loopTime;
				this.listenDic[name]=time;
				num++;
			}
		}
		if(this.removeArr.length > 0)
			Laya.timer.frameOnce(1,this,this.removeListen,null,false);
		if(num==0){
			Laya.timer.clear(this,this.daosjishi);
			this.isJiShi=false;
		}
	}

	__proto.removeListen=function(){
		var len=this.removeArr.length;
		for(var i=0;i < len;i++){
			delete this.listenDic[this.removeArr[i]];
		}
		this.removeArr.length=0;
	}

	/**发出事件*/
	__proto.sendEvent=function(name){
		var arr=name.split("-");
		var type=parseInt(arr[0]);
		var id=parseInt(arr[1]);
		switch(type){
			case 0:
				break ;
			}
	}

	// }
	__proto.activitTime=function(activiTyen){
		var opAct=NewActiveManager.ins.getActiveVerDic(activiTyen);
		if(opAct){
			this.flag=opAct.flag;
			this.mrlcTime=opAct.endTime;
			this.isActivity=opAct.isForeverActivity;
		}
	}

	FuliDaTingMgr.ZIAXIAN=1;
	FuliDaTingMgr.UPDATAYQS="updataYQS";
	return FuliDaTingMgr;
})()


