/**
*@author:huanghong
*@date:2022-6-30
*@desc:在线礼包mgr
*/
//class com.xq.modules.fulidating.ZaiXianLiBaoMgr
var ZaiXianLiBaoMgr=(function(){
	function ZaiXianLiBaoMgr(){
		this._model=null;
		this._red=null;
		this._icon=null;
		this._model=new ZaiXianLiBaoModel();
		this.registRed();
		FunctionOpenMgr.ins.registNewFuncOpenHandler("ZaiXianHongBao",Handler.create(this,this.onNewFuncOpen))
	}

	__class(ZaiXianLiBaoMgr,'com.xq.modules.fulidating.ZaiXianLiBaoMgr');
	var __proto=ZaiXianLiBaoMgr.prototype;
	__proto.onNewFuncOpen=function(funId){
		this.getInfo();
	}

	/**在线奖励展示数据*/
	__proto.getShowArr=function(){
		var flag=NewActiveManager.ins.getActiveFlag(70);
		var arr=this._model.getElesByFlagAndType(flag,1).concat();
		arr=arr.sort(this.compare);
		return arr;
	}

	/**获取距离下一个可领取的的时间*/
	__proto.getNextTime=function(){
		var flag=NewActiveManager.ins.getActiveFlag(70);
		return this._model.getNextTime(flag);
	}

	/**奖励状态
	*1:可领取
	*2:未达成
	*3：特权可领取
	*4：全部领取完成
	**/
	__proto.checkEleStat=function(ele){
		return this._model.checkEleStat(ele);
	}

	/**距离可领取时间*/
	__proto.getTimeLeft=function(ele){
		return this._model.getTimeLeft(ele);
	}

	__proto.compare=function(eleA,eleB){
		return eleA.sortIndex-eleB.sortIndex;
	}

	/**时间转换*/
	__proto.formToTimeString=function(_time,_insertHout,_insertMinute){
		if(!_insertHout){
			_insertHout=Lang.str(1036)
		}
		if(!_insertMinute){
			_insertMinute=Lang.str(898)
		};
		var _hour=_time / 60 / 60 >> 0;
		var _minute=(_time / 60)% 60;
		var _timeTxt="";
		if(_hour>0){
			_timeTxt+=((_hour > 100)? _hour.toString():_hour.toString())+_insertHout;
			if(_minute > 0){
				var string="";
				string+=((_minute < 10)?(_minute.toString()):_minute.toString())+_insertMinute;
				_timeTxt=_timeTxt+string;
			}
			}else{
			_timeTxt+=((_minute < 10)?(_minute.toString()):_minute.toString())+_insertMinute;
		}
		return _timeTxt;
	}

	//-------------------在线红包---------------------
	__proto.getShowEle=function(){
		var flag=NewActiveManager.ins.getActiveFlag(70);
		var arr=this._model.getElesByFlagAndType(flag,2).concat();
		arr=arr.sort(this.compare);
		var ele=arr[0];
		if(!ele)return null;
		if(this.checkEleStat(ele)>=3)return arr[arr.length-1];
		return ele;
	}

	__proto.updateZaiXianHongBaoIconVis=function(){
		if(Configs.isForbitAndroidPay||Configs.isForbitIOSPay)return;
		if(!Mgr.guide.isOpen("ZaiXianHongBao"))return;
		var ele=this.getShowEle();
		if(!ele||this.checkEleStat(ele)>2){
			if(this._icon){
				this._icon.dispose();
				this._icon.removeSelf();
				this._icon=null;
			}
		}
		else{
			if(!this._icon){
				this._icon=UIMgrR.getIView(com.xq.view.modules.zaiXianHongBao.IZaiXianHongBaoIcon)
			}
			this._icon.open();
			Game.getInstance().getNewMainView().getBox_mainAdd().addChild(this._icon);
		}
	}

	/**获取累计元宝*/
	__proto.getAccumulativeYB=function(){
		var accYb=0;
		var flag=NewActiveManager.ins.getActiveFlag(70);
		var arr=this._model.getElesByFlagAndType(flag,2)
		var len=arr.length;
		var ele;
		var stat=0;
		var onlineTime=this._model.getOnlieTime();
		var ifNext=false;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.checkEleStat(ele);
			if(stat==2){
				accYb+=Math.floor(this.getYbNum(ele)*(onlineTime/(parseInt(ele.getCfgData().time)*1000)));
				return accYb;
			}
			else{
				accYb+=this.getYbNum(ele);
			}
		}
		return accYb;
	}

	/**获取已领取总元宝数*/
	__proto.getRecYb=function(){
		var flag=NewActiveManager.ins.getActiveFlag(70);
		var arr=this._model.getElesByFlagAndType(flag,2)
		var len=arr.length;
		var ele;
		var stat=0;
		var accYb=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.checkEleStat(ele);
			if(stat>2){
				accYb+=this.getYbNum(ele);
			}
		}
		return accYb;
	}

	__proto.getYbNum=function(ele){
		if(!ele)return 0;
		var cfg=ele.getCfgData();
		var reward=cfg.jiangli;
		var num=reward.split(":")[1];
		return parseInt(num);
	}

	/**获取当前 元宝增加速度*/
	__proto.getAddSpeed=function(){
		var v=0;
		var ele=this.getAddEle();
		if(!ele)return v;
		var cfg=ele.getCfgData();
		var time=parseInt(cfg.time);
		var reward=cfg.jiangli;
		var num=parseInt(reward.split(":")[1]);
		v=num/time;
		return v;
	}

	__proto.getAddEle=function(){
		var flag=NewActiveManager.ins.getActiveFlag(70);
		var arr=this._model.getElesByFlagAndType(flag,2)
		var len=arr.length;
		var ele;
		var stat=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.checkEleStat(ele);
			if(stat==2){
				return ele;
			}
		}
		return null;
	}

	/**刷新所有数据*/
	__proto.updateInfo=function(msg){
		var flag=NewActiveManager.ins.getActiveFlag(70);
		var curTime=Mgr.curTime.serverTimer;
		this._model.updateInfo(msg,flag,curTime);
		EventCenter.instance.event("ZXLB_UpdateInfo");
		this.updateZXLBRed();
		this.updateZaiXianHongBaoIconVis();
		this.sendNextTime();
	}

	__proto.updateReward=function(msg){
		if(msg.errCode==1){
			this._model.updateReward(msg);
			var ele=this._model.getEle(msg.id);
			if(ele){
				var cfg=ele.getCfgData();
				var type=cfg.type;
			}
			EventCenter.instance.event("ZXLB_UpdateReward",[type]);
			this.updateZXLBRed();
		}
		else{
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(msg.errCode));
		}
	}

	/***/
	__proto.sendNextTime=function(){
		var nextTime=this.getNextTime();
		if(nextTime>0){
			Laya.timer.once(nextTime,this,this.getInfo);
		}
	}

	__proto.getInfo=function(){
		Mgr.onlineReward.sendGetOnlineRewardInfo();
	}

	//==========红点相关============
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("fulidating","zaixianlibao",true,"fulidating");
	}

	__proto.updateZXLBRed=function(){
		if(!Mgr.guide.isOpen("zaixianlibao"))return;
		var flag=NewActiveManager.ins.getActiveFlag(70);
		var arr=this._model.getElesByFlagAndType(flag,1);
		var len=arr.length;
		var ele;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(this.checkEleStat(ele)==1){
				this._red.showRedPoint("zaixianlibao","reward","zaixianlibao");
				return;
			}
		}
		this._red.hideRedPoint("zaixianlibao","reward","zaixianlibao");
	}

	//==========活动注册===========
	__proto.regActive=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["zaixianlibao"]);
		ActManager.ins.regist("fulidating","zaixianlibao",70,"FuLiHallEvent");
		var zaixianOpen=Handler.create(this,this.openActive,["zaixianlibao"],false);
		NewActiveManager.ins.regActOpenHandler(70,zaixianOpen);
		NewActiveManager.ins.regActEndHandler(70,Handler.create(this,this.closeAct,[70],false));
	}

	//在线奖励
	__proto.openActive=function(func){
		if(func=="zaixianlibao"){
			Mgr.onlineReward.sendGetOnlineRewardInfo();
			EventCenter.instance.event("ACTIVE_TOGGLE",["zaixianlibao",false]);
		}
	}

	__proto.closeAct=function(actId){
		if(actId==70){
			Mgr.red.hideAll("zaixianlibao","fulidating");
			EventCenter.instance.event("ACTIVE_TOGGLE",["zaixianlibao"]);
		}
	}

	return ZaiXianLiBaoMgr;
})()


