/**
*篝火Vo
*@author zhanglimin
*@date 2020-5-21
**/
//class com.xq.modules.gouhuo.GouHuoVo
var GouHuoVo=(function(){
	function GouHuoVo(){
		/**当前版本*/
		this.flag=0;
		/**道具ID*/
		this.items=null;
		/**升级篝火所需经验值*/
		this.maxExp=0;
		/**使用后获得道具*/
		this.goods=null;
		/**当前篝火等级名称*/
		this.fireName=null;
		/**篝火资源路径*/
		this.fireNameUrl=null;
		/**篝火倍率*/
		this.fireRate=null;
		/**下一级篝火倍率*/
		this.nextFireRate=null;
		/**篝火奖励展示*/
		this.rewards=null;
		/**篝火坐标*/
		this.pos=null;
		/**次数限制*/
		this.nums=null;
		/**随机坐标池*/
		this.poPool=null;
		/**随机坐标点数量*/
		this.randlen=0;
		/**升级经验*/
		this.firelevels=null;
		/**随机语句池*/
		this.talkPool=null;
		/**语句长度*/
		this.talkLen=0;
		this.firenum=null;
	}

	__class(GouHuoVo,'com.xq.modules.gouhuo.GouHuoVo');
	var __proto=GouHuoVo.prototype;
	__proto.init=function(flag,obj){
		flag=flag;
		this.items=obj.items;
		this.nums=obj.nums;
		this.setGoods(obj.goods);
		this.setFirenum(obj.firenum);
		this.firelevels=obj.firelevels;
		this.rewards=obj.rewards;
		this.talkPool=obj.talk;
		this.talkLen=this.talkPool.length;
		this.pos=new Point(parseInt(obj.pos[0]),parseInt(obj.pos[1]));
		this.initPo(obj);
	}

	/**初始化坐标池*/
	__proto.initPo=function(obj){
		var ranAry=obj.expPo;
		var len=ranAry.length;
		this.poPool=[];
		for (var i=0;i < len;i++){
			var temp=ranAry[i].split(":");
			var po=new Point(parseInt(temp[0]),parseInt(temp[1]));
			this.poPool.push(po);
		}
		this.randlen=this.poPool.length;
	}

	/**初始化使用后的奖励道具*/
	__proto.setGoods=function(_goods){
		var ary=_goods.split(",");
		var len=ary.length;
		this.goods=[];
		for (var i=0;i < len;i++){
			this.goods.push(ary[i].split(";"));
		}
	}

	/**初始化收益倍数*/
	__proto.setFirenum=function(ary){
		this.firenum=[];
		var len=ary.length;
		for (var i=0;i < ary.length;i++){
			var per=parseFloat(ary[i])*100;
			this.firenum.push(per);
		}
	}

	/**篝火名称*/
	__proto.setFireName=function(lv){
		switch(lv){
			case 0:
				this.fireNameUrl="chu";
				this.fireName=Lang.str(2493);
				break ;
			case 1:
				this.fireNameUrl="zhong";
				this.fireName=Lang.str(2494);
				break ;
			case 2:
				this.fireNameUrl="gao";
				this.fireName=Lang.str(2495);
				break ;
			}
		this.fireNameUrl=PathDefine.gettxtImg(this.fireNameUrl);
	}

	/**等级改变，刷新信息*/
	__proto.update=function(lv){
		this.setFireName(lv);
		this.fireRate=this.firenum[lv]+"%";
		this.maxExp=parseInt(this.firelevels[lv]);
		this.nextFireRate=this.firenum[lv+1]? this.firenum[lv+1]+"%":Lang.str(2496);
	}

	/**获取一个随机点*/
	__proto.getRandPo=function(){
		var index=Math.round(Math.random()*this.randlen);
		return this.poPool[index];
	}

	/**获取一句话*/
	__proto.getRandTalk=function(){
		var index=Math.round(Math.random()*this.talkLen);
		return this.talkPool[index];
	}

	return GouHuoVo;
})()


