	__proto.initCardInfo=function(msg){
		this.cardInfo.set(msg.id,msg);
	}

	/**根据id获取卡片信息*/
	__proto.getCardMsgById=function(id){
		return this.cardInfo.get(id);
	}

	/**获取最近可操作的卡片ID*/
	__proto.getNearCard=function(){
		var minId=1;
		var jhID=-1;
		if(this.cardInfo){
			var ary=this.cardInfo.values;
			var len=ary.length;
			for (var i=0;i < len;i++){
				var msg=ary[i];
				if(msg){
					if(!msg.isActivated){
						if(msg.progress >=9){
							minId=msg.id;
							break ;
						}
						else{
							var cfg=this.getCardCfg(msg.id);
							if(cfg){
								if(Mgr.item.checkMatIsEnou(cfg.costItem,1)){
									minId=msg.id;
									break ;
								}
							}
						}
					}
					else{
						jhID=msg.id
					}
				}
			}
		}
		if(minId==1 && jhID !=-1){
			minId=jhID+1;
		}
		if(minId > this.maxCardNum)
			minId=this.maxCardNum;
		return minId;
	}

