	__proto.enterChanllenge=function(){
		if(this.gqInfo && !NetMgr.ins().roleVO.isInCopy && this.gqInfo.killed >=this.gqInfo.killNeed && !this.allComplete){
			if(this.gqInfo.nextPower<=NetMgr.ins().roleVO.fightValue){
				Mgr.gqProMgr.reqRollOver(this.gqInfo.nextLevel);
				return true;
			}
			else{
				Mgr.gqProMgr.reqEnterChan(this.gqInfo.nextLevel);
				return false;
			}
		}
		return false;
	}

