/**
*@author:huanghong
*@date:2022-3-1
*@desc:功能 开启管理类
*/
//class com.xq.modules.guide.FunctionOpenMgr
var FunctionOpenMgr=(function(){
	function FunctionOpenMgr(){
		this._model=null;
		this._roleVo=null;
		this._openFuncDic=null;
		this._isShow=false;
		this._openFuncHandlerDic={};
		this._model=new FunctionOpenModel();
		this._roleVo=NetMgr.ins().roleVO;
		this.startListener();
		this._openFuncDic={};
	}

	__class(FunctionOpenMgr,'com.xq.modules.guide.FunctionOpenMgr');
	var __proto=FunctionOpenMgr.prototype;
	__proto.startListener=function(){
		EventCenter.instance.onQue("LEVEL_UP",this,this.checkFuncByOpenType,[GuideEnum.level]);
		EventCenter.instance.on("MAIN_TASK_COMPLETE",this,this.checkFuncByOpenType,[GuideEnum.task]);
		EventCenter.instance.on("BaiJiangUpLevel",this,this.checkFuncByOpenType,[GuideEnum.baijiangLv]);
		EventCenter.instance.on("CrossDays",this,this.checkFuncByOpenType,[GuideEnum.openDay]);
		EventCenter.instance.on("guanqia_changeEvent",this,this.checkFuncByOpenType,[GuideEnum.guanqia]);
		EventCenter.instance.on("VIPLEVEL_CHANGE",this,this.checkFuncByOpenType,[GuideEnum.svip]);
	}

	__proto.stopListener=function(){
		EventCenter.instance.offQue("LEVEL_UP",this,this.checkFuncByOpenType);
		EventCenter.instance.off("MAIN_TASK_COMPLETE",this,this.checkFuncByOpenType);
		EventCenter.instance.off("BaiJiangUpLevel",this,this.checkFuncByOpenType);
		EventCenter.instance.off("CrossDays",this,this.checkFuncByOpenType);
		EventCenter.instance.off("guanqia_changeEvent",this,this.checkFuncByOpenType);
		EventCenter.instance.off("VIPLEVEL_CHANGE",this,this.checkFuncByOpenType);
	}

	/**在这里注册新功能开启的回调 例子：yuanshenMgr */
	__proto.registNewFuncOpenHandler=function(funcId,handler){
		if(!this.checkFuncIsOpen(funcId)){
			this._openFuncHandlerDic[funcId]=handler;
		}
	}

	__proto.checkFuncIsOpen=function(funcId,showTip){
		(showTip===void 0)&& (showTip=false);
		var ele=this._model.getOpenEleByFuncId(funcId);
		if(!ele||ele.getValue("IsOpened"))return true;
		if(showTip){
			Mgr.prompt.optionPrompt(this.setTipDesc(ele));
		}
		return false;
	}

	/**未开启时是否需要隐藏*/
	__proto.checkFuncHide=function(funcId){
		var ele=this._model.getOpenEleByFuncId(funcId);
		if(!ele)return false;
		var cfg=ele.getCfgData();
		return cfg.isHide;
	}

	__proto.setTipDesc=function(ele){
		var cfg=ele.getCfgData();
		var privilegeOpenDesc=this.getTipStr(cfg.openType,cfg.openValue);
		var limitOneDesc=this.getTipStr(cfg.limit,cfg.value);
		var limitTwoDesc="";
		if(cfg.limit2=="0"){
			var valueTwo=cfg.value2;
			var limitArr=valueTwo.split(";");
			var len=limitArr.length;
			var limitStr;
			for(var i=0;i<len;i++){
				limitStr=limitArr[i];
				var limitStrArr=limitStr.split(":");
				var type=limitStrArr[0];
				var value=limitStrArr[1];
				limitTwoDesc+=this.getTipStr(parseInt(type),value)+Lang.str(2308);
			}
			limitTwoDesc=limitTwoDesc.substring(0,limitTwoDesc.length-1);
		}
		else{
			limitTwoDesc=this.getTipStr(cfg.limit2,cfg.value2);
		};
		var desc="";
		if(privilegeOpenDesc){
			desc+=privilegeOpenDesc+Lang.str(3319)+",";
		}
		if(limitTwoDesc){
			desc+=limitTwoDesc+Lang.str(3320);
		}
		if(limitOneDesc){
			desc+=limitOneDesc+Lang.str(1191);
		}
		return desc;
	}

	//Lang.str(2309);
	__proto.getTipStr=function(limit,value){
		if(limit==1){
			return Lang.str(2513)+value+Lang.str(251);
		}
		if(limit==2){
			var tempVo=Mgr.task.getTaskVoById(value);
			if(tempVo){
				return Lang.str(2310)+tempVo.name2+Lang.str(3321);
			}
		}
		else if(limit==3){
			return Lang.str(685)+Mgr.fhMgr.getZhuanShengInfo(value);
		}
		else if(limit==4){
			return Lang.str(2312)+value+Lang.str(477);
		}
		else if(limit==5){
			return Lang.str(2314)+value+Lang.str(527);
		}
		else if(limit==6){
			return Lang.str(2316)+value+Lang.str(251);
		}
		return ""
	}

	/**检测所有的功能 当前是否有开启了但没有记录的功能*/
	__proto.checkAllFunc=function(){
		var arr=this._model.getFuncOpenDc().array;
		var len=arr.length;
		var ele;
		var cfg;
		var ifOpened=false;
		var hadOpenCount=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			ifOpened=ele.getValue("IsOpened");
			if(ifOpened){
				hadOpenCount++
				continue ;
			}
			cfg=ele.getCfgData();
			if(!cfg.openType&&cfg.limit==GuideEnum.notOpen){
				hadOpenCount++
				continue ;
			}
			if(this.checkFuncOpen(cfg)){
				this.updateOneFunctionOpened(cfg.id);
			}
		}
		EventCenter.instance.event("FUN_OPEN_INIT");
		if(hadOpenCount==len){
			this.stopListener();
		}
	}

	/**根据条件类型判断是否含有该条件的功能是否达到开启条件*/
	__proto.checkFuncByOpenType=function(openType){
		var arr=this._model.getNotOpenCfgArrByType(openType);
		if(!arr)return;
		var len=arr.length;
		var cfg;
		for(var i=0;i<len;i++){
			cfg=arr[i];
			if(this.checkFuncOpen(cfg)){
				this.newFuncOpen(cfg);
			}
		}
	}

	/**检测功能是否开启了*/
	__proto.checkFuncOpen=function(cfg){
		if(!cfg)return false;
		var privilegeOpenType=cfg.openType;
		if(privilegeOpenType&&this.checkLimit(privilegeOpenType+"",cfg.openValue)){
			return true;
		};
		var limitOne=cfg.limit;
		var limitOneOk=!limitOne||(this.checkLimit(limitOne,cfg.value));
		if(!limitOneOk)return false;
		var limitTwo=cfg.limit2;
		var limitTwoOk=false;
		if(!limitTwo){
			limitTwoOk=true;
		}
		else{
			if(limitTwo=="0"){
				var valueTwo=cfg.value2;
				var limitArr=valueTwo.split(";");
				var len=limitArr.length;
				var limitStr;
				for(var i=0;i<len;i++){
					limitStr=limitArr[i];
					var limitStrArr=limitStr.split(":");
					var type=limitStrArr[0];
					var value=limitStrArr[1];
					if(this.checkLimit(type,value)){
						limitTwoOk=true;
						break ;
					}
				}
			}
			else{
				limitTwoOk=this.checkLimit(limitTwo,cfg.value2);
			}
		}
		return limitTwoOk;
	}

	__proto.checkLimit=function(type,value){
		switch(type){
			case GuideEnum.level:{
					return this.checkLimitLevel(value);
				}
			case GuideEnum.task:{
					return this.checkLimitTask(value);
				}
			case GuideEnum.baijiangLv:{
					return this.checkLimitZsLv(value);
				}
			case GuideEnum.openDay:{
					return this.checkLimitServerDay(value);
				}
			case GuideEnum.guanqia:{
					return this.checkLimitGuanQia(value);
				}
			case GuideEnum.svip:{
					return this.checkLimitSvip(value);
				}
			}
		return false;
	}

	/**检测角色等级是否满足条件*/
	__proto.checkLimitLevel=function(value){
		var lv=this._roleVo.level;
		return lv>=parseInt(value);
	}

	/**检测角色是否完成某任务*/
	__proto.checkLimitTask=function(value){
		var curTask=Mgr.task.curTask;
		if(!curTask)return false;
		if((curTask.id2==value && curTask.state==2)||Mgr.task.model.compareTaskId(curTask.id2,value)){
			return true;
		}
		return false;
	}

	/**检测转生等级是否满足条件*/
	__proto.checkLimitZsLv=function(value){
		var zsLv=NetMgr.ins().roleVO.baiJiangLevel;
		return zsLv >=parseInt(value);
	}

	/**检测开服天数是否满足条件*/
	__proto.checkLimitServerDay=function(value){
		var needT=parseInt(value);
		var openT=CommonUtil.openServerDay;
		return needT && needT <=openT;
	}

	/**检测关卡是否满足条件*/
	__proto.checkLimitGuanQia=function(value){
		var info=Mgr.gqMgr.gqInfo;
		if(!info)return false;
		var gqlv=info.nextLevel-1;
		return gqlv >=parseInt(value)
	}

	/**检测svip等级是否满足条件*/
	__proto.checkLimitSvip=function(value){
		var svip=NetMgr.ins().roleVO.vipLevel;
		return svip >=parseInt(value);
	}

	/**检测发现新功能开启了*/
	__proto.newFuncOpen=function(cfg){
		if(!cfg)return;
		var funcId=cfg.id;
		this.checkShowTip(cfg);
		this.updateOneFunctionOpened(funcId);
		var handler=this._openFuncHandlerDic[funcId];
		if(handler){
			handler.runWith(funcId);
			this._openFuncHandlerDic[funcId]=null;
			handler.recover();
		}
		EventCenter.instance.event("new_function_open",[funcId]);
		Mgr.guide.sendFuncOpenId(funcId);
	}

	/**检测是否需要添加至展示队列*/
	__proto.checkShowTip=function(cfg){
		if(!cfg.functionimg||this._openFuncDic[cfg.id])return;
		this._openFuncDic[cfg.id]=cfg;
		Mgr.chipPopMgr.addTeam(Handler.create(this,this.openFuncTip,[cfg]),-1);
	}

	/**展示funcopenTip*/
	__proto.openFuncTip=function(cfg){
		if(!cfg){
			Mgr.chipPopMgr.next();
			return;
		};
		var fun=UIMgrR.openIView(com.xq.view.modules.guide.INewFuncOpenTip,3);
		fun.dataSource=cfg;
	}

	/**刷新后端记录的已开启的功能*/
	__proto.updateOpenedInfo=function(msg){
		this._model.updateOpenedInfo(msg);
		this.checkAllFunc();
	}

	/**记录开启的一个功能*/
	__proto.updateOneFunctionOpened=function(funcId){
		NewGuideAction.Ins.sendFuncOpenMark(funcId);
		this._model.updateOneFunc(funcId);
	}

	__getset(1,FunctionOpenMgr,'ins',function(){
		return FunctionOpenMgr._ins=FunctionOpenMgr._ins|| new FunctionOpenMgr();
	});

	FunctionOpenMgr._ins=null;
	return FunctionOpenMgr;
})()


