//class com.xq.modules.guide.FunctionPreviewMgr
var FunctionPreviewMgr=(function(){
	function FunctionPreviewMgr(){
		this._red=null;
		this._model=null;
		this._previewView=null;
		this._model=new FunctionPreviewModel();
		this.registRed();
	}

	__class(FunctionPreviewMgr,'com.xq.modules.guide.FunctionPreviewMgr');
	var __proto=FunctionPreviewMgr.prototype;
	__proto.checkIsShowPreview=function(){
		return this._previewView;
	}

	/**获取所有展示配置数据字典*/
	__proto.getAllPreviewArr=function(){
		return this._model.getPreviewDc().array;
	}

	/**获取默认选中功能下标*/
	__proto.getDefuatIndex=function(){
		var arr=this._model.getPreviewDc().array;
		var len=arr.length;
		var ele;
		var stat=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.checkEleStat(ele);
			if(stat==1||stat==0)return i;
		}
		return len-1;
	}

	/**获取主界面预览图标*/
	__proto.getPreviewView=function(){
		return this._previewView;
	}

	/**获取下一个未开启的功能*/
	__proto.getNextFuncEle=function(){
		var arr=this._model.getPreviewDc().array;
		var len=arr.length;
		var ele;
		var stat=0;
		var hasReward=false;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.checkEleStat(ele);
			if(stat==0)return ele;
		}
		return null;
	}

	/**刷新主界面 功能预览图标数据和状态*/
	__proto.updatePreviewIcon=function(){
		var ele=this.getShowEle();
		var mainV=Game.getInstance().getNewMainView();
		if(!ele){
			if(this._previewView){
				this._previewView.removeSelf();
				this._previewView.gc();
				this._previewView=null;
				EventCenter.instance.off("new_function_open",this,this.updatePreviewIcon);
				EventCenter.instance.off("new_function_open",this,this.updateRed);
				EventCenter.instance.event("close_yulan_icon");
			};
			var scaleButton=mainV.getCustomTitle();
			if(Mgr.guide.isOpen("CustomTitle")){
				scaleButton.visible=true;
				}else{
				scaleButton.visible=false;
			}
		}
		else{
			if(!this._previewView){
				this._previewView=UIMgrR.getIView(com.xq.view.mainUI.subPanel.yulan.IYuLan);
				if(mainV){
					mainV.addChild(this._previewView);
					mainV.setChildIndex(this._previewView,3);
					Game.getInstance().getNewMainView().addViewToHide(this._previewView,1);
					Game.getInstance().getNewMainView().addViewToHide(this._previewView,2);
				}
				EventCenter.instance.on("new_function_open",this,this.updatePreviewIcon);
				EventCenter.instance.on("new_function_open",this,this.updateRed);
			}
			this._previewView.dataSource=ele;
		}
	}

	/**获取主界面展示预览数据*/
	__proto.getShowEle=function(){
		var arr=this._model.getPreviewDc().array;
		var len=arr.length;
		var ele;
		var stat=0;
		var hasReward=false;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.checkEleStat(ele);
			if(stat==0)return ele;
			if(stat==1){
				hasReward=true;
			}
		}
		if(hasReward)return ele;
		return null;
	}

	/**检测功能状态
	*0：未开启
	*1：开启可领取
	*2：已领取
	**/
	__proto.checkEleStat=function(ele){
		if(!ele)return 0;
		var cfg=ele.getCfgData();
		var funcId=cfg.funC;
		if(!FunctionOpenMgr.ins.checkFuncIsOpen(funcId)){
			return 0;
		};
		var isGot=ele.getValue("Got");
		if(isGot)return 2;
		return 1;
	}

	/**预览奖励信息*/
	__proto.updateInfo=function(msg){
		this._model.updateInfo(msg);
		this.updatePreviewIcon();
		this.updateRed();
	}

	/**领取奖励后刷新数据*/
	__proto.updateReward=function(msg){
		this._model.updateReward(msg);
		EventCenter.instance.event("GetRewardYuLan");
		this.updatePreviewIcon();
		this.updateRed();
	}

	//=====红点=============
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.registSilRed("YuLan",RedTypeEnum.YulanRed);
	}

	/**刷新红点数据*/
	__proto.updateRed=function(){
		var arr=this._model.getPreviewDc().array;
		var len=arr.length;
		var ele;
		var cfg;
		var funcId;
		var isGot=false;
		for(var i=0;i<len;i++){
			ele=arr[i];
			cfg=ele.getCfgData();
			funcId=cfg.funC;
			isGot=ele.getValue("Got");
			if(!FunctionOpenMgr.ins.checkFuncIsOpen(funcId)||isGot){
				this._red.hideRedPoint("YuLan",cfg.id,RedTypeEnum.YulanRed);
			}
			else{
				this._red.showRedPoint("YuLan",cfg.id,RedTypeEnum.YulanRed);
			}
		}
	}

	__getset(1,FunctionPreviewMgr,'ins',function(){
		return FunctionPreviewMgr._ins=FunctionPreviewMgr._ins|| new FunctionPreviewMgr();
	});

	FunctionPreviewMgr._ins=null;
	return FunctionPreviewMgr;
})()


