//class com.xq.modules.guide.GuideActivityMgr
var GuideActivityMgr=(function(){
	function GuideActivityMgr(){
		this.isPermit=false;
		this.needShowViewArr=null;
		this.activityPreCfg=null;
		this.cfgDic=null;
		/**活动关联注册字典*/
		this.activeDic=null;
		this.id=0;
		//1优先级最高
		this.mLv=0;
		this.openDay=0;
		this.mTask=0;
		this.activityPreCfg=CfgManager.getTableCfg("activityPre");
		var arr=this.activityPreCfg.objectDataArray;
		var len=arr.length;
		this.cfgDic={};
		for(var i=0;i < len;i++){
			var o=arr[i];
			this.cfgDic[o.prio]=o;
		}
		this.activeDic={};
		this.activeDic[1]=Mgr.xianShiZheKouPro;
		this.activeDic[2]=Mgr.operationPro;
		this.activeDic[3]=Mgr.vip;
	}

	__class(GuideActivityMgr,'com.xq.modules.guide.GuideActivityMgr');
	var __proto=GuideActivityMgr.prototype;
	__proto.checkLimit=function(){
		this.id++;
		if(this.id>=2){
			this.mLv=NetMgr.ins().roleVO.level;
			this.openDay=CommonUtil.openServerDay;
			this.mTask=Mgr.task.curTask.num;
			this.needShowViewArr=[];
			this.starCheck(1);
		}
	}

	__proto.starCheck=function(prio,flag){
		(flag===void 0)&& (flag=false);
		if(this.isPermit)
			return;
		var o=this.cfgDic[prio];
		if(o){
			var isOpen=Mgr.guide.isOpen(o.key);
			if(isOpen){
				var lv=o.conditionLevel;
				var sd=o.conditionKaifuDay;
				var ts=o.conditontask;
				if(this.mLv >=lv && this.openDay <=sd && this.mTask>=ts){
					var arr=o.activity;
					if(arr && arr[0]!=""){
						var len=arr.length;
						for(var i=0;i < len;i++){
							var temArr=arr[i].split("_");
							var id=parseInt(temArr[0]);
							var tid=this.activeDic[id].getActiveId();
							if(tid==-1){
								if(!flag)
									Laya.timer.once(1000,this,this.starCheck,[prio,true]);
								return;
							}
							else if(tid==parseInt(temArr[1])){
								if(Mgr.kaiFuHDMgr.progress==0){
									if(Mgr.guide.isOpen("shouchongsanrilibao")){
										Laya.timer.once(3000,this,this.openViewById,[o.view]);
									}
								}
								else if(o.view=="100000")
								UIMgrR.openIView(com.xq.view.modules.shouchonghaoli.IMeiRiShouChongView);
								this.needShowViewArr.push(o.view);
							}
						}
					}
					else{
						this.needShowViewArr.push(o.view);
					}
				}
				this.starCheck(prio+1);
			}
		}
		else{
		}
	}

	__proto.openViewById=function(uiId){
		UIMgrR.navigateToViewByID(uiId,null,2);
	}

	return GuideActivityMgr;
})()


