//class com.xq.modules.guide.GuideModel
var GuideModel=(function(){
	function GuideModel(){
		this.guideTable=null;
		this.guideDic=null;
		/**功能开启条件列表*/
		this.limitDic=null;
		this.yuLanDic=null;
		/**服务器存储的已开启引导id*/
		this.yindaoDic={};
		/**功能开启数组*/
		this.openObj={};
		/**最后一个功能*/
		this.lastObj={};
		this.red=null;
		this.gArr=[];
		this.flagDic={};
		this.isOnce=true;
		this.mulDic=new Dictionary();
		this.tiqianDec=new Dictionary();
		this.guideTable=CfgManager.getTableCfg("yindao");
		this.guideDic=new Dictionary();
		this.limitDic=new Object();
		this.yuLanDic=new Dictionary();
		this.parseGuide();
	}

	__class(GuideModel,'com.xq.modules.guide.GuideModel');
	var __proto=GuideModel.prototype;
	/**解析引导表*/
	__proto.parseGuide=function(){
		var list=this.guideTable.objectDataArray;
		var o;
		for(var $each_o in list){
			o=list[$each_o];
			if (!o.id){
				continue ;
			};
			var guideVO=this.guideDic.get(o.id);
			if(!guideVO){
				guideVO=this.getFunGuideVo(o);
				this.guideDic.set(guideVO.id,guideVO);
				var level=o.limit;
				if(level){
					var dic=this.limitDic[level];
					if(dic==null){
						dic={};
						this.limitDic[level]=dic;
					};
					var arr=dic[guideVO.value];
					if(arr==null){
						arr=[];
						dic[guideVO.value]=arr;
					}
					arr.push(guideVO);
					if(o.limit2 || o.limit2=="0"){
						this.mulDic.set(o.id,o);
					}
					if(o.openType){
						this.tiqianDec.set(o.id,o);
					}
				}
			}
			this.addAction(guideVO,o);
		}
	}

	__proto.addAction=function(guideVO,o){
		var vo=new GuideChildVO();
		vo.id=guideVO.id;
		vo.msg=o.message;
		if(o.flyto){
			vo.flyto=(o.flyto).split(":");
		}
		vo.functionimg=o.functionimg;
		vo.limit=parseInt(o.limit);
		vo.value=o.value;
		vo.message=o.message;
		vo.click=o.click;
		vo.isShow=parseInt(o.isShow)==1;
		if(vo.click){
			vo.clickAction=(o.click).split(":");
		}
		guideVO.actions.push(vo);
		if(vo.isShow && vo.limit==4){
			if(!this.openObj[vo.value])
				this.openObj[vo.value]=[];
			this.openObj[vo.value].push(vo);
		}
	}

	__proto.getFunGuideVo=function(o){
		var guideVO=new FunGuideVO();
		guideVO.id=o.id;
		guideVO.actions=[];
		guideVO.limit=parseInt(o.limit);
		guideVO.value=o.value;
		guideVO.limit2=o.limit2;
		guideVO.value2=o.value2;
		guideVO.openType=o.openType;
		guideVO.openValue=o.openValue;
		guideVO.isHide=o.isHide==1;
		if(o.flyto){
			var tp=o.flyto.split(":");
			guideVO.btnName=tp[1];
			guideVO.btnTeam=tp[0];
		}
		guideVO.funUrl=o.functionimg;
		return guideVO
	}

	__proto.getAllGUideByTask=function(taskId){
		if(this.limitDic["2"]){
			var arr=this.limitDic["2"][taskId];
		}
		return arr;
	}

	__proto.getAllGuideByLevel=function(level){
		if(this.limitDic["1"]){
			var arr=this.limitDic["1"][level];
		}
		return arr;
	}

	__proto.getAllGuideByAchieve=function(id){
		if(this.limitDic["3"]){
			var arr=this.limitDic["3"][id];
		}
		return arr;
	}

	__proto.getAllGuideBarrierLv=function(lv){
		if(this.limitDic["5"]){
			var arr=this.limitDic["5"][lv];
		}
		return arr;
	}

	__proto.getAllGuideBySvip=function(lv){
		if(this.limitDic["6"]){
			var arr=this.limitDic["6"][lv];
		}
		return arr;
	}

	/**
	*丢掉已经开启过的功能
	*@type 1等级 2完成任务 3拜将等级 4开服天数 5关卡 6svip
	**/
	__proto.disHasOpened=function(type){
		var obj=this.limitDic[type];
		for (var key in obj){
			var funAry=obj[key];
			var len=funAry.length;
			var isOpen=false;
			for (var i=0;i < len;i++){
				var itemVo=funAry[i];
				if(this.ceckOpen(itemVo.limit+"",itemVo.value)){
					if(itemVo.limit2 !=undefined && (itemVo.limit2 || itemVo.limit2.toString()=="0")){
						if(itemVo.limit2.toString()=="0"){
							var valAry=itemVo.value2.split(";");
							var valLen=valAry.length;
							for (var j=0;j < valLen;j++){
								var tempAry=valAry[j].split(":");
								if(this.ceckOpen(tempAry[0],tempAry[1])){
									isOpen=true;
									break ;
								}
							}
						}
						else if(itemVo.limit2){
							if(this.ceckOpen(itemVo.limit2+"",itemVo.value2)){
								isOpen=true;
								break ;
							}
						}
					}
					else{
						isOpen=true;
						break ;
					}
				}
			}
			if(isOpen){
				delete obj[key];
			}
		}
	}

	__proto.getMulGuide=function(){
		var funAry=[];
		var objAry=this.mulDic.values;
		var len=objAry.length;
		for (var i=len-1;i >=0;i--){
			var obj=objAry[i];
			if(obj && obj.value2){
				var valAry=obj.value2.split(";");
				var valLen=valAry.length;
				for (var j=0;j < valLen;j++){
					var tempAry=valAry[j].split(":");
					if(this.ceckOpen(tempAry[0],tempAry[1])){
						var guideVO=this.getFunGuideVo(obj);
						funAry.push(guideVO);
						objAry.splice(i,1);
						break ;
					}
				}
			}
		}
		if(this.isOnce){
			this.isOnce=false;
			return [];
		}
		return funAry;
	}

	__proto.ceckOpen=function(type,limtVal){
		var bo=false;
		switch(type){
			case GuideEnum.level:
				if(NetMgr.ins().roleVO.level >=parseInt(limtVal)){
					bo=true;
				}
				break ;
			case GuideEnum.task:
				if(Mgr.task.model.compareTaskId(Mgr.task.curTask.id2,limtVal)){
					bo=true;
				}
				break ;
			case GuideEnum.baijiangLv:
				if(NetMgr.ins().roleVO.baiJiangLevel >=parseInt(limtVal)){
					bo=true;
				}
				break ;
			case GuideEnum.openDay:
				if(CommonUtil.openServerDay >=parseInt(limtVal)){
					bo=true;
				}
				break ;
			case GuideEnum.guanqia:
				if(Mgr.gqMgr.gqInfo.nextLevel-1 >=parseInt(limtVal)){
					bo=true;
				}
				break ;
			case GuideEnum.svip:
				if(NetMgr.ins().roleVO.vipLevel >=parseInt(limtVal)){
					bo=true;
				}
				break ;
			}
		return bo;
	}

	return GuideModel;
})()


