//class com.xq.modules.guide.guild.GuideTargetMgr
var GuideTargetMgr=(function(){
	function GuideTargetMgr(){
		this.guidAct=null;
		this.curTaskId="";
		this.curViewDic=new Dictionary();
	}

	__class(GuideTargetMgr,'com.xq.modules.guide.guild.GuideTargetMgr');
	var __proto=GuideTargetMgr.prototype;
	/**切换指引模块*/
	__proto.changeGuideView=function(_view){
		if(NewGuideAction.Ins.guideIsOver){
			return;
		}
		this.curViewDic.set(_view.name,_view);
		if(!this.guidAct){
			this.guidAct=NewGuideAction.Ins;
			EventCenter.instance.on("guide_target_event",this,this.guideHandler);
		}
		if(this.guidAct.curGuideVo){
			this.curTaskId=this.guidAct.curGuideVo.startTaskID;
		}
		this.guideHandler();
	}

	__proto.guideHandler=function(){
		var tempView;
		var bindV=this.guidAct.bindView
		if(bindV){
			tempView=this.curViewDic.get(bindV);
		}
		if(!tempView){
			return;
		};
		var par;
		var tempTarge=null;
		var ary=this.guidAct.targetMark.split(":");
		if(ary){
			var tmp=tempView[ary[0]];
			if(tmp){
				if((tmp instanceof laya.ui.List )){
					if(tempView.hasOwnProperty("setGuideFlag")){
						tempView.setGuideFlag(parseInt(ary[1]),ary[2]);
						return;
					}
					tempTarge=tmp.getCell(parseInt(ary[1]));
					if(tempTarge && ary[2]){
						par=tempTarge;
						tempTarge=tempTarge[ary[2]];
					}
				}
				else if((tmp instanceof Array)){
					tmp=tmp[parseInt(ary[1])];
					if(tmp){
						par=tempView
						tempTarge=tmp[ary[2]];
					}
				}
				else if((tmp instanceof com.xq.component.aniList.AniList )){
					tmp=tmp.getItemByIndex(parseInt(ary[1]));
					if(tmp){
						par=tmp;
						tempTarge=tmp[ary[2]];
					}
				}
				else{
					if(ary[1])
						tempTarge=tmp[ary[1]];
					else
					tempTarge=tmp;
					par=tempView;
				}
			}
		}
		NewGuideAction.Ins.curTarget=tempTarge;
		if(!par)return;
		var pos=new Point(tempTarge.x,tempTarge.y);
		pos=(tempTarge.parent).localToGlobal(pos,false);
		pos=par.globalToLocal(pos,false);
		NewGuideAction.Ins.setTargetAndPos(par,pos,tempTarge);
	}

	__getset(1,GuideTargetMgr,'ins',function(){
		return GuideTargetMgr._ins=GuideTargetMgr._ins|| new GuideTargetMgr();
	});

	GuideTargetMgr._ins=null;
	return GuideTargetMgr;
})()


