	__proto.closeAler=function(vo,type){
		(type===void 0)&& (type="");
		if(type=="OK"){
			if((vo instanceof com.xq.modules.guild.vo.ApplyVO )){
				Mgr.guildPro.sendHandleApplyJoinGuild(true,vo.applyRoleId);
			}
			else{
				Mgr.guildPro.sendHandleInviteJoin(true,(vo).guildId,(vo).inviterId);
			}
		}
		else{
			if((vo instanceof com.xq.modules.guild.vo.ApplyVO )){
				Mgr.guildPro.sendHandleApplyJoinGuild(false,vo.applyRoleId);
			}
			else{
				Mgr.guildPro.sendHandleInviteJoin(false,(vo).guildId,(vo).inviterId);
			}
		};
		var arr;
		if((vo instanceof com.xq.modules.guild.vo.ApplyVO )){
			if(this.model.applyDic.values.length>0){
				this.onMsgBtnClick();
			}
		}
		else{
			if(this.model.inviteDic.values.length>0){
				this.onMsgBtnClick();
			}
		}
	}

