	/**捐献排行奖励领取状态
	*0：未上榜
	*1：可领取
	*2：已领取
	*
	**/
	__proto.getContributeRankRewardStat=function(){
		var myRank=this.model.getMyRank();
		if(!myRank)return 0;
		var id=this.getContributeIdByRank(myRank);
		if(!id)return 0;
		if(!this.model.ifReceivedId(id)||!this.model.ifReceivedToday()){
			return 1;
		}
		return 2;
	}

