	/**获取除我外的帮派成员信息*/
	__proto.getMembersWithoutMe=function(){
		if(!this.memberArr)return null;
		var arr=this.memberArr.concat();
		var len=arr.length;
		var index=-1;
		var me=NetMgr.ins().roleVO.guid;
		for(var i=0;i<len;i++){
			var mem=arr[i];
			if(mem&&mem.id==me){
				index=i;
				break ;
			}
		}
		index!=-1&&arr.splice(index,1);
		return arr;
	}

	__proto.getAppointmentArr=function(){
		var guildArr=[];
		var len=this.memberArr.length;
		var kingInfo=Mgr.guangMingDingM.getKingInfo();
		for (var i=0;i < len;i++){
			var data=Mgr.guild.memberArr [i];
			if(data.id !=NetMgr.ins().roleVO.guid&&data.id!=kingInfo.hufa1.rid&&data.id!=kingInfo.hufa2.rid)
				guildArr.push(data);
		}
		return guildArr;
	}

