	__proto.getBossCfgById=function(mainId){
		if(!this.cfgChache[mainId])
			this.cfgChache[mainId]=this.guildBossCfg.getItemByField("mainId",mainId);
		return this.cfgChache[mainId];
	}

	/**打开公会boss面板*/
	__proto.openGuildBossPanel=function(){
		UIMgrR.openIView(com.xq.view.modules.guild.IGuildMainHall,1,1);
	}

