	__proto.getDjPathArr=function(arr){
		if(!arr||!arr.length)return [];
		var pathArr=[];
		var len=arr.length;
		for (var i=0;i < len;i++){
			var splitArr=arr[i].split(":");
			if(splitArr.length > 1){
				if(splitArr[0]=="20011" && Mgr.store.getIsBuyById(splitArr[1])){
					pathArr.push(splitArr[0]);
					}else if(splitArr[0]=="70019" && !Mgr.kflbMgr.isBuyById(splitArr[1])){
					Mgr.kflbMgr.selectId=parseInt(splitArr[1]);
					pathArr.push(splitArr[0]);
				}
				}else{
				if(!Mgr.rebateHall.meiRiChongAllBuy){
					pathArr.push(splitArr[0]);
				}
			}
		}
		return pathArr;
	}

