//class com.xq.modules.hanLaiShuWang.HanDongShangChengMgr
var HanDongShangChengMgr=(function(){
	function HanDongShangChengMgr(){
		this._activityId=0;
		this._curType=0;
		/**存后端数据字典**/
		this.storeDic=null;
		/**寒冬商城配置表*/
		this.shangChengCfg=null;
		new Dictionary();
		this.storeDic=new Dictionary();
		this.shangChengCfg=CfgManager.getTableCfg("lidongshangcheng");
	}

	__class(HanDongShangChengMgr,'com.xq.modules.hanLaiShuWang.HanDongShangChengMgr');
	var __proto=HanDongShangChengMgr.prototype;
	__proto.regActive=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["TaiYuKuangHuanFrame"]);
		ActManager.ins.regist("TaiYuKuangHuanFrame","handongshangcheng",147,"TaiYuKuangHuanEvent");
		var hand=Handler.create(this,this.openAct,[147],false);
		NewActiveManager.ins.regActOpenHandler(147,hand);
		NewActiveManager.ins.regActEndHandler(147,Handler.create(this,this.closeAct,[147],false));
	}

	__proto.closeAct=function(actId){
		if(actId==147){
			EventCenter.instance.event("ACTIVE_TOGGLE",["TaiYuKuangHuanFrame"]);
		}
	}

	__proto.openAct=function(actId){
		if(actId==147){
			EventCenter.instance.event("ACTIVE_TOGGLE",["TaiYuKuangHuanFrame",false]);
			Mgr.bianCeAct.sendBianCeLiBaoInfo(147);
		}
	}

	__proto.zhongQiuStoreInfo=function(msg){
		var dic=this.storeDic.get(msg.type);
		if(!dic){
			dic=new Dictionary();
			this.storeDic.set(msg.type,dic);
		};
		var len=msg.list.length;
		for (var i=0;i < len;i++){
			var a=msg.list[i];
			dic.set(a.id,a.buyTime);
		}
		EventCenter.instance.event("han_dong_store_refresh");
	}

	__proto.getSerInfoDic=function(activityId){
		return this.storeDic.get(activityId);
	}

	__proto.getShangChengData=function(activityId){
		var cfg=this.getShangChengCfg(activityId);
		if(!cfg){
			return null;
		}
		return cfg.getAllItemByFiled("flag",this.activitTime(activityId));
	}

	__proto.getShangChengId=function(activityId,id){
		var cfg=this.getShangChengCfg(activityId);
		if(!cfg){
			return null;
		}
		return cfg.getCfgMsgArrByTwoKey("flag",this.activitTime(activityId),"id",id);
	}

	__proto.zhongQiuStoreBuy=function(vo){
		var libaoVo=vo.msg;
		var dic=this.storeDic.get(vo.type);
		if(dic)dic.set(libaoVo.id,libaoVo.buyTime);
		EventCenter.instance.event("han_dong_store_refresh");
	}

	__proto.getShangChengCfg=function(activityId){
		switch(activityId){
			case 147:{
					return this.shangChengCfg;
					break ;
				}
			}
		return null;
	}

	__proto.activitTime=function(activiTyen){
		var opAct=NewActiveManager.ins.getActiveVerDic(activiTyen);
		if(opAct){
			return opAct.flag;
		}
		return 0;
	}

	__proto.getActivitTime=function(activiTyen){
		var opAct=NewActiveManager.ins.getActiveVerDic(activiTyen);
		if(opAct){
			return opAct.endTime;
		}
		return 0;
	}

	/**
	*@private
	*/
	__getset(0,__proto,'curType',function(){
		return this._activityId;
		},function(value){
		this._activityId=value;
		if(value==1){
			this._activityId=147;
		}
	});

	HanDongShangChengMgr.HAN_DONG_STORE_REFRESH="han_dong_store_refresh";
	return HanDongShangChengMgr;
})()


