		var gd=Mgr.guide;
		var len=this.heroModel.funIDAry.length;
		for (var i=0;i < len;i++){
			var fd=this.heroModel.funIDAry[i];
			if(gd.isOpen(fd)){
				heroSA.reqActivateOpen(this.heroModel.zjTypeAry[i]);
			}
		}
