	/**助战功能开启函数*/
	__proto.newOpenFun=function(funId){
		var tempF;
		if(funId=="zhanJiang"){
			Mgr.heroSysAct.reqActivateOpen(1);
			tempF="zhanJiang"
		}
		else if(funId=="nvshen"){
			Mgr.heroSysAct.reqActivateOpen(3);
			tempF="nvshen"
		}
		else if(funId=="tianShen"){
			Mgr.heroSysAct.reqActivateOpen(2);
			tempF="tianShen"
		}
		else if(funId=="mengchong"){
			Mgr.heroSysAct.reqActivateOpen(4);
			tempF="mengchong";
		}
		if(tempF)
			this.showOpenTip(tempF);
		var ts=this.getShenJiangInfo(2);
		if(!ts || ts.status==0)
			return;
		var ns=this.getShenJiangInfo(3);
		if(!ns || ns.status==0)
			return;
		var mc=this.getShenJiangInfo(4);
		if(!mc || mc.status==0)
			return;
		var zj=this.getShenJiangInfo(1);
		if(!zj || zj.status==0)
			return;
		EventCenter.instance.off("new_function_open",this,this.newOpenFun);
	}

