				if(!this.hfTips){
					this.hfTips=UIMgrR.newInstanceByIClass(com.xq.view.modules.activityTip.IHuFuTipsView);
					mainV.addViewToHide(this.hfTips,1);
					mainV.addViewToHide(this.hfTips,2);
				}
				Game.getInstance().mainQiPaoView.addChild(this.hfTips);
				mainV.showHide(MainHideEnum.type1,!NetMgr.ins().roleVO.isInCopy);
				mainV.showHide(MainHideEnum.ZhuCheng,NetMgr.ins().roleVO.mapType!=2);
				var _x=mainV.getLeftActive().x+90;
				var _y=mainV.getLeftActive().y;
