		this.table_chongzhi=CfgManager.getTableCfg("chongzhi");
		this.redDic["tuhaojijin"]=false;
		this.redDic["zhizunjijin"]=false;
		this.redDic["chengzhangjijin"]=false;
		var len=this.ykArr.length;
		for(var i=0;i<len;i++){
			var o=this.ykArr[i];
			if(o.id==2){
				this.jingYanAddRate=parseInt(o.jingyanfubenexp);
			}
		}
		this.red=Mgr.red;
		this.red.regist("juhuasuan","newleijichongzhi");
		this.red.regist("juhuasuan","meiritehui");
		this.red.regist("juhuasuan","chengzhangjijin");
		this.red.regist("TeQuanKaFrame","yuanbaoyueka",true,RedTypeEnum.TeQuanKaRed);
		this.red.regist("fulidating","yuanbaoyuekaFldt",true,"fulidating");
