	/**获取当前目标奖励的所需积分*/
	__proto.getTargetScore=function(activityType){
		var qingDianVo=this.getQingDianVo(activityType);
		var qingDianSer=this.getQingDianDic(qingDianVo.activityType);
		if(!qingDianVo)
			return 0;
		var score=0;
		var qingDianConfig=qingDianVo.qingDianCfg;
		if(!qingDianConfig)return 0;
		var rewardArr=qingDianConfig.targetRewardArr;
		if(!rewardArr)return 0;
		var len=rewardArr.length;
		for (var i=0;i < len;i++){
			var targetVo=rewardArr[i];
			if(qingDianSer.targetScore < targetVo.targetScore){
				score=targetVo.targetScore;
				break ;
			}
			if(!score && i==(len-1)){
				score=targetVo.targetScore;
			}
		}
		return score;
	}

	/**获取当前可领取目标奖励积分*/
	__proto.getReceiveScore=function(activityType){
		var qingDianVo=this.getQingDianVo(activityType);
		var qingDianSer=this.getQingDianDic(qingDianVo.activityType);
		var score=0;
		var qingDianConfig=qingDianVo.qingDianCfg;
		var rewardArr=qingDianConfig.targetRewardArr;
		var len=rewardArr.length;
		for (var i=0;i < len;i++){
			var targetVo=rewardArr[i];
			if(qingDianSer.myScore >=targetVo.targetScore && qingDianSer.targetScore < targetVo.targetScore){
				score=targetVo.targetScore;
				break ;
			}
		}
		return score;
	}

