//class com.xq.modules.kaixueqingdian.QingDianConfig
var QingDianConfig=(function(){
	function QingDianConfig(){
		this.flag=0;
		this.target=0;
		this.targetRewardArr=null;
		this.learnReward=null;
		this.limit=0;
		this.buff=NaN;
		this.code=0;
		this.useNumArr=null;
	}

	__class(QingDianConfig,'com.xq.modules.kaixueqingdian.QingDianConfig');
	var __proto=QingDianConfig.prototype;
	__proto.setConfig=function(obj,str){
		this.targetRewardArr=[];
		if(!obj)return;
		this.flag=parseInt(obj.flag);
		this.target=parseInt(obj.target);
		if(obj.bigreward.length==1){
			this.learnReward=obj.bigreward[0];
			}else{
			this.learnReward=obj.bigreward;
		}
		this.limit=parseInt(obj.limit);
		this.buff=parseFloat(obj.buff);
		this.code=parseInt(obj.code);
		var rewardArr=obj.reward.split("|");
		var len=rewardArr.length;
		var targetVo;
		for (var i=0;i < len;i++){
			var oneTargetArr=rewardArr[i].split("_");
			targetVo=new TargetRewardVo();
			targetVo.param=str;
			targetVo.targetScore=parseInt(oneTargetArr[0]);
			targetVo.targetReward=oneTargetArr[1];
			this.targetRewardArr.push(targetVo);
		}
		if(obj.setting){
			this.useNumArr=obj.setting.split(":");
		}
	}

	return QingDianConfig;
})()


