//class com.xq.modules.lianDanLu.LianDanLuMgr
var LianDanLuMgr=(function(){
	function LianDanLuMgr(){
		this.selectDanLu=null;
		this._model=null;
		this._red=null;
		this._model=new LianDanluModel();
		this.registRed();
	}

	__class(LianDanLuMgr,'com.xq.modules.lianDanLu.LianDanLuMgr');
	var __proto=LianDanLuMgr.prototype;
	//==============================
	__proto.getCurSpeed=function(type,id){
		var ele=this.getDeviceEle(type,id);
		if(!ele)return 0;
		var vo=ele.getValue("s_data");
		if(!vo||!vo.stat)return 0;
		var cfg=ele.getCfgData();
		var speedEndTime=vo.speedEndTime;
		if(speedEndTime>Mgr.curTime.serverTimer){
			return parseFloat(cfg.defaultSpeed)+parseFloat(cfg.speedPer)
		}
		return parseFloat(cfg.defaultSpeed)
	}

	/**检测是否有正在生产的产品*/
	__proto.checkHasProduce=function(type){
		var arr=this.getDeviceArr(type);
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var vo=ele.getValue("s_data");
			if(vo&&vo.produces.length>0){
				return true;
			}
		}
		return false;
	}

	__proto.startTimer=function(type){
		if(this.checkHasProduce(type)){
			if(type==1){
				Laya.timer.loop(1000,this,this.onProduceDanYao);
			}
		}
		else{
			if(type==1){
				Laya.timer.clear(this,this.onProduceDanYao);
			}
		}
	}

	__proto.onProduceDanYao=function(){
		var arr=this.getDeviceArr(1);
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var vo=ele.getValue("s_data");
			if(vo&&vo.produces.length>0){
				var sp=this.getCurSpeed(vo.type,vo.id);
				vo.setTimePro(vo.timePro+sp*1000);
				if(this.checkProduceOver(vo)){
					Mgr.lianDanLuA.sendGetOneInfo(1,vo.id);
				}
			}
		}
	}

	__proto.checkProduceOver=function(vo){
		if(!vo)return false;
		var pVo=vo.produces[0];
		if(!pVo)return false;
		var ele=this.getFormulaByTypeAndId(vo.type,pVo.proId);
		if(!ele)return false;
		var cfg=ele.getCfgData();
		var time=parseInt(cfg.time);
		return vo.timePro>=time*1000;
	}

	/**通过装置类型获取 该类装置所有数据数组*/
	__proto.getDeviceArr=function(type){
		return this._model.getDeviceElesByType(type);
	}

	/**通过装置类型获取 该类装置所有数据数组*/
	__proto.getDeviceEle=function(type,id){
		return this._model.getDeviceByTypeAndId(type,id);
	}

	/**根据类型和Id获取对应配方 配置ele*/
	__proto.getFormulaByTypeAndId=function(type,id){
		return this._model.getFormulaByTypeAndId(type,id);
	}

	/**配方下拉组件数据*/
	__proto.getFormulaAccData=function(type){
		return this._model.getAccDataByType(type);
	}

	/**获取最大可炼制数量 通过 配置最大数量和 已拥有道具数量 计算*/
	__proto.getMaxLianDanNum=function(ele){
		if(!ele)return 0;
		var cfg=ele.getCfgData();
		var cfgNumLimit=cfg.numLimit;
		var materials=cfg.cost1;
		var len=materials.length;
		var id;
		var needNum=0;
		var haveNum=0;
		var material;
		var splitArr;
		var materialNum=cfgNumLimit;
		for(var i=0;i<len;i++){
			material=materials[i];
			splitArr=material.split(":");
			id=splitArr[0];
			needNum=parseInt(splitArr[1]);
			haveNum=Mgr.bag.getBagMatCount(id);
			if(id&&needNum){
				var mNum=Math.floor(haveNum/needNum);
				if(mNum<materialNum){
					materialNum=mNum;
				}
			}
		}
		return materialNum;
	}

	/**获取队列长度*/
	__proto.getProduceLenLimit=function(type,id){
		var ele=this.getDeviceEle(type,id);
		if(!ele)return 0;
		return ele.getCfgData().length;
	}

	/**检测当前选中的丹炉 是否可以炼制选中的丹方*/
	__proto.checkCanLianDan=function(cfg){
		if(!this.selectDanLu||!cfg)return false;
		var arr=cfg.danlu;
		if(!arr||arr.length==0)return true;
		var selectDanLuId=this.selectDanLu.getCfgData().id;
		return arr.indexOf(selectDanLuId)!=-1;
	}

	/**刷新所有装置数据*/
	__proto.updateAllInfo=function(msg){
		this._model.updateAllInfo(msg);
		EventCenter.instance.event("UpdateAllLianDanLuInfo");
		this.startTimer(msg.type);
	}

	/**刷新单个装置数据*/
	__proto.updateOneInfo=function(msg){
		this._model.updateOneInfo(msg);
		EventCenter.instance.event("UpdateOneLianDanLuInfo");
		this.startTimer(msg.type);
	}

	/**刷新 解锁装置*/
	__proto.updateUnlockDevice=function(msg){
		this._model.updateUnlockDevice(msg);
		EventCenter.instance.event("UpdateOneLianDanLuInfo");
	}

	/**刷新所有配方信息*/
	__proto.updateAllFormula=function(msg){
		this._model.updateFormulaInfo(msg);
		EventCenter.instance.event("UpdateAllFormulaInfo");
	}

	/**刷新 解锁配方*/
	__proto.updateUnlockFormula=function(msg){
		this._model.updateUnlockFormula(msg);
		EventCenter.instance.event("UpdateOneFormulaInfo");
	}

	/**刷新加速信息*/
	__proto.updateAccelerated=function(msg){
		this._model.updateAccelerated(msg);
		Mgr.prompt.optionPrompt("添加三昧真火成功！");
		EventCenter.instance.event("UpdateAcceleratedInfo");
	}

	/**刷新 增加生产项成功*/
	__proto.updateAddProduce=function(msg){
		this._model.updateAddProduce(msg);
		EventCenter.instance.event("UpdateAddProduceInfo");
	}

	/**刷新 删除生产项成功*/
	__proto.updateDelProduce=function(msg){
		this._model.updateDelProduce(msg);
		EventCenter.instance.event("UpdateAddProduceInfo");
	}

	//========红点相关============
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("DanYaoFrame","LianDanLu",false,"DanYaoFrameRed");
		this._red.regist("DanYaoFrame","LianDanLuBag",false,"DanYaoFrameRed");
	}

	/**检测是否有可炼制的丹药红点*/
	__proto.updateLianDanRed=function(type){}
	__proto.updateUnLockDanLuRed=function(type){}
	return LianDanLuMgr;
})()


