//class com.xq.modules.log.LogMgr
var LogMgr=(function(){
	function LogMgr(){
		this.startRecord=true;
		this.startTime=0;
		this._canReport=false;
		if(typeof(TXReport)!="undefined")this._canReport=true;;
		if(LocalStorage.getItem("logFinish")=="true"){
			this.startRecord=false;
		}
		Cmd.regCmd("time",Handler.create(this,this.showLog,null,false));
	}

	__class(LogMgr,'com.xq.modules.log.LogMgr');
	var __proto=LogMgr.prototype;
	__proto.showLog=function(){
		Mgr.prompt.optionPrompt(Lang.str(2631)+TextUtil.msec2THMS((Browser.now()-this.startTime)));
	}

	/**统计数据字段对照表
	id int 20
	guid varchar
	step varchar
	uid varchar 20
	roleguid varchar 20
	platform varchar 20
	rolename varchar 20
	netspeed int 11 0
	rendermode varchar 20
	entertimecost int 11
	isnewrole tinyint 1
	rolelevel tinyint 3
	stagewidth tinyint 4
	stageheight tinyint 4
	yuanbao tinyint 10 0
	viplevel tinyint 3
	useragent varchar 300
	other varchar 300 0
	inserttime timestamp
	lastupdatetime timestamp
	ip vachar 200
	*/
	__proto.report=function(step,otherParam){
		FrameSmooth.add(Handler.create(this,this.laterReport,[step,otherParam]));
	}

	__proto.laterReport=function(step,otherParam){
		if(this.startRecord && this._canReport){
			TXReport.reportStep(step ,otherParam);;
			if(step==19){
				LocalStorage.setItem("logFinish","true");
			}
		}
	}

	__getset(1,LogMgr,'ins',function(){
		return LogMgr._ins=LogMgr._ins|| new LogMgr();
	});

	LogMgr.STEP_GAME_START=1;
	LogMgr.STEP_NEW_MAIN=2;
	LogMgr.STEP_LOAD_MAIN_JS=3;
	LogMgr.STEP_ENTER_MAIN=4;
	LogMgr.STEP_VER_LOADED=5;
	LogMgr.STEP_UI_LOADED=6;
	LogMgr.STEP_HEALTHTIPS=7;
	LogMgr.STEP_PRELOAD_PAGE=8;
	LogMgr.STEP_PRE_LOADED=9;
	LogMgr.STEP_PARSER_Cfg=10;
	LogMgr.STEP_CHOOSE_SERVER=11;
	LogMgr.STEP_SDK_LOGIN=12;
	LogMgr.STEP_AGREE_PRIVACY=13;
	LogMgr.STEP_REFUSE_PRIVACY=14;
	LogMgr.STEP_GOT_SERVER_LIST=15;
	LogMgr.STEP_CONNECT_SEVER=16;
	LogMgr.STEP_CREATE_ROLE=17;
	LogMgr.STEP_ENTER_SCENE=18;
	LogMgr.STEP_LEVEL_UP=19;
	LogMgr.STEP_YUAN_BAO_ADD=20;
	LogMgr.STEP_GET_DEVICE=21;
	LogMgr._ins=null;
	return LogMgr;
})()


