	/**上一名描述*/
	__proto.getLastRank=function(type){
		var myRank=this.myRankDic[type];
		var lastEle;
		var cof;
		var str;
		var lastRank=0;
		if(myRank==0||myRank>this.maxRank){
			lastRank=this.maxRank;
		}
		else{
			lastRank=myRank-1>0?myRank-1:myRank;
		};
		var dc=type==94?this.rankhkDc:this.rankfhDc;
		lastEle=dc.getElement(lastRank);
		if(!lastEle)return "";
		var data=lastEle.getValue("S");
		if(data){
			str=Lang.str(2226)+lastRank+Lang.str(2667)+data.name+"("+data.score+")";
		}
		else{
			cof=lastEle.getCfgData();
			str=Lang.str(2226)+lastRank+Lang.str(2670);
		}
		return str;
	}

