	/**加粒子特效*/
	__proto.addParticle=function(type){
		var parUrl;
		if(type==1){
			parUrl="huaban1";
			}else if(type==2){
			parUrl="huaban2";
		}
		this.removeParticle();
		var len=this._posArr.length;
		for(var i=0;i<len;i++){
			var p=new ParticleSystem();
			p.y=this._posArr[i];
			p.zOrder=1000;
			p.setRes(PathDefine.PARTICLE+parUrl+".lz");
			Laya.stage.addChild(p);
			this._pArr.push(p);
		}
		Laya.timer.clear(this,this.removeParticle);
		Laya.timer.once(5000,this,this.removeParticle);
	}

