/**
*婚姻系统
*@author zhanglimin
*@date 2020-6-17
**/
//class com.xq.modules.marriage.MarriageMgr
var MarriageMgr=(function(){
	function MarriageMgr(){
		this.model=null;
		this._red=null;
		this.boardInfoInitIndex=0;
		this.isFirst=false;
		this.initCfg();
		this.model=Model.marriage;
		this.registRed();
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.updateYinYuanRed2);
	}

	__class(MarriageMgr,'com.xq.modules.marriage.MarriageMgr');
	var __proto=MarriageMgr.prototype;
	__proto.initCfg=function(){}
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("shejiao","marriage",true,"SheJiaoRed");
		this._red.regist("marriage","yinyuan",false,"MarriageRed");
		this._red.regist("marriage","hunJiehall",false,"MarriageRed");
		this._red.regist("hunJiehall","hunjie",false,"MarriageRingRed");
		this._red.regist("hunJiehall","marriagetitile",false,"MarriageRingRed");
		this.addRedFirst();
	}

	/**更新结婚信息*/
	__proto.updateInfo=function(msg){
		this.model.marryInfo=msg;
		EventCenter.instance.event("marriageinfo");
		this.updateYinYuanRed1();
		this.updateYinYuanRed2();
		var mainPly=Game.getInstance().player;
		if(mainPly){
			if(msg.partarner){
				mainPly.cpName=msg.partarner.roleName;
				}else{
				mainPly.cpName="";
			}
		}
	}

	/**更新亲密度信息*/
	__proto.updateQinMiDu=function(lv,pro){
		if(this.model.marryInfo.qinmiduLv<lv){
			Mgr.prompt.playOptTxt("chengong_01");
			this.updateYinYuanRed1();
		}
		this.model.marryInfo.qinmiduLv=lv;
		this.model.marryInfo.qinmiduPro=pro;
		EventCenter.instance.event("marriageinfo");
	}

	/**更新姻缘墙信息*/
	__proto.updateBoardInfo=function(msg){
		this.model.boardInfo.set(msg.type,msg);
		this.boardInfoInitIndex++;
		if(this.boardInfoInitIndex <=2){
			if(this.boardInfoInitIndex==2){
				EventCenter.instance.event("MarriageBoardInfoIndex");
			}
		}
		else{
			EventCenter.instance.event("marriageboardinfo");
		}
	}

	__proto.updateOnlineStat=function(msg){
		if(this.model.marryInfo&&this.model.marryInfo.partarner){
			this.model.marryInfo.partarner.isOnline=msg.state==1;
			if(msg.state==1){
				var index=Mgr.guangMingDingM.onlineDic.get(this.model.marryInfo.partarner.roleName);
				if(index!=3){
					Mgr.guangMingDingM.onlineDic.set(this.model.marryInfo.partarner.roleName,2);
					Laya.timer.once(2000,this,this.ifPopupMarriageOnlineTip,[msg]);
				}
			}
			EventCenter.instance.event("MarriageOnLineStat");
		}
	}

	/**是否弹出情侣上线提示*/
	__proto.ifPopupMarriageOnlineTip=function(){
		var index=Mgr.guangMingDingM.onlineDic.get(this.model.marryInfo.partarner.roleName);
		if(index==3)return;
		Mgr.prompt.marriageOnline();
	}

	/**判断是否已经结婚*/
	__proto.checkIsMarriage=function(showTip){
		(showTip===void 0)&& (showTip=false);
		var result=this.model.checkIsMarriage();
		if(!result && showTip){
			Mgr.prompt.optionPrompt(Lang.str(2679));
		}
		return result;
	}

	/**
	*获取戒指
	*@param lv-1取最低等级的，否取可升级的戒指
	**/
	__proto.getRingId=function(ringID){
		(ringID===void 0)&& (ringID="");
		var ary=this.model.configVo.marryAry;
		var len=ary.length;
		var bagMgr=Mgr.bag;
		if(ringID){
			var lv=ary.indexOf(ringID);
			if(lv+1==ary.length){
				return "";
			}
		}
		else{
			lv=-1
		}
		for (var i=0;i < len;i++){
			var tempID=ary[i];
			if(bagMgr.getBagMatCount(tempID)> 0){
				if(lv==-1){
					return tempID;
				}
				else if(lv < i){
					return tempID;
				}
			}
		}
		return "";
	}

	__proto.getDivorceDay=function(){
		return this.model.configVo.divorceDay;
	}

	/**获取亲密度配置*/
	__proto.getQinMiDuCfg=function(lv){
		return this.model.getQinMiDuCfg(lv);
	}

	/**打开仙缘面板*/
	__proto.openMarriage=function(){
		if(this.checkIsMarriage(true)){
			UIMgrR.openIView(com.xq.view.modules.marriage.IMarriageFrame);
		}
	}

	/**
	*和离通知球
	*@param type：1=离婚请求做操作 2=强制和离弹窗
	**/
	__proto.createNoticeBall=function(type){
		var vo=new CommonNoticeVo();
		var noticeType=CommonNoticeType.Marriage;
		if(type==1){
			var handler=Handler.create(this,this.onClickBall1,null,false);
		}
		else{
			handler=Handler.create(this,this.onClickBall2,null,false);
		}
		vo.setDat(noticeType,"",handler);
		NoticeManager.ins.addNotice(vo);
	}

	__proto.onClickBall1=function(){
		AlertUtil.show(CodeMgr.ins.getStringByCode(260857),Lang.str(2321),Handler.create(this,this.alertClose1));
	}

	__proto.onClickBall2=function(){
		AlertUtil.show(CodeMgr.ins.getStringByCode(260858),Lang.str(2321),Handler.create(this,this.alertClose2));
	}

	/**强制和离*/
	__proto.alertClose2=function(type){
		Mgr.marriageAct.reqDivorce(1);
		NoticeManager.ins.removeNotice(CommonNoticeType.Marriage);
	}

	/**和离操作*/
	__proto.alertClose1=function(type){
		Mgr.marriageAct.reqDivorceDeal(type=="OK");
		NoticeManager.ins.removeNotice(CommonNoticeType.Marriage);
	}

	/**亲密度奖励展示等级*/
	__proto.getShowRewardLv=function(){
		if(this.model.marryInfo.qinmiduLv>this.model.marryInfo.qinmiduRewardLv){
			return this.model.marryInfo.qinmiduRewardLv+1;
		}
		else{
			return this.model.marryInfo.qinmiduLv+1;
		}
	}

	/**刷新十里红妆数据*/
	__proto.updateSLHZ=function(msg){
		var arr=msg.list;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var obj=arr[i];
			var id=obj.id;
			var ele=this.slhzDc.getElement(id);
			ele.setValue("S",obj);
		}
		EventCenter.instance.event("MarriageLiBao");
	}

	/**刷新十里红妆数据*/
	__proto.updateSinlegSLHZ=function(msg){
		var obj=msg.msg;
		var id=obj.id;
		var ele=this.slhzDc.getElement(id);
		if(ele){
			ele.setValue("S",obj);
		}
		EventCenter.instance.event("MarriageLiBao");
		if(NewActiveManager.ins.checkIsOpen(211)){
			Mgr.marriageActivityA.sendGetStat();
		}
	}

	/**根据版本获取数据*/
	__proto.getSLHZByFlag=function(flag){
		var dc=this.slhzDc.where("flag",flag,"id");
		return dc.array;
	}

	__proto.updateSeach=function(msg){
		var id=Mgr.marriageMgr.getRingId();
		if(id){
			var v=UIMgrR.openIView(com.xq.view.modules.marriage.IMarriageQiuHun ,2);
			v.dataSource=msg.info;
		}
		else{
			AlertUtil.show(Lang.str(2680),Lang.str(2321),Handler.create(this,this.alertClose));
		}
	}

	__proto.alertClose=function(str){
		if(str=="OK"){
			UIMgrR.openIView(com.xq.view.modules.marriage.IMarriageHongZhuang,2);
		}
	}

	__proto.updateYinYuanRed1=function(){
		if(this.qinmiduRewardStat==1){
			this._red.showRedPoint("yinyuan","reward","YinYuanRed");
		}
		else{
			this._red.hideRedPoint("yinyuan","reward","YinYuanRed");
		}
	}

	/**当前升级需要*/
	__proto.getCostToNextLv=function(){
		return this.model.getCostToNextLv();
	}

	__proto.updateYinYuanRed2=function(){
		if(!Mgr.guide.isOpen("marriage"))return;
		if(!this.model.marryInfo)return;
		if(this.checkIsMarriage()){
			var need=this.getCostToNextLv();
			if(need!=""){
				var costArr=need.split(":");
				var _needId=costArr[0];
				var _needCount=parseInt(costArr[1]);
				var itemNum=Mgr.bag.getBagMatCount(_needId);
				if(itemNum>=_needCount){
					this._red.showRedPoint("yinyuan","upLv","YinYuanRed");
				}
				else{
					this._red.hideRedPoint("yinyuan","upLv","YinYuanRed");
				}
			}
			else{
				this._red.hideRedPoint("yinyuan","upLv","YinYuanRed");
			}
		}
		else{
			this._red.hideRedPoint("yinyuan","upLv","YinYuanRed");
		}
	}

	__proto.addRedFirst=function(){
		if(Mgr.guide.isOpen("marriage")){
			this._red.showRedPoint("marriage","firstRed","YinYuanRed");
			this.isFirst=true;
		}
	}

	__proto.removeRedFirst=function(){
		if(this.isFirst){
			this._red.hideRedPoint("marriage","firstRed","YinYuanRed");
		}
	}

	/**送花推荐 姻缘信息 无姻缘返回空数组*/
	__proto.getPartarner=function(){
		var arr=[];
		if(this.model.marryInfo&&this.model.marryInfo.partarner&&this.model.marryInfo.partarner.roleId){
			arr.push(this.model.marryInfo.partarner);
		}
		return arr;
	}

	/**征婚撤销*/
	__proto.onMarriageRevoke=function(){
		EventCenter.instance.event("marriagerevoke");
	}

	__getset(0,__proto,'marriageStat',function(){
		return this.model.marriageStat();
	});

	/**请密度奖励可领取状态*/
	__getset(0,__proto,'qinmiduRewardStat',function(){
		var stat=0;
		if(this.model.marryInfo.qinmiduLv>this.model.marryInfo.qinmiduRewardLv){
			return 1;
		}
		else{
			var cof=this.getQinMiDuCfg(this.model.marryInfo.qinmiduLv+1);
			if(cof){
				return 2;
			}
			else{
				return 3;
			}
		}
		return stat;
	});

	//十里红妆
	__getset(0,__proto,'slhzDc',function(){
		return this.model.slhzDc;
	});

	/**获取活动版本，活动未开启返回0*/
	__getset(0,__proto,'flagSLHZ',function(){
		var vo=NewActiveManager.ins.getActiveVerDic(90);
		if(!vo){
			return 0;
		}
		return vo.flag;
	});

	return MarriageMgr;
})()


//class com.xq.modules.marriage.MarriageRingMgr
var MarriageRingMgr=(function(){
	function MarriageRingMgr(){
		this.model=null;
		this._red=null;
		this.model=Model.marriage;
		this.initCfg();
	}

	__class(MarriageRingMgr,'com.xq.modules.marriage.MarriageRingMgr');
	var __proto=MarriageRingMgr.prototype;
	__proto.initCfg=function(){
		this._red=RedPointMgr.ins();
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.updateRingRed);
	}

	/**更新婚戒信息*/
	__proto.updateRingInfo=function(msg){
		this.model.ringInfo=msg;
		this.updateSkillInfo(msg.skills);
		this.updateRingRed();
		this.updateRingSkillRed();
		EventCenter.instance.event("MarriageRingInfo");
	}

	/**更新进阶信息*/
	__proto.updateRingUpInfo=function(lv,exp,gmLv){
		if(!this.model.ringInfo){
			this.model.ringInfo=new MarryRingInfoSC();
		}
		if(this.model.ringInfo.ringLevel!=lv){
			Mgr.prompt.playOptTxt("chengong_01");
			this.updateRingSkillRed();
		}
		this.model.ringInfo.ringLevel=lv;
		this.model.ringInfo.ringExp=exp;
		this.model.ringInfo.gongmingLevel=gmLv;
		EventCenter.instance.event("MarriageUpgrade");
	}

	__proto.updateRingSkillRed=function(){
		this.model.updateRingSkillRed();
	}

	/**更新技能信息*/
	__proto.updateSkillInfo=function(arr){
		this.clearSkill();
		var skillArr=arr;
		var len=skillArr.length;
		for(var i=0;i<len;i++){
			var skill=arr[i];
			var ele=this.skillDc.getElement(skill.skillId);
			if(ele){
				ele.setValue("level",skill.skillLevel);
			}
		}
	}

	__proto.clearSkill=function(){
		var arr=this.skillDc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			ele.setValue("level",0);
		}
	}

	/**更新单个技能数据*/
	__proto.updateSingleSkill=function(skillId,lv){
		this.model.updateSingleSkill(skillId,lv);
	}

	/**获取对应Id的技能等级*/
	__proto.getSkillLvBySkillId=function(skillId){
		return this.model.getSkillLvBySkillId(skillId);
	}

	/**更换戒指*/
	__proto.updateRingId=function(msg){
		this.model.ringInfo.ringId=msg.ringId;
		Mgr.prompt.optionPrompt(Lang.str(2682));
		EventCenter.instance.event("MarriageChangeRingId");
		this.updateRingRed();
	}

	/**根据戒指Id获取对应戒指配置*/
	__proto.getRingById=function(id){
		return this.ringDc.getElement(id);
	}

	/**获取戒指等级配置*/
	__proto.getRingLevel=function(lv){
		return this.model.getRingLevel(lv);
	}

	/**获取更高等级戒指Id数组*/
	__proto.getHeightRingId=function(){
		return this.model.getHeightRingId();
	}

	/**物品变化带来的红点变化*/
	__proto.updateRingRed=function(){
		if(!Mgr.guide.isOpen("marriage"))return;
		if(!this.model.ringInfo)
			return;
		if(Mgr.marriageMgr.checkIsMarriage()||(Model.marriage.marryInfo&&Model.marriage.marryInfo.isMarried)){
			if(this.CanUpId!=""){
				this._red.showRedPoint("hunjie","upRing","MarriageRingRed");
			}
			else{
				this._red.hideRedPoint("hunjie","upRing","MarriageRingRed");
			};
			var need=this.getCostToNextLv();
			if(need!=""){
				var costArr=need.split(":");
				var _needId=costArr[0];
				var _needCount=parseInt(costArr[1]);
				var itemNum=Mgr.bag.getBagMatCount(_needId);
				if(itemNum>=_needCount){
					this._red.showRedPoint("hunjie","upLv","MarriageRingRed");
				}
				else{
					this._red.hideRedPoint("hunjie","upLv","MarriageRingRed");
				}
			}
			else{
				this._red.hideRedPoint("hunjie","upLv","MarriageRingRed");
			}
		}
		else{
			this._red.hideRedPoint("hunjie","upRing","MarriageRingRed");
			this._red.hideRedPoint("hunjie","upLv","MarriageRingRed");
		}
	}

	/**当前升级需要*/
	__proto.getCostToNextLv=function(){
		if(!this.model.ringInfo){
			return "";
		};
		var curLv=this.model.ringInfo.ringLevel;
		var nextLv=curLv+1;
		var ele=this.ringLevelDc.getElement(nextLv);
		if(ele){
			var nextcfg=ele.getCfgData();
		}
		if(nextcfg){
			var arr=nextcfg.cost.split(":");
			var id=arr[0];
			var onceNeed=parseInt(arr[1]);
			var needJF=nextcfg.need-this.model.ringInfo.ringExp;
			var needNum=Math.ceil((needJF/nextcfg.exp)*onceNeed);
			return id+":"+needNum;
		}
		return "";
	}

	/**婚戒共鸣dc*/
	__getset(0,__proto,'ringGMDc',function(){
		return this.model.ringGMDc;
	});

	/**婚戒Leveldc*/
	__getset(0,__proto,'ringLevelDc',function(){
		return this.model.ringLevelDc;
	});

	/**婚戒dc*/
	__getset(0,__proto,'ringDc',function(){
		return this.model.ringDC;
	});

	/**戒指是否已满级*/
	__getset(0,__proto,'ifFull',function(){
		return this.model.ifFull();
	});

	__getset(0,__proto,'skillDc',function(){
		return this.model.skillDc;
	});

	/**是否可升级戒指*/
	__getset(0,__proto,'CanUpId',function(){
		var arr=this.getHeightRingId();
		var len=arr.length;
		var id="";
		var count=0;
		for(var i=0;i<len;i++){
			id=arr[i];
			count=Mgr.bag.getBagMatCount(id);
			if(count>0){
				return id;
			}
		}
		return "";
	});

	//==========================称号===================================
	__getset(0,__proto,'titleDc',function(){
		return this.model.titleDc;
	});

	return MarriageRingMgr;
})()


