var MeiRiBiZuoMgr=(function(){
	function MeiRiBiZuoMgr(){
		this.wenSanGuanTab=null;
		this.wenSanGuanData=null;
		this._curWenSanCfg=null;
		this._curWenSanRewardCfg=null;
		this._nextWenSanCfg=null;
		this._lastWenSanGuanId=0;
		this.wenSanGuanTab=CfgManager.getTableCfg("civilservice");
	}

	__class(MeiRiBiZuoMgr,'com.xq.modules.meiribizuo.MeiRiBiZuoMgr');
	var __proto=MeiRiBiZuoMgr.prototype;
	__proto.getWenSanGuanData=function(){
		if(!this.wenSanGuanData){
			this.wenSanGuanData=new DataContainer();
			var cfgArr=this.wenSanGuanTab.objectDataArray;
			var len=cfgArr.length;
			for (var i=0;i < len;i++){
				var cfg=cfgArr[i];
				var ele=new DataElement(cfg);
				this.wenSanGuanData.addElement(cfg.id,ele);
				if(i==(len-1)){
					this._lastWenSanGuanId=parseInt(cfg.id);
				}
			}
		}
		return this.wenSanGuanData;
	}

	__proto.wenSanCfg=function(){
		return this._curWenSanCfg;
	}

	__proto.nextWenSanCfg=function(){
		return this._nextWenSanCfg;
	}

	/**找出同官职所有阶的数据*/
	__proto.getStarNum=function(type){
		var jieShuArr=this.getWenSanGuanData().where("type",type,"type").array;
		var len=jieShuArr.length;
		var starNum=0;
		for (var i=0;i < len;i++){
			starNum++;
		}
		return starNum;
	}

	/**根据类型返回表中数组*/
	__proto.getDWNameArrByType=function(type){
		var ele=this.getWenSanGuanData().getElement(this._lastWenSanGuanId);
		if(!ele)return [];
		var lastCfg=ele.getCfgData();
		var minDWNum=13;
		var maxDWNum=parseInt(lastCfg.type);
		var dwAdd=type+3;
		if(dwAdd>minDWNum){
			dwAdd>maxDWNum?minDWNum=maxDWNum:minDWNum=dwAdd;
		};
		var dwNameArr=[];
		for(var i=1;i<=minDWNum;i++){
			ele=this.getWenSanGuanData().where("type",i,"type").array[0];
			dwNameArr.push(ele);
		}
		return dwNameArr;
	}

	__proto.isGray=function(curId,nextId){
		if(curId<nextId)return true;
		return false;
	}

	__proto.getCurWenSanRewardCfg=function(){
		return this._curWenSanRewardCfg;
	}

	__proto.getWenSanGuanId=function(){
		return this._lastWenSanGuanId;
	}

	__getset(0,__proto,'curWenSanCfg',null,function(wenSanCfgId){
		this._curWenSanCfg=this.getWenSanGuanData().getElement(wenSanCfgId+"").getCfgData();
		if(this.getWenSanGuanData().getElement((wenSanCfgId+1)+"")){
			this._nextWenSanCfg=this.getWenSanGuanData().getElement((wenSanCfgId+1)+"").getCfgData();
			}else{
			this._nextWenSanCfg=null;
		}
	});

	__getset(0,__proto,'curWenSanRewardCfg',null,function(wenSanCfgId){
		if(this.getWenSanGuanData().getElement(wenSanCfgId+"")){
			this._curWenSanRewardCfg=this.getWenSanGuanData().getElement(wenSanCfgId+"").getCfgData();
		}
		else{
			this._curWenSanRewardCfg=null;
		}
	});

	return MeiRiBiZuoMgr;
})()


