//class com.xq.modules.meiribizuo.XianShiMgr
var XianShiMgr=(function(){
	function XianShiMgr(){
		/**打开面板类型 0按钮 1是其他*/
		this.openType=1;
		/**限时活动预告面板*/
		this.xianshiYGView=null;
		/**活动进行提醒Mgr*/
		this._arM=null;
		/**限时活动Model*/
		this._xsModel=null;
		/**活动Tip弹出对象字典*/
		this._activityDic={};
		this.activeDic=null;
		this._arM=ActivityRemaindMgr.ins;
		this._xsModel=Model.xianshiativity;
	}

	__class(XianShiMgr,'com.xq.modules.meiribizuo.XianShiMgr');
	var __proto=XianShiMgr.prototype;
	/**日常活动注册*/
	__proto.regActivity=function(type,method){
		if(method.once){
			console.log(Lang.str(2683));
			debugger;
		}
		if(!this.activeDic){
			this.activeDic={};
		}
		if(this.activeDic[type]){
			debugger;
			console.log(Lang.str(2684)+type);
		}
		else{
			this.activeDic[type]=method;
		}
	}

	/**执行活动函数*/
	__proto.runActivity=function(type){
		var run=this.activeDic[type];
		if(run){
			run.run();
		}
	}

	/**启动计时器 弹出活动开始提示*/
	__proto.start=function(){
		Laya.timer.loop(5000,this,this.checkOpen);
		if(!this.xianshiYGView){
			this.xianshiYGView=UIMgrR.newInstanceByIClass(com.xq.view.modules.bossHall.nanManRuQin.IXianShiActiveYLView);
			this.xianshiYGView.dataSource=null;
			Game.getInstance().newMainView.addChild(this.xianshiYGView);
			Game.getInstance().newMainView.addViewToHide(this.xianshiYGView,MainHideEnum.type1);
			Game.getInstance().newMainView.addViewToHide(this.xianshiYGView,MainHideEnum.ZhuCheng);
		}
	}

	__proto.checkOpen=function(){
		var arr=this.getTodayActivity();
		var len=arr.length;
		var ele;
		var stat=0;
		var cof;
		var funcId;
		var haveOpen=false;
		var scaleButton=Game.getInstance().newMainView.getCustomTitle();
		for(var i=0;i<len;i++){
			ele=arr[i];
			cof=ele.getCfgData();
			funcId=cof.functionid;
			stat=this.getActivityStat(ele);
			if(stat==1){
				haveOpen=true;
				var isOpen=this._activityDic[funcId];
				if(!ActivityRemaindMgr.ins.activeIsOpen(funcId)&&!isOpen){
					this.xianshiYGView.dataSource=ele;
					scaleButton.right=130;
					this._arM.showActivity(cof.id);
					this._activityDic[funcId]=true;
					return;
				}
			}
		}
		if(!haveOpen){
			this.xianshiYGView.dataSource=null;
			this._arM.clearCurActivity();
			scaleButton.right=15;
		}
	}

	/**根据FuncId获取开启时间描述*/
	__proto.getOpenTimeDesc=function(funcId){
		var desc="";
		var ele;
		var cof;
		var arr=this._xsModel.getEleArrByFuncId(funcId);
		var len=arr.length;
		for(var i=0;i<len;i++){
			ele=arr[i];
			cof=ele.getCfgData();
			if(cof.week!="0"&&cof.week!="1;2;3;4;5;6;7"){
				var week=cof.week.split(";");
				desc+=CommonUtil.numsToWeek(week)+" "+cof.time+" ";
			}
			else{
				desc.indexOf("每日")==-1?desc+="每日"+cof.time+" ":desc+=cof.time+" ";
			}
		}
		return desc;
	}

	/**获取日常活动*/
	__proto.getCurTask=function(){
		var ary=Mgr.xianShi.getTodayActivity();
		var ele=ary[0];
		if(ele){
			var stat=Mgr.xianShi.getActivityStat(ele);
			if(stat <3){
				var cof=ele.getCfgData();
				var obj={};
				obj.dec="【"+cof.name+"】"+cof.time;
				obj.panelId=52004;
				obj.dec2=CodeMgr.ins.getStringByCode(260919);
				obj.state=stat==1;
				return obj
			}
		}
		return null;
	}

	/**通过功能ID打开*/
	__proto.openByFunctionID=function(func){
		switch(func){
			case "tianjianghaoli":
				Mgr.tjhlAct.reqEnter();
				break ;
			case "bangpaigouhuo":
				Mgr.ghMgr.openGouhuoView();
				break ;
			case "baodagm":
				Mgr.baoDaGMMgr.sendEnterScene();
				break ;
			default :
				Mgr.prompt.optionPrompt(Lang.str(2685));
				break ;
			}
	}

	/**获取今日 限时活动*/
	__proto.getTodayActivity=function(){
		var todayArr=[];
		var arr=this._xsModel.qtwfDc.array;
		var len=arr.length;
		var ele;
		var cof;
		for(var i=0;i<len;i++){
			ele=arr[i];
			cof=ele.getCfgData();
			if(this.ifTodayActivity(cof)){
				todayArr.push(ele);
			}
		}
		todayArr=todayArr.sort(this.compareToday);
		return todayArr;
	}

	/**获取活动总览数组*/
	__proto.getActivityOverviewArr=function(){
		var activityOverViewArr=[];
		var arr=this._xsModel.getFunIdArr();
		var funId;
		var arr2;
		var cfg;
		var activityOverViewVo;
		var len=arr.length;
		for(var i=0;i<len;i++){
			funId=arr[i].toString();
			arr2=this._xsModel.getEleArrByFuncId(funId);
			cfg=this.getCfg(arr2);
			activityOverViewVo=new ActivityOverViewVo();
			activityOverViewVo.time=this.getOpenTimeDesc(funId);
			activityOverViewVo.reward=cfg.jiangli.split(";");
			activityOverViewVo.res=cfg.res;
			activityOverViewVo.des=cfg.des;
			activityOverViewArr.push(activityOverViewVo);
		}
		return activityOverViewArr;
	}

	__proto.getCfg=function(array){
		return array[0].getCfgData();
	}

	/**判断是否是今日的活动*/
	__proto.ifTodayActivity=function(cof){
		var week=cof.week;
		if(week=="0"){
			return true;
		};
		var kfLimit=cof.kaifutime;
		if(kfLimit){
			var ifSevenDay=CommonUtil.checkIsInSevenDay();
			var arr=kfLimit.split(";");
			if(arr.indexOf(ifSevenDay.toString())!=-1){
				return true;
			}
		}
		arr=week.split(";");
		var kfDays=CommonUtil.openServerDay;
		var serDate=Mgr.curTime.serverDate;
		var day=serDate.getDay();
		day=day?day:7;
		if(arr.indexOf(day.toString())!=-1){
			return true;
		}
		return false;
	}

	/**获取该限时活动的状态
	*1：进行中
	*2：未开始
	*3：已结束
	*4：功能未开启
	**/
	__proto.getActivityStat=function(ele){
		var cof=ele.getCfgData();
		var funcId=cof.functionid;
		var partentId=cof.partentId;
		if(!Mgr.guide.isOpen(funcId)||!Mgr.guide.isOpen(partentId)){
			return 4;
		};
		var serDate=Mgr.curTime.serverDate;
		var time=cof.time;
		var timeArr=time.split("-");
		var stat=CommonUtil.compareTimes(serDate,timeArr[0],timeArr[1]);
		if(stat==0){
			return 3;
		}
		else if(stat==1){
			return 2;
		}
		else{
			return 1;
		}
	}

	__proto.compareToday=function(eleA,eleB){
		var statA=Mgr.xianShi.getActivityStat(eleA);
		var StatB=Mgr.xianShi.getActivityStat(eleB);
		if(statA==StatB){
			return eleA.getCfgData().id-eleB.getCfgData().id;
		}
		return statA-StatB;
	}

	/**获取开启时间*/
	__proto.getOpenDate=function(ele){
		var cof=ele.getCfgData();
		var time=cof.time;
		var startTime=time.split("-")[0];
		var timeArr=startTime.split(":");
		var hour=parseInt(timeArr[0]);
		var min=parseInt(timeArr[1]);
		var serverDate=Mgr.curTime.serverDate;
		return new Date(serverDate.getFullYear(),
		serverDate.getMonth(),serverDate.getDate(),
		hour,min,0);
	}

	/**清理活动字典数据*/
	__proto.clearActivityDic=function(){
		for(var key in this._activityDic){
			this._activityDic[key]=false;
		}
	}

	return XianShiMgr;
})()


