//class com.xq.modules.meirisaodang.MeiRiSaoDangMgr
var MeiRiSaoDangMgr=(function(){
	function MeiRiSaoDangMgr(){
		this.listData=null;
		this.mrskCfg=null;
		this.red=null;
		this.mrskCfg=CfgManager.getTableCfg("meiridangkou");
		this.listData=[];
		this.red=Mgr.red;
		this.red.regist("richang","meiRiDangKou",true,"ACT_CORNER_UPDATE");
	}

	__class(MeiRiSaoDangMgr,'com.xq.modules.meirisaodang.MeiRiSaoDangMgr');
	var __proto=MeiRiSaoDangMgr.prototype;
	__proto.getCfgData=function(type,count){
		var obj=this.mrskCfg.getCfgMsgArrByTwoKey("type",type,"count",count);
		return obj;
	}

	/**获取最大领取次数*/
	__proto.getCfgCount=function(type,openkey){
		var len=this.mrskCfg.objectDataArray.length;
		var count=0;
		for (var i=0;i < len;i++){
			var obj=this.mrskCfg.objectDataArray[i];
			if(obj.type==type){
				if(obj.openkey <=openkey){
					count=obj.count;
					}else{
					break ;
				}
			}
		}
		return count;
	}

	__proto.onMeiRiDangKouInfo=function(vo){
		this.listData.length=0;
		var len=vo.msgs.length;
		for (var i=0;i < len;i++){
			var dangKou=vo.msgs[i];
			var count=dangKou.getMonsterRewardId;
			var obj={};
			var objCfg=this.getCfgData(dangKou.type,count+1)[0];
			obj["isMax"]=false;
			if(!objCfg){
				objCfg=this.getCfgData(dangKou.type,count)[0];
				obj["isMax"]=true;
			}
			obj["cfg"]=objCfg;
			obj["dataSC"]=dangKou;
			this.listData.push(obj);
		}
		this.redMrxs();
		EventCenter.instance.event("meirisaokou_info");
	}

	__proto.onMeiRiDangKouReward=function(vo){
		var len=this.listData.length;
		for (var i=0;i < len;i++){
			var dataSC=this.listData[i].dataSC;
			if(vo.type==dataSC.type){
				this.listData[i].cfg=null;
				var obj={};
				var objCfg=this.getCfgData(vo.type,vo.getRewardId+1)[0];
				this.listData[i].isMax=false;
				if(!objCfg){
					objCfg=this.getCfgData(vo.type,vo.getRewardId)[0];
					this.listData[i].isMax=true;
				}
				this.listData[i].cfg=objCfg;
				dataSC.getMonsterRewardId=vo.getRewardId;
				break ;
			}
		}
		this.redMrxs();
		EventCenter.instance.event("meirisaokou_info");
		EventCenter.instance.event("meirisaokou_reward");
	}

	__proto.redMrxs=function(){
		var len=this.listData.length;
		this.red.hideRedPoint("meiRiDangKou","meiridankou",RedTypeEnum.MeiRiXuanShangRed);
		for (var i=0;i < len;i++){
			var obj=this.listData[i];
			var cfg=obj.cfg;
			var dataSC=obj.dataSC;
			if(dataSC.getMonsterRewardId < cfg.count && dataSC.monsterNum >=cfg.num && (Mgr.gqMgr.gqInfo.nextLevel-1)>=cfg.openkey){
				this.red.showRedPoint("meiRiDangKou","meiridankou",RedTypeEnum.MeiRiXuanShangRed);
				break ;
			}
		}
	}

	/**获取每日荡寇的任务*/
	__proto.getCurTask=function(){
		var ary=this.listData || [];
		var len=ary.length;
		for (var i=0;i < len;i++){
			var item=ary[i];
			if(!item.isMax){
				var cfg=item.cfg;
				if(cfg){
					if(cfg.type==5000){
						var txt=Lang.str(2686);
						}else{
						txt=Lang.str(2687);
					};
					var obj={};
					obj.dec=txt
					obj.panelId=52005;
					obj.dec2=CodeMgr.ins.getStringByCode(260918);
					obj.state=item.dataSC.monsterNum >=parseInt(cfg.num);
					return obj;
				}
			}
		}
		return null;
	}

	MeiRiSaoDangMgr.MEIRISAOKOU_INFO="meirisaokou_info";
	MeiRiSaoDangMgr.MEIRISAOKOU_REWARD="meirisaokou_reward";
	return MeiRiSaoDangMgr;
})()


