	/**传入货币类型 判断货币是否足够*/
	__proto.checkMoneyEnough=function(moneyType,moneyNum,isShowTip){
		(isShowTip===void 0)&& (isShowTip=false);
		var isEnough=false;
		var roleVo=NetMgr.ins().roleVO;
		var str=null;
		if(moneyType==2){
			isEnough=roleVo.yuanbao >=moneyNum;
			}else if(moneyType==13){
			isEnough=roleVo.taiYu >=moneyNum;
			str=Lang.str(2713);
		}
		if(isShowTip && !isEnough){
			var yuanBaoBuZu=UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
			if(str){
				yuanBaoBuZu.setTiShi(str);
			}
		}
		return isEnough;
	}

