	/**技能红点*/
	__proto.checkSkillRed=function(type){
		if(!type)
			return;
		var oId=this.model.funTypeAry[type];
		if(!Mgr.guide.isOpen(oId)){
			return;
		};
		var key=type+"_"+RedTypeEnum.UpgradeTypeSkill;
		var funID=this.pyFunObj[type];
		if(funID){
			var redBo=this.checkSkillData(type);
			if(redBo)
				this.red.showRedPoint(funID,key,RedTypeEnum.UpgradeTypeSkill);
			else
			this.red.hideRedPoint(funID,key,RedTypeEnum.UpgradeTypeSkill);
		}
	}

	__proto.getTypeCache=function(type){
		if(!this.typeCache[type])
			this.typeCache[type]=this.getCfgTableByType(type)
		return this.typeCache[type];
	}

	/**进阶材料检测*/
	__proto.getUpgradeMateri=function(type){
		if(this.model.curModel){
			var serInfo=this.model.curModel.myPayLineInfo[type];
			if(serInfo && serInfo.activeState){
				if(serInfo.jieshu >=this.getMaxJie(type))
					return false;
				var key=(type+"_"+serInfo.jieshu+serInfo.stars).toString()
				var cfgTable=this.getTypeCache(type);
				if(cfgTable){
					if(!this.cfgCahObj[key])
						this.cfgCahObj[key]=cfgTable.getCfgMsgByTwoKey("type",serInfo.jieshu,"level",serInfo.stars);
					var curCfgInfo=this.cfgCahObj[key];
					if(curCfgInfo){
						if(Mgr.item.checkMatIsEnou(curCfgInfo["needitem"]))
							return true;
					}
				}
			}
		}
		return false;
	}

	/**检测进阶技能*/
	__proto.checkSkillData=function(type){
		if(this.model.curModel){
			var serInfo=this.model.curModel.myPayLineInfo[type];
			if(!serInfo || !serInfo.activeState)
				return false;
			var cfgTable=this.getTypeCache(type);
			if(cfgTable){
				var cfgObj=cfgTable.objectDataArray;
				var len=cfgObj.length;
				var curLv=this.model.curModel.getPeiYangLevel(type);
				for(var i=0;i < len;i++){
					var tempObj=cfgObj[i];
					if(tempObj["skillCategory"]){
						if(serInfo.jieshu >=tempObj.type){
							var skillInfo=this.getModelSKill(this.model.curModel,type,tempObj.skillCategory);
							if(skillInfo){
								var nextSki=SkillManager.ins.getData(tempObj.skillCategory,false,skillInfo.skillLevel+1);
								if(nextSki && nextSki.levelneed <=curLv){
									return true
								}
							}
						}
					}
				}
			}
		}
		return false;
	}

