			var sai=Lang.str(2736);
			if(name.indexOf(sai)==-1)name=name+sai;
			var desc=Lang.str(2737)+name+Lang.str(2738);
			AlertUtil.ShowAlert(desc,Handler.create(this,this.jumpToView),null);
