//class com.xq.modules.qudaoxuqiu.QuDaoXuQiuMgr
var QuDaoXuQiuMgr=(function(){
	function QuDaoXuQiuMgr(){
		/**是否已经绑定了手机号码(默认已经绑定了已屏蔽入口)*/
		this.isBindPhone=true;
		this._superMemberModel=null;
		/**绑定手机model*/
		this._bindPhoneModel=null;
		/**添加客服model*/
		this._addCustomServicerModel=null;
		this._superMemberModel=new SuperMemberModel();
		this._bindPhoneModel=new BindPhoneModel();
		this._addCustomServicerModel=new AddCustomServicerModel();
	}

	__class(QuDaoXuQiuMgr,'com.xq.modules.qudaoxuqiu.QuDaoXuQiuMgr');
	var __proto=QuDaoXuQiuMgr.prototype;
	/**通过平台Id获取对应配置数据元素*/
	__proto.getElesByPlat=function(plat){
		return this._superMemberModel.getElesByPlat(plat);
	}

	/**通过平台Id获取对应配置 奖励*/
	__proto.getShowRewardArr=function(plat){
		var ele=this.getElesByPlat(plat);
		if(!ele)return [];
		var cfg=ele.getCfgData();
		return cfg.reward;
	}

	/**通过平台Id获取对应配置 奖励*/
	__proto.getQQ=function(plat){
		var ele=this.getElesByPlat(plat);
		if(!ele)return "";
		var cfg=ele.getCfgData();
		return cfg.number;
	}

	/**获取超级会员状态信息*/
	__proto.getSuperMemberInfo=function(){
		return this._superMemberModel.getInfo();
	}

	//================================
	__proto.initBindPhone=function(){
		this.checkBindPhoneIconVis();
		if(!this.isBindPhone&&!Configs.isForbitQuDaoAct&&NetMgr.ins().roleVO.level<parseInt(Mgr.cfgMgr.getValueByType(5001))){
			EventCenter.instance.onQue("LEVEL_UP",this,this.checkBindPhoneIconVis);
		}
	}

	/**绑定手机奖励配置*/
	__proto.getBindPhoneEle=function(plat){
		return this._bindPhoneModel.getElesByPlat(plat);
	}

	/**检测 绑定手机活动 显示还是隐藏*/
	__proto.checkBindPhoneIconVis=function(){
		if(Configs.isForbitQuDaoAct){
			EventCenter.instance.event("ACTIVE_TOGGLE",["BindPhoneNumber"]);
			return;
		}
		if(this.isBindPhone){
			EventCenter.instance.event("ACTIVE_TOGGLE",["BindPhoneNumber"]);
			return;
		}
		if(NetMgr.ins().roleVO.level<parseInt(Mgr.cfgMgr.getValueByType(5001))){
			EventCenter.instance.event("ACTIVE_TOGGLE",["BindPhoneNumber"]);
			return;
		}
		EventCenter.instance.event("ACTIVE_TOGGLE",["BindPhoneNumber",false]);
		EventCenter.instance.off("LEVEL_UP",this,this.checkBindPhoneIconVis);
	}

	/**获取添加客服渠道配置ele*/
	__proto.getAddCustomServicerEle=function(plat){
		return this._addCustomServicerModel.getElesByPlat(plat);
	}

	//======同步后端数据=======
	__proto.updateSuperMemberInfo=function(msg){
		this._superMemberModel.updateSuperMemberInfo(msg);
		EventCenter.instance.event("UpdateSuperMemberInfo");
	}

	/**同步是否绑定了手机号码*/
	__proto.updateBindPhone=function(isBind){
		this.isBindPhone=isBind
		this.initBindPhone();
	}

	return QuDaoXuQiuMgr;
})()


