//class com.xq.modules.relationship.RelationshipTianShenMgr
var RelationshipTianShenMgr=(function(){
	function RelationshipTianShenMgr(){
		this.fetterSkillCfg=null;
		this.isShowRed=false;
		this.firstLevelCfgs=null;
		this.fetterDatas=new Dictionary();
		this.setup();
	}

	__class(RelationshipTianShenMgr,'com.xq.modules.relationship.RelationshipTianShenMgr');
	var __proto=RelationshipTianShenMgr.prototype;
	__proto.setup=function(){
		this.fetterSkillCfg=CfgManager.getTableCfg("ShenJiangJiBan");
		Mgr.red.regist("zhanJiang","MoJiangJIBAN",true,RedTypeEnum.HeroSystemRed);
		Mgr.red.regist("nvshen","XianJiJIBAN",true,RedTypeEnum.HeroSystemRed);
		Mgr.red.regist("tianShen","TianShenJIBAN",true,RedTypeEnum.HeroSystemRed);
		Mgr.red.regist("mengchong","LingChongJIBAN",true,RedTypeEnum.HeroSystemRed);
	}

	__proto.updateRed=function(){
		var list=this.firstLevelFettersCfgs;
		var len=list.length;
		var firstCfg;
		var curCfg;
		var isActiveOrUpLv=false;
		this.isShowRed=false;
		for (var i=0;i < len;i++){
			firstCfg=list[i];
			isActiveOrUpLv=false;
			curCfg=com.xq.modules.relationship.RelationshipTianShenMgr.ins.getFetterCfg(firstCfg.id,com.xq.modules.relationship.RelationshipTianShenMgr.ins.getFetterLevel(firstCfg.id));
			if(!curCfg)
				continue ;
			if(this.isAddLiBaoRed(firstCfg.id)){
				this.isShowRed=true;
			}
			if(curCfg.level <=0){
				if(this.isCanActive(curCfg)){
					isActiveOrUpLv=true;
					this.isShowRed=true;
				}
			}
			else{
				var cfg=this.getFetterCfg(curCfg.id,0);
				var needLv=parseInt(curCfg.shenjiangLv);
				if(!cfg)continue ;
				var arr=cfg.shenJiangIds.split(";");
				var reachNum=this.getReachCfgLvHHNum(arr,needLv);
				if(reachNum==arr.length){
					isActiveOrUpLv=true;
					this.isShowRed=true;
				}
			}
			isActiveOrUpLv?curCfg.sortIndex=i:curCfg.sortIndex=9999+i;
		}
		this.redStateRefresh(this.isShowRed);
		list.sort(this.compare);
	}

	__proto.compare=function(cfg,cfg2){
		return cfg.sortIndex-cfg2.sortIndex;
	}

	__proto.redStateRefresh=function(state){
		if(state){
			Mgr.red.showRedPoint("MoJiangJIBAN","JiBanInfoEvent","JiBanInfoEvent");
			Mgr.red.showRedPoint("XianJiJIBAN","JiBanInfoEvent","JiBanInfoEvent");
			Mgr.red.showRedPoint("TianShenJIBAN","JiBanInfoEvent","JiBanInfoEvent");
			Mgr.red.showRedPoint("LingChongJIBAN","JiBanInfoEvent","JiBanInfoEvent");
			}else{
			Mgr.red.hideRedPoint("MoJiangJIBAN","JiBanInfoEvent","JiBanInfoEvent");
			Mgr.red.hideRedPoint("XianJiJIBAN","JiBanInfoEvent","JiBanInfoEvent");
			Mgr.red.hideRedPoint("TianShenJIBAN","JiBanInfoEvent","JiBanInfoEvent");
			Mgr.red.hideRedPoint("LingChongJIBAN","JiBanInfoEvent","JiBanInfoEvent");
		}
	}

	/**
	*得到配置数据
	*@param id
	*@return
	*
	*/
	__proto.getFetterCfg=function(id,level){
		return this.fetterSkillCfg.getCfgMsgByTwoKey("id",id,"level",level);
	}

	/**
	*得到羁绊数据
	*@param id
	*@return
	*
	*/
	__proto.getFetterData=function(id){
		return this.fetterDatas.get(id);
	}

	__proto.getAllFetterData=function(){
		return this.fetterDatas.values;
	}

	__proto.isActive=function(id){
		var msg=this.getFetterData(id);
		if(msg)
			return msg.currLv > 0;
		return false;
	}

	__proto.getFetterLevel=function(id){
		var msg=this.getFetterData(id);
		if(msg)
			return msg.currLv;
		return 0;
	}

	/**
	*羁绊是否满级
	*@param id
	*@param level
	*@return
	*
	*/
	__proto.isMaxLevel=function(id,level){
		return !(this.getFetterCfg(id,parseInt(level)+1));
	}

	__proto.isCanActive=function(cfgObj,isHint){
		(isHint===void 0)&& (isHint=false);
		var suits=cfgObj.shenJiangIds.split(";");
		var len=suits.length;
		var id=0;
		for(var i=0;i < len;i++){
			id=parseInt(suits[i]);
			if(!Mgr.szMgr.szModel.huanhuaDic[id]){
				if(isHint)
					Mgr.prompt.optionPrompt(Lang.str(2756));
				return false;
			}
		}
		return true;
	}

	/**获取羁绊技能相关的数据操作 */
	__proto.onGetFetterSkillInfoSC=function(vo){
		this.fetterDatas.clear();
		if(vo && vo.fetterDatas){
			var len=vo.fetterDatas.length;
			var msgVo;
			for(var i=0;i < len;i++){
				msgVo=vo.fetterDatas[i];
				this.fetterDatas.set(msgVo.id,msgVo);
			}
		}
	}

	/**激活羁绊操作*/
	__proto.reqActiveFetterSkillCS=function(cfgObj){
		if(!this.isCanActive(cfgObj,true))
			return;
		RelationshipTianShenAction.ins.reqActiveFetterSkillCS(cfgObj.id);
	}

	/**激活羁绊返回 */
	__proto.onActiveFetterSkillSC=function(vo){
		this.fetterDatas.set(vo.fetterData.id,vo.fetterData);
		EventCenter.instance.event("ACTIVE_JIBAN");
	}

	/**升级羁绊*/
	__proto.reqFetterSkillUpgradeCS=function(type,cfgObj){
		RelationshipTianShenAction.ins.reqFetterSkillUpgradeCS(type,cfgObj.id);
	}

	/**升级羁绊返回 */
	__proto.onFetterSkillUpgradeSC=function(vo){
		this.fetterDatas.set(vo.fetterData.id,vo.fetterData);
		EventCenter.instance.event("UP_JIBAN");
	}

	/**更新奖励*/
	__proto.onUpdateReward=function(msg){
		var vo=this.getFetterData(msg.fetterId);
		vo.rewards=vo.rewards+","+msg.level;
		EventCenter.instance.event("LqRewardRfresh");
	}

	/**获取激活羁绊相对应的幻化激活的数量*/
	__proto.getActiveHHIDNum=function(shenjiangIds){
		if(!shenjiangIds)return 0;
		var len=shenjiangIds.length;
		var hhId;
		var activeNum=0;
		var huanHuaAttr;
		for(var i=0;i<len;i++){
			hhId=shenjiangIds[i];
			huanHuaAttr=Model.shizhuang.huanhuaDic[hhId];
			if(huanHuaAttr){
				activeNum++;
			}
		}
		return activeNum;
	}

	/**获取达成当前阶的战将数量*/
	__proto.getReachCfgLvHHNum=function(shenjiangIds,needLv){
		if(!shenjiangIds)return 0;
		var len=shenjiangIds.length;
		var hhId;
		var huanHuaAttr;
		var jie=0;
		var hhCfg;
		var arr;
		var reachNum=0;
		for(var i=0;i<len;i++){
			hhId=shenjiangIds[i];
			hhCfg=Mgr.szMgr.getCfgById(hhId);
			huanHuaAttr=Model.shizhuang.huanhuaDic[hhId];
			arr=Mgr.szMgr.getCurJieAndStarByLv(huanHuaAttr.level,hhCfg.limitStar);
			jie=arr?arr[0]:0;
			if(jie>=needLv){
				reachNum++;
			}
		}
		return reachNum;
	}

	/**根据id获取数组*/
	__proto.getArrById=function(id){
		var arr=this.fetterSkillCfg.getItemsByField("id",id);
		arr.splice(0,1);
		var len=arr.length;
		var cfgLv=0;
		var state=0;
		var cfg;
		for(var i=0;i<len;i++){
			cfg=arr[i];
			cfgLv=parseInt(cfg.level);
			state=this.curLiBaoState(id,cfgLv);
			if(state==1){
				cfg.sortIndex=i;
				}else if(state==0){
				cfg.sortIndex=999+i;
				}else{
				cfg.sortIndex=9999+i;
			}
		}
		arr=arr.sort(this.compareReward);
		return arr;
	}

	__proto.compareReward=function(cfg,cfg2){
		return cfg.sortIndex-cfg2.sortIndex;
	}

	/**是否添加礼包红点*/
	__proto.isAddLiBaoRed=function(id){
		var msg=this.getFetterData(id);
		if(!msg)return false;
		var rewardArr=msg.rewards.split(",");
		var index=0;
		var showRed=false;
		for(var i=msg.currLv;i>0;i--){
			index=rewardArr.indexOf(i);
			if(index==-1){
				showRed=true;
				break ;
			}
		}
		if(showRed)return true;
		return false;
	}

	/**0 未达成 1:可以领取 2:已领取*/
	__proto.curLiBaoState=function(id,lv){
		var msg=this.getFetterData(id);
		if(!msg)return 0;
		var rewardArr=msg.rewards.split(",");
		var index=rewardArr.indexOf(lv);
		if(lv>msg.currLv)return 0;
		if(index==-1&&lv<=msg.currLv)return 1;
		return 2;
	}

	__getset(0,__proto,'firstLevelFettersCfgs',function(){
		if(this.firstLevelCfgs)
			return this.firstLevelCfgs;
		this.firstLevelCfgs=[];
		var alls=this.fetterSkillCfg.objectDataArray;
		var len=alls.length;
		if(len <=0)
			return null;
		var cfgObj;
		for(var i=0;i < len;i++){
			cfgObj=alls[i];
			if(cfgObj.level==0){
				this.firstLevelCfgs.push(cfgObj);
			}
		}
		return this.firstLevelCfgs;
	});

	__getset(1,RelationshipTianShenMgr,'ins',function(){
		return RelationshipTianShenMgr._ins=RelationshipTianShenMgr._ins||new RelationshipTianShenMgr();
	});

	RelationshipTianShenMgr._ins=null;
	return RelationshipTianShenMgr;
})()


