//class com.xq.modules.SDKMgr
var SDKMgr=(function(){
	function SDKMgr(){
		this.deviceInfo=null;
		this.isInit=false;
	}

	__class(SDKMgr,'com.xq.modules.SDKMgr');
	var __proto=SDKMgr.prototype;
	/**
	*{
		screen_height:"",//屏幕高
		screen_width:"",//屏幕宽
		device_id:"",//device_id
		ios_idfa:"",//ios idfa
		android_imei:"",//安卓imei
		android_adv_id:"",//
		android_id:"",//
		device_name:"",//设备名称
		os_ver:"",//系统版本
		sdk_ver:"",//sdk版本
		package_name:"",//报名ݷ
		os_type:"",//系统类型:h5,ios,android
		net_type:"",//网络类型:2g,3g,4g,wifi
		applicaiton_memory:"",//应用分配的系统内存
		applicaiton_usage_memory:"",//应用使用的内存
		capacity:"",//机身存储空间
		battery:"",//电量
	}

	**/
	__proto.onGetDevice=function(info){
		var ins=com.xq.modules.SDKMgr.ins();
		if(!ins.isInit){
			ins.isInit=true;
			var st=JSON.stringify(info);
			var p={other:st};
			LogMgr.ins.report(21,p);
		}
		ins.deviceInfo=info;
	}

	__proto.update=function(){
		if(typeof(SDKRuntime)!="undefined"){;
			SDKRuntime.h5_get_device && SDKRuntime.h5_get_device(this.onGetDevice);
		};
	}

	SDKMgr.ins=function(){
		return SDKMgr._ins=SDKMgr._ins|| new SDKMgr();
	}

	SDKMgr._ins=null;
	return SDKMgr;
})()


/**
*创角管理--（暂时用于自动创角）
*@author zhanglimin
*@date 2020-6-5
**/
//class com.xq.modules.server.CreateRoleMgr
var CreateRoleMgr=(function(){
	function CreateRoleMgr(){
		/**是否是全数字*/
		this.isNumAll=/^(\d)+$/;
		/**是否是全字符 */
		this.isStringAll=/^(\D)+$/;
		this.cur_chooseVo=null;
		this._autoCreateTime=0;
	}

	__class(CreateRoleMgr,'com.xq.modules.server.CreateRoleMgr');
	var __proto=CreateRoleMgr.prototype;
	__proto.autoCreate=function(){
		console.log(Lang.str(2759))
		var job=(Math.random()< 0.5)? "A" :"C";
		var name=CommonUtil.getRanNameBySex(job);
		this.checkNameIsOK(name,Handler.create(this,this.autoCreateLater,[name,job]))
		this._autoCreateTime++;
	}

	__proto.autoCreateLater=function(name,job,isLegal){
		if(!isLegal){
			this.autoCreate();
			return;
		};
		var tempCfg=Model.shenjiang.getCfgByJob(job);
		var _net=NetMgr.ins();
		_net.roleVO.res=tempCfg.res;
		this.cur_chooseVo=new ShenJiangVO();
		this.cur_chooseVo.bind2(tempCfg);
		Mgr.userLogin.sendCreateRole(this.cur_chooseVo,name,Handler.create(this,this.onCreateOK),true);
	}

	/**创角成功 发送角色登录消息*/
	__proto.onCreateOK=function(data,suc){
		if(suc){
			var roleVo=new HeroVO();
			roleVo.guid=data.id;
			roleVo.sex=data.gender;
			roleVo.res=this.cur_chooseVo.res;
			roleVo.job=data.job;
			roleVo.name=data.name;
			roleVo.level=data.level;
			roleVo.face=data.face;
			NetMgr.ins().roleVO=roleVo;
			Mgr.userLogin.sendRoleLogin(data.id,Handler.create(this,this.onRoleLoginOK));
		}
		else{
			if(this._autoCreateTime<6){
				this.autoCreate();
			}
			else{
				var str=Lang.str(2760)
				console.log(str);
				debugger
				laya.xq.cfg.reportOneBug(str,new Error(str));
				ReconnectAction.getInstance().restart();
				this._autoCreateTime=0;
			}
		}
	}

	__proto.onRoleLoginOK=function(){
		Mgr.sceneSyn.sendApplyEnterStage();
		EventCenter.instance.once("APPLY_ENTER_SCENE",this,this.onApplyEnterOK);
	}

	__proto.onApplyEnterOK=function(){
		var game=Game.getInstance();
		var vo=NetMgr.ins().roleVO;
		vo.isPlayerSelf=true;
		EventCenter.instance.once("MAP_LOAD_OK",this,this.sendEnterScene);
		Laya.stage.addChild(game);
	}

	__proto.sendEnterScene=function(){
		EventCenter.instance.once("ENTER_SCENE",this,this.enterScene);
	}

	/**准备进入场景*/
	__proto.enterScene=function(){
		var game=Game.getInstance();
		game.start();
		game.sceneContainer.unitLayer.addChild(game.player);
		Laya.loader.clearRes("res/atlas/create.json");
		Laya.loader.clearRes("res/atlas/loading.json",true);
		SoundManager.destroySound(PathDefine.getSoundUrl("man"));
		SoundManager.destroySound(PathDefine.getSoundUrl("woman"));
		var r=NetMgr.ins().roleVO;
		var p={};
		p.uid=NetMgr.ins().serverVO.userId;
		p.roleguid=r.guid;
		p.rolelevel=r.level;
		p.viplevel=r.vipLevel;
		p.yuanbao=r.yuanbao;
		p.tongban=r.taiYu;
		p.isnewrole=r.level==1 ?"1" :"0";
		LocalStorage.setItem(NetMgr.ins().serverVO.userId,r.job);
		LogMgr.ins.report(18,p);
	}

	/**检测当前姓名是否合法*/
	__proto.checkNameIsOK=function(userName,callBack,nameType){
		if(!nameType){
			nameType=Lang.str(2761)
		}
		this.checkStringIsOK(userName,callBack,nameType,true);
	}

	__proto.checkStringIsOK=function(userName,callBack,nameType,isName){
		(isName===void 0)&& (isName=false);
		if(!nameType){
			nameType=Lang.str(2761)
		};
		var tempStr="";
		if(!TextUtil.checkStrIsOK(userName)){
			tempStr=Lang.str(2762)+nameType+Lang.str(2763);
		}
		if(isName){
			if(userName.length<2 || userName.length>7){
				tempStr=nameType+Lang.str(2764)
			}
			if(userName.match(this.isNumAll)){
				tempStr=nameType+Lang.str(2765);
			}
			if(userName.indexOf(" ")>=0)
				tempStr=Lang.str(2766);
		}
		if(tempStr){
			Mgr.prompt.optionPrompt(tempStr);
			if(callBack){
				callBack.runWith(false);
			}
			return;
		}
		if(callBack){
			BaseSDK.ins.checkMsgIsLegal(userName,Handler.create(this,this.checkNameIsOKLater,[callBack,nameType]))
		}
	}

	__proto.checkNameIsOKLater=function(callBack,nameType,isLegal){
		if(!isLegal){
			Mgr.prompt.optionPrompt(nameType+Lang.str(2763));
		}
		callBack.runWith(isLegal);
	}

	CreateRoleMgr.ins=function(){
		return CreateRoleMgr._ins=CreateRoleMgr._ins|| new CreateRoleMgr();
	}

	CreateRoleMgr._ins=null;
	return CreateRoleMgr;
})()


/**
*服务器列表Mgr
*author zlm
*2020-4-9
*
**/
//class com.xq.modules.server.ServerMgr
var ServerMgr=(function(){
	function ServerMgr(){
		/***服务器请求次数*/
		this.reqServerCount=0;
		this.gameServerObj=null;
		/**玩家登录账号*/
		this.roleLoginName=null;
		/**已登陆过的服务器列表*/
		this.lasterAry=[];
		/**所有服务器列表*/
		this.allAry=null;
		/**新服列表*/
		this.newAry=null;
		/**推荐服*/
		this.weightAry=null;
		this._menuIndex=0;
		/**平台sdk数据*/
		this.loginSDKUserData=null;
		/**选服列表接口地址*/
		this.serverPath=null;
		/**平台标记*/
		this.gameChannel=null;
		/**微信相关*/
		this.wxchannel=null;
		/**加载的服务器列表*/
		this.serverListUrl=null;
		/**玩家id*/
		this.userID=null;
		/**服务器是否初始化完成*/
		this.serverIsOK=false;
		/**是否点击了开始游戏*/
		this.isClickStart=false;
		this._isAllOK=false;
		/**SDK是否登录成功*/
		this.sdkIsLogin=false;
		/**当前选中服务器大页签*/
		this.serverIndex=0;
		this._isDeveloper=false;
		this._debugLv=0;
		this.dlAlert=null;
		this.menuDic=new Dictionary();
		this.isClickStart=false;
		this.serverIsOK=false;
		this.isAllOK=false;
		this.sdkIsLogin=false;
		this._isDeveloper=false;
		this.serverPath=Configs.server_path;
		if(!Configs.userDataFromPublish){
			try{
				var callBackHandler=Handler.create(this,this.onSDKLoginCallback,null);
				SDKLoginCallback=callBackHandler;
				console.log(Lang.str(2767));
			}
			catch(e){
				console.error(e);
			}
		}
		if(typeof(wxchannel)!='undefined'){
			this.wxchannel=wxchannel;
			WXSDK.wxchannel=this.wxchannel;
		}
		this.initServerList();
	}

	__class(ServerMgr,'com.xq.modules.server.ServerMgr');
	var __proto=ServerMgr.prototype;
	/**平台登陆成功 */
	__proto.onSDKLoginCallback=function(bo){
		(bo===void 0)&& (bo=true);
		if(!bo){
			if(!this.sdkIsLogin){
				var errStr=Lang.str(2768);
				sdk_login();
				if(!this.dlAlert || !this.dlAlert.isPopup){
					this.dlAlert=AlertUtil.show(Lang.str(2769));
				}
			}
			else{
				errStr=Lang.str(2770);
			}
			laya.xq.cfg.reportOneBug(Lang.str(2771),new Error(errStr));
			return;
		}
		if(typeof(userDataFromPublish)!='undefined'){
			this.loginSDKUserData=userDataFromPublish;
			Configs.userDataFromPublish=this.loginSDKUserData;
		}
		if(this.dlAlert){
			this.dlAlert.close();
			this.dlAlert=null;
		}
		this.sdkIsLogin=true;
		console.log(Lang.str(2772),this.loginSDKUserData);
		this.reqServerList();
		EventCenter.instance.event(ServerMgr.SDK_LOGIN_BACK);
	}

	/**检查是否是外网*/
	__proto.initServerList=function(isDirectLoad){
		(isDirectLoad===void 0)&& (isDirectLoad=false);
		this.userID=LocalStorage.getItem("userName")?LocalStorage.getItem("userName"):"test888";
		if(!PathDefine.isPublish || !Configs.isStartPublishLogin || isDirectLoad){
			this.sdkIsLogin=true;
			this.serverListUrl=this.serverPath+"channelId="+Configs.platform+"&userId="+this.userID;
			if(this.serverListUrl){
				Laya.loader.load([{url:this.serverListUrl,type:"text"}],Handler.create(this,this.loaderListCom),null,null,0,true,null,false,false);
				console.log(Lang.str(2773)+this.serverListUrl);
			}
		}
		else{
			if(Browser.onMiniGame){
				this.serverIsOK=true;
				}else{
				sdk_login();
			}
		}
	}

	/**服务器加载成功*/
	__proto.loaderListCom=function(){
		var data=Laya.loader.getRes(this.serverListUrl);
		try{
			this.reqServerCount=0;
			var obj=JSON.parse(data);
			this.initAlllist(obj.serverList);
			this.initLastList(obj.lastLogin);
			LogMgr.ins.report(15,{});
			this.serverIsOK=true;
			EventCenter.instance.event(ServerMgr.GET_SERVER_LIST_BACK);
		}
		catch(e){
			this.reqServerCount++;
			if(this.reqServerCount < 10){
				Laya.timer.once(5000,this,this.reloadServer);
			}
			else{
				console.log(Lang.str(2774));
				ReconnectAction.getInstance().restart();
			}
		}
	}

	__proto.reloadServer=function(){
		Laya.loader.load([{url:this.serverListUrl,type:"text"}],Handler.create(this,this.loaderListCom),null,null,0,false,null,false,false);
		console.log(Lang.str(2775)+this.serverListUrl);
	}

	/**拉取服务器列表*/
	__proto.reqServerList=function(){
		if(typeof(userDataFromPublish)!='undefined'){
			this.loginSDKUserData=userDataFromPublish;
			Configs.userDataFromPublish=this.loginSDKUserData;
		}
		BaseSDK.loginSDKUserData=this.loginSDKUserData;
		var user_id;
		var token="";
		var game_channel_id;
		if(this.loginSDKUserData){
			user_id=this.loginSDKUserData.user_id;
			game_channel_id=this.loginSDKUserData.game_channel_id;
			token=this.loginSDKUserData.token;
			this.userID=user_id;
			}else{
			if((typeof(super_channelid)!='undefined')){
				game_channel_id=super_channelid;
			}
			else{
				game_channel_id=Configs.game_channel_id;
			}
			user_id=this.userID;
			if(user_id==""){
				user_id="12";
			}
		}
		this.serverListUrl=this.serverPath+"channelId="+game_channel_id+"&userId="+user_id+"&token="+token;
		Configs.platformId=game_channel_id;
		console.log(Lang.str(2776)+this.serverListUrl);
		Laya.loader.load([{url:this.serverListUrl,type:"text"}],Handler.create(this,this.loaderListCom),null,null,0,true,null,false,false);
	}

	/**初始化登陆过的服务器*/
	__proto.initLastList=function(obj){
		this.lasterAry=[];
		for (var serId in obj){
			var temp=this.getInfo(serId);
			if(temp){
				temp["lastLoginTime"]=obj[serId]["lastLoginTime"];
				temp["roleName"]=obj[serId]["roleName"];
				temp["level"]=obj[serId]["level"];
				this.lasterAry.push(temp);
			}
		}
		function sortList (a,b){
			return b["lastLoginTime"]-a["lastLoginTime"];
		}
		this.lasterAry.sort(sortList);
		this.menuDic.set(Lang.str(2777),this.lasterAry);
	}

	/**初始化所有服务器*/
	__proto.initAlllist=function(obj){
		this.allAry=[];
		var severTitle=Configs.severTitleDic;
		var temp;
		for(var $each_temp in obj){
			temp=obj[$each_temp];
			if(severTitle&&severTitle[temp.serverId]){
				temp.titleName=severTitle[temp.serverId];
				temp.isTitle=true;
			}
			this.allAry.push(temp);
		}
		function sortList (a,b){
			return a.serverId-b.serverId;
		}
		this.allAry.sort(sortList);
		this.chipList();
	}

	/**获取服信息*/
	__proto.getInfo=function(id){
		var len=this.allAry.length;
		for (var i=0;i < len;i++){
			var obj=this.allAry[i];
			if(id==obj.serverId){
				return obj;
			}
		}
		return null;
	}

	/**获取已有角色列表*/
	__proto.getLastList=function(){
		return this.lasterAry;
	}

	/**获取所有服务器列表*/
	__proto.getAllList=function(){
		return this.allAry;
	}

	/**获取菜单列表*/
	__proto.getLeftMenu=function(){
		return this.menuDic.keys;
	}

	/**获取类行服务器列表*/
	__proto.getServerList=function(key){
		return this.menuDic.get(key);
	}

	/**
	*获取快捷登陆服
	*@param isLast 是否获取最后登录的服
	**/
	__proto.getQuickServer=function(){
		if(this.lasterAry && this.lasterAry.length > 0){
			this.menuIndex=0;
			return this.lasterAry[0];
		}
		if(this.weightAry && this.weightAry.length > 0){
			this.menuIndex=2;
			return this.weightAry[0];
		}
		if(this.newAry){
			var len=this.newAry.length;
			for (var i=0;i < len;i++){
				var temp=this.newAry[i];
				if(temp.openTime <=Mgr.curTime.serverTimer){
					this.menuIndex=1;
					return temp;
				}
			}
		}
		this.menuIndex=2;
		return this.getOpenedServer();
	}

	__proto.getOpenedServer=function(){
		var len=this.allAry.length;
		for (var i=len-1;i >=0;i--){
			var obj=this.allAry[i];
			if(obj.openTime <=Browser.now()){
				return obj;
			}
		}
		console.log(Lang.str(2778))
		return null;
	}

	/**整理服务器列表*/
	__proto.chipList=function(){
		this.newAry=[];
		this.weightAry=[];
		this.menuDic.set(Lang.str(2777),this.lasterAry);
		this.menuDic.set(Lang.str(279),this.newAry);
		var len=this.allAry.length;
		var num=0;
		var tempStr;
		var menuNum=2;
		var temp;
		for (var i=0;i < len;i++){
			temp=this.allAry[i];
			if(temp.isNew==1){
				this.newAry.push(temp);
			}
			if(temp.weight > 0){
				this.weightAry.push(temp);
			};
			var serName=this.getServerName(temp.serverName);
			if(!this.menuDic.get(serName)){
				this.menuDic.set(serName,[]);
			};
			var ary=this.menuDic.get(serName);
			ary.push(temp);
		}
		this.sortNew();
		this.sortWeight();
		this.dealMenu();
	}

	/**处理菜单*/
	__proto.dealMenu=function(){
		var keys=this.menuDic.keys;
		var len=keys.length;
		var maxNum=Configs.serverMaxNum || 10;
		var oldKey=[];
		for (var i=0;i < len;i++){
			var key=keys[i];
			if(key !=Lang.str(2777)&& key !=Lang.str(279)){
				var eleAry=this.menuDic.get(key);
				var eleTime=Math.ceil(eleAry.length / maxNum);
				oldKey.push(key);
				for (var j=0;j < eleTime;j++){
					var start=j *maxNum;
					var end=(j+1)*maxNum;
					var tempKey=(start+1)+"-"+end+Lang.str(2780)
					tempKey=key+tempKey;
					this.menuDic.set(tempKey,eleAry.slice(start,end));
				}
			}
		}
		for (i=0;i < len;i++){
			this.menuDic.remove(oldKey[i]);
		};
		var hideAry=Configs.hideServer;
		if(hideAry){
			len=hideAry.length;
			for (i=0;i < len;i++){
				this.menuDic.remove(hideAry[i]);
			}
		}
	}

	/**权重服*/
	__proto.sortWeight=function(){
		function sortList (a,b){
			return b.weight-a.weight;
		}
		this.weightAry.sort(sortList);
	}

	/**新服*/
	__proto.sortNew=function(){
		function sortList (a,b){
			return b.openTime-a.openTime;
		}
		this.newAry.sort(sortList);
	}

	/**获取最新服*/
	__proto.getNewServer=function(){
		if(this.newAry){
			var len=this.newAry.length;
			for (var i=0;i < len;i++){
				var temp=this.newAry[i];
				if(temp.openTime <=Browser.now()){
					return temp;
				}
			}
		}
		return this.getOpenedServer();
	}

	/**获取服务器名称*/
	__proto.getServerName=function(str){
		var len=str.length;
		for (var i=0;i < len;i++){
			if(!isNaN(parseInt(str.charAt(i)))){
				break ;
			}
		}
		str=str.substr(0,i);
		return str
	}

	/**最后一个开启的服*/
	__proto.getLastServer=function(){
		var len=this.allAry.length;
		var lastTime=0;
		var lastSer;
		for (var i=len-1;i >=0;i--){
			var obj=this.allAry[i];
			if(obj.openTime <=Browser.now()&&lastTime<obj.openTime){
				lastSer=obj;
				lastTime=obj.openTime;
			}
		}
		return lastSer;
	}

	/**
	*@private
	*/
	/**是否是开发者登录*/
	__getset(0,__proto,'isDeveloper',function(){
		return this._isDeveloper;
		},function(value){
		this._isDeveloper=value;
		if(value){
			LogLimitMgr.ins.updateRights(4);
		}
	});

	/**
	*@private
	*/
	/**当前选择的服*/
	__getset(0,__proto,'menuIndex',function(){
		return this._menuIndex;
		},function(value){
		this._menuIndex=value;
	});

	/**
	*@private
	*/
	/**资源是否初始化完成*/
	__getset(0,__proto,'isAllOK',function(){
		return this._isAllOK;
		},function(value){
		this._isAllOK=value;
	});

	__getset(1,ServerMgr,'ins',function(){
		return ServerMgr._ins=ServerMgr._ins|| new ServerMgr();
	});

	ServerMgr.SDK_LOGIN_BACK="SDK_LOGIN_BACK";
	ServerMgr.GET_SERVER_LIST_BACK="GET_SERVER_LIST_BACK";
	ServerMgr._ins=null;
	return ServerMgr;
})()


