//class com.xq.modules.shenshou.ShenShouMgr
var ShenShouMgr=(function(){
	function ShenShouMgr(){
		this._model=null;
		this._red=null;
		this._curSelectShenShou=null;
		this.isShowHeadRedPoint=true;
		this._model=new ShenShouModel();
		this._red=Mgr.red;
		EventCenter.instance.onQue("ITEM_CHANGE",this ,this.itemChange);
	}

	__class(ShenShouMgr,'com.xq.modules.shenshou.ShenShouMgr');
	var __proto=ShenShouMgr.prototype;
	__proto.itemChange=function(){
		this.updateRedPoint();
	}

	//======同步后端数据=======
	__proto.updateShenShouInfo=function(msg){
		this._model.updateShenShouInfo(msg);
		this.updateRedPoint();
		EventCenter.instance.event("UpdateShenShouInfo");
	}

	__proto.onGetShenShouUpgradeInfo=function(msg){
		this._model.onGetShenShouUpgradeInfo(msg);
		this.updateRedPoint();
		EventCenter.instance.event("FeedShenShouInfo");
	}

	__proto.onGetGuildShenShouDispatchInfo=function(msg){
		this._model.onGetGuildShenShouDispatchInfo(msg);
		EventCenter.instance.event("DispatchShenShou");
		if(!msg.lingdiId){
			Mgr.prompt.optionPrompt("撤出成功!");
		}
	}

	//======更新红点=========
	__proto.updateRedPoint=function(){
		var arr=this.getCurShenShouArr();
		var len=arr.length;
		var info;
		var ele;
		var haveCount=0;
		var needCount=0;
		var cfg;
		var needItemArr;
		var needItemId;
		var isShowRedPoint=false;
		var maxLv=0;
		var isOpen=Mgr.guide.isOpen("TongTianMonster");
		if(!isOpen)return;
		for(var i=0;i<len;i++){
			ele=arr[i];
			info=ele.getValue("s_data");
			if(info){
				cfg=ele.getCfgData();
				needItemArr=cfg.baseCost[0].split(":");
				needItemId=needItemArr[0];
				needCount=parseInt(needItemArr[1]);
				haveCount=Mgr.bag.getBagMatCount(needItemId);
				maxLv=parseInt(cfg.maxLv);
				if(haveCount>=needCount&&info.level<maxLv){
					this._red.showRedPoint("TongTianMonster","TongTianMonster","TongTianMonster");
					isShowRedPoint=true;
					break ;
				}
			}
		}
		if(!isShowRedPoint){
			this._red.hideRedPoint("TongTianMonster","TongTianMonster","TongTianMonster");
		}
	}

	/**获取神兽数组*/
	__proto.getCurShenShouArr=function(){
		var arr=this._model.getShDc().array;
		return arr;
	}

	/**获取神兽Att对象*/
	__proto.getShenShouAttObj=function(ele,ifNext){
		(ifNext===void 0)&& (ifNext=false);
		var obj={};
		var arr=this.getPropArr(ele,ifNext);
		var len=arr.length;
		var vo;
		for(var i=0;i<len;i++){
			vo=arr[i];
			if(vo.attrName=="physicdamage"){
				obj.physicdamage=vo.attrVal;
				}else if(vo.attrName=="physicdefence"){
				obj.physicdefence=vo.attrVal;
				}else if(vo.attrName=="hitpoints"){
				obj.hitpoints=vo.attrVal;
				}else if(vo.attrName=="hitrate"){
				obj.hitrate=vo.attrVal;
				}else if(vo.attrName=="dodge"){
				obj.dodge=vo.attrVal;
				}else if(vo.attrName=="critical"){
				obj.critical=vo.attrVal;
				}else if(vo.attrName=="tenacity"){
				obj.tenacity=vo.attrVal;
			}
		}
		return obj;
	}

	/**获取Prop数组*/
	__proto.getPropArr=function(ele,ifNext){
		(ifNext===void 0)&& (ifNext=false);
		var cfg=ele.getCfgData();
		var info=ele.getValue("s_data");
		var lv=info?info.level:0;
		var propId=cfg.propId;
		var per=parseFloat(cfg.propPer);
		var perAdd=parseFloat(cfg.propAddPer);
		if(ifNext)lv++;
		var propArr=Mgr.propM.attrFormula1(propId,per,perAdd,lv);
		return propArr;
	}

	/**获取神兽最大等级*/
	__proto.getShenShouMaxLv=function(ele){
		var cfg=ele.getCfgData();
		return cfg.maxLv;
	}

	/**获取当前选中对象的经验值*/
	__proto.getCurSelectObjNeedExp=function(ele){
		var cfg=ele.getCfgData();
		var info=ele.getValue("s_data");
		var expPer=parseFloat(cfg.expPer);
		if(!info)return 0;
		return Math.round((((info.level-1)*expPer)+1)*cfg.exp);
	}

	/**获取当前神兽的res*/
	__proto.getMonsterResById=function(ele){
		var cfg=ele.getCfgData();
		var res=Model.monster.getUrlById(cfg.monster);
		return res;
	}

	/**获取神兽是否激活*/
	__proto.isShenShouActive=function(ele){
		var cfg=ele.getCfgData();
		var guildLv=Mgr.guild.guildLevel;
		var unlockGuildLv=parseInt(cfg.guildLv);
		if(guildLv>=unlockGuildLv){
			return true
		}
		return false
	}

	/**获取解锁神兽数组*/
	__proto.getUnlockShenShouArr=function(){
		var arr=[];
		var shArr=this.getCurShenShouArr();
		var len=shArr.length;
		var info;
		var ele;
		for(var i=0;i<len;i++){
			ele=shArr[i];
			info=ele.getValue("s_data");
			if(info){
				arr.push(ele);
			}
		}
		return arr;
	}

	/**获取驻守神兽的名字*/
	__proto.getGarrisonShenShouName=function(lingdiId){
		var unlockArr=this.getUnlockShenShouArr();
		var GarrisonShenShouName="";
		var len=unlockArr.length;
		var info;
		var ele;
		var cfg;
		var shName;
		for(var i=0;i<len;i++){
			ele=unlockArr[i]
			cfg=ele.getCfgData();
			info=ele.getValue("s_data");
			if(info.lingdiId==lingdiId){
				shName=Model.monster.getMonsterNameById(cfg.monster);
				GarrisonShenShouName+=shName+"、";
			}
		}
		GarrisonShenShouName=GarrisonShenShouName.substring(0,GarrisonShenShouName.length-1);
		return GarrisonShenShouName;
	}

	/**设置当前选中的神兽*/
	__proto.setCurSelectShenShou=function(selectObj){
		this._curSelectShenShou=selectObj;
	}

	/**获取当前选中的神兽*/
	__proto.getCurSelectShenShou=function(){
		return this._curSelectShenShou;
	}

	/**是否超出派遣数量*/
	__proto.isExceedDispatchNum=function(cfg){
		var id=parseInt(cfg.id);
		var dispatchCount=0;
		var dispatchMaxNum=parseInt(cfg.shenshouNum);
		var unlockArr=this.getUnlockShenShouArr();
		var len=unlockArr.length;
		var info;
		for(var i=0;i<len;i++){
			info=unlockArr[i].getValue("s_data");
			if(id==info.lingdiId){
				dispatchCount++;
			}
		}
		if(dispatchCount<dispatchMaxNum){
			return false;
		}
		return true;
	}

	return ShenShouMgr;
})()


