		this.tarPos=null;
		this.shouChongTip=null;
		this.isOpenTip=false;
		this.isOne=false;
		this.allGetRewardDic=new Dictionary();
		EventCenter.instance.on("new_function_open",this,this.newOpenFun);
		EventCenter.instance.on("ENTER_SCENE",this,this.checkMapTypeHandler);
		EventCenter.instance.on("close_shou_chong_hao_li_tip",this,this.refreshTipTime);
		EventCenter.instance.on("open_shou_chong_hao_li_tip",this,this.openShouChongTip);
