	__proto.checkIsClose=function(){
		var isClose=true;
		if(this.shouChongInfoSc.chongZhiId){
			var rewardArr=this.getDataByFlag(this.shouChongInfoSc.chongZhiId);
			var len=rewardArr.length;
			for (var i=0;i < len;i++){
				var ele=rewardArr[i];
				if(!this.getRewardState(parseInt(ele.getCfgData().id))){
					isClose=false;
					break ;
				}
			}
			if(this.shouChongInfoSc.buzhongId){
				rewardArr=this.getDataByFlag(this.shouChongInfoSc.buzhongId);
				len=rewardArr.length;
				for (i=0;i < len;i++){
					ele=rewardArr[i];
					if(!this.getRewardState(parseInt(ele.getCfgData().id))){
						isClose=false;
						break ;
					}
				}
				}else{
				if(this.getHuBuTime()> 0){
					isClose=false;
				}
			}
			EventCenter.instance.event("ACTIVE_TOGGLE",["shouchonghaoli",isClose]);
		}
	}

