//class com.xq.modules.store.vo.StoreItemVo
var StoreItemVo=(function(){
	function StoreItemVo(){
		this.cfgItem=null;
		/**根据sellId 从道具表中取到的配置数据*/
		this.djCfgItem=null;
		/**发放数量*/
		this.num=0;
		/**花费货币类型*/
		this.moneyType=0;
		/**
		*@param 神秘商店
		*是否购买过
		*/
		this.buyed=false;
		/**
		*神秘商店的格子
		*/
		this.slot=0;
		/**
		*折扣
		*/
		this.discount=0;
		/**
		*原价
		*/
		this.preMoney=0;
		/**花费(现价)*/
		this.money=0;
		/**限购类型
		*0-不限购
		*1-每日限购
		*2-每周限购
		*3-永久限购
		**/
		this.countLimitType=0;
		/**限购数量*/
		this.maxCount=0;
		/**已经购买的次数*/
		this.boughtCount=0;
		/**角色等级限制 */
		this.roleLevel=0;
		/**帮派等级限制*/
		this.guildLevel=0;
		/**转生等级限制*/
		this.zsLevel=null;
		/**是否神秘商店*/
		this.isRandomShop=false;
		/**是否玉币商店*/
		this.isTaiYuRandomShop=false;
		/**是否vip商店*/
		this.isVipShop=false;
		/**
		*解锁条件
		*1=战役通关X层解锁
		*2=宠物阁通关X层解锁
		**/
		this.lockType=0;
		/**解锁条件值 */
		this.lockValue=0;
		/**解锁提示*/
		this.lockTipStr=null;
	}

	__class(StoreItemVo,'com.xq.modules.store.vo.StoreItemVo');
	var __proto=StoreItemVo.prototype;
	__proto.setData=function(cof){
		this.cfgItem=cof;
		this.boughtCount=0;
		this.maxCount=parseInt(this.cfgItem.maxCount);
		this.num=this.cfgItem.num=="" ? 1 :parseInt(this.cfgItem.num);
		this.djCfgItem=Mgr.item.getItemVO(this.cfgItem.sellId,0,this.num);
		this.djCfgItem.whichPanel=10;
		this.moneyType=parseInt(this.cfgItem.moneyType);
		this.discount=this.cfgItem.discount;
		this.preMoney=this.cfgItem.preMoney;
		this.money=this.cfgItem.money;
		this.countLimitType=this.cfgItem.countLimitType==""? 0 :parseInt(this.cfgItem.countLimitType);
		this.roleLevel=this.cfgItem.roleLevel=="" ? 0 :parseInt(this.cfgItem.roleLevel);
		this.guildLevel=this.cfgItem.guildLevel=="" ? 0 :parseInt(this.cfgItem.guildLevel);
		this.lockType=this.cfgItem.lockType==""? 0 :parseInt(this.cfgItem.lockType);
		this.lockValue=this.cfgItem.lockValue==""? 0 :parseInt(this.cfgItem.lockValue);
		this.lockTipStr=this.cfgItem.lockTipStr;
		this.zsLevel=this.cfgItem.zsLevel;
	}

	return StoreItemVo;
})()


