	/**根据类型获取助战单位*/
	__proto.getPlaerByType=function(type){
		var ary=this.model.getShenJiangNums();
		var l=ary.length;
		var pl;
		var vo;
		for (var i=0;i < l;i++){
			pl=ary[i]
			vo=pl.vo;
			if(vo.subType==type){
				return pl;
			}
		}
		return null;
	}

	/**更改子角色名称*/
	__proto.changeSubName=function(type,_name){
		var pl=this.getPlaerByType(type);
		if(pl){
			var str=pl.unitName;
			if(!str)return;
			var mark=str.indexOf("[");
			str=str.substring(0,mark);
			pl.changeName(str+"["+_name+"]");
		}
	}

	__proto.changeSubAttackType=function(){
		if(MapType.isCopy(NetMgr.ins().roleVO.mapType)){
			this.attackType=2;
		}
		else{
			this.attackType=1;
		}
	}

