	/**元宝是否足够 cost1消耗 货币数量货币类型*/
	__proto.isEnough=function(cost1,type,showTip){
		(showTip===void 0)&& (showTip=true);
		var arrCost=cost1.split(":");
		var need=0;
		var id;
		var have=0;
		var moneyType=0;
		if(arrCost.length>1){
			id=arrCost[0];
			need=parseInt(arrCost[1]);
			}else{
			need=parseInt(arrCost[0]);
		}
		if(id){
			moneyType=Mgr.moneyMgr.getMoneyTypeById(id);
			if(moneyType){
				have=Mgr.moneyMgr.getMoneyByType(moneyType);
			}
			else{
				have=Mgr.bag.getBagMatCount(id);
			}
		}
		else{
			have=Mgr.moneyMgr.getMoneyByType(type);
		}
		if(need > have){
			if(showTip){
				if(id){
					if(moneyType&&moneyType==2){
						UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
					}
					else{
						var tip=UIMgrR.openIView(com.xq.view.modules.common.IDaoJuPath,2);
						tip.setData(id);
					}
				}
				else if(type){
					if(type==2){
						UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
					}
					else{
						tip=UIMgrR.openIView(com.xq.view.modules.common.IDaoJuPath,2);
						var moneyId=Mgr.moneyMgr.getIdByMoneyType(type);
						tip.setData(moneyId);
					}
				}
			}
			return false;
		}
		return true;
	}

	__proto.yushuRed=function(){
		var len=this.fuqizhi.length;
		for (var i=0;i < len;i++){
			if(this.rewardHistory.indexOf(this.fuqizhi[i])==-1 && this.fuqizhiSc >=this.getZhuFuZhiRed(i)){
				this.red.showRedPoint("yushu","ysxb","taiYuMain");
				return;
				}else{
				this.red.hideRedPoint("yushu","ysxb","taiYuMain");
			}
		}
	}

	__proto.getZhuFuZhiRed=function(index){
		var len=this.fuqizhi.length;
		var zhuFuZhi=0;
		for (var i=0;i <=index;i++){
			if(this.rewardHistory.indexOf(this.fuqizhi[i])==-1){
				zhuFuZhi+=this.fuqizhi[i];
			}
		}
		return zhuFuZhi;
	}

	/**获取一次增加的福气值*/
	__proto.getOneFuQiValue=function(){
		if(!this.fqz){
			var arr=this.yuShuCfg.objectDataArray;
			var cof=arr[0];
			this.fqz=cof.num;
		}
		return this.fqz;
	}

