//class com.xq.modules.tianshenbianshen.TianShenBianShenMgr
var TianShenBianShenMgr=(function(){
	function TianShenBianShenMgr(){
		/**当前活动 156 为护法变身活动*/
		this._curType=0;
		/**护法变身活动*/
		this._isBianShen=false;
		/**当前变身进度*/
		this._bianShenPro=0;
		/**是否自动变身*/
		this._isAutoBianShen=false;
		this.red=null;
		this._maxValue=0;
		this._model=null;
		/**是否全部完成*/
		this._ifOver=false;
		this._model=new TianShenActiveModel();
		this._maxValue=parseInt(CfgManager.getTableCfg("tianShenBianShenConfig").objectDataArray[0].maxValue);
		this.red=Mgr.red;
		this.red.regist("tianshenactive",null,true);
		EventCenter.instance.onQue("ITEM_CHANGE" ,this,this.updateRed);
		EventCenter.instance.on("ENTER_SCENE",this,this.checkMapTypeHandler);
	}

	__class(TianShenBianShenMgr,'com.xq.modules.tianshenbianshen.TianShenBianShenMgr');
	var __proto=TianShenBianShenMgr.prototype;
	__proto.checkMapTypeHandler=function(){
		var rolevo=NetMgr.ins().roleVO;
		if(!MapType.isCopy(rolevo.mapType)){
			this.isBianShen=false;
			Mgr.tianShenActiveMgr.BianShenPro=0;
		}
	}

	__proto.regActive=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["tianshenactive"]);
		var hand=Handler.create(this,this.openAct,[156],false);
		NewActiveManager.ins.regActOpenHandler(156,hand);
		NewActiveManager.ins.regActEndHandler(156,Handler.create(this,this.closeAct,[156],false));
		ActManager.ins.regist("WaiXianHall","tianshenactive",156,"WaiXianActive");
	}

	__proto.openAct=function(activityId){
		var openDay=CommonUtil.openServerDay;
		if(activityId==156){
			EventCenter.instance.event("ACTIVE_TOGGLE",["tianshenactive",false]);
			Mgr.waiXianActiveAction.sendWaiXianInfo(activityId,openDay);
		}
	}

	__proto.closeAct=function(activityId){
		if(activityId==156){
			EventCenter.instance.event("ACTIVE_TOGGLE",["tianshenactive"]);
		}
	}

	/**武神附体活动是否还在进行中*/
	__proto.ifActiveOpen=function(){
		var ifOpen=NewActiveManager.ins.checkIsOpen(156);
		return ifOpen&&!this._ifOver;
	}

	/**获取大奖数据*/
	__proto.getBigRewardData=function(){
		return this._model.getBigRewardInfo();
	}

	/**获取奖励ele 数组*/
	__proto.getRewardArr=function(){
		return this._model.getRewardDc().array;
	}

	/**获取rewardEle*/
	__proto.getRewardEle=function(taskId){
		return this._model.getRewardDc().getElement(taskId);
	}

	/**默认选中下标*/
	__proto.getCurIndex=function(){
		return this._model.getCurIndex();
	}

	__proto.getCurTaskId=function(){
		var index=this.getCurIndex();
		var arr=this.getRewardArr();
		var ele=arr[index];
		if(!ele)return 0;
		return ele.getCfgData().taskId;
	}

	/**获取TaskEles*/
	__proto.getTaskElesById=function(taskId){
		return this._model.getTaskElesById(taskId);
	}

	/**获取taskId相同 taskType相同的数组*/
	__proto.getTaskArray=function(taskId,taskType){
		(taskType===void 0)&& (taskType=0);
		return this._model.getTaskDc().where("taskId",taskId,"id").where("taskType",taskType,"id").array;
	}

	/**获取当前任务状态 0:未达成 1:可领取 2:已领取 3:自动领取*/
	__proto.getCurTaskStat=function(taskId){
		var rewardEle=this._model.getRewardDc().getElement(taskId);
		if(!rewardEle)return 0;
		var ifGet=rewardEle.getValue("s_data");
		if(ifGet)return 2;
		var arr=this.getTaskElesById(taskId);
		var len=arr.length;
		var isCanLq=true;
		var isAotoLq=true
		for(var i=0;i<len;i++){
			var taskEle=arr[i];
			var taskCfg=taskEle.getCfgData();
			if(taskCfg.taskType=="1" || taskCfg.taskType=="2"){
				var num=Mgr.bag.getBagMatCount(taskCfg.chengjiuId);
				if(num<parseInt(taskCfg.target)){
					isCanLq=false;
				}
				}else{
				var progress=taskEle.getValue("s_data");
				if(progress<parseInt(taskCfg.target)||!progress){
					isAotoLq=false;
				}
			}
		}
		if(isAotoLq)return 3;
		if(isCanLq)return 1;
		return 0;
	}

	__proto.updateIfOver=function(){
		this._ifOver=true;
		var rewardArr=this.getRewardArr();
		var len=rewardArr.length;
		for(var i=0;i<len;i++){
			var rewardEle=rewardArr[i];
			var cfg=rewardEle.getCfgData();
			var taskId=parseInt(cfg.taskId);
			var stat=this.getCurTaskStat(taskId);
			if(stat!=2){
				this._ifOver=false;
				break ;
			}
		}
		if(this._ifOver){
			EventCenter.instance.event("ACTIVE_TOGGLE",["tianshenactive"]);
			EventCenter.instance.event("allLqCloseView");
			var data=Mgr.actionSkillM.getSkillDataByHjType("BIANSHEN");
			if(data){
				Mgr.actionSkillM.updateStat(data);
				EventCenter.instance.event("UpdateActionSkillItems");
			}
		}
	}

	/**是否全部完成任务*/
	__proto.getIfOver=function(){
		return this._ifOver;
	}

	//========同步后端数据=========
	__proto.updateTaskInfo=function(msg){
		this._model.updateTaskInfo(msg);
		this.updateIfOver();
		EventCenter.instance.event("UpdateTaskInfo");
		this.updateRed();
	}

	//
	__proto.updateReward=function(msg){
		Mgr.waiXianActiveAction.sendWaiXianInfo(156,0);
		EventCenter.instance.event("getReward",[msg.taskId]);
	}

	//============红点==============
	__proto.updateRed=function(){
		var rewardArr=this.getRewardArr();
		var len=rewardArr.length;
		for(var i=0;i<len;i++){
			var rewardEle=rewardArr[i];
			var cfg=rewardEle.getCfgData();
			var taskId=parseInt(cfg.taskId);
			var stat=this.getCurTaskStat(taskId);
			if(stat==1||stat==3){
				this.red.showRedPoint("tianshenactive",taskId+"","WaiXianActiveRed");
			}
			else{
				this.red.hideRedPoint("tianshenactive",taskId+"","WaiXianActiveRed");
			}
		}
	}

	/**变身所需怒气*/
	__getset(0,__proto,'maxValue',function(){
		return this._maxValue;
	});

	__getset(0,__proto,'curType',function(){
		return this._curType;
		},function(type){
		this._curType=type;
	});

	__getset(0,__proto,'isBianShen',function(){
		return this._isBianShen;
		},function(boo){
		var player=Game.getInstance().player
		if(player){
			(player.vo).isBianShen=boo;
		};
		var roleVO=NetMgr.ins().roleVO;
		var huanHuaCfgInfo=Mgr.szMgr.getHuanHuaInfoByOne(roleVO.roleHuanHuaId+"");
		if(boo !=this._isBianShen){
			if(boo){
				huanHuaCfgInfo=Mgr.szMgr.getHuanHuaInfoByOne(roleVO.tianShenBianShenId+"");
				player.setRes(huanHuaCfgInfo.res);
				player.isHideWeapon(false);
				if(Mgr.guide.isOpen("zuoqi")==true && player.isMount){
					player.mount(false);
				}
				this.BianShenPro=0;
				}else{
				roleVO.roleHuanHuaId=roleVO.roleHuanHuaId;
				if(roleVO.roleHuanHuaId > 0){
					player.setRes(huanHuaCfgInfo.res);
					roleVO.job=huanHuaCfgInfo.sex;
				}
				else
				player.setRes(roleVO.res[0]);
				player.isHideWeapon(true);
				if(Mgr.guide.isOpen("zuoqi")==true){
					player.mount(true);
				}
			}
		}
		this._isBianShen=boo;
	});

	__getset(0,__proto,'BianShenPro',function(){
		return this._bianShenPro;
		},function(pro){
		var roleVo=NetMgr.ins().roleVO;
		if(!roleVo || !roleVo.tianShenBianShenId){
			return
		}
		if(!this.isBianShen && this.isAutoBianShen && pro >=100){
			Mgr.sceneSyn.sendBianShen();
		}
		this._bianShenPro=pro;
		EventCenter.instance.event("BianShenProgress_Event");
	});

	__getset(0,__proto,'isAutoBianShen',function(){
		return this._isAutoBianShen;
		},function(boo){
		this._isAutoBianShen=boo;
	});

	return TianShenBianShenMgr;
})()


