/**
*@author:zhuju
*@date:2022-5-25
*@desc:一元抢购Mgr
*/
//class com.xq.modules.unitaryPurchase.UnitaryPurchaseMgr
var UnitaryPurchaseMgr=(function(){
	function UnitaryPurchaseMgr(){
		this._model=null;
		this.isBuy=false;
		this.isAllLq=false;
		this._startShowTip=false;
		this._guideTip=null;
		this._model=new UnitaryPurchaseModel();
		EventCenter.instance.onQue("ITEM_CHANGE" ,this,this.updateRed);
	}

	__class(UnitaryPurchaseMgr,'com.xq.modules.unitaryPurchase.UnitaryPurchaseMgr');
	var __proto=UnitaryPurchaseMgr.prototype;
	__proto.regActive=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["UnitaryPurchase"]);
		NewActiveManager.ins.regActOpenHandler(209,Handler.create(this,this.onActOpen,null,false));
		NewActiveManager.ins.regActEndHandler(209,Handler.create(this,this.onActClose,null,false));
	}

	__proto.onActOpen=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["UnitaryPurchase",false]);
		Mgr.unitaryPurchaseA.sendGetInfo();
	}

	__proto.onActClose=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["UnitaryPurchase"]);
	}

	__proto.checkAllGot=function(){
		if(this._model.checkAllGot()){
			EventCenter.instance.event("ACTIVE_TOGGLE",["UnitaryPurchase"]);
		}
	}

	__proto.checkShowTip=function(){
		if(Configs.isForbitAndroidPay||Configs.isForbitIOSPay)return;
		if(!this._startShowTip&&!this._model.checkAllGot()){
			Laya.timer.once(3000,this,this.startTipShow);
		}
		else if(this._startShowTip&&this._model.checkAllGot()){
			this.stopTipShow();
		}
	}

	__proto.startTipShow=function(){
		this._startShowTip=true;
		Laya.timer.loop(300000,this,this.showTip);
		this.showTip();
	}

	__proto.stopTipShow=function(){
		this._startShowTip=false;
		Laya.timer.clear(this,this.showTip);
		this.removeTip();
	}

	__proto.showTip=function(){
		if(!this._guideTip){
			this._guideTip=UIMgrR.newInstanceByIClass(com.xq.view.modules.unitaryPurchase.IYiYuanMiaoShaTip);
			this._guideTip.zOrder=999;
		};
		var activeRender=Game.getInstance().getNewMainView().getCenterRender().getIonRender("UnitaryPurchase");
		if(!activeRender)return;
		var tarPos=new Point(activeRender.x,activeRender.y);
		if(activeRender.parent){
			tarPos=(activeRender.parent).localToGlobal(tarPos);
			this._guideTip.x=tarPos.x+activeRender.width+5;
			this._guideTip.y=tarPos.y-15;
			FloatTween.start(this._guideTip,8,0.05,0);
		}
		Game.getInstance().mainQiPaoView.addChild(this._guideTip);
		Game.getInstance().getNewMainView().addViewToHide(this._guideTip,MainHideEnum.type1);
		Game.getInstance().getNewMainView().addViewToHide(this._guideTip,MainHideEnum.ZhuCheng);
		this._guideTip.open();
	}

	__proto.removeTip=function(){
		if(this._guideTip){
			this._guideTip.dispose();
			FloatTween.stop(this._guideTip);
		}
	}

	/**更新一元抢购信息*/
	__proto.updateInfo=function(msg){
		this.isBuy=msg.isBuy;
		this._model.updateInfo(msg);
		this.updateRed();
		EventCenter.instance.event("UpdateInfo");
		this.checkAllGot();
		this.checkShowTip();
	}

	__proto.updateSingleInfo=function(msg){
		this._model.updateSingleInfo(msg);
		this.updateRed();
		EventCenter.instance.event("RefreshInfo");
		this.checkAllGot();
		this.checkShowTip();
		var ele=this._model.getBuyDc().getElement(msg.rewardId);
		if(!ele)return;
		var cfg=ele.getCfgData();
		var rewards=cfg.reward.split(";");
		RewardUtil.show(rewards);
	}

	//=======红点相关=========
	__proto.updateRed=function(){
		var arr=this._model.getBuyDc().array;
		var ele;
		var info;
		var len=arr.length;
		var ifShowRedPoint=false;
		var cfg;
		var needVal=0;
		if(this.isBuy){
			for(var i=0;i<len;i++){
				ele=arr[i];
				info=ele.getValue("s_data");
				if(!info||info.state)continue ;
				cfg=ele.getCfgData();
				needVal=parseInt(cfg.val);
				if(info.val>=needVal){
					ifShowRedPoint=true;
					break ;
				}
			}
		}
		if(ifShowRedPoint){
			EventCenter.instance.event("MAIN_VIEW_CORNOR",["UnitaryPurchase",true]);
			}else{
			EventCenter.instance.event("MAIN_VIEW_CORNOR",["UnitaryPurchase",false]);
		}
	}

	//=======前端接口=========
	__proto.getArr=function(){
		return this._model.getBuyDc().array;
	}

	__proto.ifAddRedPoint=function(ele){
		var info=ele.getValue("s_data");
		var cfg=ele.getCfgData();
		var val=parseInt(cfg.val);
		if(!this.isBuy||info.state)return false;
		if(info.val>=val)return true
		return false;
	}

	__proto.getShowAni=function(){
		var arr=this.getArr();
		var ele=arr[0];
		if(!ele)return "";
		var cfg=ele.getCfgData();
		return cfg.res;
	}

	return UnitaryPurchaseMgr;
})()


