	__proto.peiDai=function(type,id,isAwaken){
		(isAwaken===void 0)&& (isAwaken=false);
		var player=Game.getInstance().player;
		var model_obj;
		var huanHuaCfgInfo=this.getHuanHuaInfoByOne(id+"");
		if(!huanHuaCfgInfo)return;
		var roleVO=NetMgr.ins().roleVO;
		var url="";
		var skillModel;
		switch(type){
			case 1:
			case 32:
				if(huanHuaCfgInfo.type==32){
					if(type==32){
						SkillGroupMgr.ins().updateSkillByType(huanHuaCfgInfo.skill,"ShiZhuangYuLing");
						this.skillIdObj.shiZhuangYuLingJiNengType=huanHuaCfgInfo.skill;
					}
					}else if(this.skillIdObj.shiZhuangYuLingJiNengType!=""){
					skillModel=Mgr.skillGroup.getSkillModel(Model.game.mPlayer.guid);
					skillModel.removeSkillByType(this.skillIdObj.shiZhuangYuLingJiNengType);
					this.skillIdObj.shiZhuangYuLingJiNengType="";
				}
				roleVO.roleHuanHuaId=id;
				if(id>0){
					player.setRes(huanHuaCfgInfo.res);
					roleVO.job=huanHuaCfgInfo.sex;
				}
				else
				player.setRes(roleVO.res[0]);
				roleVO.res[1]=roleVO.res[1].substr(0,roleVO.res[1].length-1)+roleVO.job;
				UnitManager.ins.setWeapon(Game.getInstance().player);
				break ;
			case 6:
			case 31:
				if(huanHuaCfgInfo.type==31){
					if(type==31){
						SkillGroupMgr.ins().updateSkillByType(huanHuaCfgInfo.skill,"ShenWuYuLing");
						this.skillIdObj.shenWuYuLingjiNengType=huanHuaCfgInfo.skill;
					}
					}else if(this.skillIdObj.shenWuYuLingjiNengType!=""){
					skillModel=Mgr.skillGroup.getSkillModel(Model.game.mPlayer.guid);
					skillModel.removeSkillByType(this.skillIdObj.shenWuYuLingjiNengType);
					this.skillIdObj.shenWuYuLingjiNengType="";
				}
				roleVO.wuQiHuanHuaId=id;
				if(id>0){
					player.setWeaponRes(huanHuaCfgInfo.res+"_A");
				}
				else{
					var weap=roleVO.res[1];
					var arr=weap.split("_");
					player.setWeaponRes(arr[0]+"_A");
				}
				break ;
			case 3:
			case 30:
				if(huanHuaCfgInfo.type==30){
					if(type==30){
						SkillGroupMgr.ins().updateSkillByType(huanHuaCfgInfo.skill,"XianYiYuLing");
						this.skillIdObj.xianYiYuLingJiNengType=huanHuaCfgInfo.skill;
					}
					}else{
					if(this.skillIdObj.xianYiYuLingJiNengType!=""){
						skillModel=Mgr.skillGroup.getSkillModel(Model.game.mPlayer.guid);
						skillModel.removeSkillByType(this.skillIdObj.xianYiYuLingJiNengType);
						this.skillIdObj.xianYiYuLingJiNengType="";
					}
				}
				roleVO.wingHuanHuaId=id;
				if(id>0){
					player.setWingRes(PathDefine.WING+huanHuaCfgInfo.res+"/"+huanHuaCfgInfo.res,1,true,false,true);
					}else{
					if(roleVO.wingLevel>0){
						model_obj=CfgManager.getTableCfg("shenyi").getItemByField("type",roleVO.wingLevel);
						Game.getInstance().player.setWingRes(PathDefine.WING+model_obj.res+"/"+model_obj.res,1,true,false,true);
					}
				}
				break ;
			case 2:
			case 29:
				if(huanHuaCfgInfo.type==29){
					if(type==29){
						SkillGroupMgr.ins().updateSkillByType(huanHuaCfgInfo.skill,"ZuoQiYuLing");
						this.skillIdObj.zuoQiYuLingJiNengType=huanHuaCfgInfo.skill;
					}
					}else if(this.skillIdObj.zuoQiYuLingJiNengType!=""){
					skillModel=Mgr.skillGroup.getSkillModel(Model.game.mPlayer.guid);
					skillModel.removeSkillByType(this.skillIdObj.zuoQiYuLingJiNengType);
					this.skillIdObj.zuoQiYuLingJiNengType="";
				}
				roleVO.zuoQiHuanHuaId=id;
				if(id>0){
					player.setMountRes(PathDefine.MOUNT+huanHuaCfgInfo.res+"/",1,true,false,true);
					}else{
					if(roleVO.zuoqiPeiDaiId2>0){
						model_obj=CfgManager.getTableCfg("Zuoqi").getItemByField("type" ,roleVO.zuoqiPeiDaiId2);
						Game.getInstance().player.setMountRes(PathDefine.MOUNT+model_obj.res+"/",1,true,false,true);
					}
					else
					Mgr.payLinePro.sendGetPaylineInfo(2);
				}
				break ;
			case 22:
				roleVO.bingFuHuanHuaId=id;
				SkillGroupMgr.ins().updateSkillByType(huanHuaCfgInfo.skill,"Bf");
				var turl=PathDefine.FABAO+huanHuaCfgInfo.uires+"/"+huanHuaCfgInfo.uires+".amt";
				var turl2=PathDefine.SKILL+huanHuaCfgInfo.skill+"/"+huanHuaCfgInfo.skill+".amt";
				Game.getInstance().player.equipRune(turl)
				Game.getInstance().player.equipRune(turl,turl2);
				break ;
			case 23:
				roleVO.jiangHunHuanHuaId=id;
				var bo=SkillGroupMgr.ins().updateSkillByType(huanHuaCfgInfo.skill,"Jh");
				if(bo){
					turl=PathDefine.SKILL+huanHuaCfgInfo.uires+"/"+huanHuaCfgInfo.uires+".amt";
					Game.getInstance().player.equipSoul(turl);
				}
				break ;
			case 24:
				roleVO.jiaoYinHuanHuaId=id;
				turl=PathDefine.Cloak+huanHuaCfgInfo.uires
				Game.getInstance().player.equipCloakAni(turl);
				break ;
			case 25:
				roleVO.tianShenBianShenId=id;
				Mgr.actionSkillM.updateBianShenSkill(id);
				break ;
			case 26:
				roleVO.yuXiHuanHuaId=id;
				break ;
			case 27:
				roleVO.tianShiFuHuanHuaId=id;
				break ;
			case 20:
				turl=PathDefine.QiLinBiEff+huanHuaCfgInfo.res;
				Game.getInstance().player.equipQiLingBi(turl);
				break ;
			}
	}

