	__proto.checkShizhuangRed=function(funId){
		for(var type in this.replationDic){
			if(funId&&funId!=this.paylineOpenDic[type])continue ;
			if(!Mgr.guide.isOpen(this.paylineOpenDic[type]))
				continue ;
			if(this.specialPaylineIsOpen(type)){
				continue ;
			};
			var arr=this.getListByType(type);
			for (var j=1;j <=6;j++){
				this.red.hideRedPoint(this.replationDic[type],j+"_"+RedTypeEnum.ShiZhuangRed);
			};
			var len=arr.length;
			for (var i=0;i < len;i++){
				var huanhua=this.szModel.huanhuaCfgDic[arr[i].huanhuaid];
				var xiuLianCfg=this.getXiuLianInfoByType(huanhua.id+"","1");
				if(!xiuLianCfg)continue ;
				var curObj=this.getCfgById(huanhua.id+"");
				if(curObj.jihuo==6){
					if(Mgr.zhuanshuMgr.isJiHuoHuanHua(curObj.jihuolevel)){
						this.setShiZhuanRed(huanhua,xiuLianCfg,curObj,arr[i].type);
					}
					}else{
					this.setShiZhuanRed(huanhua,xiuLianCfg,curObj,arr[i].type);
				}
			}
		}
	}

	__proto.setShiZhuanRed=function(huanhua,xiuLianCfg,curObj,type){
		var isUp=Mgr.item.checkMatIsEnou(xiuLianCfg.count);
		var key=huanhua.id+"_"+RedTypeEnum.ShiZhuangRed;
		if(isUp && huanhua.level < parseInt(xiuLianCfg.shangxian)){
			this.red.showRedPoint(this.replationDic[type],curObj.quality+"_"+RedTypeEnum.ShiZhuangRed);
			this.red.showRedPoint(this.replationDic[type],key,RedTypeEnum.ShiZhuangRed);
		}
		else{
			this.red.hideRedPoint(this.replationDic[type],key,RedTypeEnum.ShiZhuangRed);
		}
	}

	__proto.refreshRedPoint=function(isAdd,type,huanhuaId){
		if(isAdd){
			if(!this._curSelectRedPointObj[type+"_"+huanhuaId]){
				this.red.showRedPoint(this.replationDic[type],"ExclusiveRedPoint_"+huanhuaId,RedTypeEnum.ShiZhuangRed);
				this._curSelectRedPointObj[type+"_"+huanhuaId]=true;
			}
			}else{
			if(this._curSelectRedPointObj[type+"_"+huanhuaId]){
				this.red.hideRedPoint(this.replationDic[type],"ExclusiveRedPoint_"+huanhuaId,RedTypeEnum.ShiZhuangRed);
				this._curSelectRedPointObj[type+"_"+huanhuaId]=false;
			}
		}
	}

	/**刷新所有红点*/
	__proto.refreshAllRedPointSta=function(skilld,lv,type,huanhuaId){
		var isShowRedPoint=this.canAddExclusiveRedPointSkill(skilld,lv);
		this.refreshRedPoint(isShowRedPoint,type,huanhuaId);
	}

