/**
*充值管理类
*author:huanghong
*2020-3-25
*/
//class com.xq.modules.vip.ChargeMgr
var ChargeMgr=(function(){
	function ChargeMgr(){
		this._chargeCof=null;
		/**充值dataContainer*/
		this._chargeData=null;
		/**返回表数据*/
		this.fanghuanData=null;
		this._red=null;
		this._chongzhiList=null;
		this._chongzhiDic=null;
		this._chargeCof=CfgManager.getTableCfg("chongzhi");
		this.init();
		this.registRed();
	}

	__class(ChargeMgr,'com.xq.modules.vip.ChargeMgr');
	var __proto=ChargeMgr.prototype;
	/**注册红点*/
	__proto.registRed=function(){
		this._red=Mgr.red;
		this._red.regist("RechargeHall","directBuyGift",true,"RechargeHall");
		this._red.regist("directBuyGiftIcon","weekBuyGift",true,"RechargeHall");
		this._red.regist("directBuyGiftIcon","monthBuyGift",true,"RechargeHall");
		this._red.regist("directBuyGiftIcon","directBuyGiftIconRed",true);
	}

	/**
	*充值面板获取列表数据源
	**/
	__proto.getChongZhiList=function(){
		if(this._chongzhiList==null){
			this._chongzhiDic={};
			this._chongzhiList=[];
			var arr=this._chargeCof.objectDataArray;
			for (var i=0;i < arr.length;i++){
				var cfg=arr[i];
				var vo=new ChongZhiVO(cfg);
				if(cfg.pos){
					this._chongzhiList.push(vo);
				}
				this._chongzhiDic[vo.id]=vo;
			}
			this._chongzhiList.sort(this.compare);
		}
		return this._chongzhiList;
	}

	__proto.getChongZhiVo=function(productId){
		if(this._chongzhiDic==null){
			this.getChongZhiList();
		};
		var vo=this._chongzhiDic[productId];
		return vo;
	}

	__proto.getRmbByID=function(productId){
		if(this._chongzhiDic==null){
			this.getChongZhiList();
		};
		var vo=this._chongzhiDic[productId];
		if(!vo)return 0;
		return vo.getRmb();
	}

	__proto.compare=function(voA,voB){
		if(voA.cfgItem.pos > voB.cfgItem.pos){
			return 1;
		}
		else{
			return-1;
		}
	}

	/**注册活动开关*/
	__proto.registAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGiftIcon"]);
		var directBuy=Handler.create(this,this.openDirectBuy,null,false);
		NewActiveManager.ins.regActOpenHandler(88,directBuy);
		NewActiveManager.ins.regActEndHandler(88,Handler.create(this,this.closeAct,[88],false));
		ActManager.ins.regist("RechargeHall","directBuyGift",88,"Recharge");
	}

	__proto.openDirectBuy=function(){
		Mgr.directBuyGiftA.c_getInfo();
		Mgr.weekBuyGiftA.c_getInfo(1);
		Mgr.weekBuyGiftA.c_getInfo(2);
		EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGiftIcon",false]);
	}

	__proto.closeAct=function(actId){
		if(actId==88){
			this._red.hideAll("directBuyGift");
			this._red.hideAll("directBuyGiftIcon");
			EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGift"]);
			EventCenter.instance.event("ACTIVE_TOGGLE",["directBuyGiftIcon"]);
		}
	}

	__proto.init=function(){
		this.fanghuanData=new DataContainer();
		var cfg=CfgManager.getTableCfg("DanBiFanHuan");
		var ary=cfg.objectDataArray;
		var len=ary.length;
		for (var i=0;i < len;i++){
			var ele=new DataElement(ary[i]);
			this.fanghuanData.addElement(i,ele);
		}
	}

	__proto.getDanBiList=function(){
		return this.fanghuanData.array;
	}

	__proto.getDbData=function(flag,targetValue){
		var obj=this.fanghuanData.where("flag",flag,"targetValue").where("targetValue",targetValue,"targetValue").getElement(targetValue);
		if(obj){
			var cof=this._chargeCof.getItemByField("huodongId",obj.getCfgData().id);
		}
		return cof;
	}

	__proto.getRewardShow=function(flag,targetValue){
		var obj=this.fanghuanData.where("flag",flag,"targetValue").where("targetValue",targetValue,"targetValue").getElement(targetValue);
		return obj.getCfgData().rewardshow;
	}

	__proto.compareByHuodongId=function(ele1,ele2){
		return ele1.getCfgData().huodongId-ele2.getCfgData().huodongId;
	}

	/**直购礼包是否开启*/
	__getset(0,__proto,'ifOpenDirectBuyGift',function(){
		return NewActiveManager.ins.checkIsOpen(88);
	});

	return ChargeMgr;
})()


