	/**更新Vip称号（还有几关获得vip几）*/
	__proto.updataVipTitle=function(nextLv){
		var pl=Game.getInstance().player;
		if(!pl || !Mgr.gqMgr.gqInfo){
			return;
		}
		if(Mgr.kaiFuHDMgr.progress !=0){
			if(pl.vipTitle){
				pl.setVipTitle(0,0);
			}
			return;
		};
		var nextInfo=Mgr.vip.getNormalVipByLv(nextLv);
		if(nextInfo){
			if(nextInfo.lv==1)return;
			var difGuanQia=parseInt(nextInfo.condition)-(Mgr.gqMgr.gqInfo.nextLevel-1);
			if(difGuanQia < 0){
				return;
			}
			pl.setVipTitle(difGuanQia,parseInt(nextInfo.lv));
		}
		else{
			if(Mgr.gqMgr.gqInfo.nextLevel-1 > this.vipPass){
				if(pl.vipTitle){
					pl.setVipTitle(0,0);
				}
			}
			else{
				pl.setVipTitle(0,-1);
			}
		}
	}

