	/**获取默认选中SvipLv*/
	__proto.getSvipDefualtLv=function(){
		var myLv=this._model.vipData.vipLevel;
		for(var lv=1;lv<=myLv;lv++){
			if(!this.ifReceived(lv)){
				return lv;
			}
		}
		if(myLv<this.maxSvipLv){
			return myLv+1;
		}
		else{
			return myLv;
		}
	}

	/**当前选中前后是否又可领取的奖励*/
	__proto.getSvipOtherRed=function(lv,ifLast){
		var myLv=this._model.vipData.vipLevel;
		if(ifLast){
			for(var i=1;i<lv;i++){
				if(!this.ifReceived(i)&&i<myLv){
					return true;
				}
			}
			return false;
		}
		else{
			for(i=lv+1;i<=myLv;i++){
				if(!this.ifReceived(i)){
					return true;
				}
			}
			return false;
		}
	}

