var ChongZhiVO=(function(){
	function ChongZhiVO(cfg){
		this.cfgItem=null;
		this.rmbDic=null;
		this.id=this.id;
		this.cfgItem=cfg;
		this.id=cfg.id;
	}

	__class(ChongZhiVO,'com.xq.modules.vip.VO.ChongZhiVO');
	var __proto=ChongZhiVO.prototype;
	__proto.getRmbStr=function(){
		return ""+this.getRmb();
	}

	__proto.getRmb=function(){
		var channel_id=Configs.payChannelId;
		if(channel_id!=""){
			if(this.rmbDic==null){
				this.rmbDic={};
				var str=this.cfgItem.channel_rmb;
				if(str){
					var arr=str.split(";");
					for (var i=0;i < arr.length;i++){
						var values=arr[i].split(":");
						this.rmbDic[values[0]]=values[1];
					}
				}
			}
			if(this.rmbDic[channel_id]){
				return this.rmbDic[channel_id];
			}
		}
		return this.cfgItem.rmb;
	}

	return ChongZhiVO;
})()


