/**
*主角演习战争
*@author zhanglimin
*@date 2019-8-23
*/
//class com.xq.modules.wargame.MainPlayerWar
var MainPlayerWar=(function(){
	function MainPlayerWar(){
		this.player=null;
		/**战斗结果*/
		this.isWin=false;
		/**结束时间*/
		this.time=NaN;
		/**战力比例*/
		this.ratio=NaN;
		/**掉血值*/
		this.onceBlood=NaN;
	}

	__class(MainPlayerWar,'com.xq.modules.wargame.MainPlayerWar');
	var __proto=MainPlayerWar.prototype;
	/**
	*开始战斗
	*@param _isWin 战斗结果
	*@param time 结束时间
	**/
	__proto.startHurt=function(_isWin,_time,_ratio){
		(_ratio===void 0)&& (_ratio=0);
		this.isWin=_isWin;
		this.time=_time;
		this.ratio=_ratio;
		this.player=Game.getInstance().player;
		if(this.isWin){
			if(this.ratio >=0.5)
				var num=10;
			else if(this.ratio >=0.2)
			num=5;
			else if(this.ratio >=0.2)
			num=5;
			else
			num=1;
			this.onceBlood=this.player.vo.maxHp / (this.time *num);
		}
		else
		this.onceBlood=this.player.vo.maxHp / (this.time *2);
		Laya.timer.loop(500,this,this.hurt);
	}

	/**停止战斗*/
	__proto.end=function(){
		Laya.timer.clear(this,this.hurt);
	}

	__proto.hurt=function(){
		var type=Math.round(Math.random()*10)<2?2:0;
		var curHp=this.player.vo.curHp;
		var maxHp=this.player.vo.maxHp;
		this.player.vo.curHp-=Math.round(this.onceBlood);
		var canshu=Math.round(Math.random()*this.onceBlood);
		HarmManager.ins.hurt(type,Math.round(this.onceBlood+canshu),this.player,(this.player.curDir+4)%8,100);
		this.player.updateBlood(this.player.vo.curHp/maxHp);
		if(this.player.vo.curHp <=0){
			this.player.dead();
			this.Finish();
		}
	}

	__proto.Finish=function(){
		Laya.timer.clear(this,this.hurt);
		EventCenter.instance.event("MainPlayerWar_Finish");
	}

	__getset(1,MainPlayerWar,'ins',function(){
		return MainPlayerWar._ins=MainPlayerWar._ins|| new MainPlayerWar();
	});

	MainPlayerWar.MainPlayerWar_Finish="MainPlayerWar_Finish";
	MainPlayerWar._ins=null;
	return MainPlayerWar;
})()


/**
*军事演习
*@author zhanglimin
*@date 2019-8-21
*/
//class com.xq.modules.wargame.Wargame
var Wargame=(function(){
	function Wargame(){
		/**敌方Vo*/
		this.eneyVo=null;
		/**主角位置*/
		this.rolePo=null;
		/**是否胜利*/
		this.isWin=false;
		/**主角*/
		this.mainPlayer=null;
		/**敌方大佬*/
		this.eneyPlayer=null;
		/**敌方战力*/
		this.eneyPower=NaN;
		/**我方战力*/
		this.myPower=NaN;
		/**战力比例*/
		this.ratio=NaN;
		/**敌方单位列表*/
		this.eneyTeamList=[];
		/**我方单位列表*/
		this.myTeamList=[];
		/**结束回调函数*/
		this.endCom=null;
		this.tempPk=3;
	}

	__class(Wargame,'com.xq.modules.wargame.Wargame');
	var __proto=Wargame.prototype;
	__proto.init=function(vo,roPo,_isWin,_endCom){
		this.mainPlayer=Game.getInstance().player;
		this.mainPlayer.reqMount(false);
		EventCenter.instance.on("MainPlayerWar_Finish",this,this.onFinishWar);
		this.eneyVo=vo;
		this.rolePo=roPo;
		this.isWin=_isWin;
		this.endCom=_endCom;
		this.eneyPower=vo.roleObj.fightValue;
		this.myPower=NetMgr.ins().roleVO.fightValue;
		this.ratio=Math.abs((this.myPower-this.eneyPower)/ this.myPower);
		this.mainPlayer.curHp=this.mainPlayer.maxHp;
		this.mainPlayer.updateBlood(1);
		AIController.ins().stopAutoCombat();
		if(this.eneyTeamList.length > 0)
			this.eneyTeamList=[];
		if(this.myTeamList.length > 0)
			this.myTeamList=[];
		this.createEney();
		this.createMySubPlayer();
		Laya.timer.once(3000,this,this.startFight);
	}

	__proto.startFight=function(){
		console.log(Lang.str(3025))
		this.tempPk=Mgr.setting.pkModel;
		Mgr.setting.pkModel=3;
		TargetSelectMgr.ins.curMouseUnit=this.eneyPlayer;
		AIController.ins().startAutoCombat();
		Laya.timer.once(1000,this,this.mainHurt);
		var len=this.myTeamList.length;
		for (var i=0;i < len;i++){
			var robot=this.myTeamList[i];
			robot.start(3,this.eneyPlayer,true);
		}
		len=this.eneyTeamList.length;
		for (var j=0;j < len;j++){
			robot=this.eneyTeamList[j];
			robot.start(3,this.mainPlayer,true);
		}
	}

	__proto.mainHurt=function(){
		MainPlayerWar.ins.startHurt(this.isWin,this.getFailSaveTime(),this.ratio);
	}

	/**创建我自己的武将*/
	__proto.createMySubPlayer=function(){
		var roleVo=NetMgr.ins().roleVO;
		var ary=Mgr.subPlayer.getHeroHeadList()
		var len=ary.length;
		var ty1=0;
		var ty2=0;
		for (var i=1;i < len;i++){
			var subVo=ary[i];
			if(subVo){
				var wjObj={};
				wjObj.ID=110+i;
				wjObj.sjId=subVo.shenJiangType;
				wjObj.name=roleVo.name;
				var wjRobot=UnitManager.ins.createRobotShenJiang(wjObj);
				wjRobot.x=this.rolePo.x;
				var gp=i%2;
				var tty=NaN;
				if(gp==0){
					ty1++
					tty=this.rolePo.y+(1 *64 *ty1);
				}
				else{
					ty2++;
					tty=this.rolePo.y-(1 *64 *ty2);
				}
				wjRobot.y=tty;
				wjRobot.updatePos();
				SceneContainer.getInstance().unitLayer.addChild(wjRobot);
				if(this.isWin){
					wjRobot.liveTime=1000;
				}
				else{
					wjRobot.liveTime=this.getFailSaveTime(true);
				};
				var rand=Math.floor(Math.random()*10)+1;
				wjRobot.piaoB=Math.round(Math.random()*(roleVo.fightValue/rand)+1000);
				wjRobot.setEnemyLater(false);
				this.myTeamList.push(wjRobot);
			}
		}
	}

	/**敌方初始化*/
	__proto.createEney=function(){
		this.eneyPlayer=Mgr.robot.create(this.eneyVo.roleObj);
		SceneContainer.getInstance().unitLayer.addChild(this.eneyPlayer);
		var ary=SceneContainer.GridToGlobal(this.eneyVo.poVo.x,this.eneyVo.poVo.y);
		this.eneyPlayer.pos(ary[0],ary[1]);
		this.eneyPlayer.on("dead",this,this.onFinishWar);
		this.eneyPlayer.setEnemyLater(true);
		if(!this.isWin){
			this.eneyPlayer.liveTime=1000;
		}
		else{
			this.eneyPlayer.liveTime=this.getFailSaveTime();
		};
		var rand=Math.floor(Math.random()*10)+1;
		this.eneyPlayer.piaoB=Math.round(Math.random()*(this.eneyPower/rand)+1000);
		this.eneyTeamList.push(this.eneyPlayer);
		var len=this.eneyVo.subRoles.length;
		for (var q=0;q < len;q++){
			var msg=this.eneyVo.subRoles[q];
			var wjObj={};
			wjObj.ID=110;
			wjObj.sjId=msg.shenjiangType;
			wjObj.name=this.eneyVo.roleObj.name;
			var wjRobot=UnitManager.ins.createRobotShenJiang(wjObj,true);
			wjRobot.x=this.eneyPlayer.x;
			wjRobot.y=this.eneyPlayer.y+(1 *64 *q);
			SceneContainer.getInstance().unitLayer.addChild(wjRobot);
			wjRobot.setEnemyLater(true);
			rand=Math.floor(Math.random()*5)+1;
			wjRobot.piaoB=Math.round(Math.random()*(this.eneyPower/rand)+1000);
			this.eneyTeamList.push(wjRobot);
			if(!this.isWin){
				wjRobot.liveTime=1000;
			}
			else{
				wjRobot.liveTime=this.getFailSaveTime(true);
			}
		}
	}

	/**
	*获取存活时间
	*@param isMy:是否是自己
	*@param isSub:是否是武将
	**/
	__proto.getFailSaveTime=function(isSub){
		(isSub===void 0)&& (isSub=false);
		var saveTime=0;
		var cha=Math.abs((this.myPower-this.eneyPower)/ this.myPower);
		if(cha >=0.5)
			saveTime=1;
		else if(cha >=0.2)
		saveTime=3;
		else if(cha >=0)
		saveTime=7;
		var rand=Math.floor(Math.random()*2)+1;
		saveTime=saveTime+rand;
		if(isSub){
			saveTime=Math.floor(saveTime *0.8);
		}
		return saveTime;
	}

	__proto.stopRobot=function(){
		var len=this.myTeamList.length;
		for (var i=0;i < len;i++){
			var robot=this.myTeamList[i];
			robot.end();
		}
		len=this.eneyTeamList.length;
		for (i=0;i < len;i++){
			robot=this.eneyTeamList[i];
			robot.end();
		}
	}

	/**结束*/
	__proto.onFinishWar=function(){
		this.stopRobot();
		AIController.ins().stopAutoCombat();
		MainPlayerWar.ins.end();
		this.mainPlayer.isNotClick=false;
		EventCenter.instance.off("MainPlayerWar_Finish",this,this.onFinishWar);
		this.eneyPlayer.off("dead",this,this.onFinishWar);
		Mgr.setting.pkModel=this.tempPk;
		if(this.endCom)
			this.endCom.run();
	}

	/**测试创建*/
	__proto.testRole=function(o){
		var roVo=NetMgr.ins().roleVO;
		o={};
		o.level=roVo.level;
		o.ID=110;
		o.sjId=3;
		o.name=roVo.name;
		var sjPlaer=UnitManager.ins.createRobotShenJiang(o);
		sjPlaer.x=this.mainPlayer.x;
		sjPlaer.y=this.mainPlayer.y;
		SceneContainer.getInstance().unitLayer.addChild(sjPlaer);
	}

	__getset(1,Wargame,'Ins',function(){
		return Wargame._ins=Wargame._ins|| new Wargame();
	});

	Wargame._ins=null;
	return Wargame;
})()


