//class com.xq.modules.weekBuyGift.MonthBuyGiftMgr
var MonthBuyGiftMgr=(function(){
	function MonthBuyGiftMgr(){
		this._dirGiftDc=null;
		this._dirGiftCof=null;
		this._red=null;
		this._dirGiftCof=CfgManager.getTableCfg("meiyuelibao");
		this._red=Mgr.red;
	}

	__class(MonthBuyGiftMgr,'com.xq.modules.weekBuyGift.MonthBuyGiftMgr');
	var __proto=MonthBuyGiftMgr.prototype;
	__proto.init=function(){
		this._dirGiftDc=null;
		Mgr.weekBuyGiftA.c_getInfo(2);
	}

	__proto.compare=function(a,b){
		var statA=Mgr.monthBuyGiftM.getStat(a.getCfgData().id);
		var statB=Mgr.monthBuyGiftM.getStat(b.getCfgData().id);
		return statA-statB;
	}

	/**获取当前版本Flag的数据*/
	__proto.getCurFlagData=function(flag){
		var dc=this.dirGiftDc.where("flag",flag,"id");
		return dc.array;
	}

	/**刷新后台下发数据*/
	__proto.updateSInfo=function(msg){
		var arr=msg.infos;
		var len=arr.length;
		var data;
		for(var i=0;i<len;i++){
			data=arr[i];
			var ele=this.dirGiftDc.getElement(data.id);
			if(ele){
				ele.setValue("s_charge",data.rechargeTimes);
				ele.setValue("s_reward",data.getTimes);
			}
		}
		this.updateRed();
	}

	/**领取奖励后刷新*/
	__proto.updateSReward=function(msg){
		var id=msg.id;
		var ele=this.dirGiftDc.getElement(id);
		var getTimes=ele.getValue("s_reward");
		if(!isNaN(getTimes)){
			ele.setValue("s_reward",getTimes+1);
		}
		this.updateRed();
	}

	/**通过Id获取状态*/
	__proto.getStat=function(id){
		var ele=this.dirGiftDc.getElement(id);
		var cof=ele.getCfgData();
		var buyTimes=ele.getValue("s_charge");
		var getTimes=ele.getValue("s_reward");
		if(getTimes<buyTimes){
			return 1;
		}
		else{
			if(buyTimes<cof.buylimitnum){
				return 2;
			}
			else{
				return 3;
			}
		}
	}

	/**红点刷新*/
	__proto.updateRed=function(){
		var arr=this.curArr;
		var len=arr.length;
		for(var i=0;i<len;i++){
			if(this.getStat(arr[i].getCfgData().id)==1){
				this._red.showRedPoint("monthBuyGift","reward","RechargeRed");
				return;
			}
		}
		this._red.hideRedPoint("monthBuyGift","reward","RechargeRed");
	}

	__getset(0,__proto,'dirGiftDc',function(){
		if(!this._dirGiftDc){
			this._dirGiftDc=new DataContainer();
			var cofArr=this._dirGiftCof.objectDataArray;
			var len=cofArr.length;
			var cof;
			var ele;
			for(var i=0;i<len;i++){
				cof=cofArr[i];
				ele=new DataElement(cof);
				ele.setValue("s_charge",0);
				ele.setValue("s_reward",0);
				this._dirGiftDc.addElement(cof.id,ele);
			}
		}
		return this._dirGiftDc;
	});

	/**活动结束时间*/
	__getset(0,__proto,'openTime',function(){
		var info=NewActiveManager.ins.getActiveVerDic(187);
		if(info){
			return info.endTime;
		}
		return 0;
	});

	/**当前版本数据源*/
	__getset(0,__proto,'curArr',function(){
		var info=NewActiveManager.ins.getActiveVerDic(187);
		if(info){
			var flag=info.flag;
			return this.getCurFlagData(flag).sort(this.compare);
		}
		return [];
	});

	return MonthBuyGiftMgr;
})()


