//class com.xq.modules.wendao.WenDaoMgr
var WenDaoMgr=(function(){
	function WenDaoMgr(){
		this.wdTaskArr=null;
		this.wdSkillArr=null;
		this.zhuanShengSkillArr=null;
		this.shiShenTaiSkillArr=null;
		this.shenZhuangSkillArr=null;
		this.zhanZhuangSkillArr=null;
		this.shenZhuSkillArr=null;
		/**当前完成进度值*/
		this.taskValue=0;
		/**点击是否成功*/
		this.dianjiOK=false;
		/**名将问道配置表里的问道id*/
		this.wdId=0;
		/**技能激活状态 0:未激活、1:可激活、2:已激活*/
		this.activeState=0;
		/**技能任务列表*/
		this.mjTaskArr=null;
		/**技能激活查看列表*/
		this.skillMsg=null;
		this.red=null;
		this.juexueskill=null;
		this.teJiSelect=0;
		EventCenter.instance.event("ACTIVE_TOGGLE",["wenDao"]);
		var wdMasterstask=CfgManager.getTableCfg("masterstask");
		this.wdTaskArr=wdMasterstask.objectDataArray;
		var wdMasterstroke=CfgManager.getTableCfg("masterstroke");
		this.wdSkillArr=wdMasterstroke.getItemsByField("skillType",1);
		this.juexueskill=CfgManager.getTableCfg("juexueskill");
		this.shiShenTaiSkillArr=this.juexueskill.getItemsByField("skillType",3);
		this.zhuanShengSkillArr=this.juexueskill.getItemsByField("skillType",2);
		this.shenZhuangSkillArr=this.juexueskill.getItemsByField("skillType",4);
		this.zhanZhuangSkillArr=this.juexueskill.getItemsByField("skillType",5);
		this.shenZhuSkillArr=this.juexueskill.getItemsByField("skillType",6);
		this.red=Mgr.red;
		this.red.regist("wenDao",null,true,"wenDao");
	}

	__class(WenDaoMgr,'com.xq.modules.wendao.WenDaoMgr');
	var __proto=WenDaoMgr.prototype;
	__proto.getShiShenTai=function(condition){
		return this.juexueskill.getCfgMsgByTwoKey("skillType",3,"openCondition",condition);
	}

	__proto.getShiShenTaiSkill=function(){
		return this.shiShenTaiSkillArr;
	}

	/**拉取名将问道技能状态列表*/
	__proto.setMingJiangSkillData=function(vo){
		this.skillMsg=vo.skillsState;
		var len=this.skillMsg.length;
		for (var i=0;i < len;i++){
			var obj=this.skillMsg[i];
			if(obj.CanOrCant){
				Mgr.wdAction.sendMingJiangInfo(obj.id);
			}
		}
	}

	/**拉取初始数据*/
	__proto.setMingJiangInfoData=function(vo){
		this.wdId=vo.id;
		this.activeState=vo.activeState;
		this.mjTaskArr=vo.progressMsg;
		this.skillMsg=vo.skillMsg;
		this.taskValue=vo.progress;
		this.closeIcon();
		this.redTask();
		EventCenter.instance.event("wd_info");
	}

	/**激活数据*/
	__proto.setMingJiangSkill=function(vo){
		this.wdId=vo.id;
		this.activeState=vo.activeState;
		this.skillMsg=vo.msg;
		this.closeIcon();
		this.redTask();
		this.showSkill();
		EventCenter.instance.event("wd_jhSkill");
		EventCenter.instance.event("wd_info");
	}

	__proto.showSkill=function(){
		Mgr.hjMgr.activeSkillType=this.getStroKe(this.wdId).skillId;
		var uiv=UIMgrR.openIView(com.xq.view.modules.guide.INewSkill,3);
	}

	/**领取奖励数据*/
	__proto.setMingJiangReward=function(vo){
		var len=this.mjTaskArr.length;
		for (var i=0;i < len;i++){
			var obj=this.mjTaskArr[i];
			if(obj.taskId==vo.taskId){
				obj.FinishState=vo.FinishState;
				break ;
			}
		}
		this.wdId=vo.id;
		this.redTask();
		EventCenter.instance.event("wd_info");
		EventCenter.instance.event("wd_reward");
	}

	__proto.getStroKe=function(needId){
		var len=this.wdSkillArr.length;
		for (var i=0;i < len;i++){
			var obj=this.wdSkillArr[i];
			if(obj.id==needId){
				return obj;
			}
		}
		return null;
	}

	/**根据id类型获取数据*/
	__proto.getMasterData=function(id){
		var len=this.wdTaskArr.length;
		var leng=this.mjTaskArr.length;
		var data=[];
		for (var i=0;i < len;i++){
			var obj=this.wdTaskArr[i];
			if(obj.id==id){
				for (var j=0;j < leng;j++){
					var objMj=this.mjTaskArr[j];
					if(obj.taskid==objMj.taskId){
						if(objMj.FinishState==2){
							obj["sort"]=obj.taskid+999;
							}else if(objMj.FinishState==1){
							obj["sort"]=0;
							}else{
							obj["sort"]=obj.taskid
						}
						break ;
					}
				}
				data.push(obj);
			}
		}
		data.sort(this.compare);
		return data;
	}

	__proto.compare=function(vo1,vo2){
		if(vo1 && vo2)
			return vo1.sort-vo2.sort;
		return 0;
	}

	/**根据任务id获取当前任务数据*/
	__proto.getProgressMsg=function(taskId){
		var len=this.mjTaskArr.length;
		for (var i=0;i < len;i++){
			if(taskId==this.mjTaskArr[i].taskId){
				return this.mjTaskArr[i];
			}
		}
		return null;
	}

	/**根据任务id获取当前任务数据*/
	__proto.getSkillMsg=function(id){
		if(!this.skillMsg){
			return null
		};
		var len=this.skillMsg.length;
		for (var i=0;i < len;i++){
			if(id==this.skillMsg[i].id){
				return this.skillMsg[i];
			}
		}
		return null;
	}

	/***获取技能下标*/
	__proto.getListIndex=function(){
		if(!this.skillMsg){
			return null
		};
		var index=0;
		var indexArr=[];
		var len=this.skillMsg.length;
		for (var i=0;i < len;i++){
			var sk=this.skillMsg[i];
			if(sk.CanOrCant && sk.activeState !=2){
				indexArr.push(sk);
			}
		}
		if(!indexArr[0]){
			return 0;
			}else{
			return indexArr[0].id-1;
		}
	}

	//id从1开始 下标从0开始
	__proto.jiHuoSkill=function(obj){
		var skillMsg=this.getSkillMsg(obj.id)
		if(skillMsg && skillMsg.CanOrCant){
			Mgr.wdAction.sendMingJiangInfo(obj.id);
			this.dianjiOK=true;
			}else{
			Mgr.prompt.optionPrompt(Lang.str(3026)+this.getStroKe(obj.needId).name);
			this.dianjiOK=false;
		}
	}

	__proto.closeIcon=function(){
		if(this.checkIsClose()){
			EventCenter.instance.event("ACTIVE_TOGGLE",["wenDao"]);
		}
	}

	/**判断技能是否全部开启激活 关闭icon*/
	__proto.checkIsClose=function(){
		var len=this.skillMsg.length;
		for (var i=0;i < len;i++){
			var sk=this.skillMsg[i];
			if(!sk.CanOrCant || sk.activeState !=2){
				return false;
			}
		}
		return true
	}

	__proto.redTask=function(){
		var taskArr=[];
		var tempRed=false;
		var taskId=0;
		taskArr=this.getMasterData(this.wdId);
		var skill=this.skillMsg[this.wdId-1];
		if(skill && skill.CanOrCant){
			for (var j=0;j < taskArr.length;j++){
				var taskData=taskArr[j];
				for (var k=0;k < this.mjTaskArr.length;k++){
					var mjTask=this.mjTaskArr[k];
					if(taskData.taskid==mjTask.taskId){
						taskId=taskData.id;
						if(mjTask && mjTask.FinishState==1 && mjTask.progress >=taskData.value || this.activeState==1){
							tempRed=true;
							break ;
						}
					}
				}
			}
		}
		if(tempRed){
			this.red.showRedPoint("wenDao",taskId+"redTask","wenDao");
			}else{
			this.red.hideRedPoint("wenDao",taskId+"redTask","wenDao");
		}
	}

	WenDaoMgr.WD_INFO="wd_info";
	WenDaoMgr.WD_JHSKILL="wd_jhSkill";
	WenDaoMgr.WD_REWARD="wd_reward";
	return WenDaoMgr;
})()


//class com.xq.modules.woyaobianqiang.WoyaobianqiangMgr
var WoyaobianqiangMgr=(function(){
	function WoyaobianqiangMgr(){
		/**我要变强配置数据1*/
		this.cfg=null;
		/**引导表*/
		this.yindaoCfg=null;
		/**任务表*/
		this.taskCfg=null;
		/**成就表*/
		this.achiveCfg=null;
		this.lv=0;
		/**
		*多少种
		*/
		this.KINDS=13;
		this.cfg=CfgManager.getTableCfg("woyaobianqiang");
		this.yindaoCfg=CfgManager.getTableCfg("yindao");
		this.taskCfg=CfgManager.getTableCfg("ZhuXianRenWu");
		this.achiveCfg=CfgManager.getTableCfg("chengjiu");
		this.setLv();
	}

	__class(WoyaobianqiangMgr,'com.xq.modules.woyaobianqiang.WoyaobianqiangMgr');
	var __proto=WoyaobianqiangMgr.prototype;
	__proto.setLv=function(){
		this.lv=NetMgr.ins().roleVO.level;
	}

	/**
	*获取我要变强一个节点子类数据
	*/
	__proto.gN=function(i){
		var arr=this.cfg.getCfgMsgArrByTwoKey("type","1","grade",i.toString());
		var arr2=[];
		for (var j=0;j < arr.length;j++){
			var o=arr[j];
			if(Mgr.guide.isOpen(o.func_key)){
				arr2.push(o);
			}
		}
		return arr2;
	}

	/**根据类型获取数据*/
	__proto.getDataByType=function(_type){
		return this.cfg.getItemsByField("type",_type);
	}

	/**
	*通过节点的索引grade值判断此节点下的子列表数量是否大于0
	*/
	__proto.nodeOpen=function(g){
		var arr=this.gN(g);
		for (var i=0;i < arr.length;i++){
			var o=arr[i];
			var fun=o.func_key;
			if (Mgr.guide.isOpen(fun)){
				return true;
			}
		}
		return false;
	}

	/**
	*通过grade索引获得我要变强中的第一个数据
	*/
	__proto.gFO=function(x,y){
		return this.cfg.getCfgMsgByTwoKey("type",x.toString(),"grade",y.toString());
	}

	/**
	*通过type，grade，class获取一行数据
	*/
	__proto.gTO=function(x,y,z){
		return this.cfg.getCfgMsgByThreeKey("type",x.toString(),"grade",y.toString(),"classnum",z.toString());
	}

	/**
	*通过一行数据和角色等级取到当前的推荐评分
	*/
	__proto.gRecFV=function(o){
		var condition=o.condition;
		if (condition=="")return 0;
		var arr=condition.split(";");
		if (arr.length==1){
			return parseInt(arr[0]);
		}
		for (var i=0;i < arr.length;i++){
			var str=arr[i];
			var strArr=str.split(":");
			var checkLv=parseInt(strArr[0]);
			if (checkLv >=this.lv){
				return parseInt(strArr[1]);
			}
		}
		return 0;
	}

	/**
	*获取我要变强一个节点的推荐战力
	*/
	__proto.gRFV=function(i){
		var lv=NetMgr.ins().roleVO.level;
		var arr=this.gN(i);
		var fv=0;
		for (var j=0;j < arr.length;j++){
			var obj=this.gTO(1,i,j+1);
			var fv1=this.gRecFV(obj);
			fv+=fv1;
		}
		return fv;
	}

	/**
	*获得总的推荐战力
	*/
	__proto.getRTotalFV=function(){
		var totalFV=0;
		for (var i=1;i <=this.KINDS;i++){
			totalFV+=this.gRFV(i);
		}
		return totalFV;
	}

	/**
	*通过一行数据获取当前某一类型的战斗力
	*/
	__proto.getCurFV=function(o){
		var str=o.func_id;
		var fv=0;
		var power=Mgr.power;
		if (str.indexOf(";")> 0){
			var arr=str.split(";");
			for (var i=0;i < arr.length;i++){
				fv+=power.getPowerByType(arr[i]);
			}
		}
		else{
			fv=power.getPowerByType(parseInt(str));
		}
		return fv;
	}

	/**
	*获取我要变强一个节点的当前战斗力
	*/
	__proto.getNodeCurFV=function(grade){
		var arr=this.cfg.getCfgMsgArrByTwoKey("type","1","grade",grade.toString());
		var fv=0;
		for (var i=0;i < arr.length;i++){
			fv+=this.getCurFV(arr[i]);
		}
		return fv;
	}

	/**
	*获得当前的总战力
	*/
	__proto.getCTotalFV=function(){
		return NetMgr.ins().roleVO.fightValue;
	}

	/**
	*获得同一类型的数组
	*/
	__proto.getArr=function(t){
		var arr=this.cfg.getItemsByField("type",t.toString());
		return arr;
	}

	/**
	*获取评分
	*/
	__proto.getStateArr=function(v){
		if (v <=1/6)
			return "C";
		else if (v <=2/6)
		return "B";
		else if (v <=3/6)
		return "A";
		else if (v <=4/6)
		return "S";
		else if (v <=5/6)
		return "SS";
		else
		return "SSS";
	}

	return WoyaobianqiangMgr;
})()


