		this.maxRewardList=msg.maxRewardList;
		this.mfCiShu=msg.jinrimianfeiCiShu;
		var objCfg=this.dataCfig[this.getIndex(msg.type)].objectDataArray[0];
		if(objCfg && parseInt(objCfg.tipshow)&& this.rewardList.length >=objCfg.times1){
			this.shouChouBiDe=true;
		}
		this.red.showRedPoint("xunbaobag","xbck","chuanshixunbao");
