//class com.xq.modules.xunbao.tianJiLing.TianJiLingMgr
var TianJiLingMgr=(function(){
	function TianJiLingMgr(){
		this.tjlCfg=null;
		this.tjlCfgBaoKu=null;
		/**抽奖所需要消耗的道具 数量*/
		this.jdItemConst=null;
		/**当前层数*/
		this.version=0;
		/**上一层*/
		this.upVersion=0;
		/**后端给过来的奖励数组*/
		this.rewardList=null;
		/**抽奖返回的奖励数据*/
		this.reward=null;
		/**抽中的奖励id*/
		this.rewardId=null;
		this.red=null;
		this.chouJiangJiLu=null;
		EventCenter.instance.onQue("ITEM_CHANGE",this,this.tianJiLingRed);
		this.tjlCfg=CfgManager.getTableCfg("tianjizhuanpanconfig");
		this.tjlCfgBaoKu=CfgManager.getTableCfg("tianjizhuanpanku");
		this.red=Mgr.red;
		this.red.regist("tianjiling","tianjilingView",true,"tianjiling");
	}

	__class(TianJiLingMgr,'com.xq.modules.xunbao.tianJiLing.TianJiLingMgr');
	var __proto=TianJiLingMgr.prototype;
	//天机令
	__proto.regActive=function(){
		var hand=Handler.create(this,this.openAct,null,false);
		NewActiveManager.ins.regActOpenHandler(91,hand);
		NewActiveManager.ins.regActEndHandler(91,Handler.create(this,this.closeAct,null,false));
	}

	/**活动开启*/
	__proto.openAct=function(){
		Mgr.tianJiLingAction.sendTianJiLingCfgCS(91);
	}

	/**活动关闭*/
	__proto.closeAct=function(){
		EventCenter.instance.event("ACTIVE_TOGGLE",["tianjiling"]);
	}

	/**根据层数获取数据*/
	__proto.getDjItenArr=function(version){
		var arrBaoKu=this.tjlCfgBaoKu.getItemsByField("version",version);
		var arrCfg=this.tjlCfg.getItemsByField("version",version);
		if(arrCfg&&arrCfg[0])this.jdItemConst=arrCfg[0].item;
		return arrBaoKu;
	}

	__proto.onTianJiLingCfgSC=function(msg){
		this.version=msg.version;
		this.upVersion=this.version;
		this.rewardList=[];
		this.rewardList=msg.rewardList;
		this.tianJiLingRed();
		EventCenter.instance.event("tianjilingInfo");
	}

	__proto.onTianJiLingChouJiang=function(msg){
		this.version=msg.version;
		this.reward=msg.reward;
		var len=this.rewardList.length;
		for (var i=0;i < len;i++){
			var tjlReward=this.rewardList[i];
			if(this.reward.id==tjlReward.id){
				tjlReward.isGain=this.reward.isGain;
				break ;
			}
		}
		this.tianJiLingRed();
		EventCenter.instance.event("tianjilingReward");
	}

	/**抽奖回来 道具飞背包 刷新数据*/
	__proto.upDataTianJiLingInfo=function(){
		if(this.version !=this.upVersion){
			Mgr.tianJiLingAction.sendTianJiLingCfgCS(91);
			}else{
			EventCenter.instance.event("tianjilingInfo");
		}
	}

	/**获取道具列表道具下标*/
	__proto.getIndex=function(){
		var index=-1;
		var rewardArr=this.getDjItenArr(this.upVersion);
		var len=rewardArr.length;
		if(!this.reward)return 0;
		for (var i=0;i < len;i++){
			if(this.reward.id==rewardArr[i].id){
				index=i;
				this.rewardId=rewardArr[i].item.split(":")[0];
				break ;
			}
		}
		return index;
	}

	/**获取抽奖道具*/
	__proto.getreward=function(){
		return this.reward;
	}

	/**天机令个人抽奖记录*/
	__proto.geRenJiLu=function(msg){
		var gerenArr=[];
		var len=msg.msgs.length;
		var myJob=NetMgr.ins().roleVO.job;
		for (var i=0;i < len;i++){
			var fsRecordMsg=msg.msgs[i];
			var object={};
			var tid=fsRecordMsg.item.templateId;
			var djCfg=Mgr.item.getItemCfg(tid);
			if(djCfg&& djCfg.job!="0" && djCfg.job!=myJob){
				continue ;
			}
			object["djId"]=tid;
			object["count"]=fsRecordMsg.item.count;
			object["name"]=fsRecordMsg.name;
			gerenArr.push(object);
		}
		this.chouJiangJiLu=gerenArr;
		EventCenter.instance.event("tianjilingjilu");
	}

	/***是否已经抽奖全部奖励*/
	__proto.shiFouChouWan=function(){
		var _isGain=0;
		if(this.rewardList){
			var len=this.rewardList.length;
			for (var i=0;i < len;i++){
				var fsRecordMsg=this.rewardList[i];
				if(fsRecordMsg.isGain){
					_isGain++;
					}else{
					return false;
				}
			}
			if(_isGain==len){
				return true;
			}
		}
		return false;
	}

	/**天机令红点*/
	__proto.tianJiLingRed=function(){
		this.getDjItenArr(this.version);
		if(this.jdItemConst){
			var djItem=this.jdItemConst.split(":");
			var djCount=Mgr.bag.getBagMatCount(djItem[0]);
			var xiaoHaoDJ=djItem[1];
			if(djCount >=xiaoHaoDJ && !this.shiFouChouWan()){
				this.red.showRedPoint("tianjilingView","tjlview","tianjiling");
				}else{
				this.red.hideRedPoint("tianjilingView","tjlview","tianjiling");
			}
		}
	}

	TianJiLingMgr.TIANJILINGINFO="tianjilingInfo";
	TianJiLingMgr.TIANJILINGREWARD="tianjilingReward";
	TianJiLingMgr.TIANJILINGJILU="tianjilingjilu";
	return TianJiLingMgr;
})()


