/**
*@author zhanglimin
*@date 2020-8-11
**/
//class com.xq.modules.zhanzhuang.ZhanzhuangMgr
var ZhanzhuangMgr=(function(){
	function ZhanzhuangMgr(){
		this.red=null;
		this._model=null;
		this._model=new ZhanZhuangModel();
		EventCenter.instance.onQue("ITEM_CHANGE" ,this ,this.onBagChange);
	}

	__class(ZhanzhuangMgr,'com.xq.modules.zhanzhuang.ZhanzhuangMgr');
	var __proto=ZhanzhuangMgr.prototype;
	__proto.init=function(){
		this.registRed();
	}

	__proto.onBagChange=function(){
		this.updateAllRed();
	}

	/**获取套装类型配置eles*/
	__proto.getSuitEles=function(){
		return this._model.getTypeDc().array;
	}

	/**获取当前佩戴的套装Id*/
	__proto.getCurEquipSuit=function(){
		return this._model.getCurEquipSuit();
	}

	/**获取套装等级Ele 默认取1级数据*/
	__proto.getSuitLvEle=function(type,lv){
		(lv===void 0)&& (lv=1);
		return this._model.getSuitLvEle(type,lv);
	}

	/**根据套装类型获取当前的套装等级Ele(等级为0 给到等级1的数据)*/
	__proto.getSuitLvEleByType=function(type){
		var typeEle=this.getTypeEle(type);
		if(!typeEle)return null;
		var info=typeEle.getValue("s_data");
		var lv=info&&info.level?info.level:1;
		var suitLvEle=this.getSuitLvEle(type,lv);
		if(!suitLvEle)return null;
		return suitLvEle;
	}

	/**获取套装名称*/
	__proto.getSuitName=function(type,lv){
		var ele=this.getSuitLvEle(type,lv);
		if(!ele)return "";
		return ele.getCfgData().name;
	}

	/**检测套装是否已激活 可传入套装类型ele 或者类型id*/
	__proto.checkSuitActive=function(data){
		if((data instanceof laya.xq.cfg.DataElement )){
			var ele=data;
		}
		else{
			ele=this.getTypeEle(data);
		}
		if(!ele)return false;
		var info=ele.getValue("s_data");
		return info&&info.level>0;
	}

	/**根据套装类型获取对应类型配置ele*/
	__proto.getTypeEle=function(type){
		return this._model.getTypeEle(type);
	}

	/**根据套装类型获取部位数据ele*/
	__proto.getPartElesByType=function(type){
		return this._model.getPartElesByType(type);
	}

	/**获取部位状态
	*0：未激活 不可激活
	*1：可激活
	*2：已激活 不可升级
	*3：已激活 可升级
	*4：已满级
	**/
	__proto.getPartStat=function(partEle){
		if(!partEle)return 0;
		var cfg=partEle.getCfgData();
		var info=partEle.getValue("s_data");
		if(!info||info.level<=0){
			var activeCost=cfg.cost;
			if(Mgr.item.checkMatIsEnou(activeCost)){
				return 1;
			}
			else{
				return 0;
			}
		}
		if(!info.nextAttr||info.nextAttr.length==0){
			return 4;
		};
		var upgradeCost=info.cost;
		if(Mgr.item.checkMatIsEnou(upgradeCost)){
			return 3;
		}
		return 2;
	}

	/**通过配置套装下标 检测是否满足配置开启条件*/
	__proto.checkIndexOpen=function(index){
		var typeEle=this._model.getTypeEleByIndex(index);
		return this.checkTypeOpen(typeEle);
	}

	/**通过配置套装类型 检测是否满足配置开启条件*/
	__proto.checkTypeOpen=function(typeEle){
		if(!typeEle)return false;
		if(this.checkSuitActive(typeEle))return true;
		var ele=this._model.getSuitLvEle(typeEle.getCfgData().id,1);
		if(!ele)return false;
		var cof=ele.getCfgData();
		var preSuitType=cof.rareitemid;
		var zsLv=cof.zhuanshengLv;
		var curZsLv=NetMgr.ins().roleVO.baiJiangLevel;
		var zsFlag=curZsLv>=zsLv;
		if(preSuitType){
			var preTypeEle=this._model.getTypeEle(preSuitType);
			return this.checkSuitActive(preTypeEle)&&zsFlag;
		}
		return zsFlag;
	}

	/**根据下标获取开启条件提示*/
	__proto.getOpenDesc=function(index){
		var typeEle=this._model.getTypeEleByIndex(index);
		if(typeEle){
			var ele=this._model.getSuitLvEle(typeEle.getCfgData().id,1);
			if(ele){
				var desc="";
				var cof=ele.getCfgData();
				var preSuitType=cof.rareitemid;
				var zsLv=cof.zhuanshengLv;
				if(zsLv>0){
					desc+=Lang.str(2513)+Mgr.fhMgr.getZhuanShengInfo(zsLv);
				};
				var preTypeEle=this._model.getSuitLvEle(preSuitType,1);
				if(preTypeEle){
					var preCfg=preTypeEle.getCfgData();
					var name=preCfg.name;
					desc+="且"+Lang.str(2733)+name
				}
				return desc+Lang.str(2309);
			}
		}
		return "";
	}

	__proto.getFightValueByType=function(type){
		var arr=this.getPartElesByType(type);
		if(!arr||!arr.length)return 0;
		var len=arr.length;
		var ele;
		var info;
		var value=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			info=ele.getValue("s_data");
			if(info&&info.attr&&info.attr.length>0){
				value+=parseInt(CommonUtil.getPowerByAttrs(info.attr));
			}
		}
		return value;
	}

	__proto.getDefualtIndex=function(type){
		var arr=this.getPartElesByType(type);
		if(!arr||!arr.length)return-1;
		var len=arr.length;
		var ele;
		var stat=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.getPartStat(ele);
			if(stat==1||stat==3){
				return i;
			}
		}
		return 0;
	}

	__proto.getMaxActiveType=function(){
		var arr=this.getSuitEles();
		var len=arr.length;
		var ele;
		var suitType=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(!ele)continue ;
			if(!this.checkSuitActive(ele))break ;
			suitType=ele.getCfgData().id;
		}
		return suitType;
	}

	/**刷新套装信息*/
	__proto.updateAllInfo=function(msg){
		this._model.updateInfo(msg);
		EventCenter.instance.event("UpdateInfoZZ");
		this.updateZongLanRed();
		this.updateAllRed();
	}

	/**刷新套装部位升级*/
	__proto.updateUpgradePart=function(msg){
		this._model.updateUpgradePart(msg);
		EventCenter.instance.event("UpgradeUpZZ");
		this.updateZongLanRed();
		this.updateTypeRed(msg.suitId);
	}

	/**套装等级提升推送*/
	__proto.updateSuitUpgrade=function(msg){
		this._model.updateSuitUpgrade(msg);
		EventCenter.instance.event("UpgradeUpSuitZZ");
		this.updateZongLanRed();
		if(msg.level==1){
			var v=UIMgrR.openIView(com.xq.view.modules.zhanZhuang.IZhanZhuangShow,2);
			v.dataSource=msg.suitId;
		}
	}

	/**装配套装刷新*/
	__proto.updateEquipSuit=function(msg){
		this._model.updateEquip(msg);
		EventCenter.instance.event("UpdatePeiDaiIDZZ");
		this.updateZongLanRed();
	}

	/**所有属性*/
	__proto.updateTotalAttr=function(msg){
		if(!msg)return;
		var viw=UIMgrR.openIView(com.xq.view.modules.zhanZhuang.ITotalAtr,2);
		viw.dataSource=msg.attr;
	}

	//================红点================
	__proto.registRed=function(){
		this.red=Mgr.red;
		this.red.regist("roleMain","ZhanZhuangHall",true,RedTypeEnum.RoleOneMenuRed);
		this.red.regist("ZhanZhuangHall","TaoZhuangHall",false,"ZhanZhuangHallRed");
		this.red.regist("TaoZhuangHall","TaoZhuangZongLan",false,"TaoZhuangHallRed");
		this.registFuncRed();
	}

	__proto.registFuncRed=function(){
		var arr=this.getSuitEles();
		var len=arr.length;
		var ele;
		var cfg;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(!ele)continue ;
			cfg=ele.getCfgData();
			this.red.regist("TaoZhuangHall",cfg.funcId,false,"TaoZhuangHallRed");
		}
	}

	/**总览当前未装配 且有可装配光环*/
	__proto.updateZongLanRed=function(){
		if(!Mgr.guide.isOpen("TaoZhuangHall"))return;
		var curEquipType=this._model.getCurEquipSuit();
		if(!curEquipType){
			var arr=this.getSuitEles();
			var len=arr.length;
			var ele;
			for(var i=0;i<len;i++){
				ele=arr[i];
				if(this.checkSuitActive(ele)){
					this.red.showRedPoint("TaoZhuangZongLan","canEquip","TaoZhuangZongLan");
					return;
				}
			}
			this.red.hideRedPoint("TaoZhuangZongLan","canEquip","TaoZhuangZongLan");
		}
	}

	__proto.updateTypeRed=function(type){
		if(!Mgr.guide.isOpen("TaoZhuangHall"))return;
		var typeEle=this.getTypeEle(type);
		if(!typeEle||!this.checkTypeOpen(typeEle))return;
		var funcId=typeEle.getCfgData().funcId;
		var arr=this.getPartElesByType(type);
		var len=arr.length;
		var ele;
		var stat=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			stat=this.getPartStat(ele);
			if(stat==1||stat==3){
				this.red.showRedPoint(funcId,"canUpgrade",funcId);
				return;
			}
		}
		this.red.hideRedPoint(funcId,"canUpgrade",funcId);
	}

	__proto.updateAllRed=function(){
		if(!Mgr.guide.isOpen("TaoZhuangHall"))return;
		var arr=this.getSuitEles();
		var len=arr.length;
		var ele;
		var cfg;
		for(var i=0;i<len;i++){
			ele=arr[i];
			if(!ele)continue ;
			cfg=ele.getCfgData();
			this.updateTypeRed(cfg.id);
		}
	}

	return ZhanzhuangMgr;
})()


