//class com.xq.modules.zhengba.DZFSMgr
var DZFSMgr=(function(){
	function DZFSMgr(){
		/**是否勾选自动挑战*/
		this.ifAuto=false;
		/**是否开启*/
		this.isOpen=false;
		/**当前id*/
		this.curId=0;
		/**当前id对象*/
		this.curCfg=null;
		/**当前段位*/
		this.curStage=0;
		/**当前级别*/
		this.curLv=0;
		/**当前星*/
		this.curStar=0;
		/**当前排名*/
		this.rank=0;
		/**剩余挑战次数*/
		this.times=0;
		/**恢复时间*/
		this.recoverTime=NaN;
		/**最大挑战次数*/
		this.maxTimes=0;
		this.cfgDic=null;
		/**段位等级字典*/
		this.dwLvDic=null;
		/**段位奖励数组*/
		this.dwArr=null;
		/**钻石组排名奖励*/
		this.zsArr=null;
		/**段位名字字典*/
		this.dwNameDic=null;
		/**购买次数对应价格字典*/
		this.buyCost=null;
		/**已经购买次数*/
		this.buyTimes=0;
		/**jing胜场*/
		this.win=0;
		/**匹配对手的数据*/
		this.otherInfo=null;
		/**是否胜利*/
		this.isWin=false;
		/**对手的段位数据*/
		this.otherCfg=null;
		/**钻石段位的最低id*/
		this.zuanId=0;
		/**每日奖励领取状态数组*/
		this.everyRewardArr=null;
		/**今日获胜次数*/
		this.everyWinNum=0;
		/**主角坐标*/
		this.rolePo=null;
		/**敌人坐标*/
		this.eneyPo=null;
		/***逐鹿中原*/
		this.dzfsArr=null;
		/***逐鹿中原排名奖励*/
		this.dzfsRankRewardArr=null;
		this.red=null;
		this.player=null;
		this.copyInfo=null;
		this.cfgDic={};
		var tab=CfgManager.getTableCfg("DouZhanFengShen");
		var arr=tab.objectDataArray;
		this.dzfsArr=tab.objectDataArray.reverse();
		var len=arr.length;
		this.dwArr=[];
		this.dwNameDic={1:Lang.str(3072),2:Lang.str(3073),3:Lang.str(3074),4:Lang.str(3075)};
		this.dwLvDic={};
		for(var i=0;i<len;i++){
			var o=arr[i];
			this.cfgDic[o.id]=o;
			if(!this.dwArr[o.stage-1]){
				this.dwArr[o.stage-1]=o.levelReward;
			}
			if(!this.dwLvDic[o.stage]){
				this.dwLvDic[o.stage]={};
				this.zuanId=o.id;
			}
			this.dwLvDic[o.stage][o.level]=o;
		}
		this.zsArr=[];
		tab=CfgManager.getTableCfg("DouZhanFengShenRankReward");
		arr=tab.objectDataArray;
		this.dzfsRankRewardArr=tab.objectDataArray;
		len=arr.length;
		for(i=0;i < len;i++){
			o=arr[i];
			o.data=null;
			this.zsArr.push(o);
		}
		tab=CfgManager.getTableCfg("Config");
		o=tab.getItemByField("type",126);
		this.maxTimes=parseInt(o.value);
		this.buyCost={};
		tab=CfgManager.getTableCfg("DouZhanCount");
		arr=tab.objectDataArray;
		len=arr.length;
		for(i=0;i < len;i++){
			o=arr[i];
			this.buyCost[o.count]=o.yuanbao;
		}
		this.red=Mgr.red;
		this.red.regist("zhanchangdating","duorenjingji",true,RedTypeEnum.JingJiRed);
		this.red.regist("danrenjingji","douzhanfengshen",false,RedTypeEnum.JingJiRed);
		CopyTipMgr.ins.regisCopyTip(106,Handler.create(this,this.closeTips,null,false));
	}

	__class(DZFSMgr,'com.xq.modules.zhengba.DZFSMgr');
	var __proto=DZFSMgr.prototype;
	__proto.updateRed=function(){
		if(this.isOpen && this.times>0){
			this.red.showRedPoint("douzhanfengshen","hasTimes",RedTypeEnum.ZhuLuZhongYuan);
		}
		else{
			this.red.hideRedPoint("douzhanfengshen","hasTimes",RedTypeEnum.ZhuLuZhongYuan);
		};
		var rewardArr=this.everyRewardArr;
		var len=rewardArr.length;
		for (var i=0;i < len;i++){
			if(rewardArr[i]==1){
				this.red.showRedPoint("douzhanfengshen",""+i,RedTypeEnum.ZhuLuZhongYuan);
				}else{
				this.red.hideRedPoint("douzhanfengshen",""+i,RedTypeEnum.ZhuLuZhongYuan);
			}
		}
	}

	__proto.setRolePos=function(){
		var actCfg=CfgManager.getTableCfg("KuaFuJingJi");
		var actobj=actCfg.objectDataArray[0];
		var ary1=actobj.bornpoint.split(";");
		var ary=ary1[0].split(":");
		this.rolePo=new Point(parseInt(ary[0]),parseInt(ary[1]));
		ary=SceneContainer.GridToGlobal(this.rolePo.x,this.rolePo.y);
		this.rolePo.setTo(ary[0],ary[1]);
		ary=ary1[1].split(":");
		this.eneyPo=new Point(parseInt(ary[0]),parseInt(ary[1]));
		this.eneyPo.setTo(ary[0],ary[1]);
	}

	__proto.laterEnter=function(r){
		Laya.timer.loop(2000,this,this.hurt);
		r.tiao(this.player.x+600,this.player.y);
		r.start(3,this.player);
	}

	__proto.hurt=function(){
		var type=Math.round(Math.random()*10)<2?2:0;
		var curHp=this.player.vo.curHp;
		var maxHp=this.player.vo.maxHp;
		if(this.isWin){
			var cha=maxHp*0.01;
		}
		else{
			cha=maxHp*0.2;
		}
		this.player.vo.curHp-=Math.round(cha);
		var canshu=Math.round(Math.random()*cha);
		HarmManager.ins.hurt(type,Math.round(cha+canshu),this.player,(this.player.curDir+4)%8,100);
		this.player.updateBlood(this.player.vo.curHp/maxHp);
		if(this.player.vo.curHp <=0){
			this.player.dead();
		}
	}

	__proto.initFightVo=function(fightVo){
		fightVo.hideAry=[2,3,4];
		fightVo.aniType=2;
		this.copyInfo=UIMgrR.openIView(com.xq.view.modules.wargame.IWarCopyInfo,2);
	}

	__proto.closeTips=function(){
		if(this.copyInfo){
			this.copyInfo.close();
			this.copyInfo=null;
		}
		RobotPlayerMgr.ins.RobotIsEney=false;
	}

	return DZFSMgr;
})()


