	/**
	*更具类型获取配置
	*type 1是运营活动 累计充值 2是七夕活动 七夕累充 3是砸蛋活动 砸蛋返利 4是开学活动 开学返利 5是开学活动 开学累充 10是冰天雪地 寒冬累充 11是冰天雪地 寒冬返利
	**/
	__proto.getCfgByType=function(type,isSort){
		(type===void 0)&& (type=-1);
		(isSort===void 0)&& (isSort=true);
		if(type==-1){
			type=this.curType;
		};
		var dateContainer;
		if(type==1){
			var actVo=NewActiveManager.ins.getActiveVerDic(81);
			if(!actVo || !this.leiJiChongZhiTab){
				return [];
			};
			var oprVo=Mgr.opeAct.getOprationVo(81);
			var ary=oprVo.infos;
			dateContainer=this.getLeiChongHaoLiData();
		}
		else if(type==2){
			actVo=NewActiveManager.ins.getActiveVerDic(100);
			if(!actVo || !this.qiXiLeiChongTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(100);
			ary=oprVo.infos;
			dateContainer=this.getQiXiLeiChongData();
		}
		else if(type==3){
			actVo=NewActiveManager.ins.getActiveVerDic(103);
			if(!actVo || !this.bianCeFanLiTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(103);
			ary=oprVo.infos;
			dateContainer=this.getBianCeFanLiData();
		}
		else if(type==4){
			actVo=NewActiveManager.ins.getActiveVerDic(111);
			if(!actVo || !this.kaiXueFanLiTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(111);
			ary=oprVo.infos;
			dateContainer=this.getKaiXueFanLiData();
		}
		else if(type==5){
			actVo=NewActiveManager.ins.getActiveVerDic(109);
			if(!actVo || !this.kaiXueLeiChongTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(109);
			ary=oprVo.infos;
			dateContainer=this.getKaiXueLeiChongData();
		}
		else if(type==6){
			actVo=NewActiveManager.ins.getActiveVerDic(124);
			if(!actVo || !this.guoqingFanLiTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(124);
			ary=oprVo.infos;
			dateContainer=this.getGuoQingFanLiData();
		}
		else if(type==7){
			actVo=NewActiveManager.ins.getActiveVerDic(123);
			if(!actVo || !this.guoqingLeiChongTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(123);
			ary=oprVo.infos;
			dateContainer=this.getGuoQingLeiChongData();
		}
		else if(type==8){
			actVo=NewActiveManager.ins.getActiveVerDic(135);
			if(!actVo || !this.hefuLeiChongTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(135);
			ary=oprVo.infos;
			dateContainer=this.getHeFuLeiChongData();
		}
		else if(type==9){
			actVo=NewActiveManager.ins.getActiveVerDic(139);
			if(!actVo || !this.bianCeLeiChongTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(139);
			ary=oprVo.infos;
			dateContainer=this.getBianCeLeiChongData();
		}
		else if(type==10){
			actVo=NewActiveManager.ins.getActiveVerDic(145);
			if(!actVo || !this.hanDongLeiChongTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(145);
			ary=oprVo.infos;
			dateContainer=this.getHanDongLeiChongData();
		}
		else if(type==11){
			actVo=NewActiveManager.ins.getActiveVerDic(149);
			if(!actVo || !this.hanDongFanLiTab){
				return [];
			}
			oprVo=Mgr.opeAct.getOprationVo(149);
			ary=oprVo.infos;
			dateContainer=this.getHanDongFanLiData();
		};
		var wlq=100;
		var wdc=200;
		var ylq=300;
		var len=ary.length;
		var arr=[];
		var vo;
		for(var $each_vo in ary){
			vo=ary[$each_vo];
			var ele=dateContainer.getElement(vo.id);
			if(ele){
				if(oprVo){
					if(vo){
						ele.data=vo;
						if(vo.state==1){
							ele.sortIndex=ylq++;
						}
						else if(vo.process >=ele.getCfgData().num){
							ele.sortIndex=wlq++;
						}
						else{
							ele.sortIndex=wdc++;
						}
					}
					else{
						ele.sortIndex=wdc++;
					}
				}
				else{
					ele.sortIndex=wdc++;
				}
				arr.push(ele);
			}
		}
		if(isSort){
			var fun=function (a,b){
				return a.sortIndex-b.sortIndex;
			}
			arr.sort(fun);
		}
		return arr;
	}

