		var len=arr.length;
		var index=0;
		var ele;
		var cfg;
		for(var i=0;i<len;i++){
			ele=arr[i];
			cfg=ele.getCfgData();
			var attrArr=cfg.needAttr;
			if(!attrArr||attrArr.length)continue ;
			if(!Mgr.zhuoYueZhuangBeiM.checkZYZLAll(attrArr)){
				break ;
			}
			index=i;
		}
		ele=arr[index];
