//class com.xq.rpg.action.AttackAction
var AttackAction=(function(){
	function AttackAction(unit){
		this._unit=null;
		this._unit=unit;
	}

	__class(AttackAction,'com.xq.rpg.action.AttackAction');
	var __proto=AttackAction.prototype;
	/**普通攻击 */
	__proto.attackNormal=function(opbase,forbitSound){
		(forbitSound===void 0)&& (forbitSound=false);
		if(!opbase || !opbase.vo){
			return;
		};
		var dir=this._unit.curDir;
		var targets=opbase.targetArr;
		var targetUnit;
		if(targets && targets.length>0){
			targetUnit=targets[0];
		}
		if((this._unit instanceof com.xq.rpg.unit.Player )){
			if(this._unit.doAction(opbase.vo.action,dir)){
			}
			if((this._unit instanceof com.xq.rpg.unit.MainPlayer )|| SkillBase.skillNum < 15){
				opbase.start(forbitSound);
			}
		}
		else{
			if(this._unit.doAction(5,dir)){
				opbase.start(forbitSound);
			}
		}
	}

	return AttackAction;
})()


