		this.effectid=cfgData.effectid;
		this.effecttypeID=cfgData.effecttypeID;
		this.head_uri=cfgData.head_uri;
		this.icon=cfgData.icon;
		this.skillable=cfgData.skillable;
		this.walkable=cfgData.walkable;
		this.buffOffsetY=cfgData.offY || 1;
