	__proto.getTarget=function(rect){
		var childs=this._unitLayer._childs;
		var len=childs.length;
		var tarArr=[];
		for(var i=0;i<len;i++){
			var unit=childs [i];
			if(rect.contains(unit.x,unit.y)){
				tarArr.push(unit);
			}
		}
		return tarArr;
	}

	__proto.hitTestBySprite=function(sp){
		var childs=this._unitLayer._childs;
		var len=childs.length;
		var tarArr=[];
		var po=new Point();
		for(var i=0;i<len;i++){
			var unit=childs [i];
			if((unit instanceof com.xq.rpg.unit.Monster )|| (unit instanceof com.xq.rpg.unit.Player )){
				unit.graphics.clear();
				po.setTo(unit.x,unit.y);
				SceneContainer.getInstance().upMapLayer.localToGlobal(po);
				if(sp.hitTestPoint(po.x,po.y)){
					if((unit instanceof com.xq.rpg.unit.MainPlayer )){
						if(!RobotPlayerMgr.ins.RobotIsEney){
							continue ;
						}
					}
					else if((unit instanceof com.xq.rpg.unit.SubPlayer )|| (unit instanceof com.xq.rpg.unit.RobotSubPlayer )){
						continue ;
					}
					tarArr.push(unit);
				}
			}
		}
		return tarArr;
	}

