var FriendModel=(function(){
	function FriendModel(){
		/**最大好友数量*/
		this._maxFriend=0;
		/**最大黑名单数量*/
		this._maxBlack=0;
		/**最大聊天保留条数*/
		this._chatNum=0;
		/**当前操作类型*/
		this._curOperatType=0;
		/**当前操作RoleId*/
		this._curOperatRoleIds=null;
		/**他人操作RoleId*/
		this._otherOperatRoleId=NaN;
		/**当前操作好友数据*/
		this._curOperatFriends=null;
		/**是否自动接受好友请求*/
		this._ifAutoAccept=false;
		this._strangerArr=null;
		this._allFriendsDic=null;
		this._friendDic=null;
		this._blackDic=null;
		this._applyDic=null;
		/**key:roleId value:dic key:guestId value mess*/
		this._chatDic=null;
		/**key:guestId value mess*/
		this._allChatDic=null;
		this._recommondDic=null;
		this._searchArr=null;
		/**friend配置*/
		this._friendCof=null;
		this.initCof();
	}

	__class(FriendModel,'com.xq.rpg.model.FriendModel');
	var __proto=FriendModel.prototype;
	__proto.initCof=function(){
		this._friendCof=CfgManager.getTableCfg("Friends");
		var arr=this._friendCof.objectDataArray;
		if(arr[0]){
			this._maxFriend=arr[0].FriendsNum;
			this._maxBlack=arr[0].BlacklistNum;
			this._chatNum=arr[0].ChatNum;
		}
		this._strangerArr=[];
		this._allFriendsDic=new Dictionary();
		this._friendDic=new Dictionary();
		this._blackDic=new Dictionary();
		this._applyDic=new Dictionary();
		this._allFriendsDic.set(1,this._friendDic);
		this._allFriendsDic.set(3,this._applyDic);
		this._allFriendsDic.set(2,this._blackDic);
		this._chatDic=new Dictionary();
		this._allChatDic=new Dictionary();
		this._recommondDic=new Dictionary();
		this._searchArr=[];
	}

	/**根据类型获取对应好友类型数据*/
	__proto.getDicByType=function(type){
		return this._allFriendsDic.get(type);
	}

	/**通过好友Guid获取好友信息*/
	__proto.getFriendById=function(guid){
		return this._friendDic.get(guid);
	}

	/**更新 分类所有朋友数据*/
	__proto.initFriends=function(msg){
		this._ifAutoAccept=msg.isAutoAdd;
		var arr=msg.friends;
		var len=arr.length;
		for(var i=0;i<len;i++){
			this.updateFriendByType(arr[i]);
		}
	}

	__proto.updateFriendByType=function(msg){
		switch(msg.type){
			case 0:
				break ;
			case 1:
				if(msg.online==true){
					msg.offlineTime=Mgr.curTime.serverTimer+1000 *60 *60 *24;
				}
				this._friendDic.set(msg.roleId,msg);
				break ;
			case 2:
				this._blackDic.set(msg.roleId,msg);
				break ;
			case 3:
				this._applyDic.set(msg.roleId,msg);
				break ;
			}
	}

	/**更新搜索*/
	__proto.updateSearch=function(msg){
		this._searchArr=msg.searchResults;
	}

	__proto.updateAutoAccept=function(msg){
		this._ifAutoAccept=msg.isAutoAdd;
	}

	/**更新好友操作*/
	__proto.updateMyOperatType=function(msg){
		this._curOperatType=msg.type;
		this._curOperatRoleIds=msg.roleId;
	}

	__proto.updateOthersOperatType=function(msg){
		this._curOperatType=msg.type;
		this._curOperatRoleIds=[msg.roleId];
	}

	__proto.updateOperatData=function(msg){
		this._curOperatFriends=msg.friends;
	}

	__proto.updateOnlineStat=function(msg,curTime){
		var roleId=msg.targetId;
		var online=msg.online;
		var keys=this._allFriendsDic.keys;
		var len=keys.length;
		for(var i=0;i<len;i++){
			var type=keys[i];
			var dic=this._allFriendsDic.get(type);
			if(!dic){
				continue ;
			};
			var friend=dic.get(roleId);
			if(friend){
				friend.online=online;
				if(!online){
					friend.offlineTime=curTime;
					}else{
					friend.offlineTime=curTime+10000;
				}
			}
		}
	}

	/**更新 所有的列表 */
	__proto.updateAllData=function(friends){
		if(!friends||friends.length==0)return;
		var len=friends.length;
		for(var i=0;i<len;i++){
			var friend=friends[i];
			this.updateSingleFriend(friend);
		}
	}

	__proto.updateSingleFriend=function(friend){
		var t=friend.type;
		var keys=this._allFriendsDic.keys;
		var len=keys.length;
		for(var i=0;i<len;i++){
			var type=keys[i];
			var dic=this._allFriendsDic.get(type);
			if(t==type){
				dic.set(friend.roleId,friend);
			}
			else{
				if(dic.get(friend.roleId)){
					dic.remove(friend.roleId);
				}
			}
		}
	}

	/**初始化留言后台数据*/
	__proto.initChat=function(msg,myId){
		var arr=msg.guests;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var message=arr[i];
			this.updateChatData(message,myId);
		}
	}

	__proto.updateSingleChat=function(msg,myId){
		var message=msg.guest;
		this.updateChatData(message,myId);
	}

	__proto.updateChatData=function(message,myRoleId){
		var flag=message.sourceId==myRoleId
		if(flag){
			message.state=1;
		};
		var friendRoleId=flag?message.targetId:message.sourceId;
		var singleChat=this._chatDic.get(friendRoleId);
		if(!singleChat){
			singleChat=new Dictionary();
			this._chatDic.set(friendRoleId,singleChat);
		};
		var keys=singleChat.keys;
		var len=keys.length;
		if(len>=this._chatNum){
			var num=len-this._chatNum+1;
			for(var i=0;i<num;i++){
				singleChat.remove(keys[i]);
			}
		}
		singleChat.set(message.guestId,message);
		this._allChatDic.set(message.guestId,message);
	}

	__proto.getChatArrById=function(roleId){
		var singleChat=this._chatDic.get(roleId)
		if(singleChat){
			return singleChat.values;
		}
		return [];
	}

	/**通过消息Id获取对应的消息数据*/
	__proto.getMessage=function(guestId){
		var mess=this._allChatDic.get(guestId)
		return mess;
	}

	/**更新消息状态*/
	__proto.updateMessageStat=function(msg){
		var targetMsg=this.getMessage(msg.guestId);
		if(targetMsg){
			targetMsg.state=msg.state;
		}
	}

	//系统推荐好友
	__proto.updateRecommond=function(msg){
		this._recommondDic.clear();
		var arr=msg.infos;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var info=arr[i];
			this._recommondDic.set(info.roleId,info);
		}
	}

	__proto.deletRecommond=function(roleId){
		this._recommondDic.remove(roleId);
	}

	/**当前操作类型 更新得friendNMsg*/
	__getset(0,__proto,'curOperatFriends',function(){
		return this._curOperatFriends;
	});

	//=============属性访问器定义====================
	__getset(0,__proto,'maxFriend',function(){
		return this._maxFriend;
	});

	/**当前操作类型*/
	__getset(0,__proto,'curOperatType',function(){
		return this._curOperatType;
	});

	/**所有关系字典*/
	__getset(0,__proto,'allFriendDic',function(){
		return this._allFriendsDic;
	});

	__getset(0,__proto,'maxBlack',function(){
		return this._maxBlack;
	});

	/**留言数据字典*/
	__getset(0,__proto,'chatDic',function(){
		return this._chatDic;
	});

	/**当前操作RoleId*/
	__getset(0,__proto,'otherOperatRoleId',function(){
		return this._otherOperatRoleId;
	});

	__getset(0,__proto,'ifAutoAccept',function(){
		return this._ifAutoAccept;
	});

	__getset(0,__proto,'maxChatNum',function(){
		return this._chatNum;
	});

	/**申请列表类型*/
	__getset(0,__proto,'searchArr',function(){
		return this._searchArr;
	});

	/**当前操作RoleId*/
	__getset(0,__proto,'curOperatRoleIds',function(){
		return this._curOperatRoleIds;
	});

	/**推荐好友数组*/
	__getset(0,__proto,'recommondArr',function(){
		return this._recommondDic.values;
	});

	return FriendModel;
})()


