var GuoQiModel=(function(){
	function GuoQiModel(){
		this.flagObj=null;
		this.bangCfg=null;
		/**活动时间*/
		this.endTime=0;
		/**后端数据*/
		this.msgInfo=null;
		/**排行数据*/
		this.rankAry=null;
		this.flagObj={};
		this.bangCfg=CfgManager.getTableCfg("shengqibang");
	}

	__class(GuoQiModel,'com.xq.rpg.model.GuoQiModel');
	var __proto=GuoQiModel.prototype;
	__proto.getCfgByFlag=function(flag){
		return this.bangCfg.getAllItemByFiled("flag",flag);
	}

	/**获取排行数据*/
	__proto.getRankAry=function(){
		return this.rankAry
	}

	/**更新协议数据*/
	__proto.updateServer=function(msg,flag){
		var temp=msg.list;
		var l=temp.length;
		var rankScObj={}
		for (var i=0;i < l;i++){
			var rankMsg=temp[i];
			rankScObj[rankMsg.rank]=rankMsg;
		}
		this.endTime=msg.endTime;
		this.regConfig(flag,rankScObj);
	}

	/**合并server数据*/
	__proto.regConfig=function(flag,msgObj){
		var cfgAry=this.getRankCfg(flag);
		var l=cfgAry.length;
		for (var i=0;i < l;i++){
			var item=cfgAry[i];
			item["msg"]=msgObj[item.rank];
		}
		this.rankAry=cfgAry;
	}

	/**获取排行配置*/
	__proto.getRankCfg=function(flag){
		if(this.flagObj[flag]){
			return this.flagObj[flag];
		};
		var rankAry=[];
		var ary=this.getCfgByFlag(flag);
		var l=ary.length;
		for (var i=0;i < l;i++){
			var obj=ary[i];
			var a=obj.rank.split("|");
			var min=parseInt(a[0]);
			var max=parseInt(a[1]);
			var leng=1;
			var qujian=max-min;
			if(qujian > leng){
				leng=qujian+1;
			}
			for (var j=0;j < leng;j++){
				var ele={};
				ele["reward"]=obj.reward;
				ele["limit"]=obj.limit;
				ele["rank"]=min+j;
				ele["name"]=min+j;
				rankAry.push(ele);
			}
		}
		this.flagObj[flag]=rankAry;
		return rankAry;
	}

	return GuoQiModel;
})()


