	__proto.initShenJiangData=function(){
		this.heroCfgData=new DataContainer();
		var cfgAry=this.heroCfg.objectDataArray;
		var len=cfgAry.length;
		for (var i=0;i < len;i++){
			var obj=cfgAry[i];
			var ele=new DataElement(obj);
			this.heroCfgData.addElement(obj.id,ele);
		}
	}

	/**
	*获取觉醒配置表数据
	*@param type 英雄类型
	*@param stage 觉醒阶数
	*@param lv 觉醒等级
	**/
	__proto.getJXCfg=function(type,stage,lv){
		if(this.jxCfgData){
			var daObj=this.jxCfgData.where("sjtype",type,"level");
			if(daObj){
				daObj=daObj.where("stage",stage,"level");
				if(daObj){
					daObj=daObj.where("level",lv,"level");
					if(daObj){
						return daObj.getElement(lv).getCfgData();
					}
				}
			}
		}
		return null;
	}

	/**觉醒表数据*/
	__proto.initJueXigData=function(){
		if(!this.jxCfgData){
			this.jxCfgData=new DataContainer();
			var cfgAry=this.jxCfg.objectDataArray;
			var len=cfgAry.length;
			var stageObj={};
			for (var i=0;i < len;i++){
				var obj=cfgAry[i];
				var ele=new DataElement(obj);
				this.jxCfgData.addElement(i,ele);
				if(obj.level==0){
					var type=obj.sjtype
					if(!stageObj[type]){
						stageObj[type]=[];
						this.jxCfgData.setCustomData(type,stageObj[type]);
					}
					stageObj[type].push(obj);
				}
			}
		}
	}

	/**设置英雄信息*/
	__proto.setShenJiangInfo=function(msg){
		this.heroMsgObj[msg.shenJiangType]=msg;
		this.sortPySkill(msg);
		this.sortJjSkill(msg.juexing);
		this.initSkillObj(msg);
	}

	/**
	*获取神将信息
	*@param type 类型
	**/
	__proto.getShenJiangInfo=function(type){
		return this.heroMsgObj[type];
	}

