//class com.xq.rpg.model.MarriageTaskModel
var MarriageTaskModel=(function(){
	function MarriageTaskModel(){
		this._taskCof=null;
		this._taskDc=null;
		this._lifelongDic=null;
		this._taskCof=CfgManager.getTableCfg("marryTask");
		this._lifelongDic=new Dictionary();
	}

	__class(MarriageTaskModel,'com.xq.rpg.model.MarriageTaskModel');
	var __proto=MarriageTaskModel.prototype;
	__proto.updateTask=function(msg){
		var taskList=msg.taskList;
		var len=taskList.length;
		for(var i=0;i<len;i++){
			var task=taskList[i];
			var id=task.id;
			var ele=this.taskDc.getElement(id);
			if(ele){
				ele.setValue("server",task);
			}
		}
	}

	__proto.updateReward=function(msg){
		var ele=this.taskDc.getElement(msg.id);
		if(ele){
			var vo=ele.getValue("server");
			if(vo){
				vo.finishState=msg.finishState;
			}
		}
	}

	/**获取任务状态1 可领取 2未达成 3已领取 为了方便排序所以这么定义*/
	__proto.getStat=function(ele){
		if(ele){
			var cof=ele.getCfgData();
			var taskMsg=ele.getValue("server");
			if(!taskMsg){
				return 2;
			};
			var target=cof.target;
			var finishtype=cof.finishtype;
			var finishStat=taskMsg.finishState;
			var progress=taskMsg.progress+taskMsg.cpProgress;
			if(finishtype==1){
				progress=taskMsg.progress;
				if(progress < taskMsg.cpProgress)target=taskMsg.cpProgress;
				}else if(finishtype==2){
				if(taskMsg.progress >=taskMsg.cpProgress){
					progress=taskMsg.cpProgress;
					}else{
					progress=taskMsg.progress;
				}
			}
			if(finishStat && progress >=target){
				return 3;
				}else{
				if(!finishStat && progress >=target){
					return 1;
				}
				else{
					return 2;
				}
			}
		}
		else{
			return 2;
		}
	}

	__proto.compareByStat=function(a,b){
		var statA=Model.marrTaskModel.getStat(a);
		var statB=Model.marrTaskModel.getStat(b);
		return statA-statB;
	}

	__getset(0,__proto,'dailyTaskList',function(){
		var data=this.taskDc.where("tasktype",1,"id");
		var arr=data.array.concat();
		arr=arr.sort(this.compareByStat);
		return arr;
	});

	__getset(0,__proto,'lifelongDic',function(){
		return this._lifelongDic;
	});

	__getset(0,__proto,'taskDc',function(){
		if(!this._taskDc){
			this._taskDc=new DataContainer();
			var arr=this._taskCof.objectDataArray;
			var len=arr.length;
			var ele;
			var cof;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this._taskDc.addElement(parseInt(cof.id),ele);
			}
		}
		return this._taskDc;
	});

	//需要排序
	__getset(0,__proto,'lifelongTaskList',function(){
		this._lifelongDic.clear();
		var data=this.taskDc.where("tasktype",2,"id");
		var arr=data.array;
		var len=arr.length;
		var ele;
		var cof;
		var id=0;
		var stat=0;
		for(var i=0;i<len;i++){
			ele=arr[i];
			id=parseInt(ele.getCfgData().chengjiuid);
			stat=this.getStat(ele);
			if(stat==1){
				var selectEle=this._lifelongDic.get(id)
				if(!selectEle||this.getStat(selectEle)!=1){
					this._lifelongDic.set(id,ele);
					continue ;
				}
			}
			if(stat==2){
				selectEle=this._lifelongDic.get(id)
				if(!selectEle||this.getStat(selectEle)==3){
					this._lifelongDic.set(id,ele);
					continue ;
				}
			}
			if(stat==3){
				selectEle=this._lifelongDic.get(id)
				if(!selectEle||this.getStat(selectEle)==3){
					this._lifelongDic.set(id,ele);
					continue ;
				}
			}
		};
		var selectArr=this._lifelongDic.values.concat();
		selectArr=selectArr.sort(this.compareByStat);
		return selectArr;
	});

	return MarriageTaskModel;
})()


