var MergeSvrGiftModel=(function(){
	function MergeSvrGiftModel(){
		this._cof=null;
		this._dc=null;
		/**当前_版本flag*/
		this._flag=0;
		this._cof=CfgManager.getTableCfg("hefuhaoli");
	}

	__class(MergeSvrGiftModel,'com.xq.rpg.model.mergeSvrCelebration.MergeSvrGiftModel');
	var __proto=MergeSvrGiftModel.prototype;
	/**通过flag获取数据*/
	__proto.getListByFlag=function(flag){
		var data=this.dc.where("flag",flag,"id");
		return data.array;
	}

	__proto.getCurList=function(){
		var data=this.dc.where("flag",this._flag,"id");
		return data.array;
	}

	__proto.updateData=function(msg){
		this._flag=msg.flag;
		var arr=msg.msg;
		var len=arr.length;
		var ele;
		var stat;
		for(var i=0;i<len;i++){
			stat=arr[i];
			ele=this.dc.getElement(stat.id);
			if(ele){
				ele.setValue("S",stat.state);
			}
			if(stat.state){
				ele.setValue("Z",(stat.id+10));
			}
		}
	}

	__getset(0,__proto,'dc',function(){
		if(!this._dc){
			this._dc=new DataContainer();
			var arr=this._cof.objectDataArray;
			var len=arr.length;
			var ele;
			var cof;
			for(var i=0;i<len;i++){
				cof=arr[i];
				ele=new DataElement(cof);
				this._dc.addElement(cof.id,ele);
			}
		}
		return this._dc;
	});

	return MergeSvrGiftModel;
})()


