//class com.xq.rpg.model.NpcModel
var NpcModel=(function(){
	function NpcModel(){
		this.npcConfig=null;
		this.npcDic=new Dictionary();
		this.npcMapDic=new Dictionary();
		this.npcMapSeeDic=new Dictionary();
		this.npcConfig=CfgManager.getTableCfg("NpcLieBiao");
		this.parseNpc();
	}

	__class(NpcModel,'com.xq.rpg.model.NpcModel');
	var __proto=NpcModel.prototype;
	__proto.parseNpc=function(){
		var datas=this.npcConfig.objectDataArray;
		if(!datas)return;
		var len=datas.length;
		var npcVO;
		for(var i=0;i<datas.length;i++){
			npcVO=new NpcVO();
			npcVO.bind(datas[i]);
			this.npcDic.set(npcVO.id,npcVO);
		}
	}

	__proto.getNpcItemByMap=function(){}
	__proto.getNpcVO=function(id){}
	__proto.getNpcsByMapId=function(id){
		var npcs=this.npcMapDic.get(id);
		if(!npcs){
			npcs=[];
			var values=this.npcDic.values;
			var len=values.length;
			for(var i=0;i<len;i++){
				if(values[i].map==id)
					npcs.push(values[i]);
			}
			this.npcMapDic.set(id,npcs);
		}
		return npcs;
	}

	__proto.getSeeNpcsByMapId=function(id){
		var npcs=this.npcMapSeeDic.get(id);
		if(!npcs){
			npcs=[];
			var values=this.npcDic.values;
			var len=values.length;
			for(var i=0;i<len;i++){
				if(values[i].map==id && values[0].see>0)
					npcs.push(values[i]);
			}
			this.npcMapSeeDic.set(id,npcs);
		}
		return npcs;
	}

	__proto.getNpcByNpcId=function(id){
		return this.npcDic.get(id);
	}

	return NpcModel;
})()


