		/**昨日冲榜排名数据*/
		this._preRankInfo=null;
		/**排名变化数据*/
		this._rankChangeInfo=null;
		/**排名下降数据*/
		this._rankReduceInfo=null;
		this._preMaxValue=NaN;
		this._curMaxValue=NaN;
