//class com.xq.rpg.model.UIModel
var UIModel=(function(){
	function UIModel(){
		this.isOpenFrameView=false;
		/**一级面板 数据*/
		this._1stViewDic=null;
		/**二级面板 数据*/
		this._2ndViewDic=null;
		/**三级面板*/
		this._3ndViewDic=null;
		this._1stViewDic=new Object();
		this._2ndViewDic=new Object();
		this._3ndViewDic=new Object();
	}

	__class(UIModel,'com.xq.rpg.model.UIModel');
	var __proto=UIModel.prototype;
	__proto.checkHasFrameOpen=function(){
		if(this._1stViewDic){
			var obj=this._1stViewDic;
			var v;
			for(var $each_v in obj){
				v=obj[$each_v];
				if(v.parent){
					return true
				}
			}
		}
		if(this._2ndViewDic){
			var $each_v;
			for($each_v in this._2ndViewDic){
				v=this._2ndViewDic[$each_v];
				if((v instanceof laya.ui.FrameView )){
					if(v.parent){
						return true;
					}
				}
			}
		}
		return false;
	}

	return UIModel;
})()


