//class com.xq.rpg.model.XinWuModel
var XinWuModel=(function(){
	function XinWuModel(){
		/**见证数据*/
		this.jianZhengObj={};
		/**见证数据-DataContainer*/
		this.jzDataObj=null;
		/**task数据-DataContainer*/
		this.taskDataObj=null;
		/**令牌cfg*/
		this.lingpaiCfg=null;
		/**见证cfg*/
		this.jianZhenCfg=null;
		/**任务cfg*/
		this.taskCfg=null;
		this.lingpaiCfg=CfgManager.getTableCfg("jianZhengLingPai");
		this.jianZhenCfg=CfgManager.getTableCfg("jianZheng");
		this.taskCfg=CfgManager.getTableCfg("jianZhengTask");
		this.initCfg();
	}

	__class(XinWuModel,'com.xq.rpg.model.XinWuModel');
	var __proto=XinWuModel.prototype;
	__proto.initCfg=function(){
		this.jzDataObj={};
		this.taskDataObj={};
		for (var j=0;j < 2;j++){
			var jzData=new DataContainer();
			var ary=this.jianZhenCfg.getItemsByField("bigType",j);
			var l=ary.length;
			var ele;
			var cfg;
			for (var i=0;i < l;i++){
				cfg=ary[i];
				ele=new DataElement(cfg);
				jzData.addElement(cfg.Id,ele);
			}
			this.jzDataObj[j]=jzData;
			var taskData=new DataContainer();
			ary=this.taskCfg.getItemsByField("bigType",j);
			l=ary.length;
			for (i=0;i < l;i++){
				cfg=ary[i];
				ele=new DataElement(cfg);
				ele.setValue("sortMark",100);
				taskData.addElement(cfg.Id,ele);
			}
			this.taskDataObj[j]=taskData;
		}
	}

	/**初始化见证信息*/
	__proto.initJianZhengObj=function(msg){
		this.jianZhengObj[msg.type]=msg;
		var tempData=this.jzDataObj[msg.type];
		var ary=msg.jianZhengDatas;
		var l=ary.length;
		for (var i=0;i < l;i++){
			var tsg=ary[i];
			var d=tempData.getElement(tsg.id);
			d.setValue("msg",tsg);
		}
	}

	/**获取见证信息*/
	__proto.getJianZhengInfo=function(type){
		return this.jianZhengObj[type]
	}

	/**见证激活*/
	__proto.jianZhengAvtive=function(msg){
		var temp=this.jianZhengObj[msg.type];
		temp.totalLevel+=1;
		this.updateJianZhengMsg(msg.type,msg.activeIndex,msg.jianZhengData);
	}

	/**见证升级*/
	__proto.jianZhengUpgrade=function(type,id,tsg,ttLv){
		var temp=this.jianZhengObj[type];
		this.updateJianZhengMsg(type,id,tsg);
		temp.totalLevel=ttLv;
	}

	/**更新见证*/
	__proto.updateJianZhengMsg=function(type,id,tsg){
		var tempData=this.jzDataObj[type];
		var ele=tempData.getElement(id);
		ele.setValue("msg",tsg);
	}

	/**初始化任务信息*/
	__proto.initTask=function(msg){
		var tempData=this.taskDataObj[msg.type];
		var ary=msg.taskDatas;
		var l=ary.length;
		for (var i=0;i < l;i++){
			var tsg=ary[i];
			var d=tempData.getElement(tsg.taskId);
			if(d){
				d.setValue("msg",tsg);
				if(tsg.taskState==2){
					d.setValue("sortMark",999);
					}else if(tsg.taskState==1){
					d.setValue("sortMark",1);
				}
			}
		}
	}

	/**更新任务*/
	__proto.updateTask=function(type,tsg){
		var tempData=this.taskDataObj[type];
		var d=tempData.getElement(tsg.taskId);
		d.setValue("msg",tsg);
		if(tsg.taskState==2){
			d.setValue("sortMark",999);
			}else if(tsg.taskState==1){
			d.setValue("sortMark",1);
		}
	}

	/**更新碎片数量*/
	__proto.updateSuiPian=function(type,num){
		var msg=this.jianZhengObj[type];
		msg.suiPianVal=num;
	}

	/**获取令牌配置*/
	__proto.getLingPai=function(type){
		return this.lingpaiCfg.getItemByField("type",type);
	}

	/**获取任务数据*/
	__proto.getTaskData=function(type,sort){
		(sort===void 0)&& (sort=false);
		if(!sort){
			return this.taskDataObj[type].array;
		}
		else{
			var ary=this.taskDataObj[type].array;
			var sorF=function (a,b){
				var sortA=a.getValue("sortMark");
				var sortB=b.getValue("sortMark");
				return sortA-sortB;
			}
			ary.sort(sorF);
		}
		return ary
	}

	/**获取见证数据*/
	__proto.getJianZhengData=function(type){
		return this.jzDataObj[type].array;
	}

	return XinWuModel;
})()


