//class com.xq.rpg.model.ZhenFaModel
var ZhenFaModel=(function(){
	function ZhenFaModel(){
		/**品质Obj*/
		this.qualityObj={};
		this.infoObj={};
		/**阵法总览*/
		this.zfZLCfg=null;
		/**阵法修炼*/
		this.zfXlCfg=null;
		/**阵法总览数据容器*/
		this.zfZlData=null;
		/**阵法修炼数据容器*/
		this.zfXlData=null;
		this.zfZLCfg=CfgManager.getTableCfg("newzhenfa");
		this.zfXlCfg=CfgManager.getTableCfg("zhenfaxiulian");
	}

	__class(ZhenFaModel,'com.xq.rpg.model.ZhenFaModel');
	var __proto=ZhenFaModel.prototype;
	__proto.setInfo=function(msg){
		this.infoObj[msg.type]=msg;
	}

	__proto.getInfo=function(type){
		return this.infoObj[type];
	}

	/**更新激活状态*/
	__proto.updateActivate=function(type,id,lv){
		var tsg=new HuanHuaAttr();
		tsg.level=lv;
		tsg.id=id;
		var msg=this.infoObj[type];
		msg.message.push(tsg);
	}

	/**更新幻化等级*/
	__proto.updateJjLevel=function(type,id,lv){
		var tsg=this.getHuanHuaAttr(type,id);
		if(tsg){
			tsg.level=lv;
		}
	}

	/**更新佩戴ID*/
	__proto.updatePeiDai=function(type,id){
		var msg=this.infoObj[type];
		msg.peidaiId=id;
	}

	/**获取佩戴ID*/
	__proto.getPeiDai=function(type){
		var msg=this.infoObj[type];
		return msg.peidaiId;
	}

	/**获取id阵法信息*/
	__proto.getHuanHuaAttr=function(type,id){
		var msg=this.infoObj[type];
		if(msg){
			var ary=msg.message;
			var len=ary.length;
			for (var i=0;i < ary.length;i++){
				var tsg=ary[i];
				if(tsg.id==id){
					return tsg;
				}
			}
		}
		return null
	}

	/**阵法总览数据*/
	__proto.initZfZongLan=function(){
		if(!this.zfZlData){
			this.zfZlData=new DataContainer;
			var cfgAry=this.zfZLCfg.objectDataArray;
			var len=cfgAry.length;
			var tempObj=this.qualityObj;
			tempObj[16]=[]
			tempObj[17]=[]
			tempObj[18]=[]
			tempObj[19]=[]
			for (var i=0;i < len;i++){
				var obj=cfgAry[i];
				var ele=new DataElement(obj);
				this.zfZlData.addElement(i,ele);
				var ary=tempObj[obj.type]
				if(ary && ary.indexOf(obj.quality)==-1){
					ary.push(obj.quality);
				}
			}
			this.sortQuality(tempObj[16]);
			this.sortQuality(tempObj[17]);
			this.sortQuality(tempObj[18]);
			this.sortQuality(tempObj[19]);
		}
	}

	__proto.sortQuality=function(ary){
		if(ary){
			var sorF=function (a,b){
				return a-b;
			}
			ary.sort(sorF);
		}
	}

	__proto.init=function(){
		this.initZfZongLan();
		this.initZfXiuLian();
	}

	/**阵法修炼数据*/
	__proto.initZfXiuLian=function(){
		if(!this.zfXlData){
			this.zfXlData=new DataContainer();
			var cfgAry=this.zfXlCfg.objectDataArray;
			var len=cfgAry.length;
			for (var i=0;i < len;i++){
				var obj=cfgAry[i];
				var ele=new DataElement(obj);
				this.zfXlData.addElement(i,ele);
			}
		}
	}

	/**
	*获取阵法修炼配置表的数据
	*@param huanhuaId 阵法ID
	*@param star 星级
	**/
	__proto.getZfXlCfg=function(huanhuaId,star){
		var data=this.zfXlData.where("ID",huanhuaId,"star")
		.where("star",star,"star").getElement(star);
		if(data){
			return data.getCfgData();
		}
		return null;
	}

	__proto.getZfCfg=function(id){
		return this.zfZLCfg.getItemByField("huanhuaid",id);
	}

	return ZhenFaModel;
})()


