/**
*@author:huanghong
*@date:2021-10-29
*@desc:下方 合击 技能栏 mgr
*/
//class com.xq.rpg.skill.ActionSkillMgr
var ActionSkillMgr=(function(){
	function ActionSkillMgr(){
		this._model=null;
		/**公共点击cd*/
		this._clickCd=NaN;
		this._hero=null;
		this._nuqiMax=0;
		this._nuqiAdd=0;
		/**当前展示的技能数据*/
		this._curShowData=null;
		this._openTaskVO=null;
		this._model=new ActionSkillModel();
		this._hero=NetMgr.ins().roleVO;
		this._nuqiMax=Mgr.hjModel.hejiNeedNuQi;
		this._nuqiAdd=Mgr.hjModel.hejiHuiFu;
	}

	__class(ActionSkillMgr,'com.xq.rpg.skill.ActionSkillMgr');
	var __proto=ActionSkillMgr.prototype;
	__proto.getSkillDataByHjType=function(hjtype){
		return this._model.getSkillDataByHjType(hjtype);
	}

	/**获取合击技能数据*/
	__proto.getSkillArr=function(){
		return this._model.getSkillArr();
	}

	/**更新公共点击cd*/
	__proto.updateClickCd=function(){
		this._clickCd=Browser.now()+2000;
	}

	/**检测是否可以点击使用（点击cd是否满足条件）*/
	__proto.checkCanClick=function(){
		return !this._clickCd||this._clickCd<=Browser.now();
	}

	/**合击技能栏位是否解锁*/
	__proto.checkIsOpen=function(vo){
		if(!vo)return false;
		if(!this._openTaskVO){
			var heJiOpenSkill=Mgr.cfgMgr.getValueByType(168);
			this._openTaskVO=Mgr.task.getTaskVoById(heJiOpenSkill);
		};
		var curTask=Mgr.task.curTask;
		if(!curTask)return false;
		if(this._openTaskVO&&this._openTaskVO.num>=curTask.num){
			return false;
		}
		if(vo.heJiType=="BIANSHEN"){
			if(NewActiveManager.ins.checkIsOpen(156)){
				if(!Mgr.tianShenActiveMgr.getIfOver()){
					return false;
				}
			}
			else{
				return false;
			}
		};
		var openfunc=vo.openFunc;
		if(!Mgr.guide.isOpen(openfunc)){
			return false;
		}
		return true;
	}

	/**检测栏位是否已装配技能*/
	__proto.checkEquip=function(vo){
		return vo.skill?true:false;
	}

	/**刷新状态*/
	__proto.updateStat=function(vo){
		if(vo.stat==1){
			if(this.checkIsOpen(vo)){
				vo.stat=2;
				this.updateStat(vo);
			}
		}
		else if(vo.stat==2){
			if(this.checkEquip(vo)){
				vo.stat=4;
				this.updateStat(vo);
				if(vo.heJiType=="heji01"){
					this._hero.nuqi=this._nuqiMax;
				}
			}
		}
		else{
			this.updateCdStat(vo);
		}
	}

	/**刷新技能冷却状态*/
	__proto.updateCdStat=function(vo){
		if(vo.stat==3){
			if(vo.readyTime<=Browser.now()){
				vo.stat=4;
				this.updateStat(vo);
				if(vo.heJiType=="heji01"){
					this._hero.nuqi=this._nuqiMax;
				}
			}
		}
		else if(vo.stat==4){
			if(vo.readyTime>Browser.now()){
				vo.stat=3;
				this.updateStat(vo);
			}
		}
	}

	/**检测是否弹出提示窗*/
	__proto.checkShowTip=function(){
		if(this._hero.level <=Mgr.hjModel.guideHejiLevel && MapType.isCopy(NetMgr.ins().roleVO.mapType)&&this._curShowData&&this._curShowData.stat==4){
			return true;
		}
		return false;
	}

	/**刷新当前需要展示技能数据*/
	__proto.updateShowData=function(){
		if(this._curShowData&&this._curShowData.stat==4)return;
		var arr=this.getSkillArr();
		var len=arr.length;
		var readyTime=NaN;
		var showData;
		for(var i=0;i<len;i++){
			var data=arr[i];
			if(data.stat<3)continue ;
			if(!readyTime||readyTime>data.readyTime){
				readyTime=data.readyTime;
				showData=data;
			}
		}
		if(!showData){
			this._curShowData=arr[0];
			return;
		}
		if(this._curShowData&&this._curShowData.slot==showData.slot)return;
		this._curShowData=showData;
	}

	__proto.updateHeJiReadyTime=function(){
		var data=this._model.getSkillDataByHjType("heji01");
		if(data){
			this._hero.nuqi=0;
			data.readyTime=Browser.now()+(this._nuqiMax/this._nuqiAdd)*1000;
			this.updateCdStat(data);
			EventCenter.instance.event("UpdateActionSkillItems");
		}
	}

	/**superSkillType:String,skillType:String,skillLevel:int=1,cdTime:int=0*/
	__proto.updateSuperSkillReadyTime=function(superSkillType,cdTime){
		var data=this._model.getSkillDataByHjType(superSkillType);
		if(data){
			if(cdTime <=0){
				cdTime=59000;
			}
			data.readyTime=Browser.now()+cdTime;
			this.updateCdStat(data);
			EventCenter.instance.event("UpdateActionSkillItems");
		}
	}

	/**重置技能就绪时间*/
	__proto.resetSkillReadyTime=function(){
		Mgr.skillGroup.recoverAuto();
		var time=parseInt(Mgr.cfgMgr.getValueByType(224))
		Mgr.skillGroup.mdlPubSkillCD=Browser.now()+time*1000;
		var mapId=NetMgr.ins().roleVO.mapId;
		var mapData=SceneContainer.getInstance().mapDataDic.getItemByField("mapid",mapId);
		if(mapData.hejireset)return;
		var dataArr=this.getSkillArr();
		var len=dataArr.length;
		var ifNew=this._hero.level <=Mgr.hjModel.guideHejiLevel;
		var cd=ifNew?2000:5000;
		var data;
		var curTime=Browser.now();
		for(var i=0;i<len;i++){
			data=dataArr[i];
			data.readyTime=curTime+cd;
			this.updateCdStat(data);
		}
		EventCenter.instance.event("UpdateActionSkillItems");
	}

	/**拉取所有出战合击后刷新数据*/
	__proto.updateAllSkillData=function(arr,cdTime){
		var len=arr.length;
		var info;
		for(var i=0;i<len;i++){
			info=arr[i];
			this.updateSkillData(info,cdTime);
		}
		EventCenter.instance.event("UpdateActionSkillItems");
	}

	/**更改合击技能后刷新数据*/
	__proto.updateChangeSkill=function(hejiMsg,cdTime){
		this.updateSkillData(hejiMsg,cdTime);
		EventCenter.instance.event("UpdateActionSkillItems");
	}

	/**更新技能数据*/
	__proto.updateSkillData=function(hejiMsg,cdTime){
		if(!hejiMsg)return;
		var slot=hejiMsg.slot;
		var data=this._model.getSkillDataBySlot(slot);
		if(data){
			data.skill=Mgr.hjMgr.getCurUseSkillId(hejiMsg.id);
			data.readyTime=Browser.now()+cdTime;
			this.updateStat(data);
		}
	}

	__proto.getTaskHeJi=function(){
		var data=this._model.getSkillDataByHjType("heji01");
		if(data){
			data.skill="heji01";
			data.readyTime=Browser.now()+2000;
			this.updateStat(data);
			EventCenter.instance.event("UpdateActionSkillItems");
		}
	}

	/**当前任务发生变化是刷新数据*/
	__proto.updateTaskSkill=function(){
		var data=this._model.getSkillDataByHjType("heji01");
		if(data.skill){
			EventCenter.instance.event("UpdateActionSkillItems");
			EventCenter.instance.event("OpenAutoChallenge");
			return;
		}
		if(!this._openTaskVO){
			var heJiOpenSkill=Mgr.cfgMgr.getValueByType(168);
			this._openTaskVO=Mgr.task.getTaskVoById(heJiOpenSkill);
		};
		var curTask=Mgr.task.curTask;
		if(this._openTaskVO&&this._openTaskVO.num<curTask.num){
			data.skill="heji01";
			this.updateStat(data);
			EventCenter.instance.event("UpdateActionSkillItems");
			EventCenter.instance.event("OpenAutoChallenge");
		}
	}

	/**使用合击技能 返回 是否使用成功*/
	__proto.useSuperSkillByVo=function(vo){
		if(!vo)return false;
		if(!this.checkCanClick())return false;
		if(vo.stat!=4)return false;
		var hjType=vo.heJiType;
		if(hjType=="heji01"){
			Mgr.skillGroup.castSuperSkill();
			}else if(hjType=="BIANSHEN"){
			Mgr.sceneSyn.sendBianShen();
		}
		else{
			Mgr.skillGroup.useSuperSkill(hjType);
		}
		this.updateClickCd();
		return true;
	}

	//===============变身相关================
	__proto.updateBianShenSkill=function(huanhuaId){
		var huanHuanCfg=Mgr.szMgr.getHuanHuaInfoByOne(huanhuaId+"");
		if(!huanHuanCfg)return;
		var skill=huanHuanCfg.skill;
		var data=this._model.getSkillDataByHjType("BIANSHEN");
		if(!data.skill){
			data.readyTime=Browser.now()+2000;
		}
		data.skill=skill;
		this.updateStat(data);
		EventCenter.instance.event("UpdateActionSkillItems");
		Mgr.skillGroup.updateBianShenSkillGroup(huanhuaId);
	}

	/**收到变身信息*/
	__proto.updateBianShen=function(msg){
		this.changePlayerRes(msg.roleId,msg.huanHuaId,msg.isBianShen);
		if(msg.isBianShen&&msg.roleId==this._hero.guid){
			this.updateSuperSkillReadyTime("BIANSHEN",60000);
		}
	}

	// AIController.ins().startAutoCombat();
	__proto.changePlayerRes=function(roleId,huanHuaId,ifBianShen){
		var player=UnitManager.ins.getPlayerByRoleID(roleId);
		if(!player)return;
		var roleVo=player.vo;
		if(roleVo.isBianShen==ifBianShen)return;
		var huanHuanCfg=Mgr.szMgr.getHuanHuaInfoByOne(huanHuaId+"");
		player.curActIsOk=true;
		if(ifBianShen){
			player.mount(false);
			player.setRes(huanHuanCfg.res);
			player.isHideWeapon(false);
			roleVo.bianShenRes=huanHuanCfg.res;
			roleVo.isBianShen=true;
			roleVo.tianShenBianShenId=huanHuaId;
			}else{
			roleVo.isBianShen=false;
			roleVo.tianShenBianShenId=huanHuaId;
			roleVo.roleHuanHuaId=roleVo.roleHuanHuaId;
			if(roleVo.roleHuanHuaId > 0){
				huanHuanCfg=Mgr.szMgr.getHuanHuaInfoByOne(roleVo.roleHuanHuaId+"");
				player.setRes(huanHuanCfg.res);
			}
			else
			player.setRes(roleVo.res[0]);
			if(roleVo.isRide){
				player.mount(true);
			}
			player.isHideWeapon(true);
		}
	}

	/**切换场景后 强制结束变身*/
	__proto.recoverBianShen=function(){
		var player=Game.getInstance().player;
		if(!player)return;
		if(this._hero.isBianShen){
			this._hero.isBianShen=false;
			this._hero.roleHuanHuaId=this._hero.roleHuanHuaId;
			if(this._hero.roleHuanHuaId > 0){
				var huanHuanCfg=Mgr.szMgr.getHuanHuaInfoByOne(this._hero.roleHuanHuaId+"");
				player.setRes(huanHuanCfg.res);
				this._hero.job=huanHuanCfg.sex;
			}
			else
			player.setRes(this._hero.res[0]);
			if(this._hero.isRide){
				player.mount(true);
			}
			player.isHideWeapon(true);
		}
	}

	/**变身技能图标*/
	__proto.getTianShenSkill=function(){
		var tsId=this._hero.tianShenBianShenId;
		var huanhuaCfg=Mgr.szMgr.getHuanHuaInfoByOne(tsId+"");
		if(huanhuaCfg){
			return huanhuaCfg.skill.split(";")[0];
		}
		return "";
	}

	__getset(0,__proto,'curShowData',function(){
		return this._curShowData;
	});

	return ActionSkillMgr;
})()


