//class com.xq.rpg.skill.newVic.NewSkillMgr
var NewSkillMgr=(function(){
	function NewSkillMgr(){
		/**特效配置*/
		this.skillCfg=null;
		/**效果配置*/
		this.skillAct=null;
		this.ActCac={};
		this.cfgCac={};
		this.skillCfg=CfgManager.getTableCfg("skillCfg");
		this.skillAct=CfgManager.getTableCfg("skillAct");
	}

	__class(NewSkillMgr,'com.xq.rpg.skill.newVic.NewSkillMgr');
	var __proto=NewSkillMgr.prototype;
	__proto.getSkillVo=function(id){
		var vo=this.ActCac[id];
		if(!vo){
			var cfg=this.skillAct.getItemByField("skillID",id);
			vo=new SkillActVo();
			vo.skillId=id;
			vo.readyTime=cfg.readyTime || 0;
			vo.isShake=cfg.isShake;
			vo.hurtDelayTime=cfg.hurtDelayTime;
			vo.actionAry=cfg.action;
			vo.readyEff=this.getCfgVo(cfg.readyEff);
			vo.flyEff=this.getCfgVo(cfg.flyEff);
			vo.flySpeed=cfg.flySpeed;
			vo.hitEff=this.getCfgVo(cfg.hitEff);
			vo.hitDelay=cfg.hitDelay || 0;
			vo.aimEff=this.getCfgVo(cfg.aimEff);
			vo.aimDelay=cfg.aimDelay;
			vo.isMainRole=cfg.isMainRole !=2;
			vo.rushSpeed=cfg.rushSpeed;
			vo.rushDis=cfg.rushDis;
			vo.isMoment=cfg.isMoment;
			vo.isStopFight=cfg.isStopFight==1;
			vo.fullCol=cfg.fullCol;
			vo.fullRow=cfg.fullRow;
			vo.fullDelay=cfg.fullDelay
			if(cfg.fullGap){
				vo.fullRowGap=parseInt(cfg.fullGap[0]);
				vo.fullColGap=parseInt(cfg.fullGap[1]);
			};
			var ary=cfg.queue
			if(ary){
				vo.queueAry=[];
				var l=ary.length;
				for (var i=0;i < l;i++){
					vo.queueAry.push(this.getCfgVo(ary[i]));
				}
			}
			vo.queueActionAry=cfg.queueAction;
			this.ActCac[id]=vo;
		}
		return vo;
	}

	/**增加配置Vo*/
	__proto.getCfgVo=function(id){
		var vo=this.cfgCac[id];
		if(!vo){
			var cfg=this.skillCfg.getItemByField("id",id);
			if(!cfg){
				return null;
			}
			vo=new SkillCfgVo();
			vo.id=id;
			if(cfg.bottomEff){
				vo.skillName=cfg.bottomEff;
				vo.layer=0;
			}
			else if(cfg.upEff){
				vo.skillName=cfg.upEff;
				vo.layer=1;
			}
			vo.bottomEff=cfg.bottomEff;
			vo.upEff=cfg.upEff;
			vo.isDir=cfg.isDir==1;
			vo.count=cfg.count==0? 0 :(cfg.count || 1);
			vo.isRotate=cfg.isRotate;
			vo.randNum=cfg.randNum;
			vo.randType=cfg.randType;
			vo.soundRes=cfg.soundRes;
			vo.delayTime=cfg.delayTime || 1;
			this.cfgCac[id]=vo;
		}
		return vo;
	}

	__getset(1,NewSkillMgr,'ins',function(){
		return NewSkillMgr._ins=NewSkillMgr._ins|| new NewSkillMgr();
	});

	NewSkillMgr._ins=null;
	return NewSkillMgr;
})()


