	SkillBase.sort=function(sx,sy,tarArr,nums,disLimitlen,disLimit){
		var finalArr=[];
		var flagArr=[];
		var len=tarArr.length;
		if(len==0)
			return [];
		if(nums>len)
			nums=len;
		var minDis=NaN;
		var tarObj;
		var startX=sx;
		var startY=sy;
		var endX=0;
		var endY=0;
		var flag=0;
		var isFirst=true;
		for(var j=0;j <nums;j++){
			flag=-1;
			minDis=99999;
			for(var i=0;i < len;i++){
				if(flagArr[i]==1)
					continue ;
				tarObj=tarArr[i];
				if(tarObj.isDead)
					continue ;
				endX=tarObj.x;
				endY=tarObj.y;
				var tempDis=CommonUtil.getDistance(startX,startY,endX,endY);
				if(isFirst){
					if(tempDis > disLimitlen)
						continue ;
				}
				else{
					if(tempDis>disLimit)
						continue ;
				}
				if(minDis > tempDis){
					flag=i;
					minDis=tempDis;
				}
			}
			if(flag !=-1){
				isFirst=false;
				flagArr[flag]=1;
				finalArr.push(tarArr[flag]);
				startX=tarArr[flag].x;
				startY=tarArr[flag].y;
			}
			else{
				break ;
			}
		}
		return finalArr;
	}

	SkillBase.showChain=function(skillvo){
		var len=skillvo.tarArr.length;
		if(len==0)
			return;
		var skillName=skillvo.skillUseRes;
		var i=0;
		var curX=skillvo.curObj.x;
		var curY=skillvo.curObj.y-50;
		var tarX=0;
		var tarY=0;
		var distance=NaN;
		var curDelayTime=0;
		for(i=0;i<len;i++){
			tarX=skillvo.tarArr[i].x;
			tarY=skillvo.tarArr[i].y-50;
			distance=CommonUtil.getDistance(curX,curY,tarX,tarY);
			if(distance>skillvo.radius){
				console.log(Lang.str(3148));
				continue ;
			};
			var skillnum=distance/100+1;
			var ar=Math.atan2(tarY-curY,tarX-curX);
			var r=ar / Math.PI *180+180;
			var tempX=0;
			var tempY=0;
			for(var j=0;j <=skillnum;j++){
				if(j==skillnum){
					tempX=tarX-100 *Math.cos(ar);
					tempY=tarY-100 *Math.sin(ar);
				}
				else{
					tempX=curX+distance *Math.cos(ar)*(j)/skillnum;
					tempY=curY+distance *Math.sin(ar)*(j)/skillnum;
				}
				SkillBase.createSkillInMap(skillvo,skillName,tempX,tempY,0,-1,r+180,curDelayTime,1,1,skillvo.isAutoAlpha,skillvo.alphaTime,false);
				SkillBase.createSkillInMap(skillvo,skillName,tempX,tempY,0,-1,r+180,curDelayTime+100,1,1,skillvo.isAutoAlpha,skillvo.alphaTime,false);
				SkillBase.createSkillInMap(skillvo,skillName,tempX,tempY,0,-1,r+180,curDelayTime+200,1,1,skillvo.isAutoAlpha,skillvo.alphaTime,false);
				curDelayTime+=skillvo.delayTime;
			}
			curX=tarX;
			curY=tarY;
		}
	}

	SkillBase.showRotationRound=function(skillVO,layer){
		(layer===void 0)&& (layer=1);
		var skillUseRes=skillVO.skillUseRes;
		var x=skillVO.curObj.x;
		var y=skillVO.curObj.y;
		var actKey=skillVO.actKey;
		var dirId=skillVO.dirId;
		var nums=skillVO.nums;
		var radius=skillVO.radius;
		var delayTime=skillVO.delayTime;
		var i=0;
		var flag=1;
		var rot=NaN;
		var selfRot=NaN;
		selfRot=SkillBase.rotArr[dirId];
		var temp=nums%2;
		var even=nums-temp;
		var avgRot=360/(even);
		if(temp==1){
			SkillBase.createSkillInMap(skillVO,skillUseRes,x,y,actKey,-1,selfRot);
		};
		var offX=0;
		var offY=0;
		var perObj=SkillBase.dirPerDic[(dirId%4)];
		var perArr=perObj[even];
		if(dirId > 3)flag=-1;
		nums=(even)>=8?8:(even);
		var len=nums>>1;
		for(i=0;i < len;i++){
			offX=radius *perArr[i][0] *flag;
			offY=radius *perArr[i][1] *flag;
			SkillBase.createSkillInMap(skillVO,skillUseRes,x+offX,y+offY,actKey,-1,selfRot,delayTime*(i+1));
			offX=radius *perArr[nums-i-1][0] *flag;
			offY=radius *perArr[nums-i-1][1] *flag;
			SkillBase.createSkillInMap(skillVO,skillUseRes,x+offX,y+offY,actKey,-1,selfRot,delayTime*(i+1));
		}
	}

