//class com.xq.rpg.sound.SoundMgr
var SoundMgr=(function(){
	function SoundMgr(){
		this.soundTable=null;
		this._cache=null;
		this._isPlaying=null;
		/**背景音*/
		this.bgChanel=null;
		/**伙伴音*/
		this.manChanl=null;
		/**待机音效*/
		this.waitChanl=null;
		this.npcSoundUrl="";
		this.npcPlayCd=0;
		this.sounds=[];
		//怪物声音集合
		this.sinx=0;
		//播放序号
		this.mguid=null;
		this.curTime=NaN;
		this.bossSoundUrl=null;
		this.uiSoundUrl=null;
		this.uiPlayCD=0;
		/**面板播放channel*/
		this.uiViewSoundChannel=null;
		/**技能播放channel*/
		this.skillSoundChannel=null;
		this.lastSkillST=0;
		this.preSkillUrl=null;
		/**当前背景音乐*/
		this.curBgMusicUrl=null;
		this._cache=new SurvivalCache(8 ,75*1000,Handler.create(this,this.disposeSound ,null ,false));
		this._isPlaying={};
	}

	__class(SoundMgr,'com.xq.rpg.sound.SoundMgr');
	var __proto=SoundMgr.prototype;
	__proto.disposeSound=function(vo){
		var ur=URL.formatURL(vo.url);
		SoundManager.destroySound(ur);
		vo.url=null;
		Pool.recover("soundvo",vo);
	}

	/**播放打开NPC面板音效*/
	__proto.playNpcSound=function(url){
		if(!url)
			return;
		var sound=PathDefine.getSoundUrl(url);
		if(this.npcSoundUrl==sound && Laya.timer.currTimer<this.npcPlayCd){
			return;
		}
		else{
			SoundManager.stopSound(this.npcSoundUrl);
			this.playComplete(this.npcSoundUrl);
		}
		this._isPlaying[sound]=this.getSoundVo(sound);
		SoundManager.playSound(sound,1,Handler.create(this,this.playComplete,[sound]));
		this.npcPlayCd=Laya.timer.currTimer+10000;
		this.npcSoundUrl=sound;
	}

	__proto.getSoundVo=function(url){
		var vo=this._isPlaying[url];
		if(!vo){
			vo=this._cache.getCache(url);
			if(!vo){
				vo=new SoundVO();
				Pool.getItemByClass("soundvo",SoundVO);
				vo.url=url;
			}
		}
		return vo;
	}

	__proto.playComplete=function(url){
		var vo=this._isPlaying[url];
		if(vo){
			delete this._isPlaying[url];
			this._cache.add(url,vo,1);
		}
	}

	/**播放BOSS被攻击时说的话*/
	__proto.playBossSound=function(vo){
		var time=0;
		if(vo.monsterId==this.mguid){
			if(this.sinx>=this.sounds.length){
				this.sinx=0;
			}
			time=Laya.timer.currTimer;
			if(time>this.curTime){
				var sound=PathDefine.getSoundUrl(this.sounds[this.sinx]);
				if(this.bossSoundUrl){
					SoundManager.stopSound(this.bossSoundUrl);
					this.playComplete(this.bossSoundUrl);
				}
				this._isPlaying[sound]=this.getSoundVo(sound);
				SoundManager.playSound(sound,1,Handler.create(this,this.playComplete,[sound]));
				this.bossSoundUrl=sound;
				this.curTime=Laya.timer.currTimer+30000;
			}
			this.sinx++;
		}
		else{
			this.sounds=vo.hitsound.split(";");
			this.mguid=vo.monsterId;
			this.sinx=0;
			this.curTime=0;
			this.playBossSound(vo);
		}
	}

	/**播放打开UI的特效*/
	__proto.playUISound=function(name,tab){
		if(!this.soundTable)
			this.soundTable=CfgManager.getTableCfg("UiControl");
		var data=this.soundTable.getCfgMsgByTwoKey("main",name,"tab",tab);
		if(data && data.sound){
			var sound=PathDefine.getSoundUrl(data.sound)
			if(this.uiSoundUrl==sound && Laya.timer.currTimer<this.uiPlayCD){
				return;
			}
			else{
				SoundManager.stopSound(this.uiSoundUrl);
				this.playComplete(this.uiSoundUrl);
			}
			this._isPlaying[sound]=this.getSoundVo(sound);
			SoundManager.playSound(sound,1,Handler.create(this,this.playComplete,[sound]));
			this.uiPlayCD=Laya.timer.currTimer+5000;
			this.uiSoundUrl=sound;
		}
	}

	__proto.playUiViewSoundChannel=function(view){
		var name=ClassTool.getClassName(view);
		if(!this.soundTable)
			this.soundTable=CfgManager.getTableCfg("UiControl");
		var soundArr=this.soundTable.getAllItemByFiled("main",name);
		if(soundArr && soundArr.length>0){
			var soundUrl=soundArr[0].sound;
			if(soundUrl){
				soundUrl=PathDefine.getSoundUrl(soundUrl);
			}
			if(this.uiViewSoundChannel)
				this.uiViewSoundChannel.stop();
			this._isPlaying[soundUrl]=this.getSoundVo(soundUrl);
			this.uiViewSoundChannel=SoundManager.playSound(soundUrl,1,Handler.create(this,this.playComplete,[soundUrl]));
		}
	}

	/**播放技能特效*/
	__proto.playSkillSound=function(url,loopTimes){
		(loopTimes===void 0)&& (loopTimes=1);
		var soundUrl=PathDefine.getSoundUrl(url);
		this.preSkillUrl=soundUrl;
		SoundManager.playSound(soundUrl,loopTimes,Handler.create(this,this.playComplete,[soundUrl]));
	}

	// }
	__proto.resumeBgMusic=function(){
		this.playBgMusic(this.curBgMusicUrl);
	}

	__proto.playBgMusic=function(url){
		if(!url){
			return;
		}
		url=PathDefine.getSoundUrl(url);
		if (url!="" && this.curBgMusicUrl!=url){
			var tSound=Laya.loader.getRes(url);
			if(tSound){
				if(tSound["loaded"]){
					this.changeMusic(url);
				}
				else{
					this.loadSound(url);
				}
			}
			else{
				this.loadSound(url);
			}
		}
	}

	__proto.loadSound=function(url){
		Laya.timer.once(500,this,this.ls,[url]);
	}

	__proto.ls=function(url){
		var soundClass=Browser.onMiniGame ? SoundManager._soundClass :SoundManager._musicClass;
		if (soundClass){
			var tSound=new soundClass();
			tSound.on("complete" ,this,this.onLoaded,[url]);
			tSound.load(url);
			Loader.cacheRes(url,tSound);
		}
		else{
			this.changeMusic(url);
		}
	}

	__proto.onLoaded=function(url){
		this.changeMusic(url);
	}

	__proto.changeMusic=function(url){
		if (this.curBgMusicUrl){
			SoundManager.destroySound(this.curBgMusicUrl);
		}
		this.curBgMusicUrl=url;
		this.bgChanel=SoundManager.playMusic(this.curBgMusicUrl);
	}

	/**
	*独白的时候，减弱场景音
	*@param bo 是否减弱
	**/
	__proto.changeBgSound=function(bo){
		if(!this.bgChanel)
			return;
		Laya.timer.clear(this,this.resBgSoundVal);
		Laya.timer.clear(this,this.redBgSoundVal);
		if(bo){
			this.redBgSoundVal();
		}
		else{
			this.resBgSoundVal();
		}
	}

	/**恢复到场景音*/
	__proto.resBgSoundVal=function(){
		if(this.bgChanel && this.bgChanel.volume < 1){
			var temp=this.bgChanel.volume+0.1;
			this.bgChanel.volume=temp > 1? 1 :temp;
			Laya.timer.once(200,this,this.resBgSoundVal);
		}
	}

	/**降低场景音效*/
	__proto.redBgSoundVal=function(){
		if(this.bgChanel && this.bgChanel.volume > 0.3){
			this.bgChanel.volume=this.bgChanel.volume-0.1;
			Laya.timer.once(200,this,this.redBgSoundVal);
		}
	}

	/**
	*播放伙伴音效
	**/
	__proto.playManSound=function(name){
		if(this.manChanl){
			this.manChanl.stop();
		}
		this.manChanl=SoundManager.playSound(PathDefine.getSoundUrl(name),1,Handler.create(this,this.asideCom));
		this.changeBgSound(true);
	}

	/**旁白读完,恢复正常场景音量*/
	__proto.asideCom=function(_calBack){
		this.changeBgSound(false);
		if(_calBack)
			_calBack.run();
	}

	/**
	*播放场景待机音效
	**/
	__proto.playScenSound=function(name,soundCom){
		return;
		if(this.waitChanl){
			this.waitChanl.stop();
		}
		this.waitChanl=SoundManager.playSound(PathDefine.getSoundUrl(name),1,Handler.create(this,this.asideCom,[soundCom]));
		this.changeBgSound(true);
	}

	/**
	*暂停/恢复播放 场景待机音
	*@param bo 是否暂停
	**/
	__proto.changSceSound=function(bo){
		if(this.waitChanl){
			if(bo){
				this.waitChanl.stop()
			}
			else{
				this.waitChanl.play();
			}
		}
	}

	SoundMgr.ins=function(){
		return SoundMgr._ins=SoundMgr._ins||new SoundMgr();
	}

	SoundMgr._ins=null;
	return SoundMgr;
})()


