var SceneWarSoul=(function(){
	function SceneWarSoul(){
		this.master=null;
		this.soulAni=null;
		this.url=null;
	}

	__class(SceneWarSoul,'com.xq.rpg.unit.SceneWarSoul');
	var __proto=SceneWarSoul.prototype;
	/**装备战符*/
	__proto.equip=function(_url,pl){
		this.master=pl;
		this.url=_url;
		if(!this.soulAni){
			this.soulAni=new SceneAni();
		}
	}

	/**播放被动效果,不是技能，只存在一次*/
	__proto.playBeiDong=function(_url,pl){
		if(!this.soulAni){
			this.soulAni=new SceneAni();
		}
		this.callHero(_url,pl);
	}

	/**
	*召唤战魂
	*@param turl 是否是存在一次
	**/
	__proto.callHero=function(turl,pl){
		(turl===void 0)&& (turl="");
		if(this.soulAni.isDisposed){
			this.soulAni.resetInit();
		}
		if(pl){
			pl.upLayer.addChild(this.soulAni);
			}else if(this.master){
			this.master.upLayer.addChild(this.soulAni);
		}
		this.soulAni.loopTimes=1;
		if(turl){
			this.soulAni.setRes(turl);
		}
		else if(this.url){
			this.soulAni.setRes(this.url);
		}
	}

	__proto.dispose=function(){
		if(this.soulAni){
			this.soulAni.dispose();
			this.soulAni=null
		}
	}

	return SceneWarSoul;
})()


