	__proto.checkOtherCondition=function(type){
		switch(type){
			case 0:
				if(this.settingMgr.isShieldClanPlayer)
					this.shieldUnit(2,true);
				if(this.settingMgr.isShieldOtherClanPlayer)
					this.shieldUnit(1,true);
				break ;
			case 1:
				if(this.settingMgr.isShieldClanPlayer)
					this.shieldUnit(2,true);
				if(this.settingMgr.isShieldOtherPlayer)
					this.shieldUnit(0,true);
				break ;
			case 2:
				if(this.settingMgr.isShieldOtherClanPlayer)
					this.shieldUnit(1,true);
				if(this.settingMgr.isShieldOtherPlayer)
					this.shieldUnit(0,true);
				break ;
			}
	}

	__proto.sheildName=function(unit,isSheild){
		if(unit.unitNameBox){
			unit.unitNameBox.visible=isSheild
		}
		if(unit.unitCpName){
			unit.unitCpName.visible=isSheild;
		}
		if(unit.unitGuild)
			unit.unitGuild.visible=isSheild;
	}

	/**屏蔽血条名字加影子*/
	__proto.sheildOther=function(unit,isSheild){
		if(unit.unitNameBox){
			unit.unitNameBox.visible=isSheild
		}
		if(unit.unitCpName){
			unit.unitCpName.visible=isSheild;
		}
		if(unit.unitGuild)
			unit.unitGuild.visible=isSheild;
		if(unit.blood){
			if(unit.bossType==0)
				unit.blood.visible=false;
			else
			unit.blood.visible=isSheild;
		}
		if(unit.title)
			unit.title.visible=isSheild;
	}

	/**获取当前在显示区域的怪物数量*/
	__proto.getShowUnitNum=function(){
		var monsterArr=this._monsterList.values;
		var len=monsterArr.length;
		var rect=this.scene.mapCamera.viewPort;
		var num=0;
		if(rect){
			for(var i=0;i< len;i++){
				var unit=monsterArr[i];
				if(this.unitShowRect.contains(unit.x,unit.y)){
					num++;
				}
			}
			var robot;
			for(var $each_robot in this._robotList){
				robot=this._robotList[$each_robot];
				if((robot instanceof com.xq.rpg.unit.Monster )){
					if(this.unitShowRect.contains(robot.x,robot.y)){
						num++;
					}
				}
			}
		}
		return num;
	}

	/**根据显示区域来显示或者隐藏掉对应的单位*/
	__proto.updateUnitShow=function(rect,isUpdate){
		if(this.mainPlayer && (this.mainPlayer.isJuQing || this.mainPlayer.isDouYin))
			return;
		if(this.settingMgr.isShieldMonster)
			return;
		if(this.showTime > Laya.timer.currTimer)
			return;
		this.showTime=Laya.timer.currTimer+300;
		this.unitShowRect.setTo(rect.x-200,rect.y-200,rect.width+400,rect.height+400);
		var unitArr=this._unitList.values;
		var len=unitArr.length;
		var screenAry=[[],[]];
		for(var i=0;i< len;i++){
			var unit=unitArr[i];
			if(!isUpdate){
				if(!unit.visible)
					unit.visible=true;
				continue ;
			}
			if(this.unitShowRect.contains(unit.x,unit.y)){
				unit.visible=true;
				if((unit instanceof com.xq.rpg.unit.SubPlayer )){
					screenAry[1].push(unit);
				}
				else{
					screenAry[0].push(unit);
				}
			}
			else{
				unit.visible=false;
			}
		}
		this.sortPlayerList(screenAry);
	}

	/**
	*玩家排序，最多只显示
	**/
	__proto.sortPlayerList=function(unitAry){
		if(this.mainPlayer==null||!this.mainPlayer.isInZhuCheng){
			return;
		};
		var maxPlayerNum=5;
		var plAry=unitAry[0];
		var subAry=unitAry[1];
		var len=plAry.length;
		if(len < 6){
			return;
		};
		var tempAry=[];
		for (var i=0;i < len;i++){
			var pl=plAry[i];
			if(pl && pl.vo){
				tempAry.push({player:pl,fight:(pl.vo).fightValue});
			}
		}
		tempAry=tempAry.sort(function(a,b){
			return b.fight-a.fight
		});
		var IDAry=[];
		for (i=0;i < len;i++){
			var temp=tempAry[i]
			if(temp){
				pl=temp.player;
				if(pl){
					if(i < maxPlayerNum || ((pl instanceof com.xq.rpg.unit.MainPlayer ))){
						IDAry.push((pl.vo).guid);
						pl.visible=true;
					}
					else{
						pl.visible=false;
					}
				}
			}
		}
		len=subAry.length;
		for (i=0;i < len;i++){
			var subPl=subAry[i];
			var vo=subPl.vo;
			if(IDAry.indexOf(vo.parentPlayerID)!=-1){
				subPl.visible=true;
			}
			else{
				subPl.visible=false;
			}
		}
	}

	/**创建一个墓碑 贼6了
	*,x,y,格子坐标哦~
	*time
	*tip*/
	__proto.createTomb=function(id,x,y,time,tip){
		(tip===void 0)&& (tip="");
		time=time-ServerTimeAction.ins().serverTimer;
		if(time>0){
			var arr=SceneContainer.GridToGlobal(x,y);
			var tomb=new Tomb();
			tomb.create(PathDefine.OTHER_UNIT+"tomb"+".amt",arr[0],arr[1],time,tip);
			this.tombDic[id]=tomb;
			this._unitList.set(id,tomb);
			this.scene.bottomLayer.addChildAt(tomb,0);
		}
	}

	__proto.destoryAllTomb=function(){
		for(var id in this.tombDic){
			var tomb=this.tombDic[id];
			if(!tomb.isDispose)
				tomb.dispose();
			delete this.tombDic[id];
			this._unitList.remove(tomb.guid);
		}
	}

	__proto.creatTransferDoorSmall=function(x,y,handler){
		var pos=SceneContainer.GridToGlobal(x,y);
		var transfer=TransferDoorSmall.getItem();
		transfer.bindVO(pos,handler);
		this._transferDoorSmallPool.push(transfer);
		this.scene.bottomLayer.addChildAt(transfer,0);
		if(!this._ifStartListener&&this._transferDoorSmallPool.length>0){
			this._ifStartListener=true;
			EventCenter.instance.on("MAIN_PLAYER_MOVE_END",this,this.onPlayerMoveEnd);
		}
	}

	__proto.clearTranserDoorSmall=function(){
		var arr=this._transferDoorSmallPool;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var transfer=arr[i];
			transfer.dispose();
		}
		this._transferDoorSmallPool.length=0;
		this._ifStartListener=false;
		EventCenter.instance.off("MAIN_PLAYER_MOVE_END",this,this.onPlayerMoveEnd);
	}

	__proto.onPlayerMoveEnd=function(){
		var player=Model.game.mPlayer;
		var arr=this._transferDoorSmallPool;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var transfer=arr[i];
			if(transfer.hitTestPoint(player.x,player.y)){
				transfer.doHandler();
				break ;
			}
		}
	}

	/**预加载一个怪物的资源*/
	__proto.preLoadMonsterRes=function(monsterId){
		Laya.timer.once(1000,this,this.laterPreLoadMonsterRes,[monsterId]);
	}

	__proto.laterPreLoadMonsterRes=function(monsterId){
		if(monsterId){
			var monsterVO=new MonsterVO();
			monsterVO.monsterId=monsterId;
			monsterVO.guid=--this.flagId;
			monsterVO.isJuqing=true;
			var monster=this.createMonster(monsterVO);
			monster.doAction(0,0,true);
			monster.doAction(5,0,true);
			monster.doAction(1,0,true);
			monster.doAction(2,0,true);
			monster.dispose();
		}
	}

