/**
*Code码转换工具
*2019-10-25
*@auther gfr
*/
//class com.xq.util.CodeMgr
var CodeMgr=(function(){
	function CodeMgr(){
		this.config=null;
		this.broadCfg=null;
		this.onBagFullHandler=null;
		this.regArr=null;
		this.config=CfgManager.getTableCfg("Code");
		this.broadCfg=CfgManager.getTableCfg("broadcast");
		this.regArr=[];
		var r=/[\{][0][\}]/g;
		this.regArr.push(r);
		r=/[\{][1][\}]/g;
		this.regArr.push(r);
		r=/[\{][2][\}]/g;
		this.regArr.push(r);
		r=/[\{][3][\}]/g;
		this.regArr.push(r);
		r=/[\{][4][\}]/g;
		this.regArr.push(r);
		r=/[\{][5][\}]/g;
		this.regArr.push(r);
		r=/[\{][6][\}]/g;
		this.regArr.push(r);
		r=/[\{][7][\}]/g;
		this.regArr.push(r);
		r=/[\{][8][\}]/g;
		this.regArr.push(r);
		r=/[\{][9][\}]/g;
		this.regArr.push(r);
	}

	__class(CodeMgr,'com.xq.util.CodeMgr');
	var __proto=CodeMgr.prototype;
	/**获取code码所对应的字符串
	*支持0-9个参数，再多就先不支持了反正也用不了那么多
	*@param code :如果是字符串，则其表示 code表中ID ；如果字符串是数组，则 code[0]表示code表中的ID，code[1...N]表示要替换的参数*/
	__proto.getStringByCode=function(code,isCode){
		(isCode===void 0)&& (isCode=true);
		if(code==1006){
			if(this.onBagFullHandler){
				this.onBagFullHandler.run();
			}
			return null;
		}
		if(!code && code!=0)
			return "";
		if((code instanceof Array)){
			var id=code[0]+"";
			if(id==""){
				return "";
			};
			var args=code;
		}
		else{
			id=code+"";
		};
		var str;
		if(isCode)
			var data=this.config.getItemByField("id",id);
		else
		data=this.broadCfg.getItemByField("id",id);
		if(!data){
			str=id;
			return str+"";
		}
		else{
			str=data.content.concat();
		}
		if(str==null)
			str=id;
		if(args && args.length>1){
			var len=args.length;
			for(var i=1;i<len;i++){
				var reg=this.regArr[i-1];
				str=str.replace(reg,args[i]);
			}
		}
		return str;
	}

	/**替换字符串中的{0}格式的字符*/
	__proto.replaceStr=function(str,rep){
		var len=rep.length;
		for(var i=0;i<len;i++){
			var reg=this.regArr[i];
			str=str.replace(reg,rep[i]);
		}
		return str;
	}

	__getset(1,CodeMgr,'ins',function(){
		return CodeMgr._ins=CodeMgr._ins|| new CodeMgr();
	});

	CodeMgr._ins=null;
	return CodeMgr;
})()


