	CommonUtil.refreshSkin=function(v){
		var o=CommonUtil.skinDic[v];
		if(!o){
			o={};
			o["skin"]=[];
			o["labelSkin"]=[];
			o["list"]=[];
			CommonUtil.searchSkinElement(v,o["skin"],o["labelSkin"],o["list"]);
		}
		Laya.timer.frameOnce(1,CommonUtil,com.xq.util.CommonUtil.laterRfresh,[o],false);
	}

	CommonUtil.laterRfresh=function(o){
		var skins=o.skin;
		var skinItem;
		for(var $each_skinItem in skins){
			skinItem=skins[$each_skinItem];
			var pre=skinItem.skin;
			if(skinItem.parent && pre){
				skinItem.skin="";
				skinItem.skin=pre;
			}
		};
		var labelSkins=o.labelSkin;
		var labelSkinItem;
		for(var $each_labelSkinItem in labelSkins){
			labelSkinItem=labelSkins[$each_labelSkinItem];
			var pre1=labelSkinItem.labelSkin;
			if(pre1){
				labelSkinItem.labelSkin="";
				labelSkinItem.labelSkin=pre1;
			}
		};
		var lists=o.list;
		var listItem;
		for(var $each_listItem in lists){
			listItem=lists[$each_listItem];
			var cells=listItem.cells;
			if(cells){
				var len=cells.length;
				for (var i=0;i < len;i++){
					CommonUtil.refreshList(cells[i]);
				}
			}
		}
	}

	CommonUtil.refreshList=function(v){
		var clidrens=v._childs;
		var len=clidrens.length;
		for (var i=0;i < len;i++){
			var node=clidrens[i];
			CommonUtil.refreshSkin(node);
		}
		if(v.hasOwnProperty("skin")){
			var pre=v["skin"];
			if(pre){
				v["skin"]="";
				v["skin"]=pre;
			}
		}
	}

	CommonUtil.searchSkinElement=function(comp,skinItems,labelSkinItems,lists){
		var clidrens=comp._childs;
		var len=clidrens.length;
		for (var i=0;i < len;i++){
			var node=clidrens[i];
			CommonUtil.searchSkinElement(node,skinItems ,labelSkinItems ,lists);
		}
		if(comp.hasOwnProperty("labelSkin")){
			labelSkinItems.push(comp);
		}
		if(comp.hasOwnProperty("skin")){
			skinItems.push(comp);
		}
		else if((comp instanceof laya.ui.List )){
			lists.push(comp);
		}
	}

