	CommonUtil.mergeCalcAdd=function(attrList,nextAttrList,isFull,allAttrStr){
		(isFull===void 0)&& (isFull=false);
		if(nextAttrList==null || nextAttrList.length==0){
			nextAttrList=attrList;
		}
		for (var i=0;i < attrList.length;i++){
			var data=attrList[i];
			data.addVal=nextAttrList[i].attrVal-data.attrVal;
			if(isFull){
				data.isFull=true;
			}
			if(allAttrStr){
				data.allAttrStr=allAttrStr;
			}
		}
	}

