	CommonUtil.getAttrGap=function(atrAry1,atrAry2,add){
		(add===void 0)&& (add=false);
		var ary=[];
		var isZero=false;
		var len=atrAry2.length;
		if(len==0){
			len=atrAry1.length;
			isZero=true;
		}
		for (var i=0;i < len;i++){
			if(!isZero){
				var atr2=atrAry2[i]
				if(!atr2){
					continue ;
				};
				var atr1=null;
				var len1=atrAry1.length;
				for (var j=0;j < len1;j++){
					var tempMsg=atrAry1[j];
					if(atr2.attrId==tempMsg.attrId){
						atr1=tempMsg;
					}
				}
			}
			else{
				atr1=atrAry1[i];
			}
			if(!atr1){
				atr1=new AttributeMsg();
				atr1.attrId=atr2.attrId;
				atr1.attrValue=0;
			};
			var obj={};
			if(atr1){
				obj.attrName=com.xq.util.CommonUtil.getAtrName(atr1.attrId);
				obj.attrVal=atr1.attrValue;
				obj.sortFlag=AttrEnum.getFlag(atr1.attrId);
				if(atr2){
					if(atr1)
						obj.addVal=Math.abs(atr1.attrValue-atr2.attrValue);
					else
					obj.addVal=atr2.attrValue
				}
				else
				obj.addVal=0;
			}
			else if(atr2){
				obj.attrName=com.xq.util.CommonUtil.getAtrName(atr2.attrId);
				obj.attrVal=0;
				obj.addVal=atr2.attrValue;
				obj.sortFlag=AttrEnum.getFlag(atr2.attrId);
			}
			ary.push(obj);
		};
		var sortFun=function (a,b){
			return a.sortFlag-b.sortFlag
		}
		ary.sort(sortFun);
		if(add){
			ary.splice(1,0,{});
		}
		return ary;
	}

