	CommonUtil.rewardMerge=function(reward_one,reward_two){
		if(reward_one.length==0){
			return reward_two;
		}
		if(reward_two.length==0){
			return reward_one;
		};
		var len1=reward_one.length;
		if(reward_one[len1-1]==""){
			reward_one.pop();
		};
		var len2=reward_two.length;
		if(reward_two[len2-1]==""){
			reward_two.pop();
		};
		var newArr=[];
		if(len1==0){
			newArr=reward_two
			return newArr;
		};
		var arr=reward_one.concat(reward_two);
		var len=arr.length;
		var o={};
		for(var i=0;i< len;i++){
			var oldArr=arr[i].split(":");
			var id=oldArr[0];
			var num=parseInt(oldArr[1]);
			var oldNum=o[id];
			if(!oldNum){
				oldNum=0;
			}
			o[id]=oldNum+num;
		}
		for(var id in o){
			var num=o[id];
			newArr.push(id+":"+num+":1");
		}
		return newArr;
	}

