	CommonUtil.getChineseByNum=function(num){
		var numArr=num.toString().split("");
		var ary=[];
		var len=numArr.length
		for(var i=len-1;i>=0;i--){
			ary.push(numArr[i]);
		};
		var zero="";
		var newary="";
		var i4=-1;
		for (var j=0;j < ary.length;j++){
			if (j % 4==0){
				i4++;
				newary=CommonUtil.ary2[i4]+newary;
				zero="";
			}
			if (ary[j]=='0'){
				switch (j % 4){
					case 0:
						break ;
					case 1:
					case 2:
					case 3:
						if (ary[j-1] !='0'){
							zero="零"
						}
						break ;
					}
				newary=zero+newary;
				zero='';
			}
			else {
				newary=CommonUtil.ary0[parseInt(ary[j])]+CommonUtil.ary1[j % 4]+newary;
			}
		}
		while(newary.indexOf("零")==0||CommonUtil.isUnit(newary)){
			newary=newary.substr(1);
		}
		return newary;
	}

