var MedalListDataUtil=(function(){
	function MedalListDataUtil(){
		this._renderArr=null;
	}

	__class(MedalListDataUtil,'com.xq.util.MedalListDataUtil');
	var __proto=MedalListDataUtil.prototype;
	__proto.updateData=function(msg,ifReverse){
		this._renderArr=[];
		if((msg instanceof com.xq.proto.gen.chat.ChatAnyCSC )|| (msg instanceof Array)){
			this.setTeQuanImg(msg,ifReverse);
			}else if((msg instanceof com.xq.proto.gen.chat.WatchOtherInfoSC )){
			this.setOtherTopBtn(msg);
		}
		return this._renderArr;
	}

	__proto.changeArray=function(arr){
		var arr2=[]
		parseInt(arr[0])?arr2.push("1"):arr2.push("0");
		parseInt(arr[1])?arr2.push("1"):arr2.push("0");
		parseInt(arr[2])?arr2.push("1"):arr2.push("0");
		parseInt(arr[3])?arr2.push("1"):arr2.push("0");
		parseInt(arr[4])?arr2.push("1"):arr2.push("0");
		parseInt(arr[17])?arr2.push("1"):arr2.push("0");
		return arr2;
	}

	__proto.setMedaDataVo=function(msg){
		var vo=new MedaDataVo();
		vo.type=msg.type;
		vo.ifShowFrame=msg.ifShowFrame;
		this._renderArr.push(vo);
	}

	__proto.setTeQuanImg=function(msg,ifReverse){
		var teQuanArr=(msg instanceof Array)?msg:msg.params2.split(";");
		var vo={};
		if(teQuanArr[0]=="1"){
			vo.type="yueka";
			this.setMedaDataVo(vo);
		}
		if(teQuanArr[1]=="1"){
			vo.type="zhizunka";
			this.setMedaDataVo(vo);
		}
		if(teQuanArr[2]=="1"){
			vo.type="caishen";
			this.setMedaDataVo(vo);
		}
		if(teQuanArr[3]=="1"){
			vo.type="hufu";
			this.setMedaDataVo(vo);
		}
		if(teQuanArr[4]=="1"){
			vo.type="qilinbi";
			this.setMedaDataVo(vo);
		}
		if(teQuanArr[5]=="1"){
			vo.type="zhujueguanghuan";
			this.setMedaDataVo(vo);
		}
		if(ifReverse){
			this._renderArr.reverse();
		}
	}

	__proto.setOtherTopBtn=function(msg){
		var vo={};
		vo.ifShowFrame=true;
		if(msg.zhanwen1||msg.zhanwen2){
			vo.type="fuwen";
			this.setMedaDataVo(vo);
		}
		if(msg.qiLingBiPower>0){
			vo.type="qilinbi";
			this.setMedaDataVo(vo);
		}
		if(msg.hufu.length>0){
			vo.type="hufu";
			this.setMedaDataVo(vo);
		}
	}

	MedalListDataUtil.ins=function(){
		return MedalListDataUtil._ins=MedalListDataUtil._ins||new MedalListDataUtil();
	}

	MedalListDataUtil._ins=null;
	return MedalListDataUtil;
})()


