/**
*根据任务空闲加载的管理类
*2019-10-10
*@auther gfr
*/
//class com.xq.util.PreLoadManager
var PreLoadManager=(function(){
	function PreLoadManager(){
		/**预加载字典*/
		this.preDic=null;
		/**预加载的数组*/
		this.preArr=null;
		/**预加载数组的索引*/
		this.index=0;
		/**数组长度*/
		this.len=0;
		/**当前正在加载的资源索引*/
		this.curIndex=0;
		/**正在加载中*/
		this.isLoad=false;
		/**任务Num*/
		this.taskNum=0;
		PreloadUtils.preloadMgr=this;
		this.preDic=Laya.loader.getRes("pre.json");
		Cmd.regCmd("log",Handler.create(this,this.copyRecord,null,false),Lang.str(3265));
	}

	__class(PreLoadManager,'com.xq.util.PreLoadManager');
	var __proto=PreLoadManager.prototype;
	Laya.imps(__proto,{"laya.xq.loader.IPreLoadManager":true})
	/**开始预加载*/
	__proto.starPre=function(taskId){
		if(!Mgr.task.curTask)
			return;
		if(WXSDK.isInWX){
			return;
		}
		if(this.preDic){
			this.clearPreDic();
			PreLoadManager.curTaskId=taskId;
			Laya.timer.callLater(this,this.start);
		}
	}

	__proto.start=function(){
		this.taskNum=Mgr.task.curTask.num;
		if(!PreLoadManager.isLog && !this.isLoad){
			console.log(Lang.str(3266)+PreLoadManager.curTaskId+Lang.str(3267));
			this.preArr=this.preDic[PreLoadManager.curTaskId];
			if(this.preArr){
				this.isLoad=true;
				this.len=this.preArr.length;
				this.index=0;
				this.preToLoad();
			}
			else{
				this.next();
			}
		}
	}

	/**清理掉数据组为空的*/
	__proto.clearPreDic=function(){
		for (var key in this.preDic){
			var ary=this.preDic[key];
			if(!ary || ary.length <=0){
				delete this.preDic[key];
			}
		}
	}

	/**下一个预加载*/
	__proto.next=function(){
		this.taskNum+=1;
		var id=Mgr.task.getTaskId(this.taskNum.toString());
		if(!id){
			console.log(Lang.str(3268)+this.taskNum);
			return
		}
		this.preArr=this.preDic[id];
		if(this.preArr){
			this.isLoad=true;
			this.len=this.preArr.length;
			this.index=0;
			this.preToLoad();
		}
		else{
			Laya.timer.callLater(this,this.next);
		}
	}

	__proto.preToLoad=function(){
		if(this.index < this.len){
			if(!this.preArr)
				return;
			var urls=this.preArr[this.index++];
			urls=URL.formatURL(urls);
			CacheLoader.instance().load(urls,"arraybuffer",Handler.create(this,this.onLoadCom));
			return;
		}
		else{
			this.isLoad=false;
			this.next();
		}
	}

	__proto.onLoadCom=function(data){
		this.preToLoad();
	}

	/**复制记录下来的预加载资源数据*/
	__proto.copyRecord=function(){
		if(PreLoadManager.isLog){
			var str=JSON.stringify(PreLoadManager.logObj);
			copyClip(str);
		}
	}

	__proto.recordPreLoad=function(url){
		PreLoadManager.record(url);
	}

	PreLoadManager.changeId=function(id){
		if(id !=PreLoadManager.curTaskId)
			var flag=true;
		else
		flag=false;
		PreLoadManager.curTaskId=id;
		if(PreLoadManager.isLog){
			if(!PreLoadManager.logObj[PreLoadManager.curTaskId]){
				PreLoadManager.logObj[PreLoadManager.curTaskId]=[];
			}
		}
	}

	PreLoadManager.record=function(str){
		if(!PreLoadManager.isLog)
			return;
		if(PreLoadManager.logObj[PreLoadManager.curTaskId]){
			str=str.replace(PreLoadManager.reg1,"res2/");
			if(str.indexOf("E:")!=-1){
				console.log("============pre========"+str);
			}
			str=str.replace(PreLoadManager.reg2,"");
			str=str.replace(PreLoadManager.reg3,"");
			if(PreLoadManager.logDic[str] !=1){
				PreLoadManager.logDic[str]=1;
				PreLoadManager.logObj[PreLoadManager.curTaskId].push(str);
			}
		}
	}

	PreLoadManager.logObj={};
	PreLoadManager.logDic={};
	PreLoadManager.curTaskId="";
	PreLoadManager.reg1="http://192.168.10.170/res2/";
	PreLoadManager.reg2="file:///E:/work/xiakemeng/gitbt/client/bin/h5/";
	PreLoadManager.reg3="http://192.168.10.170/gamebt/";
	PreLoadManager.isLog=false;
	__static(PreLoadManager,
	['ins',function(){return this.ins=new PreLoadManager();}
	]);
	return PreLoadManager;
})()


