//class com.xq.util.red.RedDispatch
var RedDispatch=(function(){
	function RedDispatch(){
		this.funcDic=null;
		this._disp=null;
		this.funcDic=RedPointMgr.ins().dic;
		this._disp=EventCenter.instance;
	}

	__class(RedDispatch,'com.xq.util.red.RedDispatch');
	var __proto=RedDispatch.prototype;
	__proto.dispatchEvent=function(eventType,funId){
		var redVo=this.funcDic[funId];
		var flag1=redVo.hasCornor;
		var flag=this.checkGroupRed(redVo);
		redVo.hasCornor=flag;
		if(flag !=flag1){
			this.checkUptoRoot(redVo);
		}
		if(eventType)
			this._disp.event(eventType);
	}

	/**
	*递增向上询问
	*/
	__proto.checkUptoRoot=function(redVo){
		if(redVo.parentId){
			var flag=redVo.parentVo.hasCornor;
			if(redVo.hasCornor){
				redVo.parentVo.hasCornor=true;
			}
			else{
				redVo.parentVo.hasCornor=this.checkGroupRed(redVo.parentVo);
			}
			if(flag !=redVo.parentVo.hasCornor){
				this.checkUptoRoot(redVo.parentVo);
			}
			if(redVo.redEvent){
				this._disp.event(redVo.redEvent,[redVo.funcId,redVo.hasCornor]);
			}
		}
		else{
			if(redVo.isMainFunID){
				this._disp.event("MAIN_VIEW_CORNOR",[redVo.funcId,redVo.hasCornor]);
			}
		}
	}

	/**遍历所有节点*/
	__proto.checkGroupRed=function(redVo){
		var o=redVo.redTypeObj;
		var tpOb;
		for(var $each_tpOb in o){
			tpOb=o[$each_tpOb];
			if(tpOb)
				return true;
		};
		var childO=redVo.elementVoObj;
		var tpRed;
		for(var $each_tpRed in childO){
			tpRed=childO[$each_tpRed];
			if(tpRed.hasCornor)
				return true;
		}
		return false;
	}

	return RedDispatch;
})()


