//class com.xq.util.red.RedPointMgr
var RedPointMgr=(function(){
	function RedPointMgr(){
		this._dic=null;
		this._dic={};
	}

	__class(RedPointMgr,'com.xq.util.red.RedPointMgr');
	var __proto=RedPointMgr.prototype;
	/**
	*注册主界面与模块之间的联系<br/>
	*mainviewId:主界面的功能id<br/>
	*funId：子模块的功能id<br/>
	*isMainFunID：parFunId是否是主界面一级的<br/>
	*例如：<br>
	*FunctionDefine.XIANJI 在主界面已经注册(MainViewMgr)了对应按钮<br>
	*此按钮点开的主界面对应XianJiView这个大面板<br>
	*其下有3个页签 分别为 成长、好感、装扮 对应其funId为 FunctionDefine.XIANJI_CJ ,FunctionDefine.XIANJI_HG,FunctionDefine_XIANJI_ZB<br>
	*red=Mgr.red;<br>
	*red.regist(FunctionDefine.XIANJI,FunctionDefine.XIANJI_CZ);<br>
	*red.regist(FunctionDefine.XIANJI,FunctionDefine.XIANJI_HG);<br>
	*red.regist(FunctionDefine.XIANJI,FunctionDefine.XIANJI_ZB);<br>
	**/
	__proto.regist=function(parFunID,funId,isMainFunID,redEvent){
		(isMainFunID===void 0)&& (isMainFunID=false);
		(redEvent===void 0)&& (redEvent="");
		if(parFunID==funId){
			alert(Lang.str(3273)+funId);
			return;
		};
		var parRedVo=this._dic[parFunID];
		if(!parRedVo){
			parRedVo=new RedVo();
			parRedVo.funcId=parFunID;
			parRedVo.hasCornor=false;
			parRedVo.isMainFunID=isMainFunID;
			this._dic[parFunID]=parRedVo;
		}
		if(funId){
			var funRedVo=this._dic[funId];
			if(!funRedVo || !funRedVo.parentVo){
				funRedVo=new RedVo();
				funRedVo.funcId=funId;
				funRedVo.parentVo=parRedVo;
				funRedVo.parentId=parFunID;
				funRedVo.hasCornor=false;
				funRedVo.redEvent=redEvent;
				this._dic[funId]=funRedVo;
			}
			else{
				alert(funId+Lang.str(3274)+funRedVo.parentId+Lang.str(3275));
				return;
			}
			parRedVo.addElementVo(funRedVo);
		}
	}

	/**注册单模块的红点*/
	__proto.registSilRed=function(funId,redEvent){
		(redEvent===void 0)&& (redEvent="");
		var funRedVo=this._dic[funId];
		if(!funRedVo){
			funRedVo=new RedVo();
			funRedVo.funcId=funId;
			funRedVo.hasCornor=false;
			funRedVo.redEvent=redEvent;
			this._dic[funId]=funRedVo;
		}
		else{
			alert(funId+Lang.str(3274)+funRedVo.parentId+Lang.str(3275));
			return;
		}
	}

	/**
	*设置红点显示数据<br>
	*funId:子模块的功能id<br>
	*redType:红点数据类型 例如某一个button有红点显示，可以设置为一个 （任意且唯一的标志id字符串【不可以用parent、parentId、hasCornor这三个内置字符串，否则会出问题】）<br>
	*subEventName:事件名称，用来抛给页面来更新页签红点的事件<br>
	*例子：<br>
	*red.showRedPoint(FunctionDefine.XIANJI_ZB,id,XianJiView.XJ_CORNOR_UPDATE);
	**/
	__proto.showRedPoint=function(funId,redType,subEventName){
		(redType===void 0)&& (redType="default");
		(subEventName===void 0)&& (subEventName="");
		var redVo=this._dic[funId];
		if(redVo){
			redVo.setCornerState(redType,true);
			if(subEventName){
				redVo.dispatchEvent(subEventName,funId);
			}
		}
		else{
		}
	}

	/**
	*设置红点隐藏数据<br>
	*funId:子模块的功能id<br>
	*fun_type_Id:子模块内的不同红点数据的的类型 例如某一个button有红点显示，可以设置为一个 （任意且唯一的标志id字符串【不可以用parent、parentId、hasCornor这三个内置字符串，否则会出问题】）<br>
	*subEventName:事件名称，用来抛给页面来更新页签红点的事件<br>
	*例子：<br>
	*red.hideRedPoint(FunctionDefine.XIANJI_ZB,id,XianJiView.XJ_CORNOR_UPDATE);
	**/
	__proto.hideRedPoint=function(funId,redType,subEventName){
		(redType===void 0)&& (redType="default");
		(subEventName===void 0)&& (subEventName="");
		var redVo=this._dic[funId];
		if(redVo){
			redVo.setCornerState(redType,false);
			if(subEventName){
				redVo.dispatchEvent(subEventName,funId);
			}
		}
		else{
		}
	}

	// NewAlert.ShowAlert(Lang.str(3276)+funId+Lang.str(3277));
	__proto.hideAll=function(funId,events){
		(events===void 0)&& (events="");
		var redVo=this._dic[funId];
		if(redVo){
			redVo.clearAllRed();
			redVo.dispatchEvent(events,funId);
		}
	}

	/**
	*获取子模块的红点字典对象。<br>
	*例子：<br>
	*当主面板打开时 手动刷新页签的红点
	*private function refreshCornor():void<br>
	{<br>
		var redDic:Object=Mgr.red.getValue(FunctionDefine.XIANJI);<br>
		updateCornor(FunctionDefine.XIANJI_CZ,redDic[FunctionDefine.XIANJI_CZ].hasCornor);<br>
		updateCornor(FunctionDefine.XIANJI_HG,redDic[FunctionDefine.XIANJI_HG].hasCornor);<br>
		updateCornor(FunctionDefine.XIANJI_ZB,redDic[FunctionDefine.XIANJI_ZB].hasCornor);<br>
	}<br>

	**/
	__proto.getValue=function(funId){
		return this._dic[funId];
	}

	/**
	*获取子模块的唯一类型对应红点状态<br>
	*例子：<br>
	*面板中的某个按钮是否需要加红点
	*list中的render渲染：<br>
	*if(Mgr.red.getRedPoint(funId,fun_type_Id))<br>
	*{<br>
		*addcornor;<br>
		*}<br>
	*else<br>
	*{<br>
		*removecornor;<br>
		*}<br>
	**/
	__proto.getRedPoint=function(funId,redType){
		var redVo=this._dic[funId];
		if(redVo)
			return redVo.getCornerState(redType);
		return false;
	}

	/**获取模块(页签)的红点状态*/
	__proto.getRedStateByFunId=function(funId){
		var redVo=this._dic[funId];
		if(redVo)
			return redVo.hasCornor;
		return false;
	}

	/**
	*刷新单个事件红点
	*@param type 红点大类型
	*@param redType 红点功能类型
	*@param bo 红点状态
	**/
	__proto.updateSigRed=function(type,redType,bo){
		var redVo=this._dic[type];
		if(!redVo){
			redVo=new RedVo();
			redVo.hasCornor=false;
			this._dic[type]=redVo;
		}
		if(bo){
			redVo.hasCornor=true;
			redVo.setCornerState(redType,true);
		}
		else{
			redVo.setCornerState(redType,false);
			redVo.hasCornor=redVo.checkRedTypeHasTrue();
		}
	}

	/**每次登录游戏，特殊主界面图标显示红点 打开面板红点消失*/
	__proto.specialRedIcon=function(functionId,isShowRed){
		EventCenter.instance.event("MAIN_VIEW_CORNOR",[functionId,isShowRed]);
	}

	/**功能总字典*/
	__getset(0,__proto,'dic',function(){
		return this._dic;
		},function(value){
		this._dic=value;
	});

	RedPointMgr.ins=function(){
		return RedPointMgr._ins=RedPointMgr._ins|| new RedPointMgr();
	}

	RedPointMgr._ins=null;
	return RedPointMgr;
})()


