//class com.xq.util.red.RedVo
var RedVo=(function(){
	function RedVo(){
		/**FunctionDefineID*/
		this.funcId=null;
		/**是否显示红点*/
		this.hasCornor=false;
		/**是否是主界面按钮功能(FunctionDefine)*/
		this.isMainFunID=false;
		/**父级RedVo*/
		this.parentVo=null;
		/**父级功能ID(FunctionDefine)*/
		this.parentId=null;
		/**自己的刷新事件*/
		this.redEvent=null;
		this._elementVo={};
		this._redTypeObj={};
		this.redDis=new RedDispatch();
	}

	__class(RedVo,'com.xq.util.red.RedVo');
	var __proto=RedVo.prototype;
	/**清除所有红点类型数据*/
	__proto.clearAllRed=function(){
		this._redTypeObj={};
		this._elementVo={};
	}

	/**根据类型获取红点状态*/
	__proto.getCornerState=function(type){
		return this.redTypeObj[type];
	}

	/**设置红点类型数据*/
	__proto.setCornerState=function(type,bo){
		this.redTypeObj[type]=bo;
	}

	/**增加新的Vo*/
	__proto.addElementVo=function(red){
		this.elementVoObj[red.funcId]=red;
	}

	/**获取Vo*/
	__proto.getElementVo=function(funcId){
		return this.elementVoObj[funcId];
	}

	/**派发刷新事件*/
	__proto.dispatchEvent=function(subEventName,funId){
		Laya.timer.callLater(this.redDis,this.redDis.dispatchEvent,[subEventName,funId]);
	}

	/**检测是否红点类型中有true*/
	__proto.checkRedTypeHasTrue=function(){
		var bo;
		for(var $each_bo in this.redTypeObj){
			bo=this.redTypeObj[$each_bo];
			if(bo){
				return true;
			}
		}
		return false;
	}

	/**子级RedVos数据 Objct*/
	__getset(0,__proto,'elementVoObj',function(){
		return this._elementVo;
	});

	/**红点类型数据*/
	__getset(0,__proto,'redTypeObj',function(){
		return this._redTypeObj;
	});

	return RedVo;
})()


