//class com.xq.util.RewardItemUtil
var RewardItemUtil=(function(){
	function RewardItemUtil(){}
	__class(RewardItemUtil,'com.xq.util.RewardItemUtil');
	RewardItemUtil.show=function(rewardList){
		var len=rewardList.length;
		var objVO;
		var itemMgr=Mgr.item;
		var rewardItem;
		for(var i=0;i<len;i++){
			rewardItem=rewardList[i];
			objVO=itemMgr.getItemVO(rewardItem.templateId);
			com.xq.util.RewardItemUtil.showItem(objVO,rewardItem.count);
		}
	}

	RewardItemUtil.showItem=null;
	return RewardItemUtil;
})()


//class com.xq.util.RewardUtil
var RewardUtil=(function(){
	function RewardUtil(){}
	__class(RewardUtil,'com.xq.util.RewardUtil');
	RewardUtil.show=function(rewardList,type){
		(type===void 0)&& (type=0);
		var v=UIMgrR.getIView(com.xq.view.modules.common.IGetRewardView,2);
		if(v&&v.isPopup){
			v.close();
		};
		var url="modules/forge/gongxihuode.png";
		PreLoadMgr.ins.preLoad([{url:url,type:"image"}],Handler.create(RewardUtil,com.xq.util.RewardUtil.onLoadComplete,[rewardList,type]));
	}

	RewardUtil.onLoadComplete=function(rewardList,type){
		(type===void 0)&& (type=0);
		Mgr.chipPopMgr.addTeam(Handler.create(RewardUtil,com.xq.util.RewardUtil.onOpenRewardView,[rewardList,type]),-1,true,true);
	}

	RewardUtil.onOpenRewardView=function(rewardList,type){
		(type===void 0)&& (type=0);
		var v=UIMgrR.openIView(com.xq.view.modules.common.IGetRewardView,2);
		v.dataSource=[rewardList,type];
	}

	return RewardUtil;
})()


/**
*被击打后的动画的效果
*2018-3-16
*@author gfr@mmp
*/
//class com.xq.util.scene.BeBitAniUtil
var BeBitAniUtil=(function(){
	function BeBitAniUtil(){}
	__class(BeBitAniUtil,'com.xq.util.scene.BeBitAniUtil');
	BeBitAniUtil.BeBit=function(type,x,y,boomArr){
		if(!BeBitAniUtil.aniDic){
			BeBitAniUtil.aniDic={};
			BeBitAniUtil.aniDic[1]=BeBitAniUtil.ExpBoom;
			BeBitAniUtil.aniDic[2]=BeBitAniUtil.MoneyBoom;
			BeBitAniUtil.aniDic[3]=BeBitAniUtil.ItemBoom;
		}
		if(BeBitAniUtil.aniDic[type])
			BeBitAniUtil.aniDic[type](x,y,boomArr);
	}

	BeBitAniUtil.ExpBoom=function(x,y,boomArr){
		var randomNum=Math.round(Math.random()*3)+3;
		for(var i=0;i < randomNum;i++){
			var img=BeBitAniUtil.imgCache.length>0?BeBitAniUtil.imgCache.pop():new Image();
			img.skin=PathDefine.RES2_ROOT+PathDefine.DROP_ICON+"exp"+".png";
			img.x=x;
			img.y=y;
			Model.game.sceneContainer.unitLayer.addChild(img);
			var flag=i%2==0?-1:1;
			var randomY=-(Math.round(Math.random()*100)+20)+y;
			var randomX=flag*(Math.round(Math.random()*200)+50)+x;
			Tween.to(img,{x:randomX},500);
			Tween.to(img,{y:randomY},250,Ease.circIn);
			Tween.to(img,{y:randomY+50+Math.round(Math.random()*200)},250,Ease.backInOut,null,250);
			if(boomArr){
				if(boomArr.length > 30)
					BeBitAniUtil.dispose(boomArr.shift());
				boomArr.push(img);
			}
			else
			Laya.timer.once(1500,null,com.xq.util.scene.BeBitAniUtil.dispose,[img],false);
		}
	}

	BeBitAniUtil.MoneyBoom=function(x,y,boomArr){
		var randomNum=Math.round(Math.random()*3)+3;
		for(var i=0;i < randomNum;i++){
			var img=BeBitAniUtil.imgCache.length>0?BeBitAniUtil.imgCache.pop():new Image();
			img.skin=PathDefine.RES2_ROOT+PathDefine.DROP_ICON+"money"+".png";
			img.x=x;
			img.y=y;
			Model.game.sceneContainer.unitLayer.addChild(img);
			var flag=i%2==0?-1:1;
			var randomY=-(Math.round(Math.random()*100)+20)+y;
			var randomX=flag*(Math.round(Math.random()*200)+50)+x;
			Tween.to(img,{x:randomX},500);
			Tween.to(img,{y:randomY},250,Ease.circIn);
			Tween.to(img,{y:randomY+50+Math.round(Math.random()*200)},250,Ease.backInOut,null,250);
			if(boomArr){
				if(boomArr.length > 30)
					BeBitAniUtil.dispose(boomArr.shift());
				boomArr.push(img);
			}
			else
			Laya.timer.once(1500,null,com.xq.util.scene.BeBitAniUtil.dispose,[img],false);
		}
	}

	BeBitAniUtil.ItemBoom=function(x,y,boomArr){
		var randomNum=Math.round(Math.random()*3)+3;
		for(var i=0;i < randomNum;i++){
			var img=BeBitAniUtil.imgCache.length>0?BeBitAniUtil.imgCache.pop():new Image();
			img.skin=PathDefine.RES2_ROOT+PathDefine.DROP_ICON+"item"+".png";
			img.x=x;
			img.y=y;
			Model.game.sceneContainer.unitLayer.addChild(img);
			var flag=i%2==0?-1:1;
			var randomY=-(Math.round(Math.random()*100)+20)+y;
			var randomX=flag*(Math.round(Math.random()*200)+50)+x;
			Tween.to(img,{x:randomX},500);
			Tween.to(img,{y:randomY},250,Ease.circIn);
			Tween.to(img,{y:randomY+50+Math.round(Math.random()*200)},250,Ease.backInOut,null,250);
			if(boomArr){
				if(boomArr.length > 30)
					BeBitAniUtil.dispose(boomArr.shift());
				boomArr.push(img);
			}
			else
			Laya.timer.once(1500,null,com.xq.util.scene.BeBitAniUtil.dispose,[img],false);
		}
	}

	BeBitAniUtil.laterDispose=function(img,x,y){
		Tween.to(img,{x:x,y:y},500,Ease.circIn,Handler.create(null,com.xq.util.scene.BeBitAniUtil.dispose,[img]));
	}

	BeBitAniUtil.dispose=function(img){
		img.removeSelf();
		Tween.clearTween(img);
		if(BeBitAniUtil.imgCache.length > 150){
			img.destroy();
		}
		else{
			BeBitAniUtil.imgCache.push(img);
		}
	}

	BeBitAniUtil.aniDic=null;
	BeBitAniUtil.imgCache=[];
	return BeBitAniUtil;
})()


/**
*一下通用小特效
*用完记得push到aniPool里面
*@author zhanglimin
*@date 2019-9-10
*/
//class com.xq.util.scene.CommonAniUtil
var CommonAniUtil=(function(){
	function CommonAniUtil(){
		this._uiAniList=[];
		this.imgPool=[];
	}

	__class(CommonAniUtil,'com.xq.util.scene.CommonAniUtil');
	var __proto=CommonAniUtil.prototype;
	__proto.getAni=function(){
		var ani;
		ani=new UIAni();
		ani.scale(1,1);
		ani.visible=true;
		return ani
	}

	/**
	*仿粒子特效,缩小到消失
	*@param num:数量 starPo:开始位置 endPo:结束位置
	*/
	__proto.particleAni=function(num,starPo,endPo,rangeX,rangeY,url,time,hasEase,scale,offSetX,offSetY,isPlayEndTween){
		(rangeX===void 0)&& (rangeX=100);
		(rangeY===void 0)&& (rangeY=50);
		(url===void 0)&& (url="");
		(time===void 0)&& (time=900);
		(hasEase===void 0)&& (hasEase=true);
		(scale===void 0)&& (scale=0.2);
		(offSetX===void 0)&& (offSetX=0);
		(offSetY===void 0)&& (offSetY=0);
		(isPlayEndTween===void 0)&& (isPlayEndTween=false);
		for (var i=0;i < num;i++){
			var uiAni=this.getAni();
			this._uiAniList.push(uiAni);
			var endPosX=endPo.x-offSetX+(Math.random()*(offSetX *2));
			var endPosY=endPo.y-offSetY+(Math.random()*(offSetY *2));
			if(num > 1){
				var _x=(starPo.x-rangeX)+(Math.random()*(rangeX *2));
				var _y=(starPo.y-rangeY)+(Math.random()*(rangeY *2));
			}
			else{
				_x=starPo.x;
				_y=starPo.y;
			}
			uiAni.pos(_x,_y);
			if(url){
				uiAni.setRes(url);
			}
			else{
				uiAni.setRes(PathDefine.EFFECT_UI+"tiaozhan.amt");
			}
			Laya.stage.addChild(uiAni);
			uiAni.zOrder=9999;
			var tempEase=null;
			if(hasEase){
				tempEase=Ease.backIn;
			}
			else{
				tempEase=null;
			}
			Tween.to(uiAni,{x:endPosX,y:endPosY,scaleX:scale,scaleY:scale},time,tempEase,Handler.create(this,this.particleCom,[uiAni,isPlayEndTween]),50 *i);
		}
	}

	__proto.particleCom=function(ani,isPlayEndTween){
		(isPlayEndTween===void 0)&& (isPlayEndTween=false);
		if(!isPlayEndTween){
			ani.removeSelf();
			ani.dispose();
			}else{
			Tween.to(ani,{alpha:0},1500,null,Handler.create(this,this.isEndTween,[ani]));
		}
	}

	__proto.isEndTween=function(ani){
		ani.removeSelf();
		ani.dispose();
	}

	__proto.removeAllAni=function(){
		var len=this._uiAniList.length;
		for(var i=0;i<len;i++){
			var ani=this._uiAniList[i];
			Tween.clearAll(ani);
			ani.removeSelf();
			ani.dispose();
		}
		this._uiAniList=[];
	}

	/**
	*小光点特效
	*@param _parent:容器
	*/
	__proto.pointLightAni=function(_parent,_x,_y,name){
		(name===void 0)&& (name="tiaozhan");
		var uiAni=this.getAni();
		uiAni.setRes(PathDefine.EFFECT_UI+name+".amt");
		_parent.addChild(uiAni);
		uiAni.pos(_x,_y);
		uiAni.callBack=Handler.create(this,this.particleCom,[uiAni])
		return uiAni;
	}

	__proto.getImg=function(){
		var img;
		img=new Image();
		img.scale(1,1);
		img.visible=true;
		return img;
	}

	/**
	*仿粒子特效,缩小到消失
	*@param num:数量 starPo:开始位置 endPo:结束位置 time:动画时间
	*/
	__proto.particleImg=function(num,url,starPo,endPo,rangeX,rangeY,time){
		(rangeX===void 0)&& (rangeX=100);
		(rangeY===void 0)&& (rangeY=50);
		(time===void 0)&& (time=900);
		for (var i=0;i < num;i++){
			var uiImg=new Image()
			if(num > 1){
				var _x=(starPo.x-rangeX)+(Math.random()*(rangeX *2));
				var _y=(starPo.y-rangeY)+(Math.random()*(rangeY *2));
			}
			else{
				_x=starPo.x;
				_y=starPo.y;
			}
			uiImg.pos(_x,_y);
			uiImg.skin=url;
			Laya.stage.addChild(uiImg);
			uiImg.zOrder=9999;
			Tween.to(uiImg,{x:endPo.x,y:endPo.y,scaleX:0.2,scaleY:0.2},time,Ease.backIn,Handler.create(this,this.addImgCha,[uiImg]),50 *i);
		}
	}

	__proto.addImgCha=function(img){
		img.removeSelf();
		this.imgPool.push(img);
	}

	__getset(1,CommonAniUtil,'ins',function(){
		return CommonAniUtil._ins=CommonAniUtil._ins|| new CommonAniUtil();
	});

	CommonAniUtil._ins=null;
	return CommonAniUtil;
})()


