//class com.xq.util.scene.FlyAniUtil
var FlyAniUtil=(function(){
	function FlyAniUtil(){}
	__class(FlyAniUtil,'com.xq.util.scene.FlyAniUtil');
	FlyAniUtil.ZDLFly=function(nums,sx,sy){}
	FlyAniUtil.EXPFly=function(nums){
		if(UIMgrR.frameGroup.numOfViews()>0){
			return;
		};
		var mainPlayer=Game.getInstance().player;
		if(mainPlayer==null){
			return;
		};
		var x=mainPlayer.x;
		var y=mainPlayer.y;
		FlyAniUtil.exppoint.setTo(x,y-(mainPlayer.rHeight>>1));
		if(!mainPlayer.parent)return;
		FlyAniUtil.exppoint=(mainPlayer.parent).localToGlobal(FlyAniUtil.exppoint);
		x=FlyAniUtil.exppoint.x;
		y=FlyAniUtil.exppoint.y;
		var expHead=Game.getInstance().actBar.getProBar().getExpBar();
		FlyAniUtil.exppoint.setTo(expHead.width-10,6);
		FlyAniUtil.exppoint=(expHead).localToGlobal(FlyAniUtil.exppoint);
		var tx=FlyAniUtil.exppoint.x;
		var ty=FlyAniUtil.exppoint.y;
		FlyAniUtil.fly(nums,x,y,tx,ty,"exp");
	}

	FlyAniUtil.fly=function(nums,sx,sy,tx,ty,res){
		var spArr=[];
		for(var i=0;i < nums;i++){
			var tempBall;
			if(FlyAniUtil.imagePool.length>0){
				tempBall=FlyAniUtil.imagePool.pop();
			}
			else{
				tempBall=new Image();
			}
			tempBall.skin=PathDefine.RES2_ROOT+PathDefine.IMAGE+"juqing/"+res+".png";
			tempBall.width=50;
			tempBall.height=50;
			tempBall.pivotX=25;
			tempBall.pivotY=25;
			tempBall.x=sx;
			tempBall.y=sy;
			Game.getInstance().addChild(tempBall);
			spArr[i]=tempBall;
		}
		FlyAniUtil.flyStart(spArr,tx,ty);
	}

	FlyAniUtil.flyStart=function(sp,tx,ty){
		var len=sp.length;
		var r=360/len;
		var tempR=0;
		for(var i=0;i < len;i++){
			var tempX=((Math.random()*75+50)*Math.sin(tempR))+sp[i].x;
			var tempY=((Math.random()*75+50)*Math.cos(tempR))+sp[i].y;
			tempR+=r;
			Tween.to(sp[i],{x:tempX,y:tempY},300,Ease.backInOut,null,i*100);
		}
		Laya.timer.once(i*100,FlyAniUtil,FlyAniUtil.flying,[sp,tx,ty],false);
	}

	FlyAniUtil.flying=function(sp,tx,ty){
		var len=sp.length;
		for(var i=0;i < len;i++){
			Tween.to(sp[i],{x:tx,y:ty},800,Ease.cubicOut,HandlerN.create(sp[i],sp[i].removeSelf,null,true,"flyMoney"),i*50);
		}
		Laya.timer.once(800+i*50,FlyAniUtil,FlyAniUtil.flyEnd,[sp],false);
	}

	FlyAniUtil.flyEnd=function(sp){
		var len=sp.length;
		for(var i=0;i < len;i++){
			var img=sp[i];
			img.removeSelf();
			if(FlyAniUtil.imagePool.length<30){
				FlyAniUtil.imagePool.push(img);
			}
		}
	}

	FlyAniUtil.itemFly=function(item){
		if(item==null){
			return;
		}
		if(item.iconItemView){
			var templateId=item.iconItemView.itemVO.templateId;
			if(templateId=="dj1000"){
				var flyX=Laya.stage.width*0.5;
				var flyY=Laya.stage.height*0.4;
				MoneyFlyEffectUtill.instance.play(1,flyX,flyY,5);
				return;
			}
			else if(templateId=="dj1688"){
				var flyX=Laya.stage.width*0.5;
				var flyY=Laya.stage.height*0.4;
				MoneyFlyEffectUtill.instance.play(2,flyX,flyY,5);
				return;
			}
		};
		var btn=Game.getInstance().actBar.getBtnUpgrade();
		var bagPos=btn.localToGlobal(new Point(0,0));
		var iconPos=item.localToGlobal(new Point(0,0));
		var sprite=new Sprite();
		var bgImg=new Image();
		bgImg.skin=item.bgskins;
		var img=new Image();
		img.skin=item.skins;
		sprite.addChild(bgImg);
		sprite.addChild(img);
		Laya.stage.addChild(sprite);
		sprite.x=iconPos.x;
		sprite.y=iconPos.y;
		Tween.to(sprite,{x:bagPos.x,y:bagPos.y},1000,Ease.backIn,HandlerN.create(FlyAniUtil,com.xq.util.scene.FlyAniUtil.itemFlyEnd,[sprite],true,"flyMoney"));
	}

	FlyAniUtil.itemFlyEnd=function(sprite){
		sprite.removeSelf();
	}

	FlyAniUtil.imagePool=[];
	FlyAniUtil.radius=75;
	__static(FlyAniUtil,
	['zdlpoint',function(){return this.zdlpoint=new Point();},'exppoint',function(){return this.exppoint=new Point();}
	]);
	return FlyAniUtil;
})()


