var DeviceVo=(function(){
	function DeviceVo(){
		this.type=0;
		/**装置的 配置id*/
		this.id=0;
		/**解锁状态 0：未解锁 1：已解锁*/
		this.stat=0;
		/**该装置 正在生产的产品的开始时间戳*/
		this.startTime=NaN;
		/**该装置 正在生产的产品的当前进度*/
		this.timePro=NaN;
		/**加速状态 结束时间戳*/
		this.speedEndTime=NaN;
		/**生产队列*/
		this.produces=null;
	}

	__class(DeviceVo,'com.xq.vo.lianDanLu.DeviceVo');
	var __proto=DeviceVo.prototype;
	__proto.setTimePro=function(time){
		this.timePro=time;
		if(this.produces){
			var pvo=this.produces[0];
			if(pvo&&pvo.proId){
				pvo.curTimePro=this.timePro;
			}
		}
	}

	/**设置刚解锁时的初始数据*/
	__proto.setUnlockData=function(id,type,len){
		this.id=id;
		this.stat=1;
		this.startTime=0;
		this.timePro=0;
		this.speedEndTime=0;
		this.produces=[];
		this.produces.length=len;
		this.type=type;
	}

	/**根据后端数据刷新*/
	__proto.updateData=function(info,type,len){
		this.id=info.id;
		this.stat=info.state;
		this.startTime=info.starTime;
		this.timePro=info.protime;
		this.speedEndTime=info.speedEndTime;
		this.type=type;
		this.produces=[];
		this.produces.length=len;
		var pArr=info.infos;
		var len=pArr.length;
		var pInfo;
		var produceVo;
		for(var i=0;i<len;i++){
			pInfo=pArr[i];
			produceVo=new ProduceVo();
			produceVo.updateData(pInfo,type);
			produceVo.deviceId=this.id;
			if(i==0){
				produceVo.isProducing=true;
				produceVo.curTimePro=this.timePro;
			}
			this.produces[i]=produceVo;
		}
	}

	/**添加生产项 成功返回ture 失败返回false*/
	__proto.addProduce=function(msg){
		if(!this.produces)return false;
		var pVo=new ProduceVo();
		pVo.setAddNewData(msg,this.type);
		var len=this.produces.length;
		for(var i=0;i<len;i++){
			if(!this.produces[i]){
				this.produces[i]=pVo
				return true;
			}
		}
		return false;
	}

	/**移除生产项 成功返回ture 失败返回false*/
	__proto.delProduce=function(msg){
		if(!this.produces)return false;
		var len=this.produces.length;
		var pVo;
		for(var i=0;i<len;i++){
			pVo=this.produces[i];
			if(pVo&&pVo.index==msg.idx){
				this.produces[i]=null;
				return true;
			}
		}
		return false;
	}

	return DeviceVo;
})()


