//class com.xq.vo.PropAttrVo
var PropAttrVo=(function(){
	function PropAttrVo(){
		this._attrId=0;
		this.attrName=null;
		this.attrVal=NaN;
		this.color=null;
		/**下一级增加属性值*/
		this.nextLvAddVal=NaN;
		/**用于自定义展示的属性名称*/
		this.ifShow=false;
		this.showName=null;
		this.showVal=NaN;
		this.ifShowPer=false;
		this.typeName=null;
		this.per=NaN;
		this.cloVal=null;
	}

	__class(PropAttrVo,'com.xq.vo.PropAttrVo');
	var __proto=PropAttrVo.prototype;
	/**传入数据 [name,value]*/
	__proto.setData=function(arr){
		this.attrName=arr[0];
		this.attrVal=arr[1];
	}

	__getset(0,__proto,'cnName',function(){
		if(!this.attrName)return "";
		var cof=Model.prop.getAttrCofByName(this.attrName);
		if(!cof)return "";
		return cof.mingzi;
	});

	/**属性Id*/
	__getset(0,__proto,'attrId',function(){
		if(!this.attrName)return-1;
		return Model.prop.getAttrIdByName(this.attrName);
	});

	/**属性战力 前端自己算的 会有一些偏差，用于小模块算战力，大模块还是用后端的数据*/
	__getset(0,__proto,'attrFV',function(){
		if(!this.attrName)return 0;
		var cof=Model.prop.getAttrCofByName(this.attrName);
		if(!cof)return 0;
		var attrFactor=cof.pingfen;
		return parseInt(Math.round(this.attrVal *attrFactor).toString());
	});

	__getset(0,__proto,'ifPer',function(){
		if(!this.attrName)return false;
		var cof=Model.prop.getAttrCofByName(this.attrName);
		if(!cof)return false;
		return cof.isPer==1;
	});

	return PropAttrVo;
})()


//class com.xq.vo.qunxiongzhengba.CityItemVo
var CityItemVo=(function(){
	function CityItemVo(){
		/**城池Id*/
		this.cityId=0;
		/**类型1 本服 2 跨服*/
		this.type=0;
		/**城池等级*/
		this.cityLv=0;
		/**城池Pos*/
		this.cityPos=null;
		/**地图碎片Pos*/
		this.mapPos=null;
		/**城池名字*/
		this.cityName=null;
		/**是否已被占领*/
		this.ifBeOccupied=false;
		/**占领国号*/
		this.countryName=null;
		/**剩余开放时间*/
		this.openDay=0;
		/**是否正在发生战争*/
		this.ifBattle=false;
	}

	__class(CityItemVo,'com.xq.vo.qunxiongzhengba.CityItemVo');
	var __proto=CityItemVo.prototype;
	__proto.setData=function(ele){
		var cof=ele.getCfgData();
		this.cityId=cof.id;
		this.type=cof.gjId+1;
		this.cityLv=cof.level;
		this.cityPos=cof.cityPos;
		this.cityName=cof.name;
		this.mapPos=cof.cityMapPos;
		var day=cof.openday-CommonUtil.openServerDay;
		this.openDay=day>0?day:0;
		var info=ele.getValue("s");
		this.ifBeOccupied=info&&info.guild?true:false;
		if(this.ifBeOccupied){
			if(info.contryName){
				this.countryName=info.contryName
			}
			else{
				var arr=info.guildName.split(".");
				var name=arr[1];
				this.countryName=name[0];
			}
		}
		if(info&&info.attackerId&&info.attackerId!=info.guild){
			this.ifBattle=true;
		}
		else{
			this.ifBattle=false;
		}
	}

	return CityItemVo;
})()


