//class com.xq.vo.wendingtianxia.WDTXGuildVo
var WDTXGuildVo=(function(){
	function WDTXGuildVo(){
		/**帮派Id*/
		this.guildId=NaN;
		/**帮派名*/
		this.guildName=null;
		/**国名*/
		this.countryName=null;
	}

	__class(WDTXGuildVo,'com.xq.vo.wendingtianxia.WDTXGuildVo');
	var __proto=WDTXGuildVo.prototype;
	__proto.setData=function(data){
		if(!data){
			this.guildId=0;
			this.guildName=Lang.str(3298);
			this.countryName=Lang.str(3298)
			return;
		}
		this.guildId=data.id;
		this.guildName=data.name?data.name:Lang.str(3298);
		if(data.countryName){
			this.countryName=data.countryName;
		}
		else{
			var arr=data.name.split(".");
			var name=arr[1];
			if(name){
				this.countryName=name[0];
			}
			else{
				this.countryName=Lang.str(3298);
			}
		}
	}

	return WDTXGuildVo;
})()


