var HeroTowerBehaviorQueueBase=(function(){
	function HeroTowerBehaviorQueueBase(){
		/**行为队列*/
		this.beaviorQueue=null;
		this.unit=null;
		this.target=null;
		this.callBack=null;
	}

	__class(HeroTowerBehaviorQueueBase,'com.xq.xiaoGame.heroTower.behavior.HeroTowerBehaviorQueueBase');
	var __proto=HeroTowerBehaviorQueueBase.prototype;
	__proto.registBeavior=function(){}
	__proto.startPlay=function(unit,target,callBack){
		this.unit=unit;
		this.target=target;
		this.callBack=callBack;
		this.registBeavior();
		this.doNextBehavior();
	}

	__proto.doBeHavior=function(vo){
		var unit=vo.actionUnit;
		var target=vo.actionTarget;
		var behavoirHandler=HeroTowerBehaviorMgr.ins.getBehavior(vo.behaviorType);
		if(behavoirHandler){
			behavoirHandler.runWith([unit,target]);
		}
		this.doNextBehavior();
	}

	__proto.doNextBehavior=function(){
		if(this.beaviorQueue.length<=0){
			Laya.timer.once(500,this,this.runCallBack,null,false);
			this.unit=null;
			this.target=null;
			return;
		}
		HeroTowerBehaviorMgr.ins.isDoingBehavior=true;
		var vo=this.beaviorQueue.shift();
		if(vo.delay){
			Laya.timer.once(vo.delay,this,this.doBeHavior,[vo],false);
		}
		else{
			this.doBeHavior(vo);
		}
	}

	__proto.runCallBack=function(){
		HeroTowerBehaviorMgr.ins.isDoingBehavior=false;
		this.callBack&&this.callBack.run();
	}

	return HeroTowerBehaviorQueueBase;
})()


