//class com.xq.core.net.NetMgr extends laya.events.EventDispatcher
var NetMgr=(function(_super){
	function NetMgr(){
		/**当前服务器信息*/
		this.serverVO=null;
		/**当前玩家信息*/
		this.roleVO=null;
		this.curUrl=null;
		this.msgDic={};
		/**协议检测时间*/
		this.waitTime=15000;
		this.isEnterScene=false;
		this.sendTime={};
		this.sendCount={};
		this.smoothTime={};
		this.smoothCount={};
		this.receiveTime={};
		this.receiveCount={};
		this.dispatchTime={};
		this.dispatchCount={};
		this.socket=null;
		this.byte=null;
		this.msgBytes=null;
		this.emptyProtocal=null;
		this.lastReceiveT=0;
		this.receiveMsgCount=0;
		this.userName=null;
		this.onCompHandler=null;
		this.isRecconet=false;
		//public function send(code,msg:ProtocolBase)
		this.bytedic={};
		this.numDic={};
		this.timeByteDic={};
		this.timeByteTotalLen=0;
		this.timeByteLen=0;
		this.timeNum=0;
		NetMgr.__super.call(this);
		this.byte=new Byte();
		this.byte.endian="littleEndian";
		this.msgBytes=new Byte();
		this.msgBytes.endian="littleEndian";
		this.socket=new Socket();
		this.socket.endian="littleEndian";
		this.emptyProtocal=new ProtocolBase();
		this.serverVO=new SeverInfoVO();
		this.roleVO=new HeroVO();
		this.roleVO.isPlayerSelf=true;
	}

	__class(NetMgr,'com.xq.core.net.NetMgr',_super);
	var __proto=NetMgr.prototype;
	/**注册监听事件*/
	__proto.registerHandler=function(msgId,handler){
		if(this.msgDic[msgId]){
			throw new Error(Lang.str(2039),msgId);
		}
		this.msgDic[msgId]=handler;
	}

	/**移除监听事件*/
	__proto.unregisterHandler=function(msgId){
		if(this.msgDic[msgId]){
			delete this.msgDic[msgId];
		}
		else{
			throw new Error(Lang.str(2040),msgId);
		}
	}

	/**
	*发送协议消息
	**/
	__proto.sendMsg=function(msgId,msg,leapfrog){
		(leapfrog===void 0)&& (leapfrog=false);
		FrameSmooth.add(Handler.create(this,this.sendMsgSmoothly,[msgId,msg,leapfrog]));
	}

	/**检测冷却时间的发送协议消息*/
	__proto.sendMsgCheckCd=function(msgId,msg){
		if(!MsgFilter.ins.checkMsg(msgId,msg))return;
		FrameSmooth.add(Handler.create(this,this.sendMsgSmoothly,[msgId,msg]));
	}

	/**排队发送
	*leapfrog:跳过超时检测（例如 场景切换时可能需要较长时间，这种类型的协议跳过超时检测）
	**/
	__proto.sendMsgSmoothly=function(msgId,msg,leapfrog){
		(leapfrog===void 0)&& (leapfrog=false);
		if(this.socket.connected){
			if(leapfrog){
				this.lastReceiveT=Browser.now();
			}
			if(!leapfrog && this.receiveMsgCount > 10 && (Browser.now()-this.lastReceiveT)> this.waitTime){
				if(NetMgr.AUTO_RECONNET){
					this.closeConnect();
					this.receiveMsgCount=0;
					EventCenter.instance.event(GameEvent.RESTART_CONNECT);
					console.error(Lang.str(2041)+this.waitTime+Lang.str(2042));
					return;
				}
			}
			this.byte.clear();
			this.msgBytes.clear();
			if(msg==null){
				msg=this.emptyProtocal;
			}
			msg.encode(this.msgBytes);
			this.byte.writeInt16(this.msgBytes.length+4);
			this.byte.writeInt32(msgId);
			this.byte.writeArrayBuffer(this.msgBytes.buffer);
			if(msgId==8840000){}
				this.socket.send(this.byte.buffer);
			this.byte.clear();
			this.msgBytes.clear();
		}
		else{
			console.error(Lang.str(2044)+msgId);
		}
	}

	/**
	*主动断开连接
	*/
	__proto.closeConnect=function(){
		console.log(Lang.str(2045));
		this.socket.cleanSocket();
	}

	/**
	*连接服务器 192.168.1.18:7000
	**/
	__proto.connect=function(url,compHandle){
		this.curUrl=url;
		if(this.socket.connected){
			compHandle.runWith(true);
			return;
		}
		this.onCompHandler=compHandle;
		this.socket.connectByUrl(url);
		console.log(Lang.str(2046));
		this.socket.on("open",this,this.openHandler);
		this.socket.on("message",this,this.onReceive);
		this.socket.on("close",this,this.closeHandler);
		this.socket.on("error",this,this.errorHandler);
	}

	__proto.reconnect=function(compHandle){
		this.onCompHandler=compHandle;
		this.socket.connectByUrl(this.curUrl);
		this.isRecconet=true;
	}

	/**
	*
	**/
	__proto.openHandler=function(event){
		console.log(Lang.str(2047),this.curUrl);
		if(this.onCompHandler){
			this.onCompHandler.runWith(true);
			this.onCompHandler=null;
		}
	}

	__proto.onReceive=function(msg){
		this.lastReceiveT=Browser.now();
		this.receiveMsgCount++;
		var reByte=Pool.getItemByClass("byte",Byte);
		reByte.writeArrayBuffer(msg);
		reByte.pos=0;
		var len=reByte.getInt16();
		var msgId=reByte.getInt32();
		if(!this.bytedic[msgId])
			this.bytedic[msgId]=0;
		this.bytedic[msgId]+=reByte.length;
		if(!this.numDic[msgId])
			this.numDic[msgId]=0;
		this.numDic[msgId]++;
		if(!this.timeByteDic[msgId])
			this.timeByteDic[msgId]=0;
		this.timeByteDic[msgId]+=reByte.length;
		this.timeByteLen+=reByte.length;
		this.timeByteTotalLen+=reByte.length;
		this.timeNum++;
		var hdn=Handler.create(this,this.dispatch,[msgId,reByte]);
		FrameSmooth.add(hdn);
		if(this.socket.input.length > 1048576);
		this.socket.input.pos=this.socket.input.length;
	}

	// debugger;
	__proto.dispatch=function(msgId,data){
		var handler=this.msgDic[msgId];
		if(handler){
			try{
				var ti=Browser.now();
				handler.runWith({"msgId":msgId,"data":data});
				var dlet=Browser.now()-ti;
				if(dlet>25)
					console.warn(Lang.str(2049)+msgId+Lang.str(2050)+dlet+"ms");
			}
			catch(e){
				var msg="msgID:"+msgId+"msg:"+(e.message? e.message:e);
				console.error(e.stack);
				laya.xq.cfg.reportOneBug(e.message,e);
			}
		}
		else{
			console.log(Lang.str(2051),msgId);
		}
		data.clear();
		Pool.recover("byte",data);
	}

	__proto.closeHandler=function(e){
		if(this.roleVO.guid){
			this.event("close");
		}
		else{
			alert(Lang.str(2053));
		}
		if(this.onCompHandler){
			this.onCompHandler.runWith(false);
			this.onCompHandler=null;
		}
	}

	__proto.errorHandler=function(e){
		if(this.roleVO.guid){
		}
		else{
			console.log(Lang.str(2054));
		}
		if(this.onCompHandler){
			this.onCompHandler.runWith(false);
			this.onCompHandler=null;
		}
	}

	__proto.printDebug=function(){
		var byteArr=[];
		for(var key in this.bytedic){
			byteArr.push([key,this.bytedic[key]]);
		};
		var len=byteArr.length;
		for(var i=0;i < len-1;i++){
			for(var j=i+1;j < len;j++){
				var a=byteArr[i];
				var b=byteArr[j];
				if(a[1]<b[1]){
					var t=byteArr[i];
					byteArr[i]=byteArr[j];
					byteArr[j]=t;
				}
			}
		};
		var numArr=[];
		for(var key in this.numDic){
			numArr.push([key,this.numDic[key]]);
		};
		var len=numArr.length;
		for(var i=0;i < len-1;i++){
			for(var j=i+1;j < len;j++){
				var a=numArr[i];
				var b=numArr[j];
				if(a[1]<b[1]){
					var t=numArr[i];
					numArr[i]=numArr[j];
					numArr[j]=t;
				}
			}
		}
		console.log(Lang.str(2055));
		len=Math.min(byteArr.length,10);
		for(var i=0;i < len;i++){
			console.log(Lang.str(2056),byteArr[i][0],"----byte：",(byteArr[i][1]/1024).toFixed(2),"KB" ,Lang.str(2057),((byteArr[i][1]/this.numDic[byteArr[i][0]])/1024).toFixed(2)+"KB");
		}
		console.log(Lang.str(2058));
		len=Math.min(byteArr.length,10);
		for(var i=0;i < len;i++){
			console.log(Lang.str(2059),numArr[i][0],"-----num:",numArr[i][1],Lang.str(2060),(this.bytedic[numArr[i][0]]/numArr[i][1]/1024).toFixed(2)+"KB");
		}
	}

	__proto.traceMsg=function(key){
		var dispatchTime=this.dispatchTime[key];
		var recTime=this.receiveTime[key];
		var runTime=this.smoothTime[key];
		var seTime=this.sendTime[key];
		if(dispatchTime-seTime>=1000){
			console.warn(key+Lang.str(2061)+(runTime-seTime)+Lang.str(2062)+(recTime-runTime)+Lang.str(2063)+(dispatchTime-recTime));
		}
	}

	NetMgr.ins=function(){
		if(NetMgr._netMgr==null){
			NetMgr._netMgr=new NetMgr();
		}
		return NetMgr._netMgr;
	}

	NetMgr._netMgr=null;
	NetMgr.AUTO_RECONNET=false;
	return NetMgr;
})(EventDispatcher)


/**
*移动缓动
*2019-9-22
*@auther gfr
*/
//class com.xq.rpg.action.MoveTween extends laya.events.EventDispatcher
var MoveTween=(function(_super){
	function MoveTween(unit){
		this._unit=null;
		/**是否开始了监听*/
		this._isLoop=false;
		/**亮点之间间隔x,y*/
		this._targetX=0;
		this._targetY=0;
		/**总距离*/
		this._totalDistance=0;
		/**每次移动的距离，*/
		this._moveDis=0;
		/**x方向移动的距离*/
		this._moveX=0;
		/**y方向移动的距离*/
		this._moveY=0;
		/**运动时间*/
		this._movedTime=0;
		/**已经运动距离*/
		this._movedDis=0;
		/**需要运动的总时间*/
		this._totalTime=0;
		/**时间管理器的引用*/
		this._layaTime=null;
		// private var debugLog:Array ;
		this.toX=0;
		this.toY=0;
		this.isSynPosition=false;
		this.frameCount=0;
		this.frameDTime=0;
		this.isRushToEnd=false;
		this.rushSpeedRate=4;
		//冲刺速度提升倍率
		this.rushOn=false;
		this.frampSyn=0;
		this.tArr=[];
		MoveTween.__super.call(this);
		this.positionVo=new PlayerPosSyncCS();
		this._layaTime=Laya.scaleTimer;
	}

	__class(MoveTween,'com.xq.rpg.action.MoveTween',_super);
	var __proto=MoveTween.prototype;
	__proto.startTo=function(tx,ty,distance,rush){
		this.isRushToEnd=rush;
		this.toX=tx;
		this.toY=ty;
		this._targetX=tx-this._unit.x;
		this._targetY=ty-this._unit.y;
		this._totalDistance=distance;
		this._movedTime=0;
		this._movedDis=0;
		if(this.frameDTime==0){
			this.frameDTime=this._layaTime.delta;
		}
		this._totalTime=this.calculateTweenTime(distance);
		if(!this._isLoop){
			this._isLoop=true;
			this._layaTime.frameLoop(1,this,this.move);
		}
	}

	__proto.move=function(){
		var curTime=0;
		if(this.isSynPosition){
			this.frameCount++;
			if(this.frameCount % 25==0){
				this.synPosition();
				var toal=0;
				var tLen=this.tArr.length;
				for (var i=0;i < tLen;i++){
					toal+=this.tArr[i];
				}
				this.frameDTime=toal / tLen;
				this.tArr.length=0;
			}
			this.tArr.push(Math.min(this._layaTime.delta,60));
			curTime=this.frameDTime;
		}
		else
		curTime=this._layaTime.delta;
		this._movedTime+=curTime/1000;
		var isEnd=false;
		var leftDis=this._totalDistance-this._movedDis;
		if(leftDis <=0)
			isEnd=true;
		var leftTime=this._totalTime-this._movedTime;
		if(leftTime <=0)
			isEnd=true;
		if(!isEnd){
			if(this.isRushToEnd && leftDis <=500 && leftDis>=350){
				if(!this.rushOn){
					this.rushOn=true;
					this._unit.ghost(true);
					this._unit.doAction(6,this._unit.curDir);
				}
			}
			if(this.rushOn){
				this._moveDis=this._unit.curSpeed*this.rushSpeedRate*curTime/1000;
			}
			else{
				this._moveDis=this._unit.curSpeed*curTime/1000;
			}
			this._moveX=(this._targetX/this._totalDistance)*this._moveDis;
			this._moveY=(this._targetY/this._totalDistance)*this._moveDis;
			this._moveDis=Math.sqrt(this._moveX*this._moveX+this._moveY*this._moveY);
			if(this._moveDis >=leftDis)
				isEnd=true;
		}
		this._movedDis+=this._moveDis;
		if(isEnd){
			this.endTo();
			this.event("complete");
			return;
		}
		this._unit.x+=this._moveX;
		this._unit.y+=this._moveY;
		this._unit.updatePos();
	}

	/**
	*@param update:是否将物体位置直接设置为最终节点
	**/
	__proto.endTo=function(){
		if(this.rushOn){
			this.rushOn=false;
			this._unit.ghost(false);
		}
		this._isLoop=false;
		this._layaTime.clear(this,this.move);
	}

	__proto.dispose=function(){
		this.endTo();
		this.event("complete");
		Pool.recover("MoveTwPoolKey",this);
	}

	/**根据速度和距离计算缓动时间*/
	__proto.calculateTweenTime=function(distance){
		return ((distance)/this._unit.curSpeed);
	}

	/**同步位置*/
	__proto.synPosition=function(){
		EventCenter.instance.event("SEND_SYNC_POS",[this._unit.x,this._unit.y,false]);
	}

	MoveTween.create=function(unit){
		var mtw=Pool.getItemByClass("MoveTwPoolKey",MoveTween);
		mtw._unit=unit;
		if((unit instanceof com.xq.rpg.unit.MainPlayer ))
			mtw.isSynPosition=true;
		mtw._isLoop=false;
		return mtw
	}

	MoveTween.MoveTwPoolKey="MoveTwPoolKey";
	MoveTween.delayTime=20;
	return MoveTween;
})(EventDispatcher)


