//class com.xq.rpg.action.TiaoTween extends laya.events.EventDispatcher
var TiaoTween=(function(_super){
	function TiaoTween(unit){
		this.unit=null;
		/**跳跃高度*/
		this.tiaoHeight=0;
		this.TIME=1200;
		this.offsetX=0;
		this.offsetY=0;
		this.lastTime=0;
		/**跳时影子的位置*/
		this.tiaoy=0;
		/**跳时影子y的速度*/
		this.tiaooy=0;
		/**跳之前角色的y位置*/
		this.lastUnitY=0;
		/**跳之前角色的x位置*/
		this.lastUnitX=0;
		/**跳的时候x的速度*/
		this.speedX=0;
		this._timer=null;
		this.curTween=null;
		this.prop=null;
		TiaoTween.__super.call(this);
		this.unit=unit;
		this._timer=Laya.scaleTimer;
	}

	__class(TiaoTween,'com.xq.rpg.action.TiaoTween',_super);
	var __proto=TiaoTween.prototype;
	__proto.tiao=function(ox,oy,tiaoHeight,time){
		(time===void 0)&& (time=1200);
		this.TIME=time;
		this.offsetX=ox;
		this.offsetY=oy;
		this.tiaoHeight=tiaoHeight;
		this.tiaooy=oy/(this.TIME);
		this.speedX=ox/(this.TIME);
		this.lastUnitY=this.unit.y;
		this.lastUnitX=this.unit.x;
		this.lastTime=this._timer.currTimer;
		var tiaoTime=com.xq.rpg.action.TiaoTween.TYPE==0 ? this.TIME>>1 :this.TIME/20;
		Tween.to(this.unit,{x:this.unit.x+this.offsetX},this.TIME,null);
		this.curTween=Tween.to(this.unit,{y:(this.unit.y-tiaoHeight),update:Handler.create(this,this.updatePos,null,false)},tiaoTime,Ease.quadOut,null);
		this._timer.once(tiaoTime,this,this.down);
		this._timer.once(this.TIME+500,this,this.resetPos,[this.lastUnitX+this.offsetX,this.lastUnitY+this.offsetY]);
		this.unit.ghost(true);
	}

	/**重置坐标*/
	__proto.resetPos=function(tx,ty){
		Tween.clear(this.curTween);
		this.unit.x=tx;
		this.unit.y=ty;
		this.updatePos2();
	}

	__proto.updatePos=function(data){
		if(this.speedX!=0){
			var time=Math.abs((this.unit.x-this.lastUnitX)/this.speedX);
			this.tiaoy=this.lastUnitY+this.tiaooy *time;
		}
		this.unit.updatePos(this.tiaoy);
	}

	__proto.down=function(){
		this.curTween=Tween.to(this.unit,{y:(this.unit.y+this.tiaoHeight+this.offsetY),update:Handler.create(this,this.updatePos2,null,false)},this.TIME>>1,Ease.quadIn,null);
		this._timer.once(this.TIME>>1,this,this.stop);
	}

	//curTween.update=Handler.create(this,update);
	__proto.updatePos2=function(){
		this._timer.clear(this,this.resetPos);
		this.updatePos(null);
	}

	__proto.stop=function(){
		this.unit.ghost(false);
		this.curTween.update=null;
		if((this.unit instanceof com.xq.rpg.unit.MainPlayer )){
			EventCenter.instance.event("SEND_SYNC_POS",[this.unit.x,this.unit.y,false]);
		}
		this.event("complete");
	}

	__proto.dispose=function(){
		if(this.unit){
			Tween.clearAll(this.unit);
			this.unit.ghost(false);
		}
		if(this.curTween){
			this.curTween.update=null;
		}
		this.event("complete");
		this._timer.clear(this,this.resetPos);
		this._timer.clear(this,this.stop);
		this._timer.clear(this,this.down);
	}

	TiaoTween.create=function(url){
		var moveTw=Pool.getItemByClass("tiao_pool_key",TiaoTween);
		return moveTw;
	}

	TiaoTween.TIAO_POOL_KEY="tiao_pool_key";
	TiaoTween.TYPE=0;
	return TiaoTween;
})(EventDispatcher)


