	/**收到拉取活动*/
	__proto.onGetOnlineRewardInfo=function(byte){
		var vo=new OperationActivityInfoSC();
		vo.decode(byte);
		if(vo.errCode==1){
			Mgr.kaiFuHDProMgr.onGetOnlineRewardInfo(vo);
			switch(vo.activityType){
				case "danbifanhuan":;
					var opAct=NewActiveManager.ins.getActiveVerDic(8);
					if(opAct){
						vo.finishTime=opAct.endTime;
						Mgr.danbifanhuanMgr.setData(vo);
						EventCenter.instance.event("ACTIVE_TOGGLE",["zhutihuodong",false]);
					}
					break ;
				case "dengjilibao":{
						Mgr.isOpen.dengjilibao=true;
						Mgr.fuLiDaTing.getDJLBInfo(vo);
						break ;
					}
				case "meirishouchong":{
						Mgr.rebateHall.meiRiShouChongReward(vo);
						break ;
					}
				case "baiyinjijin":
				case "huangjinjijin":
				case "zuanshijijin":{
						Mgr.jijinMgr.setData(vo);
						EventCenter.instance.event("ACTIVE_TOGGLE",["touzijijin",false]);
						break ;
					}
				case "xiaofeifanli":{
						break ;
					}
				case "xianshichongji":{
						break ;
					}
				case "lingqichengzhang":{
						break ;
					}
				case "zhigoulianfan":{
						Mgr.isOpen.lianxuchongzhi=true;
						Mgr.rebateHall.getZhiGouLianFan(vo);
						break ;
					}
				case "chaozhishouchong":{
						if(vo.rewards[0].awarded==2){
							EventCenter.instance.event("ACTIVE_TOGGLE",["viptip",true]);
							Mgr.activityTipMgr.isGouMai=true;
						}
						break ;
					}
				case "shouchonghaoli":{
					}
				}
			}else{
			switch(vo.activityType){
				case "jixiangfudai":{
						Mgr.isOpen.jixiangfudai=false;
						break ;
					}
				default :{
						break ;
					}
				}
		}
	}

