	var __proto=ChatBoundAction.prototype;
	__proto.registerMsg=function(){
		this._methodDic[8811015]=this.onChatBoundInfo;
		this._methodDic[8811016]=this.onUse;
	}

	__proto.sendUse=function(chatId,headId,headFramId){
		var o1=this.mgr.getChatObj(chatId);
		var o2=this.mgr.getHeadFrameObj(headFramId);
		var o3=this.mgr.getHeadObj(headId);
		var flag=false;
		if(o1 || o2 || o3)
			flag=true;
		if(flag){
			if(!o1)
				chatId=this.mgr.curChat;
			if(!o2)
				headFramId=this.mgr.curHeadFrame;
			if(!o3)
				headId=this.mgr.curHead;
		};
		var csc=new ChatBoundUseCSC();
		csc.chatUse=chatId;
		csc.headFrameUse=headFramId;
		csc.headUse=headId;
		this._net.sendMsg(8811016,csc);
	}

	__proto.onUse=function(b){
		var csc=new ChatBoundUseCSC();
		csc.decode(b);
		Mgr.prompt.optionPrompt(Lang.str(2266));
		this.mgr.curChat=csc.chatUse;
		this.mgr.curHead=csc.headUse;
		this.mgr.curHeadFrame=csc.headFrameUse;
		EventCenter.instance.event("CHANGE_HEAD_BOUND");
	}

	__proto.sendChatBoundInfo=function(){
		this._net.sendMsg(8811015);
	}

	__proto.onChatBoundInfo=function(b){
		var d=new ChatBoundInfoSC();
		d.decode(b);
		var headArr=d.headArr.split(";");
		var len=headArr.length;
		for(var i=0;i <len;i++){
			var id=headArr[i];
			if(id && id!=""){
				var o=this.mgr.getHeadObj(parseInt(id));
				if(o)
					o.jihuo=true;
			}
		};
		var headFrameArr=d.headFrameArr.split(";");
		len=headFrameArr.length;
		for(i=0;i < len;i++){
			var id=headFrameArr[i];
			if(id && id!=""){
				var o=this.mgr.getHeadFrameObj(parseInt(id));
				if(o)
					o.jihuo=true;
			}
		};
		var chatArr=d.chatArr.split(";");
		len=chatArr.length;
		for(i=0;i < len;i++){
			var id=chatArr[i];
			if(id && id!=""){
				var o=this.mgr.getChatObj(parseInt(id));
				if(o)
					o.jihuo=true;
			}
		}
		this.mgr.curChat=d.chatUse;
		this.mgr.curHead=d.headUse;
		this.mgr.curHeadFrame=d.headFrameUse;
		if(this.isFirst){
			this.isFirst=false;
			EventCenter.instance.event("CHANGE_HEAD_BOUND");
		}
	}

