	__proto.onAlertHan=function(state){
		if(state=="OK"){
			ReconnectAction.getInstance().restart();
		}
	}

	__proto.onError=function(b){
		this.v.decode(b);
		var errId=this.v.err;
		if(errId==1002){
			UIMgrR.openIView(com.xq.view.modules.vip.IYuanBaoBuZuView,2);
			EventCenter.instance.event("YUANBAO_BUZU");
		}
		else if(errId==261124){
			AlertUtil.ShowAlert(Lang.str(2282),Handler.create(this,this.toRongLian),null);
			}else if(errId==261125){
			AlertUtil.ShowAlert(Lang.str(2283),Handler.create(this,this.toDaoJuBag),null);
			}else if(errId==261126){
			AlertUtil.ShowAlert(Lang.str(2284),Handler.create(this,this.toFaBao),null);
		}
		else if(errId==261127){
			AlertUtil.ShowAlert(Lang.str(2285),Handler.create(this,this.toHeCheng),null);
			}else if(errId==261128){
			AlertUtil.ShowAlert(Lang.str(2286),Handler.create(this,this.toTuJian),null);
			}else if(errId==261129){
			AlertUtil.ShowAlert(Lang.str(2287),Handler.create(this,this.toFenJie),null);
		}
		else if(errId !=5100 && errId !=5300){
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(errId));
		}
		console.log(Lang.str(2288)+this.v.err+Lang.str(2289)+CodeMgr.ins.getStringByCode(errId));
	}

