	/**公会BOSS伤害排行发生变化*/
	__proto.backGuildBossHarmRankChangeSC=function(data){
		var msg=new GuildBossHarmRankChangeSC();
		msg.decode(data);
		var ary=msg.guildBossHarmRankStageMsg;
		var len=ary.length;
		var rankAry=[];
		for (var i=0;i < len;i++){
			var tsg=ary[i];
			var obj={};
			obj.roleId=tsg.roleId;
			obj.rank=tsg.ranking;
			obj.name=tsg.roleName;
			obj.power=tsg.harmVal;
			obj.myV=tsg.harmVal-tsg.subHarmVal;
			obj.subV=tsg.subHarmVal;
			rankAry.push(obj);
		}
		EventCenter.instance.event("update_rank_fightinfo",[rankAry]);
	}

