var HongBaoAction=(function(_super){
	function HongBaoAction(){
		HongBaoAction.__super.call(this);
	}

	__class(HongBaoAction,'com.xq.modules.hongbao.HongBaoAction',_super);
	var __proto=HongBaoAction.prototype;
	__proto.registerMsg=function(){
		this._methodDic[70715]=this.onHongBaoList;
		this._methodDic[70717]=this.onSendHongBao;
		this._methodDic[70716]=this.onOpenHongBao;
		this._methodDic[70718]=this.onOpenSendHongBaoPanel;
		this._methodDic[70719]=this.onReceiveHongBao;
	}

	/**拉取红包列表*/
	__proto.sendGetHongBaoList=function(){
		this._net.sendMsg(70715);
	}

	/**收到服务端返回的红包列表*/
	__proto.onHongBaoList=function(b){
		var msg=new GetRedPaperInfoSC();
		msg.decode(b);
		Mgr.hongBaoMgr.hongBaoArr=msg.redpaperList;
		EventCenter.instance.event("updata_all_hong_bao_list");
	}

	/**发红包*/
	__proto.sendHongBao=function(hongBaoId){
		var msg=new SendRedPaperCS();
		msg.repaperId=hongBaoId;
		this._net.sendMsg(70717,msg);
	}

	__proto.onSendHongBao=function(b){
		var msg=new SendRedPaperSC();
		msg.decode(b);
		if(msg.errorCode==1){
		}
	}

	/**打开红包*/
	__proto.openHongBao=function(hongBaoGuid,sendHongBaoId){
		var msg=new OpenRedPaperCS();
		msg.repaperGuId=hongBaoGuid;
		msg.sendRoleId=sendHongBaoId;
		this._net.sendMsg(70716,msg);
	}

	__proto.onOpenHongBao=function(b){
		var msg=new OpenRedPaperSC();
		msg.decode(b);
		if(msg.errorCode==1){
			var itemVO=Mgr.item.getItemVO(msg.daoJuId);
			if(itemVO.templateId=="dj1688"){
				Mgr.prompt.optionGetItem(itemVO.templateId,msg.daoJucount);
			}
			EventCenter.instance.event("refresh_red_paper_reward",[msg]);
		}
		else{
			Mgr.prompt.optionPrompt(Lang.str(2585));
			EventCenter.instance.event("refresh_red_paper_reward",[null]);
		}
		this.sendGetHongBaoList();
	}

	/**完成指定任务 后端推送打开发红包界面*/
	__proto.onOpenSendHongBaoPanel=function(b){
		var msg=new FinishRedpaperTaskSC();
		msg.decode(b);
		Mgr.hongBaoMgr.hongBaoQueue(msg.redpaperId);
	}

	/**收到红包*/
	__proto.onReceiveHongBao=function(b){
		var msg=new redPaperRainSC();
		msg.decode(b);
		if(Configs.isForbitAndroidPay||Configs.isForbitIOSPay)return;
		if(!msg.redpaperList)return;
		var cof=Mgr.hongBaoMgr.getHongBaoById(msg.redpaperList.repaperId);
		if(cof){
			if(cof.type==3){
				Mgr.hongBaoMgr.pushMarriageHB(msg.redpaperList);
			}
			else{
				Mgr.hongBaoMgr.hongBaoFall(msg.redpaperList);
			}
		}
	}

	HongBaoAction.GET_HONG_BAO_INFO=70715;
	HongBaoAction.SEND_HONG_BAO=70717;
	HongBaoAction.OPEN_HONG_BAO=70716;
	HongBaoAction.FINISH_SEND_HONG_BAO_TASK=70718;
	HongBaoAction.RECRIVE_HONG_BAO=70719;
	return HongBaoAction;
})(BaseMsgAction)


