		this._net.serverVO.combineTime=userLoginSc.combineTime;
		this._net.serverVO.debug=userLoginSc.debug;
		this._net.serverVO.roles=userLoginSc.roles;
		this._net.serverVO.serverTime=userLoginSc.serverTime;
		this._net.serverVO.timeOffset=userLoginSc.timeOffset;
		this._net.serverVO.version=userLoginSc.version;
