		msg.decode(data);
		var tempAct=false;
		this.mgr.update(msg);
		var zhMsg=new ZhuHunPaylineSC();
		zhMsg.roleId=msg.roleId;
		zhMsg.fightValue=msg.fightValue;
		zhMsg.type=msg.type;
		zhMsg.zhuHunLevel=msg.zhuHunLevel;
		this.mgr.setZHInfo(zhMsg);
		var qnMsg=new PeiYangPaylineSC();
		qnMsg.roleId=msg.roleId;
		qnMsg.fightValue=msg.fightValue;
		qnMsg.type=msg.type;
		qnMsg.peiyangLevel=msg.peiyangLevel;
		if(msg.roleId==NetMgr.ins().roleVO.guid)
			this.updateFashion(msg,true);
		EventCenter.instance.event("GET_PAYLINE_INFO_UPDATE",[msg.type]);
		if(msg.activeState && !tempAct)
			EventCenter.instance.event("UpdateJieFengData",[msg.type]);
		this.isInit=false;
