	__proto.updateFashion=function(obj,bo){
		(bo===void 0)&& (bo=false);
		if(!PayLineType.checkHasFas(obj.type)){
			return;
		};
		var mdl=this.mgr.getModelbyRoleId(obj.roleId);
		var roleVo=NetMgr.ins().roleVO;
		var url="";
		var model_obj;
		var tempType="";
		var infoMsg=mdl.myPayLineInfo[obj.type];
		if(!infoMsg || !infoMsg.activeState){
			return;
		}
		if(bo==false)
			infoMsg.displayId=obj.jieshu;
		switch(obj.type){
			case 2:{
					if(roleVo.zuoQiHuanHuaId <=0){
						roleVo.zuoqiPeiDaiId2=infoMsg.displayId;
						if(infoMsg.displayId > 0){
							if(Mgr.guide.isOpen("zuoqi")==true){
								model_obj=this.mgr.getPaylineCfg(2,infoMsg.displayId);
								if(model_obj){
									if(Game.getInstance().player)
										Laya.timer.frameOnce(1,this,this.dott,[PathDefine.MOUNT+model_obj.res+"/"]);
								}
							}
							tempType="change_check_zuoqi";
						}
					}
					break ;
				}
			case 3:{
					roleVo.wingLevel=infoMsg.displayId;
					if(Mgr.guide.isOpen("jingjiewing")==true){
						model_obj=this.mgr.getPaylineCfg(3,infoMsg.displayId);
						if(model_obj){
							if((Game.getInstance().player && NetMgr.ins().roleVO.wingHuanHuaId <=0)|| this.mgr.isOpen)
								Game.getInstance().player.setWingRes(PathDefine.WING+model_obj.res+"/"+model_obj.res,1,true,false,true);
						}
					}
					tempType="change_check_zuoqi";
					break ;
				}
			case 6:{
					roleVo.shenBingPeiDaiId=infoMsg.displayId;
					if(Mgr.guide.isOpen("shenbing")==true){
						model_obj=this.mgr.getPaylineCfg(6,infoMsg.displayId);
						if(model_obj){
							if(Game.getInstance().player && NetMgr.ins().roleVO.weaponQianghuaLevel <=0)
								Game.getInstance().player.setWeaponRes(model_obj.res+"_A");
						}
					}
					tempType="change_check_zuoqi";
					break ;
				}
			}
		EventCenter.instance.event(tempType,null);
	}

