	__proto.showLvUp=function(preLv,targetLv){
		var dengji=UIMgrR.getIView(com.xq.view.modules.common.ILevelUpTip,2);
		var x=(Laya.stage.width-dengji.width)>>1;
		var y=(Laya.stage.height>>1)-200;
		if(!dengji.parent){
			Game.getInstance().fightHintView.addChild(dengji);
		}
		dengji.pos(x,y);
		dengji.levelUp(preLv,targetLv);
	}

	__proto.showLvAni=function(unit){
		var skeleton=this.skeletonDic[unit.guid];
		if(!skeleton || skeleton.destroyed){
			skeleton=new BoneAni();
			this.skeletonDic[unit.guid]=skeleton;
			skeleton.setOnce(true);
			skeleton.load(PathDefine.BONES+"2/2.sk");
			skeleton.pos(0,0);
			skeleton.blendMode="screen";
			unit.addChild(skeleton);
		}
	}

