	__proto.onAddExp=function(b){
		var vo=new AddExpSC();
		try{
			vo.decode(b);
		}
		catch(error){
			return;
		};
		var roleVo=NetMgr.ins().roleVO;
		if(roleVo.mapType==48 || roleVo.mapType==1 || roleVo.mapType==2){
			Mgr.prompt.expPrompt(vo.increExp);
		}
		FlyAniUtil.EXPFly(5);
		EventCenter.instance.event("updata_experience_monster_exp",[vo.increExp]);
		NetMgr.ins().roleVO.exp=vo.exp;
		var cfg=this.expCfg.getItemByField("level",vo.level);
		if(!cfg)return;
		var flagexp=cfg.needexp;
		var nums=Math.round(vo.increExp/(flagexp*0.01));
		if(nums>10)
			nums=10;
		if(nums>0){
		}
		this.laterAddExp(vo);
	}

