	__proto.backHorseUpDownSC=function(data){
		var msg=new HorseUpDownSC();
		msg.decode(data);
		var isOp=CodeLinkUtil.ins().funcIsOpen("jingjiemount")
		if(msg.errCode==1){
			var player=UnitManager.ins.unitList.get(msg.roleId);
			if(player){
				if(msg.roleId==NetMgr.ins().roleVO.guid){
					if(msg.isRide && isOp && PayLineNewModel.ins().hasOwnMount())
						player.mount(true);
					else
					player.mount(false);
				}
				else{
					if(msg.isRide)
						player.mount(true);
					else
					player.mount(false);
				}
			}
		}
	}

