		vo.param2=sc.param2;
		vo.skillCategory=sc.skillCategory;
		if(this.mplyer && !this.mplyer.isJuQing)
			FrameSmooth.add(Handler.create(this.unitManager,this.unitManager.harm,[vo]));
		var len=sc.harmMsgs.length;
