//class com.xq.modules.upgrades.shiZhuang.ShiZhuangAction extends com.xq.core.net.BaseMsgAction
var ShiZhuangAction=(function(_super){
	function ShiZhuangAction(){
		/**拉取信息*/
		this.msg_881000300=881000300;
		/**激活*/
		this.msg_881000301=881000301;
		/**选择佩戴*/
		this.msg_881000302=881000302;
		/**升阶幻化*/
		this.msg_881000310=881000310;
		/**幻化过期*/
		this.msg_881000304=881000304;
		/**幻化场景同步*/
		this.msg_881000303=881000303;
		/**幻化总属性*/
		this.msg_80201000=80201000;
		this.szMgr=null;
		this.heroMgr=null;
		ShiZhuangAction.__super.call(this);
		this.szMgr=Mgr.szMgr;
		this.heroMgr=Mgr.heroSysMgr;
	}

	__class(ShiZhuangAction,'com.xq.modules.upgrades.shiZhuang.ShiZhuangAction',_super);
	var __proto=ShiZhuangAction.prototype;
	__proto.registerMsg=function(){
		this._methodDic[this.msg_881000300]=this.infoSC;
		this._methodDic[this.msg_881000301]=this.jihuoSC;
		this._methodDic[this.msg_881000302]=this.peiDaiSC;
		this._methodDic[this.msg_881000310]=this.shenJieSC;
		this._methodDic[this.msg_881000304]=this.guoqiSC;
		this._methodDic[this.msg_881000303]=this.onSceneNotice;
		this._methodDic[this.msg_80201000]=this.onTotalPower;
	}

	/**幻化场景同步*/
	__proto.onSceneNotice=function(b){
		var msg=new NoticeHuanHuaChangeSC();
		msg.decode(b);
		if(msg.peiDaiId <=0){
			return;
		};
		var tempPl=UnitManager.ins.roleList.get(msg.roleId);
		if(tempPl){
			switch(msg.type){
				case 2:;
					var huanHuaCfgInfo=Mgr.szMgr.getHuanHuaInfoByOne(msg.peiDaiId+"");
					if(huanHuaCfgInfo)
						tempPl.setMountRes(PathDefine.MOUNT+huanHuaCfgInfo.res+"/",1,true,false,true);
					break ;
				case 3:
					huanHuaCfgInfo=Mgr.szMgr.getHuanHuaInfoByOne(msg.peiDaiId+"");
					if(huanHuaCfgInfo)
						tempPl.setWingRes(PathDefine.WING+huanHuaCfgInfo.res+"/"+huanHuaCfgInfo.res,1,true,false,true);
					break ;
				case 1:
					huanHuaCfgInfo=Mgr.szMgr.getHuanHuaInfoByOne(msg.peiDaiId+"");
					if(huanHuaCfgInfo)
						tempPl.setRes(huanHuaCfgInfo.res);
					break ;
				case 6:
					huanHuaCfgInfo=Mgr.szMgr.getHuanHuaInfoByOne(msg.peiDaiId+"");
					if(huanHuaCfgInfo){
						tempPl.setWeaponRes(huanHuaCfgInfo.res+"_A");
					}
					break ;
				case 16:
				case 17:
				case 18:
				case 19:
					(tempPl).setZhenFaRes(msg.peiDaiId);
					break ;
				case 22:;
					var turl=Model.shizhuang.getHhUrl(msg.peiDaiId+"",22);
					var skillUrl=Model.shizhuang.getTianShuSkillRes(msg.peiDaiId+"");
					tempPl.equipRune(turl,skillUrl);
					break
				case 24:
					turl=Model.shizhuang.getHhUrl(msg.peiDaiId+"",24);
					tempPl.equipCloakAni(turl);
					break ;
				case 20:
					turl=Model.shizhuang.getHhUrl(msg.peiDaiId+"",20);
					tempPl.equipQiLingBi(turl);
					break ;
				case 26:
					break
				case 27:
					break ;
				}
		}
	}

	/**请求幻化信息*/
	__proto.reqInfo=function(){
		this._net.sendMsg(this.msg_881000300);
	}

	/**服务器---幻化信息*/
	__proto.infoSC=function(data){
		var msg=new GetHuanHuaInfoSC();
		msg.decode(data);
		var len=msg.infos.length;
		for (var i=0;i < len;i++){
			var tsg=msg.infos [i];
			if(tsg){
				switch(tsg.type){
					case 16:
					case 18:
					case 17:
					case 19:
						this.heroMgr.initZhenFaInfo(tsg);
						break ;
					default :
						this.szMgr.setInfo(tsg);
						if(tsg.peidaiId > 0)
							this.szMgr.peiDai(tsg.type,tsg.peidaiId);
						break ;
					}
			}
		}
		Mgr.szMgr.updateAwakenSkillInfo(msg.skills);
		EventCenter.instance.event("jihuo_szevent");
		Mgr.szMgr.checkShizhuangRed();
	}

	/**激活时装*/
	__proto.reqJiHuo=function(type,id,itemid){
		var msg=new JiHuoHuanHuaCS();
		msg.type=type;
		msg.id=id;
		msg.itemId=itemid;
		this._net.sendMsg(this.msg_881000301,msg);
	}

	/**服务器---激活幻化*/
	__proto.jihuoSC=function(data){
		var msg=new JiHuoHuanHuaSC();
		msg.decode(data);
		console.log(Lang.str(2994),msg.roleId,msg.type,msg.id);
		if(msg.errCode==1){
			switch(msg.type){
				case 16:
				case 18:
				case 17:
				case 19:
					this.heroMgr.updateZFActivate(msg.type,msg.id,msg.curLevel);
					EventCenter.instance.event("updata_heji_red");
					break ;
				default :{
						var gsg=new HuanHuaAttr();
						gsg.id=msg.id;
						gsg.level=msg.curLevel;
						this.szMgr.addOneInfo(gsg);
						if(Mgr.bag.isShowUseTip){
							Mgr.chipPopMgr.addTeam(Handler.create(this,this.showSzTip,[msg]),-1,true,true);
						}
						break ;
					}
				}
			EventCenter.instance.event("jihuo_szevent");
		}
		else
		Mgr.prompt.optionPrompt(msg.errCode);
	}

	/**服务器---佩戴*/
	__proto.peiDaiSC=function(data){
		var msg=new PeiDaiHuanHuaSC();
		msg.decode(data);
		if(msg.errCode==1){
			switch(msg.type){
				case 16:
				case 18:
				case 17:
				case 19:
					this.heroMgr.updateZFPeiDai(msg.type,msg.id);
					Mgr.prompt.optionPrompt(Lang.str(2995));
					break ;
				default :
					if(msg.type==13){
						this.heroMgr.resetChuZhan(1,msg.id);
					}
					else if(msg.type==14){
						this.heroMgr.resetChuZhan(3,msg.id);
					}
					else if(msg.type==15){
						this.heroMgr.resetChuZhan(2,msg.id);
					}
					else if(msg.type==11){
						this.heroMgr.resetChuZhan(4,msg.id);
					}
					if(msg.type==1){
						var huanhuaCfg=Mgr.szMgr.getCfgByType(msg.type,msg.id+"");
						if(huanhuaCfg){
							NetMgr.ins().roleVO.job=huanhuaCfg.sex;
						}
					}
					this.szMgr.setPDInfo(msg.type,msg.id);
					this.szMgr.peiDai(msg.type,msg.id);
					Mgr.prompt.optionPrompt(Lang.str(2995));
					Mgr.payLine.updateSupSkill(msg.type,msg.huanhuaSkill);
					Mgr.payLine.resetPeiDai(msg.type,0);
					break ;
				}
			EventCenter.instance.event("peidaisuc_szevent",[msg.type]);
		}
		else
		Mgr.prompt.optionPrompt(msg.errCode);
	}

	/**请求佩戴*/
	__proto.reqPeiDai=function(type,id){
		var msg=new PeiDaiHuanHuaCS();
		msg.type=type;
		msg.id=id;
		this._net.sendMsg(this.msg_881000302,msg);
	}

	/**请求升阶*/
	__proto.reqShengJie=function(type,id){
		var msg=new ShengJieHuanHuaCS();
		msg.type=type;
		msg.id=id;
		this._net.sendMsg(this.msg_881000310,msg);
	}

	/**服务器---升阶*/
	__proto.shenJieSC=function(data){
		var msg=new ShengJieHuanHuaSC();
		msg.decode(data);
		if(msg.errCode==1){
			switch(msg.type){
				case 16:
				case 18:
				case 17:
				case 19:
					this.heroMgr.updateZFJj(msg.type,msg.id,msg.curLevel);
					EventCenter.instance.event("updata_heji_red");
					break ;
				default :{
						var shizhuangInfo=new HuanHuaAttr();
						shizhuangInfo.level=msg.curLevel;
						shizhuangInfo.id=msg.id;
						this.szMgr.addOneInfo(shizhuangInfo);
						break ;
					}
				}
			EventCenter.instance.event("shengjie_szevent");
		}
		else
		Mgr.prompt.optionPrompt(msg.errCode);
	}

	/**服务器---过期*/
	__proto.guoqiSC=function(data){
		var msg=new HuanHuaExpiredSC();
		msg.decode(data);
		EventCenter.instance.event("guoqi_szevent");
	}

	/**幻化属性总战力*/
	__proto.onTotalPower=function(data){
		var msg=new HuanhuaPowerSC();
		msg.decode(data);
		if(msg.type==162 || msg.type==163){
			EventCenter.instance.event(DaoFaEvent.DAO_FA_POWER_CHANGE,msg);
			return;
		}
		if(msg.power > 0){
			var vw=UIMgrR.openIView(com.xq.view.modules.helpfight.ver2.ITotalAtrView,2);
			vw.dataSource=msg;
		}
		else{
			Mgr.prompt.optionPrompt(Lang.str(2996));
		}
	}

	/**请求查看总属性*/
	__proto.reqPower=function(type){
		var msg=new HuanhuaPowerCS();
		msg.type=type;
		this._net.sendMsg(this.msg_80201000,msg);
	}

	/**展示时装Tips*/
	__proto.showSzTip=function(msg){
		var obj=Mgr.szMgr.getCfgByType(msg.type,msg.id+"");
		if(obj){
			var vw=UIMgrR.openIView(com.xq.view.modules.upgrades.shiZhuang.IShiZhuangShow,2);
			vw.dataSource=[obj,msg.curLevel];
		}
	}

	return ShiZhuangAction;
})(BaseMsgAction)


