	__proto.onGetEveryReward=function(b){
		var msg=new WangZhePvpGetBoxRewardSC();
		msg.decode(b);
		if(msg.errorcode==1){
			this.mgr.everyRewardArr=msg.boxs;
			this.mgr.updateRed();
			EventCenter.instance.event("updata_everyday_reward");
		}
	}

