			var rot=CommonUtil.getRelativeDirArr(this.mainPlayer.x,this.mainPlayer.y,this.curBattleObj.x,this.curBattleObj.y);
			var distance=CommonUtil.getDistance(this.mainPlayer.x,this.mainPlayer.y,this.curBattleObj.x,this.curBattleObj.y);
