				var dir=CommonUtil.changeDir(this.mainPlayer.x,this.mainPlayer.y,this.curBattleObj.x,this.curBattleObj.y);
				this.mainPlayer.curDir=dir;
				var ok=SkillGroupMgr.ins().autoSkill(this.mainPlayer);
