//class com.xq.rpg.action.logic.FindMonsterAction extends com.xq.rpg.action.logic.LogicActionBase
var FindMonsterAction=(function(_super){
	function FindMonsterAction(){
		FindMonsterAction.__super.call(this,'find_monster');
	}

	__class(FindMonsterAction,'com.xq.rpg.action.logic.FindMonsterAction',_super);
	var __proto=FindMonsterAction.prototype;
	__proto.doAction=function(value){
		_super.prototype.doAction.call(this,value);
		var monsterId=value.monsterId;
		MapInfoLoader.getMonster(value.mapId,monsterId,Handler.create(this,this.findMonster,[monsterId]));
	}

	__proto.findMonster=function(monsterId,data){
		AIController.ins().startAutoPath(data.mapId,data.x,data.y,Handler.create(this,this.moveEnd,[monsterId]));
	}

	__proto.moveEnd=function(monsterId){
		this.find(monsterId);
	}

	// }
	__proto.find=function(monsterId){
		Laya.timer.clear(this,this.find);
		var monster=UnitManager.ins.getNearestMonster(monsterId);
		if(monster){
			if(Math.sqrt(monster.dis)<800){
				TargetSelectMgr.ins.selectUnit(monster);
				AIController.ins().startAutoCombat(monsterId);
				EventCenter.instance.off("MAIN_PLAYER_MOVE_END",this,this.moveEnd);
			}
		}
		else{
			Laya.timer.once(1000,this,this.doTask);
		}
	}

	__proto.doTask=function(){
		Laya.timer.clear(this,this.doTask);
		EventCenter.instance.event(GameEvent.DO_TASK,false);
	}

	FindMonsterAction.getObject=function(monsterId,mapId,taskid,fly){
		var o={type:'find_monster',monsterId:monsterId,mapId:mapId,taskid:taskid};
		if(fly)
			o.fly=fly;
		return o;
	}

	FindMonsterAction.TYPE='find_monster';
	return FindMonsterAction;
})(LogicActionBase)


//class com.xq.rpg.action.logic.FindNpcAction extends com.xq.rpg.action.logic.LogicActionBase
var FindNpcAction=(function(_super){
	function FindNpcAction(){
		this.model=null;
		this.taskModel=null;
		this.currentAction=null;
		this.currentNpcvo=null;
		FindNpcAction.__super.call(this,'find_npc');
		this.model=NpcMgr.ins().model;
		this.taskModel=TaskModel.ins();
	}

	__class(FindNpcAction,'com.xq.rpg.action.logic.FindNpcAction',_super);
	var __proto=FindNpcAction.prototype;
	__proto.doAction=function(value){
		_super.prototype.doAction.call(this,value);
		AIController.ins().changeForbitAutoCombat();
		var model=NpcMgr.ins().model;
		var npcid=value.npcid;
		var npcVO=model.getNpcByNpcId(npcid);
		if(!npcVO)return;
		this.currentAction=value;
		this.currentNpcvo=npcVO;
		var npc=UnitManager.ins.npcList.get(npcVO.id);
		var self=Model.game.mPlayer;
		if(npc){
			var distance=CommonUtil.getDistance(self.x,self.y,npc.x,npc.y);
			if(distance < 150){
				this.showPanel(npcid);
			}
		};
		var posArr=SceneContainer.GridToGlobal(npcVO.gx,npcVO.gy);
		AIController.ins().startAutoPath(npcVO.map,posArr[0],posArr[1],Handler.create(this,this.moveEnd,[npcVO]));
	}

	// }
	__proto.moveEnd=function(npcVo){
		var player=Model.game.mPlayer;
		var posArr=SceneContainer.GridToGlobal(npcVo.gx,npcVo.gy);
		var distance=CommonUtil.getDistance(player.x,player.y,posArr[0],posArr[1]);
		if(distance < 200){
			this.showPanel(npcVo.id);
		}
		AIController.ins().changeForbitAutoCombat(false);
	}

	/**打开对话框或者任务框*/
	__proto.showPanel=function(npcId){
		var taskVO=this.taskModel.curTaskVO;
		if(taskVO && taskVO.completeNpc==npcId && taskVO.state==1){
			EventCenter.instance.event("SHOW_NPC_PANEL");
		}
	}

	FindNpcAction.getObject=function(npcid,taskid,fly){
		var o={type:'find_npc',npcid:npcid,taskid:taskid};
		if(fly)
			o.fly=fly;
		return o;
	}

	FindNpcAction.TYPE='find_npc';
	return FindNpcAction;
})(LogicActionBase)


