//class com.xq.rpg.skill.newVic.template.SkillTemplate extends com.xq.rpg.skill.op.SkillOPBase
var SkillTemplate=(function(_super){
	function SkillTemplate(vo,unit,avo){
		SkillTemplate.__super.call(this,vo,unit,avo);
	}

	__class(SkillTemplate,'com.xq.rpg.skill.newVic.template.SkillTemplate',_super);
	var __proto=SkillTemplate.prototype;
	/**
	*释放技能(兼容旧表，动作动态修改)
	**/
	__proto.start=function(forbitSount){
		(forbitSount===void 0)&& (forbitSount=false);
		_super.prototype.start.call(this,forbitSount);
		if(this.isZuhe){
			this.actVo.readyEff=this.actVo.queueAry[this.zuheId-1];
		}
		else{}
		this.getTarget()
		this.effHandler();
		this.showHit();
	}

	__proto.effHandler=function(){
		if(this.actVo.readyEff){
			SkillBase.skillReady(this.svo);
			this.playSound(this.actVo.readyEff.soundRes);
		}
		if(this.actVo.readyTime > 0){
			if(this.actVo.isStopFight){
				AIController.ins().changeForbitAutoCombat(true);
			}
			Laya.timer.once(this.actVo.readyTime,this,this.doNext);
		}
		else{
			this.doNext();
		}
	}

	__proto.doNext=function(){
		if(this.actVo.isStopFight){
			AIController.ins().changeForbitAutoCombat(false);
		}
		if(this.actVo.flyEff){
			SkillBase.showShoot(this.svo);
			this.playSound(this.actVo.flyEff.soundRes);
		}
		else if(this.actVo.aimEff){
			this.setTarget();
			SkillBase.showAimEff(this.svo);
			this.playSound(this.actVo.aimEff.soundRes);
		}
		else if(this.actVo.rushDis > 0){
			SkillBase.showRush(this.svo);
		}
		else if(this.actVo.isMoment){}
		else{
			return;
		}
		this.doAction();
	}

	/**爆点*/
	__proto.showHit=function(){
		if(this.actVo.hitEff){
			var bdTime=this.actVo.readyTime+this.actVo.hitDelay;
			this.svo.tarArr=this.targetArr
			if(bdTime > 0){
				Laya.timer.once(bdTime,SkillBase,SkillBase.playHit,[this.svo]);
				}else{
				SkillBase.playHit(this.svo);
			}
		}
	}

	/**获取目标*/
	__proto.setTarget=function(){
		if(!this.actVo.isMainRole){
			if((this.curObj instanceof com.xq.rpg.unit.MainPlayer )){
				this.svo.attarckUnit=TargetSelectMgr.ins.curMouseUnit;
			}
			if(!this.svo.attarckUnit){
				this.svo.attarckUnit=this.targetArr[0]
			}
		}
	}

	return SkillTemplate;
})(SkillOPBase)


