var SkillOPSpecifyAreaAOE=(function(_super){
	function SkillOPSpecifyAreaAOE(vo,unit){
		SkillOPSpecifyAreaAOE.__super.call(this,vo,unit);
	}

	__class(SkillOPSpecifyAreaAOE,'com.xq.rpg.skill.op.SkillOPSpecifyAreaAOE',_super);
	var __proto=SkillOPSpecifyAreaAOE.prototype;
	/**释放技能*/
	__proto.start=function(forbitSount){
		(forbitSount===void 0)&& (forbitSount=false);
		_super.prototype.start.call(this,forbitSount);
		this.svo.curObj=this.curObj;
		this.svo.tarArr=this.targetArr;
		this.svo.actKey=this.vo.action;
		this.svo.delayTime=this.vo.skillSpace;
		this.svo.dirId=this.curObj.curDir || 0;
		this.svo.nums=this.vo.skillNum;
		this.svo.radius=this.vo.length;
		this.svo.rang=this.vo.rang;
		this.svo.skillUseRes=this.vo.skillUseRes;
		this.svo.skillBottomRes=this.vo.skillBottomRes;
		this.svo.type=7;
		this.svo.shake=this.vo.shake;
		this.svo.skillCD=this.vo.skillCD;
		SkillBase.show(this.svo);
	}

	/**计算技能范围命中的对象数组*/
	__proto.getTarget=function(){
		_super.prototype.getTarget.call(this);
		var unitArr=UnitManager.ins.unitList.values;
		var unit=TargetSelectMgr.ins.curMouseUnit;
		var hit;
		hit=new HitArea();
		hit.hit.drawCircle(0,0,this.vo.rang,"#00FF00");
		var sp=SkillOPCache.spArr.length>0?SkillOPCache.spArr.pop():new Sprite();
		sp.alpha=0.5;
		sp.graphics.clear();
		sp.graphics.drawCircle(0,0,this.vo.rang,"#00FF00");
		if(unit && unit.isEnemy){
			sp.x=unit.x;
			sp.y=unit.y;
			this.targetArr=SkillBase.sort(unit.x,unit.y,unitArr,this.vo.maxTarget,this.vo.rang,this.vo.rang);
		}
		else{
			var dir=(this.curObj).curDir;
			var tx=0,ty=0;
			switch(dir){
				case 0:tx=0;ty=this.vo.length;break ;
				case 1:tx=this.vo.length*0.7;ty=this.vo.length*0.7;break ;
				case 2:tx=this.vo.length;ty=0;break ;
				case 3:tx=this.vo.length*0.7;ty=-this.vo.length*0.7;break ;
				case 4:tx=0;ty=-this.vo.length;break ;
				case 5:tx=-this.vo.length*0.7;ty=-this.vo.length*0.7;break ;
				case 6:tx=-this.vo.length;ty=0;break ;
				case 7:tx=-this.vo.length*0.7;ty=this.vo.length*0.7;break ;
				}
			sp.x=this.curObj.x
			sp.y=this.curObj.y
		}
		sp.hitArea=hit;
		SceneContainer.getInstance().bottomLayer.addChild(sp);
		this.targetArr=UnitLayerManager.ins.hitTestBySprite(sp);
		this.targetArr=UnitManager.ins.sortUnit(sp.x,sp.y,this.targetArr,this.vo.maxTarget,this.vo.rang);
		if(unit && unit.isEnemy && ((unit instanceof com.xq.rpg.unit.Player )|| (unit instanceof com.xq.rpg.unit.Monster ))){
			var dis=CommonUtil.getDistance(unit.x,unit.y,this.curObj.x,this.curObj.y);
			if(dis <=this.vo.length)
				this.targetArr.unshift(unit);
		}
		if(!SkillManager.ins.isShowSkillfanwei)
			sp.removeSelf();
		SkillOPCache.spArr.push(sp);
		return this.targetArr;
	}

	return SkillOPSpecifyAreaAOE;
})(SkillOPBase)


