//class com.xq.map.display.ForeGroundLayer extends laya.display.Sprite
var ForeGroundLayer=(function(_super){
	function ForeGroundLayer(types){
		this.jianbian=null;
		this.type=0;
		this.tex1=null;
		this.tex2=null;
		this.fore1=null;
		this.fore2=null;
		ForeGroundLayer.__super.call(this);
		this.type=types;
	}

	__class(ForeGroundLayer,'com.xq.map.display.ForeGroundLayer',_super);
	var __proto=ForeGroundLayer.prototype;
	__proto.setUrl=function(url){
		switch(this.type){
			case 1:
				break ;
			case 2:
				this.fore1=new Sprite();
				this.fore1.width=1280;
				this.fore1.height=1024;
				this.fore1.pivotX=640;
				this.fore1.pivotY=512;
				this.fore1.scaleX=2.5;
				this.fore1.scaleY=2.5;
				this.fore2=new Sprite();
				this.fore2.width=1280;
				this.fore2.height=1024;
				this.fore2.pivotX=640;
				this.fore2.pivotY=512;
				this.fore2.scaleX=-2.5;
				this.fore2.scaleY=2.5;
				this.jianbian=new Image();
				this.jianbian.width=Laya.stage.width;
				this.jianbian.height=Laya.stage.height;
				this.jianbian.skin=PathDefine.RES2_ROOT+PathDefine.IMAGE+"juqing/jianbian"+".png";
				Laya.loader.load(url+"mask1"+".png",Handler.create(this,this.onImageLoad,[1]));
				break ;
			}
	}

	__proto.onImageLoad=function(index,tex){
		if((tex instanceof laya.resource.Texture )){
			switch(this.type){
				case 1:
					this.jingyanFore(index,tex);
					break ;
				case 2:
					this.kuafuFore(index,tex);
					break ;
				}
		}
	}

	__proto.ani=function(){
		this.fore1.x=this.tex1.width>>1;
		this.fore1.y=400;
		this.fore2.x=SceneContainer.getInstance().upMapLayer.mapWidth-(this.tex1.width>>1);
		this.fore2.y=700;
		this.jianbian.alpha=1;
		Tween.to(this.jianbian,{alpha:0},3000);
		Tween.to(this.fore1,{x:-this.tex1.width},3000,null,null);
		Tween.to(this.fore2,{x:SceneContainer.getInstance().upMapLayer.mapWidth+this.tex1.width},3000,null,null);
	}

	/**跨服副本前景*/
	__proto.kuafuFore=function(index,tex){
		EventCenter.instance.on("anigo",this,this.ani);
		switch(index){
			case 1:
				Laya.stage.addChild(this.jianbian);
				Tween.to(this.jianbian,{alpha:0},1000);
				this.tex1=tex;
				this.fore1.graphics.drawTexture(tex,0,0,tex.width,tex.height);
				this.addChild(this.fore1);
				this.fore2.graphics.drawTexture(tex,0,0,tex.width,tex.height);
				this.addChild(this.fore2);
				this.fore1.x=this.tex1.width>>1;
				this.fore1.y=400;
				this.fore2.x=SceneContainer.getInstance().upMapLayer.mapWidth-(this.tex1.width>>1);
				this.fore2.y=700;
				this.jianbian.alpha=1;
				Tween.to(this.jianbian,{alpha:0},3000);
				Tween.to(this.fore1,{x:-this.tex1.width},3000,null,null);
				Tween.to(this.fore2,{x:SceneContainer.getInstance().upMapLayer.mapWidth+this.tex1.width},3000,null,null);
				break ;
			}
	}

	/**经验副本前景 */
	__proto.jingyanFore=function(index,tex){
		switch(index){
			case 1:
				this.tex1=tex;
				if(!this.fore1)
					this.fore1=new Sprite();
				this.fore1.graphics.drawTexture(tex,0,0,tex.width,tex.height);
				this.fore1.x=0;
				this.fore1.y=SceneContainer.getInstance().upMapLayer.mapHeigth-tex.height;
				this.addChild(this.fore1);
				break ;
			case 2:
				this.tex2=tex;
				if(!this.fore2)
					this.fore2=new Sprite();
				this.fore2.graphics.drawTexture(tex,0,0,tex.width,tex.height);
				this.fore2.x=SceneContainer.getInstance().upMapLayer.mapWidth-tex.width;
				this.fore2.y=SceneContainer.getInstance().upMapLayer.mapHeigth-tex.height;
				this.addChild(this.fore2);
				break ;
			}
	}

	__proto.dispose=function(){
		if(this.tex1)
			this.tex1.destroy();
		if(this.fore1)
			this.fore1.destroy();
		if(this.tex2)
			this.tex2.destroy();
		if(this.fore2)
			this.fore2.destroy();
		this.removeSelf();
	}

	return ForeGroundLayer;
})(Sprite)


