var MapStaticLayer=(function(_super){
	function MapStaticLayer(type){
		/**静态下层地图类型 0:不动,1:向下移动,复制自己,2向左移动,复制自己*/
		this.type=0;
		this.imageUrl=null;
		this.imageUrl1=null;
		this.imageUrl2=null;
		this.imageUrl3=null;
		this.tex=null;
		this.tex0=null;
		this.tex1=null;
		this.tex2=null;
		this.bg0=null;
		this.bg1=null;
		this.bg2=null;
		/**纹理宽度和屏幕宽度的差值*/
		this.offX=0;
		/**纹理高度和屏幕高度的差值*/
		this.offY=0;
		this.speed=1;
		(type===void 0)&& (type=0);
		MapStaticLayer.__super.call(this);
		if(!type){
			type=0;
		}
		this.type=type;
		Laya.stage.on("resize" ,this ,this.onStageResize,null);
	}

	__class(MapStaticLayer,'com.xq.map.display.MapStaticLayer',_super);
	var __proto=MapStaticLayer.prototype;
	__proto.onStageResize=function(){
		var t=this.tex0 ? this.tex0 :this.tex;
		if(t){
			this.x=-Laya.stage.width*0.2;
			this.y=-Laya.stage.height*0.2;
			var per1=Laya.stage.width/t.width;
			var per2=Laya.stage.height/t.height;
			if(this.type==0)
				var per=(per1>per2?per1:per2);
			else if(this.type==1||this.type==2)
			per=per1;
			else if(this.type==3||this.type==4)
			per=per2;
			per=(per>1?per:1)+per1*0.4;
			this.scaleX=per;
			this.scaleY=per;
			this.offY=t.height-Laya.stage.height;
			this.offX=t.width-Laya.stage.width;
		}
	}

	__proto.setUrl=function(imageUrl){
		if(this.type !=0){
			this.imageUrl1=imageUrl+"0"+".jpg";
			this.imageUrl2=imageUrl+"1"+".jpg";
			this.imageUrl3=imageUrl+"2"+".jpg";
			Laya.timer.once(50,this,this.startLoad,[[this.imageUrl1,this.imageUrl2,this.imageUrl3]]);
		}
		else{
			this.imageUrl=imageUrl+".jpg";
			Laya.timer.once(50,this,this.startLoad,[[this.imageUrl]]);
		}
	}

	__proto.startLoad=function(loadRes){
		Laya.loader.load(loadRes,Handler.create(this,this.onImageLoaded,null));
	}

	__proto.onImageLoaded=function(){
		if(this.type==0){
			this.tex=Loader.getRes(this.imageUrl);
			if(!this.tex)
				return;
		}
		else{
			this.tex0=Loader.getRes(this.imageUrl1);
			this.tex1=Loader.getRes(this.imageUrl2);
			this.tex2=Loader.getRes(this.imageUrl3);
			if(!this.tex0 || !this.tex1 || !this.tex2){
				alert(Lang.str(2113)+this.imageUrl1);
				return;
			}
		}
		switch(this.type){
			case 0:
				this.graphics.drawTexture(this.tex,0,0,this.tex.width,this.tex.height);
				this.onStageResize();
				break ;
			case 1:
				this.bg0=new Sprite();
				this.bg1=new Sprite();
				this.bg2=new Sprite();
				this.bg0.graphics.drawTexture(this.tex0,0,0,this.tex0.width,this.tex0.height);
				this.bg1.graphics.drawTexture(this.tex1,0,0,this.tex1.width,this.tex1.height);
				this.bg2.graphics.drawTexture(this.tex2,0,0,this.tex2.width,this.tex2.height);
				this.offY=this.tex0.height-Laya.stage.height;
				this.bg0.y=0-this.offY;
				this.bg1.y=-this.tex0.height-this.offY;
				this.bg2.y=-(this.tex0.height<<1)-this.offY;
				this.init();
				break ;
			case 2:
				this.bg0=new Sprite();
				this.bg1=new Sprite();
				this.bg2=new Sprite();
				this.bg0.graphics.drawTexture(this.tex0,0,0,this.tex0.width,this.tex0.height);
				this.bg1.graphics.drawTexture(this.tex1,0,0,this.tex1.width,this.tex1.height);
				this.bg2.graphics.drawTexture(this.tex2,0,0,this.tex2.width,this.tex2.height);
				this.bg0.y=0;
				this.bg1.y=this.tex0.height;
				this.bg2.y=(this.tex0.height<<1);
				this.init();
				break ;
			case 3:
				this.bg0=new Sprite();
				this.bg1=new Sprite();
				this.bg2=new Sprite();
				this.bg0.graphics.drawTexture(this.tex0,0,0,this.tex0.width,this.tex0.height);
				this.bg1.graphics.drawTexture(this.tex1,0,0,this.tex1.width,this.tex1.height);
				this.bg2.graphics.drawTexture(this.tex2,0,0,this.tex2.width,this.tex2.height);
				this.offX=this.tex0.width-Laya.stage.width;
				this.bg0.x=0-this.offX;
				this.bg1.x=-this.tex0.width-this.offX;
				this.bg2.x=-(this.tex0.width<<1)-this.offX;
				this.init();
				break ;
			case 4:
				this.bg0=new Sprite();
				this.bg1=new Sprite();
				this.bg2=new Sprite();
				this.bg0.graphics.drawTexture(this.tex0,0,0,this.tex0.width,this.tex0.height);
				this.bg1.graphics.drawTexture(this.tex1,0,0,this.tex1.width,this.tex1.height);
				this.bg2.graphics.drawTexture(this.tex2,0,0,this.tex2.width,this.tex2.height);
				this.bg0.x=0;
				this.bg1.x=this.tex0.width;
				this.bg2.x=(this.tex0.width<<1);
				this.init();
				break ;
			}
	}

	// trace(Lang.str(2114),Laya.stage.width,Laya.stage.height);
	__proto.init=function(){
		this.addChild(this.bg0);
		this.addChild(this.bg1);
		this.addChild(this.bg2);
		this.onStageResize();
		Laya.timer.frameLoop(1,this,this.moveAni);
	}

	/**移动动画*/
	__proto.moveAni=function(){
		switch(this.type){
			case 1:
				if(this.bg0.y>=Laya.stage.height){
					this.bg0.y=-(this.tex0.height<<1)-this.offY+this.speed;
				}
				this.bg0.y+=this.speed;
				if(this.bg1.y>=Laya.stage.height){
					this.bg1.y=-(this.tex0.height<<1)-this.offY+this.speed;
				}
				this.bg1.y+=this.speed;
				if(this.bg2.y>=Laya.stage.height){
					this.bg2.y=-(this.tex0.height<<1)-this.offY+this.speed;
				}
				this.bg2.y+=this.speed;
				break ;
			case 2:
				if(this.bg0.y<=-this.tex0.height)
					this.bg0.y=(this.tex0.height<<1)-this.speed;
				this.bg0.y-=this.speed;
				if(this.bg1.y<=-this.tex0.height)
					this.bg1.y=(this.tex0.height<<1)-this.speed;
				this.bg1.y-=this.speed;
				if(this.bg2.y<=-this.tex0.height)
					this.bg2.y=(this.tex0.height<<1)-this.speed;
				this.bg2.y-=this.speed;
				break ;
			case 3:
				if(this.bg0.x >=Laya.stage.width)
					this.bg0.x=-(this.tex0.width<<1)-this.offX+this.speed;
				this.bg0.x+=this.speed;
				if(this.bg1.x >=Laya.stage.width)
					this.bg1.x=-(this.tex0.width<<1)-this.offX+this.speed;
				this.bg1.x+=this.speed;
				if(this.bg2.x >=Laya.stage.width)
					this.bg2.x=-(this.tex0.width<<1)-this.offX+this.speed;
				this.bg2.x+=this.speed;
				break ;
			case 4:
				if(this.bg0.x <=-this.tex0.width)
					this.bg0.x=(this.tex0.width<<1)-this.speed;
				this.bg0.x-=this.speed;
				if(this.bg1.x <=-this.tex0.width)
					this.bg1.x=(this.tex0.width<<1)-this.speed;
				this.bg1.x-=this.speed;
				if(this.bg2.x <=-this.tex0.width)
					this.bg2.x=(this.tex0.width<<1)-this.speed;
				this.bg2.x-=this.speed;
				break ;
			}
	}

	__proto.dispose=function(){
		Laya.timer.clear(this,this.moveAni);
		if(this.tex){
			this.tex.destroy(true);
			this.tex=null;
		}
		if(this.tex0){
			this.tex0.destroy(true);
			this.tex0=null;
		}
		if(this.tex1){
			this.tex1.destroy(true);
			this.tex1=null;
		}
		if(this.tex2){
			this.tex2.destroy(true);
			this.tex2=null;
		}
		Laya.stage.off("resize" ,this ,this.onStageResize);
		Laya.loader.clearRes(this.imageUrl1,true);
		Laya.loader.clearRes(this.imageUrl2,true);
		Laya.loader.clearRes(this.imageUrl3,true);
		this.removeSelf();
	}

	return MapStaticLayer;
})(Sprite)


