		if(this.isDipose)
			return;
		this.pickAni.visible=false;
		this.groundAni.visible=false;
		this.flyAni.visible=true;
		this.flyAni.setRes(PathDefine.EFFECT+"guangdian"+".amt");
		this.times=0;
		Laya.timer.loop(200,this,this.move);
		Laya.timer.once(2000,this,this.showPickAni);
